import type { BankQuestion } from "@/lib/bank";

/** MS Office, Internet and Cyber Security (Computer Awareness): 500 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"comp-ms-office-internet-1","question":"Which keyboard shortcut selects all the content of a document in MS Word?","options":["Ctrl + L","Ctrl + E","Ctrl + A","Ctrl + S"],"answer":2,"explanation":"Ctrl + A selects all. Ctrl + S saves, Ctrl + L left-aligns and Ctrl + E centres the text.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"MS Word में किस कीबोर्ड शॉर्टकट से दस्तावेज़ की सारी सामग्री चयनित (select) हो जाती है?","optionsHi":["Ctrl + L","Ctrl + E","Ctrl + A","Ctrl + S"],"explanationHi":"Ctrl + A सब कुछ चयनित करता है। Ctrl + S सेव करता है, Ctrl + L टेक्स्ट को बाएँ संरेखित करता है और Ctrl + E उसे केंद्र में संरेखित करता है।"},
  {"id":"comp-ms-office-internet-2","question":"What is the default file extension of an MS Excel workbook saved in Excel 2007 or later?","options":[".docx",".accdb",".pptx",".xlsx"],"answer":3,"explanation":".xlsx is the Excel workbook format (Office Open XML). .docx is Word, .pptx is PowerPoint and .accdb is an Access database.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"Excel 2007 या उसके बाद के संस्करण में सेव की गई MS Excel वर्कबुक का डिफ़ॉल्ट फ़ाइल एक्सटेंशन क्या है?","optionsHi":[".docx",".accdb",".pptx",".xlsx"],"explanationHi":".xlsx Excel वर्कबुक का प्रारूप (Office Open XML) है। .docx Word का, .pptx PowerPoint का और .accdb Access डेटाबेस का एक्सटेंशन है।"},
  {"id":"comp-ms-office-internet-3","question":"A malicious program that looks like useful software but secretly harms the system once installed is called a:","options":["Firewall","Trojan horse","Worm","Cookie"],"answer":1,"explanation":"A Trojan horse disguises itself as legitimate software. A worm spreads by itself across networks; a firewall is a defence and a cookie is a small browser file.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"ऐसा हानिकारक प्रोग्राम जो उपयोगी सॉफ़्टवेयर जैसा दिखता है, किंतु इंस्टॉल होने के बाद चुपचाप सिस्टम को नुकसान पहुँचाता है, कहलाता है:","optionsHi":["फ़ायरवॉल","ट्रोजन हॉर्स","वर्म","कुकी"],"explanationHi":"ट्रोजन हॉर्स स्वयं को वैध सॉफ़्टवेयर के रूप में छिपाता है। वर्म नेटवर्क पर अपने आप फैलता है; फ़ायरवॉल एक सुरक्षा उपाय है और कुकी ब्राउज़र की एक छोटी फ़ाइल है।"},
  {"id":"comp-ms-office-internet-4","question":"Which key starts a PowerPoint slide show from the first slide?","options":["F5","F12","F1","F7"],"answer":0,"explanation":"F5 runs the slide show from the beginning (Shift + F5 starts from the current slide). F7 is spell check, F12 is Save As and F1 is Help.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"PowerPoint में कौन-सी कुंजी स्लाइड शो को पहली स्लाइड से शुरू करती है?","optionsHi":["F5","F12","F1","F7"],"explanationHi":"F5 स्लाइड शो को शुरुआत से चलाती है (Shift + F5 वर्तमान स्लाइड से शुरू करती है)। F7 स्पेल चेक, F12 Save As और F1 Help के लिए है।"},
  {"id":"comp-ms-office-internet-5","question":"Which MS Excel function counts only the cells in a range that contain numbers?","options":["COUNT","COUNTA","COUNTBLANK","SUM"],"answer":0,"explanation":"COUNT counts numeric cells only. COUNTA counts every non-empty cell (text included), COUNTBLANK counts empty cells and SUM adds values.","difficulty":"moderate","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"MS Excel का कौन-सा फ़ंक्शन किसी रेंज में केवल उन सेलों की गिनती करता है जिनमें संख्याएँ हैं?","optionsHi":["COUNT","COUNTA","COUNTBLANK","SUM"],"explanationHi":"COUNT केवल संख्यात्मक सेलों की गिनती करता है। COUNTA प्रत्येक गैर-रिक्त सेल (पाठ सहित) गिनता है, COUNTBLANK रिक्त सेल गिनता है और SUM मानों को जोड़ता है।"},
  {"id":"comp-ms-office-internet-6","question":"An e-mail pretending to be from your bank that asks you to click a link and enter your login details is an example of:","options":["Spamdexing","Cracking","Phishing","Vishing"],"answer":2,"explanation":"Phishing uses fake e-mails or websites to steal credentials. Vishing is the same trick over voice calls.","difficulty":"moderate","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"आपके बैंक की ओर से होने का दिखावा करने वाला ऐसा ई-मेल, जो आपसे किसी लिंक पर क्लिक करने और लॉगिन विवरण भरने को कहता है, किसका उदाहरण है?","optionsHi":["स्पैमडेक्सिंग (Spamdexing)","क्रैकिंग (Cracking)","फ़िशिंग (Phishing)","विशिंग (Vishing)"],"explanationHi":"फ़िशिंग में नकली ई-मेल या वेबसाइट के ज़रिए क्रेडेंशियल चुराए जाते हैं। विशिंग यही चाल फ़ोन कॉल के माध्यम से चलना है।"},
  {"id":"comp-ms-office-internet-7","question":"In MS Word, the shortcut Ctrl + E is used to:","options":["Right-align the text","Justify the text","Open the Find dialog","Centre-align the text"],"answer":3,"explanation":"Ctrl + E centres, Ctrl + J justifies, Ctrl + R right-aligns, Ctrl + L left-aligns and Ctrl + F opens Find.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"MS Word में शॉर्टकट Ctrl + E का उपयोग किसलिए किया जाता है?","optionsHi":["टेक्स्ट को दाएँ संरेखित करने के लिए","टेक्स्ट को जस्टिफ़ाई करने के लिए","Find डायलॉग खोलने के लिए","टेक्स्ट को केंद्र में संरेखित करने के लिए"],"explanationHi":"Ctrl + E केंद्र में संरेखित करता है, Ctrl + J जस्टिफ़ाई करता है, Ctrl + R दाएँ संरेखित करता है, Ctrl + L बाएँ संरेखित करता है और Ctrl + F Find खोलता है।"},
  {"id":"comp-ms-office-internet-8","question":"Which protocol lets you read e-mail while keeping the messages on the server, so the mailbox stays in sync on your phone and laptop?","options":["POP3","IMAP","SMTP","FTP"],"answer":1,"explanation":"IMAP keeps mail on the server and syncs folders across devices. POP3 typically downloads mail to one device and removes it from the server; SMTP only sends mail.","difficulty":"moderate","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"कौन-सा प्रोटोकॉल संदेशों को सर्वर पर रखते हुए ई-मेल पढ़ने की सुविधा देता है, जिससे आपके फ़ोन और लैपटॉप में मेलबॉक्स समन्वित (sync) रहता है?","optionsHi":["POP3","IMAP","SMTP","FTP"],"explanationHi":"IMAP मेल को सर्वर पर रखता है और सभी उपकरणों में फ़ोल्डर सिंक करता है। POP3 सामान्यतः मेल को एक उपकरण में डाउनलोड कर देता है और सर्वर से हटा देता है; SMTP केवल मेल भेजता है।"},
  {"id":"comp-ms-office-internet-9","question":"PDF, the common document format developed by Adobe, stands for:","options":["Printable Document File","Portable Document Format","Portable Data File","Public Data Format"],"answer":1,"explanation":"PDF = Portable Document Format, introduced by Adobe in 1993 so a document looks the same on every device.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"Adobe द्वारा विकसित सामान्य दस्तावेज़ प्रारूप PDF का पूर्ण रूप क्या है?","optionsHi":["Printable Document File","Portable Document Format","Portable Data File","Public Data Format"],"explanationHi":"PDF = Portable Document Format, जिसे Adobe ने 1993 में प्रस्तुत किया ताकि दस्तावेज़ हर उपकरण पर एक जैसा दिखे।"},
  {"id":"comp-ms-office-internet-10","question":"Which device forwards data packets between different networks using IP addresses?","options":["Hub","Repeater","Switch","Router"],"answer":3,"explanation":"A router works at the network layer and routes packets between networks by IP address. A switch forwards frames within a LAN using MAC addresses; a hub and repeater only regenerate signals.","difficulty":"moderate","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"कौन-सा उपकरण IP पतों का उपयोग करके अलग-अलग नेटवर्कों के बीच डेटा पैकेट आगे भेजता है?","optionsHi":["हब (Hub)","रिपीटर (Repeater)","स्विच (Switch)","राउटर (Router)"],"explanationHi":"राउटर नेटवर्क लेयर पर कार्य करता है और IP पते के आधार पर नेटवर्कों के बीच पैकेट भेजता है। स्विच MAC पतों के आधार पर LAN के भीतर फ़्रेम भेजता है; हब और रिपीटर केवल सिग्नल को पुनः उत्पन्न करते हैं।"},
  {"id":"comp-ms-office-internet-11","question":"A system that monitors incoming and outgoing network traffic and blocks it according to set security rules is a:","options":["Firewall","Compiler","Modem","Proxy server"],"answer":0,"explanation":"A firewall (hardware or software) filters traffic by rules. A proxy forwards requests on a client's behalf; it is not primarily a rule-based filter.","difficulty":"moderate","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"ऐसी प्रणाली जो आने वाले और जाने वाले नेटवर्क ट्रैफ़िक की निगरानी करती है और निर्धारित सुरक्षा नियमों के अनुसार उसे रोकती है, कहलाती है:","optionsHi":["फ़ायरवॉल (Firewall)","कंपाइलर (Compiler)","मॉडेम (Modem)","प्रॉक्सी सर्वर (Proxy server)"],"explanationHi":"फ़ायरवॉल (हार्डवेयर या सॉफ़्टवेयर) नियमों के आधार पर ट्रैफ़िक को फ़िल्टर करता है। प्रॉक्सी किसी क्लाइंट की ओर से अनुरोध आगे भेजता है; वह मुख्य रूप से नियम-आधारित फ़िल्टर नहीं है।"},
  {"id":"comp-ms-office-internet-12","question":"In MS Excel, which cell reference remains unchanged when a formula is copied to another cell?","options":["A$1","$A1","$A$1","A1"],"answer":2,"explanation":"$A$1 is an absolute reference: both column and row are locked. A1 is relative, while A$1 and $A1 are mixed references that lock only the row or only the column.","difficulty":"moderate","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"MS Excel में, किसी सूत्र (formula) को दूसरे सेल में कॉपी करने पर कौन-सा सेल संदर्भ अपरिवर्तित रहता है?","optionsHi":["A$1","$A1","$A$1","A1"],"explanationHi":"$A$1 निरपेक्ष (absolute) संदर्भ है: कॉलम और पंक्ति दोनों लॉक रहते हैं। A1 सापेक्ष (relative) है, जबकि A$1 और $A1 मिश्रित संदर्भ हैं जो केवल पंक्ति या केवल कॉलम को लॉक करते हैं।"},
  {"id":"comp-ms-office-internet-13","question":"What value does the Excel formula =INT(-4.3) return?","options":["-5","-4","-4.3","4"],"answer":0,"explanation":"INT rounds a number down to the nearest integer, so -4.3 becomes -5 (not -4). TRUNC(-4.3) would give -4.","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"Excel का सूत्र =INT(-4.3) क्या मान लौटाता है?","optionsHi":["-5","-4","-4.3","4"],"explanationHi":"INT किसी संख्या को निकटतम पूर्णांक तक नीचे की ओर पूर्णांकित करता है, इसलिए -4.3 का मान -5 होता है (-4 नहीं)। TRUNC(-4.3) का मान -4 होता।"},
  {"id":"comp-ms-office-internet-14","question":"The WannaCry attack of May 2017, which locked files on computers worldwide and demanded payment in Bitcoin, was an example of:","options":["Keylogger","Ransomware","Adware","Spyware"],"answer":1,"explanation":"Ransomware encrypts the victim's files and demands a ransom for the key. WannaCry spread through a Windows SMB vulnerability.","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"मई 2017 का WannaCry हमला, जिसने दुनिया भर के कंप्यूटरों में फ़ाइलें लॉक कर दीं और Bitcoin में भुगतान की माँग की, किसका उदाहरण था?","optionsHi":["कीलॉगर (Keylogger)","रैनसमवेयर (Ransomware)","एडवेयर (Adware)","स्पाईवेयर (Spyware)"],"explanationHi":"रैनसमवेयर पीड़ित की फ़ाइलों को एन्क्रिप्ट कर देता है और कुंजी के बदले फिरौती माँगता है। WannaCry Windows की एक SMB कमज़ोरी के ज़रिए फैला था।"},
  {"id":"comp-ms-office-internet-16","question":"Which Excel function searches for a value in the top row of a table and returns a value from a specified row below it?","options":["MATCH","VLOOKUP","HLOOKUP","CONCAT"],"answer":2,"explanation":"HLOOKUP looks across the first row (horizontal). VLOOKUP looks down the first column; MATCH returns only a position.","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"Excel का कौन-सा फ़ंक्शन किसी तालिका की शीर्ष पंक्ति में मान खोजता है और उसके नीचे की निर्दिष्ट पंक्ति से मान लौटाता है?","optionsHi":["MATCH","VLOOKUP","HLOOKUP","CONCAT"],"explanationHi":"HLOOKUP पहली पंक्ति में (क्षैतिज रूप से) खोजता है। VLOOKUP पहले कॉलम में नीचे की ओर खोजता है; MATCH केवल स्थिति लौटाता है।"},
  {"id":"comp-ms-office-internet-17","question":"An IPv6 address is how many bits long?","options":["256","64","128","32"],"answer":2,"explanation":"IPv6 addresses are 128 bits, written as eight groups of four hexadecimal digits. IPv4 addresses are 32 bits.","difficulty":"hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"IPv6 पता कितने बिट लंबा होता है?","optionsHi":["256","64","128","32"],"explanationHi":"IPv6 पते 128 बिट के होते हैं और चार-चार हेक्साडेसिमल अंकों के आठ समूहों के रूप में लिखे जाते हैं। IPv4 पते 32 बिट के होते हैं।"},
  {"id":"comp-ms-office-internet-18","question":"Which type of malware copies itself from computer to computer over a network without attaching to a host file and without user action?","options":["Adware","Worm","Trojan horse","Virus"],"answer":1,"explanation":"A worm is self-replicating and standalone. A virus needs a host file and usually needs that file to be run; a Trojan does not replicate.","difficulty":"hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"किस प्रकार का मैलवेयर किसी होस्ट फ़ाइल से जुड़े बिना और उपयोगकर्ता की किसी क्रिया के बिना नेटवर्क पर एक कंप्यूटर से दूसरे कंप्यूटर में अपनी प्रतिलिपि बना लेता है?","optionsHi":["एडवेयर (Adware)","वर्म (Worm)","ट्रोजन हॉर्स (Trojan horse)","वायरस (Virus)"],"explanationHi":"वर्म स्व-प्रतिकृतिकारी और स्वतंत्र होता है। वायरस को होस्ट फ़ाइल चाहिए और सामान्यतः उस फ़ाइल के चलने की ज़रूरत होती है; ट्रोजन अपनी प्रतिकृति नहीं बनाता।"},
  {"id":"comp-ms-office-internet-19","question":"Logging in with a password followed by an OTP sent to your registered mobile number is an example of:","options":["Two-factor authentication","Single sign-on","Biometric authentication","CAPTCHA verification"],"answer":0,"explanation":"It combines something you know (password) with something you have (the phone receiving the OTP), which is two-factor authentication.","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"पासवर्ड के बाद आपके पंजीकृत मोबाइल नंबर पर भेजे गए OTP से लॉग इन करना किसका उदाहरण है?","optionsHi":["द्वि-कारक प्रमाणीकरण (Two-factor authentication)","सिंगल साइन-ऑन (Single sign-on)","बायोमेट्रिक प्रमाणीकरण (Biometric authentication)","CAPTCHA सत्यापन"],"explanationHi":"इसमें कुछ ऐसा जो आप जानते हैं (पासवर्ड) और कुछ ऐसा जो आपके पास है (OTP प्राप्त करने वाला फ़ोन) मिलाए जाते हैं, जो द्वि-कारक प्रमाणीकरण है।"},
  {"id":"comp-ms-office-internet-20","question":"In MS Word, pressing F7 opens:","options":["Help","Save As dialog","Thesaurus","Spelling and Grammar check"],"answer":3,"explanation":"F7 runs Spelling and Grammar. Shift + F7 opens the Thesaurus, F12 is Save As and F1 is Help.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"MS Word में F7 दबाने पर क्या खुलता है?","optionsHi":["Help","Save As डायलॉग","Thesaurus","वर्तनी और व्याकरण जाँच (Spelling and Grammar)"],"explanationHi":"F7 वर्तनी और व्याकरण जाँच चलाता है। Shift + F7 Thesaurus खोलता है, F12 Save As और F1 Help है।"},
  {"id":"comp-ms-office-internet-21","question":"In Excel, A1 = 10, A2 is blank, A3 = “Yes”, A4 = 0 and A5 is blank. What does =COUNTA(A1:A5) return?","options":["2","3","5","1"],"answer":1,"explanation":"COUNTA counts non-empty cells: A1, A3 and A4 → 3. COUNT would return 2 because it ignores the text in A3; a zero is still a value.","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"Excel में A1 = 10 है, A2 रिक्त है, A3 = “Yes” है, A4 = 0 है और A5 रिक्त है। =COUNTA(A1:A5) क्या लौटाता है?","optionsHi":["2","3","5","1"],"explanationHi":"COUNTA गैर-रिक्त सेल गिनता है: A1, A3 और A4 → 3। COUNT का मान 2 होता क्योंकि वह A3 के पाठ को अनदेखा करता है; शून्य भी एक मान है।"},
  {"id":"comp-ms-office-internet-22","question":"A small text file that a website stores in your browser to remember your login or preferences is called a:","options":["Cache","Plug-in","Applet","Cookie"],"answer":3,"explanation":"Cookies are small text files stored by websites. The cache stores copies of web pages and images to load them faster.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किसी वेबसाइट द्वारा आपके ब्राउज़र में संग्रहीत वह छोटी टेक्स्ट फ़ाइल, जो आपका लॉगिन या पसंद याद रखती है, क्या कहलाती है?","optionsHi":["कैश (Cache)","प्लग-इन (Plug-in)","एप्लेट (Applet)","कुकी (Cookie)"],"explanationHi":"कुकी वेबसाइटों द्वारा संग्रहीत छोटी टेक्स्ट फ़ाइलें होती हैं। कैश वेब पेजों और चित्रों की प्रतियाँ संग्रहीत करता है ताकि वे तेज़ी से लोड हों।"},
  {"id":"comp-ms-office-internet-23","question":"Which image format uses lossy compression and is the most common choice for photographs?","options":["JPEG","BMP","GIF","PNG"],"answer":0,"explanation":"JPEG discards some detail to shrink file size (lossy). PNG and GIF are lossless (GIF is limited to 256 colours) and BMP is usually uncompressed.","difficulty":"hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"कौन-सा छवि प्रारूप हानिपूर्ण (lossy) संपीड़न का उपयोग करता है और फ़ोटो के लिए सबसे आम विकल्प है?","optionsHi":["JPEG","BMP","GIF","PNG"],"explanationHi":"JPEG फ़ाइल का आकार घटाने के लिए कुछ विवरण छोड़ देता है (हानिपूर्ण)। PNG और GIF हानिरहित (lossless) हैं (GIF 256 रंगों तक सीमित है) और BMP सामान्यतः असंपीड़ित होता है।"},
  {"id":"comp-ms-office-internet-24","question":"A network that covers a city, such as a cable TV network or a city-wide network linking a bank's branches, is a:","options":["PAN","LAN","MAN","WAN"],"answer":2,"explanation":"MAN (Metropolitan Area Network) spans a city. LAN covers a building or campus, PAN a person's devices and WAN countries or continents.","difficulty":"hard","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किसी शहर को कवर करने वाला नेटवर्क, जैसे केबल टीवी नेटवर्क या किसी बैंक की शाखाओं को जोड़ने वाला शहर-व्यापी नेटवर्क, कहलाता है:","optionsHi":["PAN","LAN","MAN","WAN"],"explanationHi":"MAN (Metropolitan Area Network) एक शहर में फैला होता है। LAN किसी इमारत या परिसर को, PAN किसी व्यक्ति के उपकरणों को तथा WAN देशों या महाद्वीपों को कवर करता है।"},
  {"id":"comp-ms-office-internet-25","question":"How many of these MS Word shortcuts are correctly described? I. Ctrl + Home moves the cursor to the beginning of the document. II. Ctrl + Enter inserts a section break. III. Ctrl + K inserts a hyperlink. IV. Ctrl + D duplicates the selected line.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: Ctrl + Enter inserts a page break; section breaks are inserted from the Layout tab. IV is wrong: Ctrl + D in Word opens the Font dialog box.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"इनमें से MS Word के कितने शॉर्टकट सही वर्णित हैं? I. Ctrl + Home कर्सर को दस्तावेज़ की शुरुआत में ले जाता है। II. Ctrl + Enter सेक्शन ब्रेक डालता है। III. Ctrl + K हाइपरलिंक डालता है। IV. Ctrl + D चयनित पंक्ति की प्रतिलिपि बनाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है: Ctrl + Enter पेज ब्रेक डालता है; सेक्शन ब्रेक Layout टैब से डाले जाते हैं। IV गलत है: Word में Ctrl + D Font डायलॉग बॉक्स खोलता है।"},
  {"id":"comp-ms-office-internet-26","question":"Match the malware with its description: 1. Keylogger 2. Rootkit 3. Adware 4. Spyware; a. Hides deep in the operating system to keep privileged access b. Shows unwanted advertisements c. Records every keystroke d. Secretly collects user information and sends it to a third party","options":["1-a, 2-c, 3-b, 4-d","1-c, 2-a, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-d, 2-a, 3-b, 4-c"],"answer":2,"explanation":"Keylogger records keystrokes (c), rootkit hides in the OS with admin-level access (a), adware shows ads (b), spyware gathers information and sends it out (d).","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"मैलवेयर को उसके विवरण से सुमेलित कीजिए: 1. Keylogger 2. Rootkit 3. Adware 4. Spyware; a. विशेषाधिकार प्राप्त पहुँच बनाए रखने के लिए ऑपरेटिंग सिस्टम में गहराई में छिपा रहता है b. अनचाहे विज्ञापन दिखाता है c. हर कीस्ट्रोक रिकॉर्ड करता है d. उपयोगकर्ता की जानकारी चुपचाप एकत्र करके किसी तीसरे पक्ष को भेजता है","optionsHi":["1-a, 2-c, 3-b, 4-d","1-c, 2-a, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-d, 2-a, 3-b, 4-c"],"explanationHi":"Keylogger कीस्ट्रोक रिकॉर्ड करता है (c), rootkit एडमिन-स्तर की पहुँच के साथ OS में छिपता है (a), adware विज्ञापन दिखाता है (b), spyware जानकारी एकत्र करके बाहर भेजता है (d)।"},
  {"id":"comp-ms-office-internet-27","question":"In Excel, A1 = 5, A2 = 10, A3 = 15, A4 contains the text “abc” and A5 is blank. What does =AVERAGE(A1:A5) return?","options":["7.5","6","#VALUE!","10"],"answer":3,"explanation":"AVERAGE ignores text and empty cells in a range: (5 + 10 + 15)/3 = 10. Dividing by 5 cells (6) or 4 cells (7.5) is the trap.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"Excel में A1 = 5, A2 = 10, A3 = 15 है, A4 में पाठ “abc” है और A5 रिक्त है। =AVERAGE(A1:A5) क्या लौटाता है?","optionsHi":["7.5","6","#VALUE!","10"],"explanationHi":"AVERAGE रेंज में पाठ और रिक्त सेलों को अनदेखा करता है: (5 + 10 + 15)/3 = 10। 5 सेलों (6) या 4 सेलों (7.5) से भाग देना ही जाल है।"},
  {"id":"comp-ms-office-internet-28","question":"Every cell from A1 to C4 contains the number 2. What does the formula =SUM(A1:C4)/COUNT(B1:B4) return?","options":["12","6","8","3"],"answer":1,"explanation":"A1:C4 has 3 columns × 4 rows = 12 cells, so SUM = 24. COUNT(B1:B4) = 4. 24 ÷ 4 = 6.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"A1 से C4 तक हर सेल में संख्या 2 है। सूत्र =SUM(A1:C4)/COUNT(B1:B4) क्या लौटाता है?","optionsHi":["12","6","8","3"],"explanationHi":"A1:C4 में 3 कॉलम × 4 पंक्तियाँ = 12 सेल हैं, इसलिए SUM = 24। COUNT(B1:B4) = 4। 24 ÷ 4 = 6।"},
  {"id":"comp-ms-office-internet-29","question":"In Excel, A1 = 60 and B1 = 45. What does =IF(AND(A1>50,B1>50),\"Pass\",\"Fail\") return?","options":["Fail","FALSE","Pass","#VALUE!"],"answer":0,"explanation":"AND needs both conditions true; B1 > 50 is false, so AND returns FALSE and IF gives “Fail”. With OR instead of AND, the result would be “Pass”.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"Excel में A1 = 60 और B1 = 45 है। =IF(AND(A1>50,B1>50),\"Pass\",\"Fail\") क्या लौटाता है?","optionsHi":["Fail","FALSE","Pass","#VALUE!"],"explanationHi":"AND के लिए दोनों शर्तें सत्य होनी चाहिए; B1 > 50 असत्य है, इसलिए AND का मान FALSE आता है और IF “Fail” देता है। AND की जगह OR होता तो परिणाम “Pass” होता।"},
  {"id":"comp-ms-office-internet-30","question":"Arrange in chronological order: 1. First message sent over ARPANET 2. Tim Berners-Lee proposes the World Wide Web at CERN 3. ARPANET switches to TCP/IP 4. VSNL launches public internet service in India","options":["1, 2, 3, 4","1, 3, 4, 2","3, 1, 2, 4","1, 3, 2, 4"],"answer":3,"explanation":"ARPANET's first message (1969), ARPANET adopts TCP/IP (1 January 1983), WWW proposal (1989), VSNL public internet in India (15 August 1995). Order: 1, 3, 2, 4.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"कालक्रमानुसार व्यवस्थित कीजिए: 1. ARPANET पर भेजा गया पहला संदेश 2. Tim Berners-Lee द्वारा CERN में World Wide Web का प्रस्ताव 3. ARPANET का TCP/IP पर स्विच करना 4. भारत में VSNL द्वारा सार्वजनिक इंटरनेट सेवा की शुरुआत","optionsHi":["1, 2, 3, 4","1, 3, 4, 2","3, 1, 2, 4","1, 3, 2, 4"],"explanationHi":"ARPANET का पहला संदेश (1969), ARPANET द्वारा TCP/IP अपनाना (1 January 1983), WWW का प्रस्ताव (1989), भारत में VSNL की सार्वजनिक इंटरनेट सेवा (15 August 1995)। क्रम: 1, 3, 2, 4।"},
  {"id":"comp-ms-office-internet-31","question":"How many of these statements are correct? I. Phishing through SMS messages is called smishing. II. Vishing uses voice calls to trick victims. III. A DDoS attack floods a server with traffic from many compromised machines. IV. Pharming means tricking a person into revealing an OTP over a phone call.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: pharming redirects users to a fake website even when they type the correct address, often through DNS poisoning; the phone-call trick is vishing.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. SMS संदेशों के माध्यम से फ़िशिंग को स्मिशिंग (smishing) कहते हैं। II. विशिंग (vishing) में पीड़ितों को ठगने के लिए वॉयस कॉल का उपयोग किया जाता है। III. DDoS हमला कई संक्रमित मशीनों से ट्रैफ़िक भेजकर सर्वर को ठप कर देता है। IV. फ़ार्मिंग (pharming) का अर्थ है फ़ोन कॉल पर किसी व्यक्ति से OTP बताने के लिए छल करना।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: फ़ार्मिंग उपयोगकर्ताओं को सही पता टाइप करने पर भी नकली वेबसाइट पर भेज देती है, अक्सर DNS पॉइज़निंग के ज़रिए; फ़ोन कॉल वाली चाल विशिंग है।"},
  {"id":"comp-ms-office-internet-32","question":"Assertion (A): HTTPS is safer than HTTP for internet banking. Reason (R): HTTPS uses port 80 by default.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true because HTTPS encrypts traffic with TLS. R is false: HTTPS uses port 443; port 80 is plain HTTP.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"अभिकथन (A): इंटरनेट बैंकिंग के लिए HTTPS, HTTP से अधिक सुरक्षित है। कारण (R): HTTPS डिफ़ॉल्ट रूप से पोर्ट 80 का उपयोग करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"A सत्य है क्योंकि HTTPS ट्रैफ़िक को TLS से एन्क्रिप्ट करता है। R असत्य है: HTTPS पोर्ट 443 का उपयोग करता है; पोर्ट 80 सादे HTTP का है।"},
  {"id":"comp-ms-office-internet-33","question":"How many of these are valid IPv4 addresses? 192.168.0.255, 256.10.1.1, 10.10.10, 172.31.0.1","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"An IPv4 address has four octets, each from 0 to 255. 192.168.0.255 and 172.31.0.1 are valid; 256.10.1.1 has an octet above 255 and 10.10.10 has only three octets. So only two.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"इनमें से कितने वैध IPv4 पते हैं? 192.168.0.255, 256.10.1.1, 10.10.10, 172.31.0.1","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"IPv4 पते में चार ऑक्टेट होते हैं, प्रत्येक 0 से 255 तक। 192.168.0.255 और 172.31.0.1 वैध हैं; 256.10.1.1 में एक ऑक्टेट 255 से अधिक है और 10.10.10 में केवल तीन ऑक्टेट हैं। अतः केवल दो।"},
  {"id":"comp-ms-office-internet-34","question":"Match the file extension with what it stores: 1. .pptx 2. .accdb 3. .xlsm 4. .dotx; a. Access database b. Macro-enabled Excel workbook c. Word template d. PowerPoint presentation","options":["1-d, 2-a, 3-c, 4-b","1-d, 2-b, 3-a, 4-c","1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c"],"answer":2,"explanation":".pptx is a PowerPoint presentation, .accdb an Access database, .xlsm an Excel workbook with macros enabled and .dotx a Word template.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"फ़ाइल एक्सटेंशन को उसमें संग्रहीत सामग्री से सुमेलित कीजिए: 1. .pptx 2. .accdb 3. .xlsm 4. .dotx; a. Access डेटाबेस b. मैक्रो-सक्षम Excel वर्कबुक c. Word टेम्पलेट d. PowerPoint प्रस्तुति","optionsHi":["1-d, 2-a, 3-c, 4-b","1-d, 2-b, 3-a, 4-c","1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c"],"explanationHi":".pptx PowerPoint प्रस्तुति है, .accdb Access डेटाबेस है, .xlsm मैक्रो सक्षम वाली Excel वर्कबुक है और .dotx Word टेम्पलेट है।"},
  {"id":"comp-ms-office-internet-35","question":"In Excel, A1 = 25 and B1 is empty. What does =A1/B1 return?","options":["#DIV/0!","25","0","#VALUE!"],"answer":0,"explanation":"An empty cell is treated as 0 in arithmetic, so the formula divides by zero and returns #DIV/0!. #VALUE! appears when a wrong data type, such as text, is used.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"Excel में A1 = 25 है और B1 रिक्त है। =A1/B1 क्या लौटाता है?","optionsHi":["#DIV/0!","25","0","#VALUE!"],"explanationHi":"गणना में रिक्त सेल को 0 माना जाता है, इसलिए सूत्र शून्य से भाग देता है और #DIV/0! लौटाता है। #VALUE! तब आता है जब गलत डेटा प्रकार, जैसे पाठ, का उपयोग किया जाए।"},
  {"id":"comp-ms-office-internet-36","question":"A broadband connection has a speed of 100 Mbps. What is the maximum amount of data it can transfer per second, in megabytes?","options":["800 MB","12.5 MB","10 MB","100 MB"],"answer":1,"explanation":"Mbps is megabits per second and 1 byte = 8 bits, so 100 ÷ 8 = 12.5 megabytes per second.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"एक ब्रॉडबैंड कनेक्शन की गति 100 Mbps है। यह प्रति सेकंड अधिकतम कितना डेटा, मेगाबाइट में, स्थानांतरित कर सकता है?","optionsHi":["800 MB","12.5 MB","10 MB","100 MB"],"explanationHi":"Mbps का अर्थ मेगाबिट प्रति सेकंड है और 1 बाइट = 8 बिट, इसलिए 100 ÷ 8 = 12.5 मेगाबाइट प्रति सेकंड।"},
  {"id":"comp-ms-office-internet-37","question":"How many of these statements about e-mail are correct? I. Recipients in the CC field are visible to all recipients. II. Recipients in the BCC field are hidden from the other recipients. III. SMTP is the protocol a mail client uses to download messages from the server. IV. POP3 uses port 110 by default.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: SMTP sends mail; POP3 or IMAP is used to retrieve it.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"ई-मेल के बारे में इनमें से कितने कथन सही हैं? I. CC फ़ील्ड के प्राप्तकर्ता सभी प्राप्तकर्ताओं को दिखाई देते हैं। II. BCC फ़ील्ड के प्राप्तकर्ता अन्य प्राप्तकर्ताओं से छिपे रहते हैं। III. SMTP वह प्रोटोकॉल है जिससे मेल क्लाइंट सर्वर से संदेश डाउनलोड करता है। IV. POP3 डिफ़ॉल्ट रूप से पोर्ट 110 का उपयोग करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। III गलत है: SMTP मेल भेजता है; उसे प्राप्त करने के लिए POP3 या IMAP का उपयोग होता है।"},
  {"id":"comp-ms-office-internet-38","question":"In which case did the Supreme Court strike down Section 66A of the Information Technology Act, 2000 in 2015?","options":["Shreya Singhal v. Union of India","Anuradha Bhasin v. Union of India","Justice K.S. Puttaswamy v. Union of India","Vishaka v. State of Rajasthan"],"answer":0,"explanation":"Shreya Singhal (2015) struck down Section 66A, which punished “offensive” online messages, as violating free speech. Puttaswamy (2017) declared privacy a fundamental right; Anuradha Bhasin (2020) dealt with internet shutdowns.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"2015 में सर्वोच्च न्यायालय ने किस मामले में सूचना प्रौद्योगिकी अधिनियम, 2000 की धारा 66A को रद्द किया?","optionsHi":["श्रेया सिंघल बनाम भारत संघ","अनुराधा भसीन बनाम भारत संघ","न्यायमूर्ति के.एस. पुट्टस्वामी बनाम भारत संघ","विशाखा बनाम राजस्थान राज्य"],"explanationHi":"श्रेया सिंघल (2015) मामले में धारा 66A को रद्द किया गया, जो “आपत्तिजनक” ऑनलाइन संदेशों को दंडित करती थी, क्योंकि यह वाक्-स्वतंत्रता का उल्लंघन थी। पुट्टस्वामी (2017) में निजता को मौलिक अधिकार घोषित किया गया; अनुराधा भसीन (2020) इंटरनेट बंद किए जाने से संबंधित था।"},
  {"id":"comp-ms-office-internet-39","question":"Assertion (A): A computer virus usually cannot spread until an infected file or program is executed. Reason (R): A virus attaches its code to a host program or file.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true. Because a virus lives inside a host program, its code runs, and copies itself, only when that host is run, so R explains A. This is what separates it from a worm.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk · SSC CGL","questionHi":"अभिकथन (A): कंप्यूटर वायरस सामान्यतः तब तक नहीं फैल सकता जब तक कोई संक्रमित फ़ाइल या प्रोग्राम चलाया न जाए। कारण (R): वायरस अपना कोड किसी होस्ट प्रोग्राम या फ़ाइल से जोड़ देता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"दोनों सत्य हैं। चूँकि वायरस किसी होस्ट प्रोग्राम के भीतर रहता है, उसका कोड तभी चलता है और अपनी प्रतिलिपि बनाता है जब वह होस्ट चलाया जाए, इसलिए R, A की व्याख्या करता है। यही उसे वर्म से अलग करता है।"},
  {"id":"comp-ms-office-internet-40","question":"How many of these statements are correct? I. CERT-In works under the Ministry of Electronics and Information Technology. II. The IT Act, 2000 gave legal recognition to electronic records and digital signatures. III. 1930 is the national cyber-crime helpline number. IV. The Digital Personal Data Protection Act was passed in 2023.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: CERT-In is under MeitY, the IT Act 2000 recognises e-records and digital signatures, 1930 is the cyber-fraud helpline and the DPDP Act was enacted in August 2023.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. CERT-In इलेक्ट्रॉनिकी और सूचना प्रौद्योगिकी मंत्रालय के अधीन कार्य करता है। II. IT अधिनियम, 2000 ने इलेक्ट्रॉनिक अभिलेखों और डिजिटल हस्ताक्षरों को कानूनी मान्यता दी। III. 1930 राष्ट्रीय साइबर अपराध हेल्पलाइन नंबर है। IV. डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम 2023 में पारित हुआ था।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: CERT-In MeitY के अधीन है, IT अधिनियम 2000 ई-अभिलेखों और डिजिटल हस्ताक्षरों को मान्यता देता है, 1930 साइबर धोखाधड़ी हेल्पलाइन है और DPDP अधिनियम अगस्त 2023 में अधिनियमित हुआ।"},
  {"id":"comp-ms-office-internet-41","question":"In MS Word, which shortcut inserts a manual page break at the cursor position?","options":["Ctrl + Enter","Shift + Enter","Alt + Enter","Ctrl + Shift + Enter"],"answer":0,"explanation":"Ctrl + Enter starts a new page. Shift + Enter inserts only a line break within the same paragraph, and Ctrl + Shift + Enter inserts a column break.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में कौन-सा शॉर्टकट कर्सर की स्थिति पर मैन्युअल पेज ब्रेक डालता है?","optionsHi":["Ctrl + Enter","Shift + Enter","Alt + Enter","Ctrl + Shift + Enter"],"explanationHi":"Ctrl + Enter नया पेज शुरू करता है। Shift + Enter उसी अनुच्छेद में केवल लाइन ब्रेक डालता है, और Ctrl + Shift + Enter कॉलम ब्रेक डालता है।"},
  {"id":"comp-ms-office-internet-42","question":"In MS PowerPoint, which shortcut adds a new slide to the presentation?","options":["Ctrl + D","Ctrl + N","Ctrl + S","Ctrl + M"],"answer":3,"explanation":"Ctrl + M inserts a new slide. Ctrl + N opens a new presentation, Ctrl + S saves and Ctrl + D duplicates the selected slide or object.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS PowerPoint में कौन-सा शॉर्टकट प्रस्तुति में नई स्लाइड जोड़ता है?","optionsHi":["Ctrl + D","Ctrl + N","Ctrl + S","Ctrl + M"],"explanationHi":"Ctrl + M नई स्लाइड डालता है। Ctrl + N नई प्रस्तुति खोलता है, Ctrl + S सेव करता है और Ctrl + D चयनित स्लाइड या ऑब्जेक्ट की प्रतिलिपि बनाता है।"},
  {"id":"comp-ms-office-internet-43","question":"In MS Excel, which function key lets you edit the contents of the active cell directly?","options":["F7","F4","F2","F12"],"answer":2,"explanation":"F2 puts the active cell into edit mode. F4 repeats the last action or toggles references, F7 runs spell-check and F12 opens Save As.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Excel में कौन-सी फ़ंक्शन कुंजी सक्रिय सेल की सामग्री को सीधे संपादित करने देती है?","optionsHi":["F7","F4","F2","F12"],"explanationHi":"F2 सक्रिय सेल को संपादन मोड में ले जाती है। F4 अंतिम क्रिया को दोहराती है या संदर्भ बदलती है, F7 स्पेल-चेक चलाती है और F12 Save As खोलती है।"},
  {"id":"comp-ms-office-internet-44","question":"In a web address such as https://www.example.gov.in, the part '.in' is the:","options":["Protocol","Country-code top-level domain","Sub-domain","File path"],"answer":1,"explanation":".in is India's country-code top-level domain (ccTLD). 'https' is the protocol and 'www' is a sub-domain; there is no path in this address.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"https://www.example.gov.in जैसे वेब पते में '.in' भाग क्या है?","optionsHi":["प्रोटोकॉल","देश-कोड शीर्ष-स्तरीय डोमेन","सब-डोमेन","फ़ाइल पथ"],"explanationHi":".in भारत का देश-कोड शीर्ष-स्तरीय डोमेन (ccTLD) है। 'https' प्रोटोकॉल है और 'www' सब-डोमेन है; इस पते में कोई पथ नहीं है।"},
  {"id":"comp-ms-office-internet-45","question":"The HTTP status code shown when the requested web page does not exist on the server is:","options":["500","200","301","404"],"answer":3,"explanation":"404 means Not Found. 200 means OK (success), 301 means the page has moved permanently, and 500 is an internal server error.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"जब अनुरोध किया गया वेब पेज सर्वर पर मौजूद नहीं होता, तब दिखने वाला HTTP स्टेटस कोड क्या है?","optionsHi":["500","200","301","404"],"explanationHi":"404 का अर्थ है Not Found (नहीं मिला)। 200 का अर्थ OK (सफलता) है, 301 का अर्थ है कि पेज स्थायी रूप से स्थानांतरित हो गया है, और 500 आंतरिक सर्वर त्रुटि है।"},
  {"id":"comp-ms-office-internet-46","question":"Which view in MS PowerPoint shows thumbnails of all slides together so that they can be rearranged easily?","options":["Slide Sorter view","Notes Page view","Reading view","Outline view"],"answer":0,"explanation":"Slide Sorter displays every slide as a thumbnail for reordering, deleting or duplicating. Notes Page shows one slide with its speaker notes; Reading view plays the show in a window.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS PowerPoint का कौन-सा व्यू सभी स्लाइडों के थंबनेल एक साथ दिखाता है ताकि उन्हें आसानी से पुनर्व्यवस्थित किया जा सके?","optionsHi":["Slide Sorter व्यू","Notes Page व्यू","Reading व्यू","Outline व्यू"],"explanationHi":"Slide Sorter हर स्लाइड को थंबनेल के रूप में दिखाता है ताकि उन्हें दोबारा क्रमबद्ध, हटाया या डुप्लिकेट किया जा सके। Notes Page एक स्लाइड को उसके स्पीकर नोट्स के साथ दिखाता है; Reading व्यू शो को विंडो में चलाता है।"},
  {"id":"comp-ms-office-internet-47","question":"Which of the following is an example of 'something you are' in authentication?","options":["OTP received on mobile","Password","Fingerprint scan","Smart card"],"answer":2,"explanation":"Biometrics like fingerprints are inherence factors ('something you are'). A password is something you know; an OTP device and a smart card are something you have.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"प्रमाणीकरण में निम्नलिखित में से कौन 'आप जो हैं' (something you are) का उदाहरण है?","optionsHi":["मोबाइल पर प्राप्त OTP","पासवर्ड","फ़िंगरप्रिंट स्कैन","स्मार्ट कार्ड"],"explanationHi":"फ़िंगरप्रिंट जैसे बायोमेट्रिक्स अंतर्निहित (inherence) कारक हैं ('आप जो हैं')। पासवर्ड वह है जो आप जानते हैं; OTP डिवाइस और स्मार्ट कार्ड वह हैं जो आपके पास होते हैं।"},
  {"id":"comp-ms-office-internet-48","question":"In MS Excel, which shortcut inserts the current date in the active cell?","options":["Ctrl + Shift + ;","Ctrl + ;","Ctrl + D","Alt + ;"],"answer":1,"explanation":"Ctrl + ; enters today's date as a fixed value. Ctrl + Shift + ; enters the current time, and Ctrl + D fills down.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Excel में कौन-सा शॉर्टकट सक्रिय सेल में वर्तमान तारीख़ डालता है?","optionsHi":["Ctrl + Shift + ;","Ctrl + ;","Ctrl + D","Alt + ;"],"explanationHi":"Ctrl + ; आज की तारीख़ को एक स्थिर मान के रूप में डालता है। Ctrl + Shift + ; वर्तमान समय डालता है, और Ctrl + D नीचे की ओर भरता है।"},
  {"id":"comp-ms-office-internet-49","question":"Which national helpline number can a victim of online financial fraud in India dial to report it?","options":["100","1930","1098","112"],"answer":1,"explanation":"1930 is the national cyber crime helpline for reporting financial cyber fraud (complaints can also be lodged on cybercrime.gov.in). 1098 is Childline and 112 is the general emergency number.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"भारत में ऑनलाइन वित्तीय धोखाधड़ी का शिकार व्यक्ति इसकी रिपोर्ट करने के लिए कौन-सा राष्ट्रीय हेल्पलाइन नंबर डायल कर सकता है?","optionsHi":["100","1930","1098","112"],"explanationHi":"1930 वित्तीय साइबर धोखाधड़ी की रिपोर्ट करने के लिए राष्ट्रीय साइबर अपराध हेल्पलाइन है (शिकायतें cybercrime.gov.in पर भी दर्ज की जा सकती हैं)। 1098 चाइल्डलाइन है और 112 सामान्य आपातकालीन नंबर है।"},
  {"id":"comp-ms-office-internet-50","question":"Which feature of MS Word combines a standard letter with a list of names and addresses to create personalised copies?","options":["Thesaurus","Track Changes","Macro","Mail Merge"],"answer":3,"explanation":"Mail Merge joins a main document with a data source (such as an Excel list). Track Changes records edits, and a macro automates repeated tasks.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word की कौन-सी सुविधा एक मानक पत्र को नामों और पतों की सूची के साथ मिलाकर वैयक्तिकृत प्रतियाँ बनाती है?","optionsHi":["Thesaurus","Track Changes","Macro","Mail Merge"],"explanationHi":"Mail Merge मुख्य दस्तावेज़ को डेटा स्रोत (जैसे Excel सूची) से जोड़ता है। Track Changes संपादनों को दर्ज करता है, और macro दोहराए जाने वाले कार्यों को स्वचालित करता है।"},
  {"id":"comp-ms-office-internet-51","question":"The protocol whose default port number is 22 and which provides secure remote login is:","options":["SSH","Telnet","FTP","SMTP"],"answer":0,"explanation":"SSH runs on port 22 and encrypts the session. Telnet (port 23) does a similar job but sends everything, including passwords, in plain text.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"वह प्रोटोकॉल कौन-सा है जिसका डिफ़ॉल्ट पोर्ट नंबर 22 है और जो सुरक्षित रिमोट लॉगिन प्रदान करता है?","optionsHi":["SSH","Telnet","FTP","SMTP"],"explanationHi":"SSH पोर्ट 22 पर चलता है और सत्र को एन्क्रिप्ट करता है। Telnet (पोर्ट 23) भी ऐसा ही कार्य करता है, किंतु पासवर्ड सहित सब कुछ सादे पाठ में भेजता है।"},
  {"id":"comp-ms-office-internet-52","question":"In MS Word, what does the shortcut Shift + F3 do to selected text?","options":["Applies strikethrough","Opens the Find dialog","Changes its case, cycling through lowercase, UPPERCASE and Capitalise Each Word","Opens the thesaurus"],"answer":2,"explanation":"Shift + F3 cycles the case of the selection. Shift + F7 opens the thesaurus and Ctrl + F opens Find.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में, चयनित टेक्स्ट पर शॉर्टकट Shift + F3 क्या करता है?","optionsHi":["स्ट्राइकथ्रू लागू करता है","Find डायलॉग खोलता है","उसका केस बदलता है, जो lowercase, UPPERCASE और Capitalise Each Word के बीच चक्रीय रूप से बदलता है","Thesaurus खोलता है"],"explanationHi":"Shift + F3 चयन के केस को चक्रीय रूप से बदलता है। Shift + F7 Thesaurus खोलता है और Ctrl + F Find खोलता है।"},
  {"id":"comp-ms-office-internet-53","question":"In MS Word, which shortcut makes the selected text subscript (as in H₂O)?","options":["Ctrl + Shift + S","Ctrl + Shift + =","Ctrl + ]","Ctrl + ="],"answer":3,"explanation":"Ctrl + = toggles subscript; Ctrl + Shift + = (that is, Ctrl + +) toggles superscript. Ctrl + ] increases the font size by one point.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में कौन-सा शॉर्टकट चयनित टेक्स्ट को अधोलेख (subscript) बनाता है (जैसे H₂O में)?","optionsHi":["Ctrl + Shift + S","Ctrl + Shift + =","Ctrl + ]","Ctrl + ="],"explanationHi":"Ctrl + = अधोलेख को चालू/बंद करता है; Ctrl + Shift + = (अर्थात Ctrl + +) उर्ध्वलेख (superscript) को चालू/बंद करता है। Ctrl + ] फ़ॉन्ट आकार को एक पॉइंट बढ़ाता है।"},
  {"id":"comp-ms-office-internet-54","question":"In MS Word, which shortcut sets 1.5 line spacing for the selected paragraph?","options":["Ctrl + 5","Ctrl + 1","Ctrl + 2","Ctrl + 3"],"answer":0,"explanation":"Ctrl + 1 gives single spacing, Ctrl + 2 double spacing and Ctrl + 5 gives 1.5 line spacing. Ctrl + 3 is not a line-spacing shortcut.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में कौन-सा शॉर्टकट चयनित अनुच्छेद के लिए 1.5 पंक्ति अंतराल सेट करता है?","optionsHi":["Ctrl + 5","Ctrl + 1","Ctrl + 2","Ctrl + 3"],"explanationHi":"Ctrl + 1 एकल अंतराल देता है, Ctrl + 2 दोहरा अंतराल और Ctrl + 5 1.5 पंक्ति अंतराल देता है। Ctrl + 3 पंक्ति-अंतराल का शॉर्टकट नहीं है।"},
  {"id":"comp-ms-office-internet-55","question":"During a PowerPoint slide show, pressing the 'B' key:","options":["Bolds the text on the current slide","Jumps back to the first slide","Turns the screen black; pressing it again returns to the show","Ends the slide show"],"answer":2,"explanation":"B (or the full stop key) blacks out the screen and W (or comma) whitens it; pressing the key again resumes. Esc ends the show; Home goes to the first slide.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"PowerPoint स्लाइड शो के दौरान 'B' कुंजी दबाने पर:","optionsHi":["वर्तमान स्लाइड का टेक्स्ट बोल्ड हो जाता है","पहली स्लाइड पर वापस पहुँच जाता है","स्क्रीन काली हो जाती है; दोबारा दबाने पर शो पर लौट आता है","स्लाइड शो समाप्त हो जाता है"],"explanationHi":"B (या फ़ुल स्टॉप कुंजी) स्क्रीन को काला कर देती है और W (या कॉमा) उसे सफ़ेद कर देती है; वही कुंजी दोबारा दबाने पर शो फिर चलता है। Esc शो को समाप्त करता है; Home पहली स्लाइड पर ले जाता है।"},
  {"id":"comp-ms-office-internet-56","question":"In MS PowerPoint, which shortcut starts the slide show from the CURRENT slide rather than from the first?","options":["F5","Shift + F5","Ctrl + F5","Alt + F5"],"answer":1,"explanation":"Shift + F5 starts from the selected slide; F5 always starts from slide 1.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS PowerPoint में कौन-सा शॉर्टकट स्लाइड शो को पहली स्लाइड से नहीं, बल्कि वर्तमान स्लाइड से शुरू करता है?","optionsHi":["F5","Shift + F5","Ctrl + F5","Alt + F5"],"explanationHi":"Shift + F5 चयनित स्लाइड से शुरू करता है; F5 हमेशा स्लाइड 1 से शुरू करता है।"},
  {"id":"comp-ms-office-internet-57","question":"In MS Excel, which shortcut turns AutoFilter on or off for the selected data range?","options":["Ctrl + Shift + L","Ctrl + Shift + F","Alt + F","Ctrl + L"],"answer":0,"explanation":"Ctrl + Shift + L toggles the filter dropdowns. Ctrl + L (like Ctrl + T) creates a table, which also adds filters, but it does not toggle them off.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Excel में कौन-सा शॉर्टकट चयनित डेटा रेंज के लिए AutoFilter को चालू या बंद करता है?","optionsHi":["Ctrl + Shift + L","Ctrl + Shift + F","Alt + F","Ctrl + L"],"explanationHi":"Ctrl + Shift + L फ़िल्टर ड्रॉपडाउन को चालू/बंद करता है। Ctrl + L (Ctrl + T की तरह) तालिका बनाता है, जिससे फ़िल्टर भी जुड़ जाते हैं, लेकिन यह उन्हें बंद नहीं करता।"},
  {"id":"comp-ms-office-internet-58","question":"In MS Excel, pressing Alt + = in the cell below a column of numbers:","options":["Opens the Insert Function dialog","Inserts the AutoSum (SUM) formula for the numbers above","Shows all formulas instead of values","Copies the formula from the cell above"],"answer":1,"explanation":"Alt + = inserts =SUM() over the adjacent range. Shift + F3 opens Insert Function, Ctrl + ` shows formulas, and Ctrl + D copies the cell above.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Excel में, संख्याओं के कॉलम के ठीक नीचे वाले सेल में Alt + = दबाने पर:","optionsHi":["Insert Function डायलॉग खुलता है","ऊपर की संख्याओं के लिए AutoSum (SUM) सूत्र डल जाता है","मानों के बजाय सभी सूत्र दिखने लगते हैं","ऊपर वाले सेल का सूत्र कॉपी हो जाता है"],"explanationHi":"Alt + = निकटवर्ती रेंज पर =SUM() डालता है। Shift + F3 Insert Function खोलता है, Ctrl + ` सूत्र दिखाता है, और Ctrl + D ऊपर के सेल की प्रतिलिपि बनाता है।"},
  {"id":"comp-ms-office-internet-59","question":"In MS Excel, which shortcut opens the Format Cells dialog box?","options":["Ctrl + Shift + F1","Ctrl + F","Ctrl + 1","Alt + 1"],"answer":2,"explanation":"Ctrl + 1 opens Format Cells (number, alignment, font, border, fill, protection). Ctrl + F opens Find.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Excel में कौन-सा शॉर्टकट Format Cells डायलॉग बॉक्स खोलता है?","optionsHi":["Ctrl + Shift + F1","Ctrl + F","Ctrl + 1","Alt + 1"],"explanationHi":"Ctrl + 1 Format Cells खोलता है (संख्या, संरेखण, फ़ॉन्ट, बॉर्डर, फ़िल, सुरक्षा)। Ctrl + F Find खोलता है।"},
  {"id":"comp-ms-office-internet-60","question":"In MS Excel, how do you start a new line of text inside the same cell?","options":["Tab","Shift + Enter","Ctrl + Enter","Alt + Enter"],"answer":3,"explanation":"Alt + Enter inserts a line break within a cell. Shift + Enter moves to the cell above, and Ctrl + Enter enters the same data in all selected cells.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Excel में एक ही सेल के भीतर पाठ की नई पंक्ति कैसे शुरू करते हैं?","optionsHi":["Tab","Shift + Enter","Ctrl + Enter","Alt + Enter"],"explanationHi":"Alt + Enter सेल के भीतर लाइन ब्रेक डालता है। Shift + Enter ऊपर वाले सेल पर जाता है, और Ctrl + Enter सभी चयनित सेलों में वही डेटा भरता है।"},
  {"id":"comp-ms-office-internet-61","question":"What does the Excel formula =ROUND(1234.567, -2) return?","options":["1200","1234.57","1234.6","1300"],"answer":0,"explanation":"A negative second argument rounds to the left of the decimal point: -2 rounds to the nearest hundred, giving 1200. 1234.57 would need 2 as the argument.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =ROUND(1234.567, -2) क्या लौटाता है?","optionsHi":["1200","1234.57","1234.6","1300"],"explanationHi":"ऋणात्मक दूसरा तर्क (argument) दशमलव बिंदु के बाईं ओर पूर्णांकित करता है: -2 निकटतम सैकड़े तक पूर्णांकित करता है, जिससे 1200 मिलता है। 1234.57 के लिए तर्क 2 होना चाहिए।"},
  {"id":"comp-ms-office-internet-62","question":"What does the Excel formula =MID(\"COMPUTER\", 3, 4) return?","options":["OMPU","MPUT","MPUTE","PUTE"],"answer":1,"explanation":"MID takes 4 characters starting at position 3: C(1) O(2) M(3) P(4) U(5) T(6) → MPUT.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =MID(\"COMPUTER\", 3, 4) क्या लौटाता है?","optionsHi":["OMPU","MPUT","MPUTE","PUTE"],"explanationHi":"MID स्थिति 3 से शुरू करके 4 अक्षर लेता है: C(1) O(2) M(3) P(4) U(5) T(6) → MPUT।"},
  {"id":"comp-ms-office-internet-63","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =COUNTIF(A1:A6, \">50\") return?","options":["5","4","2","3"],"answer":3,"explanation":"Values strictly greater than 50 are 60, 75 and 90 → 3. The value 50 itself is not included; that would need \">=50\", which gives 4.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1:A6 में 45, 60, 75, 50, 90 और 30 हैं। =COUNTIF(A1:A6, \">50\") क्या लौटाता है?","optionsHi":["5","4","2","3"],"explanationHi":"50 से सख्ती से बड़े मान 60, 75 और 90 हैं → 3। मान 50 स्वयं शामिल नहीं है; उसके लिए \">=50\" चाहिए, जो 4 देता है।"},
  {"id":"comp-ms-office-internet-64","question":"Which Excel 'What-If Analysis' tool finds the input value needed to make a formula reach a desired result?","options":["Data Validation","Scenario Manager","Goal Seek","Consolidate"],"answer":2,"explanation":"Goal Seek works backwards: you give the target result and the cell to change, and it finds the input. Scenario Manager compares several saved sets of inputs; Data Validation restricts entries.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का कौन-सा 'What-If Analysis' टूल किसी सूत्र को वांछित परिणाम तक पहुँचाने के लिए आवश्यक इनपुट मान खोजता है?","optionsHi":["Data Validation","Scenario Manager","Goal Seek","Consolidate"],"explanationHi":"Goal Seek उल्टी दिशा में काम करता है: आप लक्ष्य परिणाम और बदले जाने वाला सेल देते हैं, और यह इनपुट खोज लेता है। Scenario Manager इनपुट के कई सहेजे गए सेटों की तुलना करता है; Data Validation प्रविष्टियों को सीमित करता है।"},
  {"id":"comp-ms-office-internet-65","question":"The Excel feature that keeps the top row or first column visible while you scroll through a large sheet is:","options":["Freeze Panes","Split Cells","Wrap Text","Group"],"answer":0,"explanation":"View → Freeze Panes locks rows/columns in place. Wrap Text only fits text within a cell, and Group collapses rows or columns.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel की वह सुविधा कौन-सी है जो बड़ी शीट में स्क्रॉल करते समय शीर्ष पंक्ति या पहले कॉलम को दिखाई देता रखती है?","optionsHi":["Freeze Panes","Split Cells","Wrap Text","Group"],"explanationHi":"View → Freeze Panes पंक्तियों/कॉलमों को अपनी जगह लॉक कर देता है। Wrap Text केवल पाठ को सेल के भीतर समाहित करता है, और Group पंक्तियों या कॉलमों को संक्षिप्त करता है।"},
  {"id":"comp-ms-office-internet-66","question":"A PowerPoint file saved with the extension .ppsx:","options":["Contains macros","Is a PowerPoint template","Opens directly as a slide show when double-clicked","Can be opened only in PowerPoint 2003"],"answer":2,"explanation":".ppsx is a PowerPoint Show and opens straight into slide-show mode. A template is .potx, and a macro-enabled presentation is .pptm.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एक्सटेंशन .ppsx के साथ सेव की गई PowerPoint फ़ाइल:","optionsHi":["में मैक्रो होते हैं","PowerPoint टेम्पलेट होती है","डबल-क्लिक करने पर सीधे स्लाइड शो के रूप में खुलती है","केवल PowerPoint 2003 में खोली जा सकती है"],"explanationHi":".ppsx एक PowerPoint Show है और सीधे स्लाइड-शो मोड में खुलती है। टेम्पलेट .potx होता है, और मैक्रो-सक्षम प्रस्तुति .pptm होती है।"},
  {"id":"comp-ms-office-internet-67","question":"In PowerPoint, which feature lets you change the font, colours and logo of ALL slides in one place?","options":["Custom Slide Show","Slide Sorter","Rehearse Timings","Slide Master"],"answer":3,"explanation":"Editing the Slide Master changes every slide based on its layouts. Slide Sorter only reorders slides; Rehearse Timings records how long each slide is shown.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"PowerPoint की कौन-सी सुविधा आपको सभी स्लाइडों का फ़ॉन्ट, रंग और लोगो एक ही जगह से बदलने देती है?","optionsHi":["Custom Slide Show","Slide Sorter","Rehearse Timings","Slide Master"],"explanationHi":"Slide Master को संपादित करने से उसके लेआउट पर आधारित हर स्लाइड बदल जाती है। Slide Sorter केवल स्लाइडों का क्रम बदलता है; Rehearse Timings दर्ज करता है कि प्रत्येक स्लाइड कितनी देर दिखाई जाती है।"},
  {"id":"comp-ms-office-internet-68","question":"Which default port does the POP3 protocol use for downloading e-mail?","options":["143","110","25","993"],"answer":1,"explanation":"POP3 uses port 110. IMAP uses 143, SMTP uses 25 for sending, and 993 is IMAP over SSL/TLS.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"ई-मेल डाउनलोड करने के लिए POP3 प्रोटोकॉल कौन-सा डिफ़ॉल्ट पोर्ट उपयोग करता है?","optionsHi":["143","110","25","993"],"explanationHi":"POP3 पोर्ट 110 का उपयोग करता है। IMAP 143 का उपयोग करता है, SMTP भेजने के लिए 25 का उपयोग करता है, और 993 SSL/TLS पर IMAP है।"},
  {"id":"comp-ms-office-internet-69","question":"An attacker redirects users who type a genuine bank's address to a fake look-alike site by corrupting DNS records. This attack is called:","options":["Spamming","Phishing","Pharming","Spoofing of caller ID"],"answer":2,"explanation":"Pharming poisons DNS or the hosts file so even a correctly typed address leads to the fake site. Phishing relies on luring the victim to click a link, usually in an e-mail.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कोई हमलावर DNS रिकॉर्ड में छेड़छाड़ करके किसी असली बैंक का पता टाइप करने वाले उपयोगकर्ताओं को उसी जैसी दिखने वाली नकली साइट पर भेज देता है। इस हमले को कहते हैं:","optionsHi":["स्पैमिंग (Spamming)","फ़िशिंग (Phishing)","फ़ार्मिंग (Pharming)","कॉलर ID स्पूफ़िंग"],"explanationHi":"फ़ार्मिंग DNS या hosts फ़ाइल को दूषित करती है, जिससे सही टाइप किया गया पता भी नकली साइट पर ले जाता है। फ़िशिंग में पीड़ित को, आमतौर पर ई-मेल में, किसी लिंक पर क्लिक करने के लिए लुभाया जाता है।"},
  {"id":"comp-ms-office-internet-70","question":"A phishing attack aimed specifically at top executives such as a CEO or CFO is known as:","options":["Baiting","Vishing","Smishing","Whaling"],"answer":3,"explanation":"Whaling targets 'big fish' — senior executives. Vishing uses voice calls and smishing uses SMS; baiting leaves infected devices or tempting downloads for victims.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"CEO या CFO जैसे शीर्ष अधिकारियों को विशेष रूप से निशाना बनाने वाला फ़िशिंग हमला क्या कहलाता है?","optionsHi":["बेटिंग (Baiting)","विशिंग (Vishing)","स्मिशिंग (Smishing)","व्हेलिंग (Whaling)"],"explanationHi":"व्हेलिंग 'बड़ी मछलियों' यानी वरिष्ठ अधिकारियों को निशाना बनाती है। विशिंग वॉयस कॉल और स्मिशिंग SMS का उपयोग करती है; बेटिंग में पीड़ितों के लिए संक्रमित उपकरण या लुभावने डाउनलोड छोड़ दिए जाते हैं।"},
  {"id":"comp-ms-office-internet-71","question":"Malicious code planted in a program that stays dormant and activates only when a particular condition is met (such as a specific date) is a:","options":["Logic bomb","Worm","Adware","Botnet"],"answer":0,"explanation":"A logic bomb is triggered by a condition or date. A worm spreads by itself across networks, and a botnet is a network of compromised computers controlled remotely.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"किसी प्रोग्राम में डाला गया ऐसा दुर्भावनापूर्ण कोड जो निष्क्रिय पड़ा रहता है और केवल किसी विशेष शर्त (जैसे निश्चित तारीख़) के पूरी होने पर सक्रिय होता है, क्या कहलाता है?","optionsHi":["लॉजिक बम (Logic bomb)","वर्म (Worm)","एडवेयर (Adware)","बॉटनेट (Botnet)"],"explanationHi":"लॉजिक बम किसी शर्त या तारीख़ से सक्रिय होता है। वर्म नेटवर्क पर अपने आप फैलता है, और बॉटनेट संक्रमित कंप्यूटरों का ऐसा नेटवर्क है जिसे दूर से नियंत्रित किया जाता है।"},
  {"id":"comp-ms-office-internet-72","question":"Under the Information Technology Act, 2000, identity theft — fraudulently using another person's password, electronic signature or other unique identification — is punishable under:","options":["Section 66A","Section 66C","Section 67","Section 43A"],"answer":1,"explanation":"Section 66C deals with identity theft. Section 66A was struck down by the Supreme Court in 2015; Section 67 concerns obscene material, and 43A covers compensation for failure to protect data.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"सूचना प्रौद्योगिकी अधिनियम, 2000 के अंतर्गत पहचान की चोरी, यानी किसी अन्य व्यक्ति के पासवर्ड, इलेक्ट्रॉनिक हस्ताक्षर या अन्य विशिष्ट पहचान का कपटपूर्वक उपयोग करना, किस धारा के अंतर्गत दंडनीय है?","optionsHi":["धारा 66A","धारा 66C","धारा 67","धारा 43A"],"explanationHi":"धारा 66C पहचान की चोरी से संबंधित है। धारा 66A को सर्वोच्च न्यायालय ने 2015 में रद्द कर दिया था; धारा 67 अश्लील सामग्री से संबंधित है, और 43A डेटा की सुरक्षा में विफलता पर मुआवज़े को कवर करती है।"},
  {"id":"comp-ms-office-internet-73","question":"Charging a phone at an infected public USB charging port, which secretly steals data or installs malware, is called:","options":["Shoulder surfing","Juice jacking","Tailgating","Clickjacking"],"answer":1,"explanation":"Juice jacking abuses the data lines of a USB port. Shoulder surfing is watching someone type a PIN, tailgating is following an authorised person through a secure door, and clickjacking tricks users into clicking hidden page elements.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"किसी सार्वजनिक संक्रमित USB चार्जिंग पोर्ट पर फ़ोन चार्ज करना, जो चुपचाप डेटा चुराता है या मैलवेयर इंस्टॉल करता है, क्या कहलाता है?","optionsHi":["शोल्डर सर्फ़िंग (Shoulder surfing)","जूस जैकिंग (Juice jacking)","टेलगेटिंग (Tailgating)","क्लिकजैकिंग (Clickjacking)"],"explanationHi":"जूस जैकिंग USB पोर्ट की डेटा लाइनों का दुरुपयोग करती है। शोल्डर सर्फ़िंग किसी को PIN टाइप करते देखना है, टेलगेटिंग अधिकृत व्यक्ति के पीछे-पीछे सुरक्षित दरवाज़े से घुसना है, और क्लिकजैकिंग उपयोगकर्ताओं को पेज के छिपे तत्वों पर क्लिक करने के लिए छलती है।"},
  {"id":"comp-ms-office-internet-74","question":"What does the Excel formula =-2^2 return?","options":["4","-4","0","#VALUE!"],"answer":0,"explanation":"In Excel, negation has higher precedence than exponentiation, so it is evaluated as (-2)^2 = 4. In ordinary algebra (and in many programming languages) -2² would be -4, which is the trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =-2^2 क्या लौटाता है?","optionsHi":["4","-4","0","#VALUE!"],"explanationHi":"Excel में निषेध (negation) की प्राथमिकता घातांक से अधिक होती है, इसलिए इसका मान (-2)^2 = 4 निकलता है। सामान्य बीजगणित (और कई प्रोग्रामिंग भाषाओं) में -2² का मान -4 होता, यही जाल है।"},
  {"id":"comp-ms-office-internet-75","question":"What does the Excel formula =2^3^2 return?","options":["36","512","12","64"],"answer":3,"explanation":"Excel evaluates operators of equal precedence from left to right: (2^3)^2 = 8^2 = 64. Mathematical convention (right-to-left) would give 2^9 = 512.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =2^3^2 क्या लौटाता है?","optionsHi":["36","512","12","64"],"explanationHi":"Excel समान प्राथमिकता वाले संक्रियकों का मूल्यांकन बाएँ से दाएँ करता है: (2^3)^2 = 8^2 = 64। गणितीय परिपाटी (दाएँ से बाएँ) से 2^9 = 512 मिलता।"},
  {"id":"comp-ms-office-internet-76","question":"What does the Excel formula =MOD(-7, 3) return?","options":["1","-1","2","-2"],"answer":2,"explanation":"Excel's MOD returns a result with the same sign as the divisor: MOD(n, d) = n − d × INT(n/d) = −7 − 3 × (−3) = 2. -1 is what truncating division (as in C or Java's %) gives.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =MOD(-7, 3) क्या लौटाता है?","optionsHi":["1","-1","2","-2"],"explanationHi":"Excel का MOD भाजक के चिह्न वाला परिणाम लौटाता है: MOD(n, d) = n − d × INT(n/d) = −7 − 3 × (−3) = 2। -1 वह है जो छोटा करने वाला भाग (जैसे C या Java के %) देता है।"},
  {"id":"comp-ms-office-internet-77","question":"What does the Excel formula =TRUNC(-4.7) return?","options":["-4.7","-5","-4","4"],"answer":2,"explanation":"TRUNC simply removes the decimal part, giving -4. INT rounds down to the next lower integer, so INT(-4.7) would be -5 — the tempting choice.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =TRUNC(-4.7) क्या लौटाता है?","optionsHi":["-4.7","-5","-4","4"],"explanationHi":"TRUNC केवल दशमलव भाग हटा देता है, जिससे -4 मिलता है। INT अगले छोटे पूर्णांक तक नीचे पूर्णांकित करता है, इसलिए INT(-4.7) का मान -5 होता, जो लुभाने वाला विकल्प है।"},
  {"id":"comp-ms-office-internet-78","question":"What does the Excel formula =ROUNDUP(-3.21, 1) return?","options":["-3.3","-3.2","-3.21","-4"],"answer":0,"explanation":"ROUNDUP always rounds away from zero, so -3.21 becomes -3.3. Rounding 'up' towards the larger value -3.2 is the trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =ROUNDUP(-3.21, 1) क्या लौटाता है?","optionsHi":["-3.3","-3.2","-3.21","-4"],"explanationHi":"ROUNDUP हमेशा शून्य से दूर की ओर पूर्णांकित करता है, इसलिए -3.21 का मान -3.3 हो जाता है। बड़े मान -3.2 की ओर 'ऊपर' पूर्णांकित करना ही जाल है।"},
  {"id":"comp-ms-office-internet-79","question":"What does the Excel formula =LEN(TRIM(\"  Data   Entry  \")) return?","options":["9","16","12","10"],"answer":3,"explanation":"TRIM removes leading and trailing spaces and reduces internal runs of spaces to a single space, leaving \"Data Entry\" — 10 characters including the one space.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =LEN(TRIM(\"  Data   Entry  \")) क्या लौटाता है?","optionsHi":["9","16","12","10"],"explanationHi":"TRIM आगे और पीछे के रिक्त स्थान हटा देता है और बीच के लगातार रिक्त स्थानों को एक रिक्त स्थान में घटा देता है, जिससे \"Data Entry\" बचता है, जो एक रिक्त स्थान सहित 10 अक्षरों का है।"},
  {"id":"comp-ms-office-internet-80","question":"What does the Excel formula =10-2^2*3 return?","options":["24","-2","192","4"],"answer":1,"explanation":"Order: exponent first (2^2 = 4), then multiplication (4 × 3 = 12), then subtraction (10 − 12 = −2). Working left to right without precedence gives 192.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =10-2^2*3 क्या लौटाता है?","optionsHi":["24","-2","192","4"],"explanationHi":"क्रम: पहले घातांक (2^2 = 4), फिर गुणा (4 × 3 = 12), फिर घटाव (10 − 12 = −2)। प्राथमिकता के बिना बाएँ से दाएँ हल करने पर 192 आता है।"},
  {"id":"comp-ms-office-internet-81","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =SUMIF(A1:A6, \">=50\") return?","options":["225","275","320","350"],"answer":1,"explanation":"Values ≥ 50 are 60, 75, 50 and 90; their sum is 275. Excluding 50 (i.e. \">50\") gives 225.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1:A6 में 45, 60, 75, 50, 90 और 30 हैं। =SUMIF(A1:A6, \">=50\") क्या लौटाता है?","optionsHi":["225","275","320","350"],"explanationHi":"≥ 50 वाले मान 60, 75, 50 और 90 हैं; उनका योग 275 है। 50 को छोड़ देने पर (अर्थात \">50\") 225 मिलता है।"},
  {"id":"comp-ms-office-internet-82","question":"In Excel, A1:A6 contain 45, 60, 75, 50, 90 and 30. What does =AVERAGEIF(A1:A6, \">40\") return?","options":["75","58.33","64","53.33"],"answer":2,"explanation":"Values greater than 40: 45, 60, 75, 50, 90 → sum 320 ÷ 5 = 64. 58.33 is the plain average of all six values (350 ÷ 6).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1:A6 में 45, 60, 75, 50, 90 और 30 हैं। =AVERAGEIF(A1:A6, \">40\") क्या लौटाता है?","optionsHi":["75","58.33","64","53.33"],"explanationHi":"40 से बड़े मान: 45, 60, 75, 50, 90 → योग 320 ÷ 5 = 64। 58.33 सभी छह मानों का साधारण औसत है (350 ÷ 6)।"},
  {"id":"comp-ms-office-internet-83","question":"In Excel, A1:A4 contain 0, 40, 60, 80 and B1:B4 contain the grades F, C, B, A. What does =VLOOKUP(73, A1:B4, 2, TRUE) return?","options":["#N/A","A","C","B"],"answer":3,"explanation":"With TRUE (approximate match) VLOOKUP finds the largest value ≤ 73 in the sorted first column, which is 60, and returns its grade B. #N/A would come only with an exact match (FALSE).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1:A4 में 0, 40, 60, 80 हैं और B1:B4 में ग्रेड F, C, B, A हैं। =VLOOKUP(73, A1:B4, 2, TRUE) क्या लौटाता है?","optionsHi":["#N/A","A","C","B"],"explanationHi":"TRUE (सन्निकट मिलान) के साथ VLOOKUP क्रमबद्ध पहले कॉलम में 73 के बराबर या उससे छोटा सबसे बड़ा मान खोजता है, जो 60 है, और उसका ग्रेड B लौटाता है। #N/A केवल सटीक मिलान (FALSE) के साथ आता।"},
  {"id":"comp-ms-office-internet-84","question":"What does the Excel formula =MATCH(25, {10,20,30,40}, 1) return?","options":["2","3","#N/A","25"],"answer":0,"explanation":"Match type 1 returns the position of the largest value less than or equal to 25 in an ascending list — 20, at position 2. MATCH returns a position, not the value.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =MATCH(25, {10,20,30,40}, 1) क्या लौटाता है?","optionsHi":["2","3","#N/A","25"],"explanationHi":"मैच टाइप 1 आरोही सूची में 25 के बराबर या उससे छोटे सबसे बड़े मान की स्थिति लौटाता है, यानी 20, जो स्थिति 2 पर है। MATCH स्थिति लौटाता है, मान नहीं।"},
  {"id":"comp-ms-office-internet-85","question":"What does the Excel formula =LARGE({12,45,7,45,30}, 2) return?","options":["45","30","12","7"],"answer":0,"explanation":"LARGE counts duplicates separately: sorted descending the list is 45, 45, 30, 12, 7, so the 2nd largest is 45. Choosing 30 assumes duplicates are ignored.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =LARGE({12,45,7,45,30}, 2) क्या लौटाता है?","optionsHi":["45","30","12","7"],"explanationHi":"LARGE दोहराए गए मानों को अलग-अलग गिनता है: अवरोही क्रम में सूची 45, 45, 30, 12, 7 है, इसलिए दूसरा सबसे बड़ा मान 45 है। 30 चुनना यह मानना है कि दोहराए गए मान अनदेखे किए जाते हैं।"},
  {"id":"comp-ms-office-internet-86","question":"What does the Excel formula =SUMPRODUCT({2,3,1}, {4,5,6}) return?","options":["120","21","29","15"],"answer":2,"explanation":"SUMPRODUCT multiplies corresponding items and adds: 2×4 + 3×5 + 1×6 = 8 + 15 + 6 = 29. 21 is simply the total of all six numbers.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =SUMPRODUCT({2,3,1}, {4,5,6}) क्या लौटाता है?","optionsHi":["120","21","29","15"],"explanationHi":"SUMPRODUCT संगत पदों को गुणा करके जोड़ता है: 2×4 + 3×5 + 1×6 = 8 + 15 + 6 = 29। 21 सभी छह संख्याओं का केवल कुल योग है।"},
  {"id":"comp-ms-office-internet-87","question":"In Excel, A1 contains the date 01-01-2024 and B1 contains 01-03-2024 (1 March 2024). What does =B1-A1 return?","options":["59","60","2","61"],"answer":1,"explanation":"Excel stores dates as serial numbers, so subtraction gives the days between them: 31 (January) + 29 (February in the leap year 2024) = 60. 59 assumes a 28-day February.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1 में तारीख़ 01-01-2024 है और B1 में 01-03-2024 (1 March 2024) है। =B1-A1 क्या लौटाता है?","optionsHi":["59","60","2","61"],"explanationHi":"Excel तारीख़ों को क्रमांक (serial number) के रूप में संग्रहीत करता है, इसलिए घटाने पर उनके बीच के दिन मिलते हैं: 31 (January) + 29 (अधिवर्ष 2024 में February) = 60। 59 फ़रवरी को 28 दिन का मानता है।"},
  {"id":"comp-ms-office-internet-88","question":"The Excel formula =A1+$B$1 is in cell C1. If it is copied to cell D3, it becomes:","options":["=A3+$B$1","=A1+$B$1","=B3+$C$3","=B3+$B$1"],"answer":3,"explanation":"The relative part shifts one column right and two rows down (A1 → B3); the absolute reference $B$1 does not change.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =A1+$B$1 सेल C1 में है। इसे सेल D3 में कॉपी करने पर यह क्या बन जाएगा?","optionsHi":["=A3+$B$1","=A1+$B$1","=B3+$C$3","=B3+$B$1"],"explanationHi":"सापेक्ष भाग एक कॉलम दाईं ओर और दो पंक्ति नीचे खिसकता है (A1 → B3); निरपेक्ष संदर्भ $B$1 नहीं बदलता।"},
  {"id":"comp-ms-office-internet-89","question":"In Excel, pressing F4 repeatedly while the cursor is on the reference A1 in a formula cycles it through which sequence?","options":["A$1 → $A1 → $A$1 → A1","$A$1 → A$1 → $A1 → A1","$A1 → A$1 → $A$1 → A1","$A$1 → $A1 → A$1 → A1"],"answer":1,"explanation":"F4 first makes the reference fully absolute ($A$1), then locks only the row (A$1), then only the column ($A1), and finally returns to relative (A1).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में, किसी सूत्र में कर्सर संदर्भ A1 पर होने पर F4 बार-बार दबाने से वह किस क्रम में बदलता है?","optionsHi":["A$1 → $A1 → $A$1 → A1","$A$1 → A$1 → $A1 → A1","$A1 → A$1 → $A$1 → A1","$A$1 → $A1 → A$1 → A1"],"explanationHi":"F4 पहले संदर्भ को पूरी तरह निरपेक्ष ($A$1) बनाता है, फिर केवल पंक्ति को लॉक करता है (A$1), फिर केवल कॉलम को ($A1), और अंत में सापेक्ष (A1) पर लौट आता है।"},
  {"id":"comp-ms-office-internet-90","question":"In Excel 2007 and later, how many rows and columns does a worksheet have?","options":["1,048,576 rows and 16,384 columns","65,536 rows and 256 columns","1,048,576 rows and 256 columns","16,384 rows and 1,048,576 columns"],"answer":0,"explanation":"Since Excel 2007 a sheet has 2²⁰ = 1,048,576 rows and 2¹⁴ = 16,384 columns (A to XFD). 65,536 × 256 was the limit in Excel 2003 and earlier.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel 2007 और उसके बाद के संस्करणों में एक वर्कशीट में कितनी पंक्तियाँ और कॉलम होते हैं?","optionsHi":["1,048,576 पंक्तियाँ और 16,384 कॉलम","65,536 पंक्तियाँ और 256 कॉलम","1,048,576 पंक्तियाँ और 256 कॉलम","16,384 पंक्तियाँ और 1,048,576 कॉलम"],"explanationHi":"Excel 2007 से एक शीट में 2²⁰ = 1,048,576 पंक्तियाँ और 2¹⁴ = 16,384 कॉलम (A से XFD) होते हैं। 65,536 × 256 Excel 2003 और उससे पहले की सीमा थी।"},
  {"id":"comp-ms-office-internet-91","question":"Which Excel error value appears when a formula refers to a cell that has been deleted?","options":["#N/A","#NAME?","#REF!","#NULL!"],"answer":2,"explanation":"#REF! signals an invalid cell reference, typically after deleting rows, columns or cells used by a formula. #NAME? means Excel does not recognise a name or function.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"जब कोई सूत्र किसी हटाए गए सेल का संदर्भ देता है, तब Excel का कौन-सा त्रुटि मान दिखता है?","optionsHi":["#N/A","#NAME?","#REF!","#NULL!"],"explanationHi":"#REF! अमान्य सेल संदर्भ का संकेत देता है, जो सामान्यतः सूत्र में प्रयुक्त पंक्तियों, कॉलमों या सेलों को हटाने के बाद आता है। #NAME? का अर्थ है कि Excel किसी नाम या फ़ंक्शन को नहीं पहचानता।"},
  {"id":"comp-ms-office-internet-92","question":"In Excel, typing =SUMM(A1:A5) by mistake produces which error?","options":["#N/A","#VALUE!","#REF!","#NAME?"],"answer":3,"explanation":"Excel does not recognise the function name SUMM, so it shows #NAME?. #VALUE! arises from a wrong type of argument, such as adding text to a number.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में गलती से =SUMM(A1:A5) टाइप करने पर कौन-सी त्रुटि आती है?","optionsHi":["#N/A","#VALUE!","#REF!","#NAME?"],"explanationHi":"Excel फ़ंक्शन नाम SUMM को नहीं पहचानता, इसलिए #NAME? दिखाता है। #VALUE! गलत प्रकार के तर्क से आता है, जैसे किसी संख्या में पाठ जोड़ना।"},
  {"id":"comp-ms-office-internet-93","question":"In Excel, the shortcut Ctrl + ` (grave accent) is used to:","options":["Copy the value from the cell above","Insert the current time","Toggle between showing formulas and showing their results","Open the Visual Basic editor"],"answer":2,"explanation":"Ctrl + ` switches the sheet to formula view and back. Ctrl + Shift + ; inserts the time, Ctrl + ' copies the formula from the cell above, and Alt + F11 opens the VBA editor.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में शॉर्टकट Ctrl + ` (ग्रेव एक्सेंट) का उपयोग किसलिए किया जाता है?","optionsHi":["ऊपर वाले सेल का मान कॉपी करने के लिए","वर्तमान समय डालने के लिए","सूत्र दिखाने और उनके परिणाम दिखाने के बीच बदलने के लिए","Visual Basic एडिटर खोलने के लिए"],"explanationHi":"Ctrl + ` शीट को सूत्र दृश्य में और वापस बदलता है। Ctrl + Shift + ; समय डालता है, Ctrl + ' ऊपर वाले सेल का सूत्र कॉपी करता है, और Alt + F11 VBA एडिटर खोलता है।"},
  {"id":"comp-ms-office-internet-94","question":"In Excel, pressing F11 with data selected:","options":["Recalculates all formulas","Inserts a new worksheet","Creates an embedded chart on the same sheet","Creates a default chart on a new chart sheet"],"answer":3,"explanation":"F11 makes a chart on a separate chart sheet; Alt + F1 makes an embedded chart on the current sheet. Shift + F11 inserts a new worksheet and F9 recalculates.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में डेटा चयनित होने पर F11 दबाने से:","optionsHi":["सभी सूत्र पुनर्गणना हो जाते हैं","नई वर्कशीट डल जाती है","उसी शीट पर एम्बेडेड चार्ट बन जाता है","नई चार्ट शीट पर डिफ़ॉल्ट चार्ट बन जाता है"],"explanationHi":"F11 अलग चार्ट शीट पर चार्ट बनाता है; Alt + F1 वर्तमान शीट पर एम्बेडेड चार्ट बनाता है। Shift + F11 नई वर्कशीट डालता है और F9 पुनर्गणना करता है।"},
  {"id":"comp-ms-office-internet-95","question":"In Excel 2013 and later, which shortcut runs Flash Fill to complete a column based on a pattern you have typed?","options":["Ctrl + F","Ctrl + E","Ctrl + R","Ctrl + Shift + E"],"answer":1,"explanation":"Ctrl + E triggers Flash Fill. Ctrl + R fills right (copies the cell on the left), and Ctrl + F opens Find.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel 2013 और उसके बाद के संस्करणों में कौन-सा शॉर्टकट आपके टाइप किए गए पैटर्न के आधार पर कॉलम को पूरा करने के लिए Flash Fill चलाता है?","optionsHi":["Ctrl + F","Ctrl + E","Ctrl + R","Ctrl + Shift + E"],"explanationHi":"Ctrl + E Flash Fill को चालू करता है। Ctrl + R दाईं ओर भरता है (बाईं ओर वाले सेल की प्रतिलिपि बनाता है), और Ctrl + F Find खोलता है।"},
  {"id":"comp-ms-office-internet-96","question":"In MS Word, which shortcut inserts a footnote at the cursor position?","options":["Ctrl + Alt + F","Ctrl + Alt + D","Ctrl + Alt + M","Ctrl + Shift + F"],"answer":0,"explanation":"Ctrl + Alt + F inserts a footnote and Ctrl + Alt + D an endnote. Ctrl + Alt + M inserts a comment.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में कौन-सा शॉर्टकट कर्सर की स्थिति पर फ़ुटनोट (footnote) डालता है?","optionsHi":["Ctrl + Alt + F","Ctrl + Alt + D","Ctrl + Alt + M","Ctrl + Shift + F"],"explanationHi":"Ctrl + Alt + F फ़ुटनोट डालता है और Ctrl + Alt + D एंडनोट। Ctrl + Alt + M टिप्पणी (comment) डालता है।"},
  {"id":"comp-ms-office-internet-97","question":"In MS Word, Ctrl + Shift + C followed by Ctrl + Shift + V on other text is used to:","options":["Count characters and paste the count","Copy and paste text without formatting","Insert a copyright symbol","Copy and paste only the formatting, like Format Painter"],"answer":3,"explanation":"Ctrl + Shift + C copies formatting and Ctrl + Shift + V applies it — the keyboard version of Format Painter. It does not copy the text itself.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में, Ctrl + Shift + C के बाद दूसरे टेक्स्ट पर Ctrl + Shift + V का उपयोग किसलिए किया जाता है?","optionsHi":["अक्षर गिनने और गिनती चिपकाने के लिए","टेक्स्ट को बिना फ़ॉर्मेटिंग के कॉपी और पेस्ट करने के लिए","कॉपीराइट चिह्न डालने के लिए","केवल फ़ॉर्मेटिंग को कॉपी और पेस्ट करने के लिए, Format Painter की तरह"],"explanationHi":"Ctrl + Shift + C फ़ॉर्मेटिंग कॉपी करता है और Ctrl + Shift + V उसे लागू करता है — यह Format Painter का कीबोर्ड रूप है। यह टेक्स्ट को स्वयं कॉपी नहीं करता।"},
  {"id":"comp-ms-office-internet-98","question":"In MS Word, which shortcut turns Track Changes on or off?","options":["Ctrl + Shift + E","Ctrl + Shift + T","Ctrl + Alt + T","Ctrl + T"],"answer":0,"explanation":"Ctrl + Shift + E toggles Track Changes. Ctrl + T creates a hanging indent and Ctrl + Shift + T removes it.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में कौन-सा शॉर्टकट Track Changes को चालू या बंद करता है?","optionsHi":["Ctrl + Shift + E","Ctrl + Shift + T","Ctrl + Alt + T","Ctrl + T"],"explanationHi":"Ctrl + Shift + E Track Changes को चालू/बंद करता है। Ctrl + T हैंगिंग इंडेंट बनाता है और Ctrl + Shift + T उसे हटाता है।"},
  {"id":"comp-ms-office-internet-99","question":"In MS Word, Ctrl + Backspace deletes:","options":["The whole current line","The word to the left of the cursor","The character to the right of the cursor","The whole paragraph"],"answer":1,"explanation":"Ctrl + Backspace deletes the previous word and Ctrl + Delete the next word. Plain Delete removes one character to the right.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में Ctrl + Backspace क्या हटाता है?","optionsHi":["पूरी वर्तमान पंक्ति","कर्सर के बाईं ओर का शब्द","कर्सर के दाईं ओर का अक्षर","पूरा अनुच्छेद"],"explanationHi":"Ctrl + Backspace पिछला शब्द हटाता है और Ctrl + Delete अगला शब्द। केवल Delete दाईं ओर का एक अक्षर हटाता है।"},
  {"id":"comp-ms-office-internet-100","question":"In MS Word, the 'gutter' margin is:","options":["The space reserved for headers and footers","The space between two columns of text","Extra space added to a margin to allow for binding","The blank area at the end of the last page"],"answer":2,"explanation":"A gutter adds space to the side or top margin so text is not hidden by binding. The space between columns is simply the column spacing.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में 'गटर' (gutter) मार्जिन क्या है?","optionsHi":["हेडर और फ़ुटर के लिए आरक्षित स्थान","टेक्स्ट के दो कॉलमों के बीच का स्थान","बाइंडिंग के लिए किसी मार्जिन में जोड़ा गया अतिरिक्त स्थान","अंतिम पेज के अंत में खाली क्षेत्र"],"explanationHi":"गटर बगल या ऊपर के मार्जिन में अतिरिक्त स्थान जोड़ता है ताकि बाइंडिंग से टेक्स्ट छिप न जाए। कॉलमों के बीच का स्थान केवल कॉलम स्पेसिंग कहलाता है।"},
  {"id":"comp-ms-office-internet-101","question":"The Word paragraph option 'Widow/Orphan control' prevents:","options":["A single line of a paragraph being left alone at the top or bottom of a page","Text from wrapping around pictures","Hyphenation of long words","Headings from appearing in the table of contents"],"answer":0,"explanation":"With widow/orphan control on, Word will not leave the last line of a paragraph alone at the top of a page (widow) or its first line alone at the bottom (orphan).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Word के अनुच्छेद विकल्प 'Widow/Orphan control' से क्या रोका जाता है?","optionsHi":["अनुच्छेद की एक पंक्ति का पेज के ऊपर या नीचे अकेले रह जाना","टेक्स्ट का चित्रों के चारों ओर लिपटना","लंबे शब्दों का हाइफ़नेशन","शीर्षकों का विषय-सूची में दिखना"],"explanationHi":"widow/orphan control चालू होने पर Word किसी अनुच्छेद की अंतिम पंक्ति को पेज के ऊपर अकेला (widow) या उसकी पहली पंक्ति को पेज के नीचे अकेला (orphan) नहीं छोड़ता।"},
  {"id":"comp-ms-office-internet-102","question":"A Word document that contains macros must be saved with which extension to keep them?","options":[".dotx",".docx",".docm",".rtf"],"answer":2,"explanation":".docm is the macro-enabled document format. .docx cannot store macros, .dotx is a macro-free template and .rtf is Rich Text Format.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"मैक्रो वाले Word दस्तावेज़ में मैक्रो बनाए रखने के लिए उसे किस एक्सटेंशन के साथ सेव करना होगा?","optionsHi":[".dotx",".docx",".docm",".rtf"],"explanationHi":".docm मैक्रो-सक्षम दस्तावेज़ प्रारूप है। .docx मैक्रो संग्रहीत नहीं कर सकता, .dotx मैक्रो-रहित टेम्पलेट है और .rtf रिच टेक्स्ट फ़ॉर्मेट है।"},
  {"id":"comp-ms-office-internet-103","question":"In a URL such as https://shop.example.com/items/list.html?page=2#reviews, the part 'page=2' is the:","options":["Fragment","Query string","Path","Host name"],"answer":1,"explanation":"Everything after '?' is the query string (here page=2). '#reviews' is the fragment, '/items/list.html' is the path, and shop.example.com is the host name.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"https://shop.example.com/items/list.html?page=2#reviews जैसे URL में 'page=2' भाग क्या है?","optionsHi":["फ़्रैगमेंट","क्वेरी स्ट्रिंग","पथ (Path)","होस्ट नाम"],"explanationHi":"'?' के बाद का सब कुछ क्वेरी स्ट्रिंग है (यहाँ page=2)। '#reviews' फ़्रैगमेंट है, '/items/list.html' पथ है, और shop.example.com होस्ट नाम है।"},
  {"id":"comp-ms-office-internet-104","question":"Which protocol finds the MAC (hardware) address of a device on a local network when its IP address is known?","options":["ICMP","DHCP","DNS","ARP"],"answer":3,"explanation":"ARP (Address Resolution Protocol) maps an IPv4 address to a MAC address. DNS maps domain names to IP addresses and DHCP assigns IP addresses; ICMP carries error messages such as ping.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कौन-सा प्रोटोकॉल, IP पता ज्ञात होने पर, स्थानीय नेटवर्क में किसी उपकरण का MAC (हार्डवेयर) पता खोजता है?","optionsHi":["ICMP","DHCP","DNS","ARP"],"explanationHi":"ARP (Address Resolution Protocol) IPv4 पते को MAC पते से जोड़ता है। DNS डोमेन नामों को IP पतों से जोड़ता है और DHCP IP पते आवंटित करता है; ICMP ping जैसे त्रुटि संदेश ले जाता है।"},
  {"id":"comp-ms-office-internet-105","question":"Which technology lets many devices on a home network with private IP addresses share a single public IP address on the internet?","options":["NAT (Network Address Translation)","DNS","FTP","VLAN"],"answer":0,"explanation":"NAT on the router rewrites private source addresses to its one public address and tracks the replies. DNS only resolves names to addresses.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कौन-सी तकनीक होम नेटवर्क के निजी IP पते वाले कई उपकरणों को इंटरनेट पर एक ही सार्वजनिक IP पता साझा करने देती है?","optionsHi":["NAT (Network Address Translation)","DNS","FTP","VLAN"],"explanationHi":"राउटर पर NAT निजी स्रोत पतों को उसके एक सार्वजनिक पते में बदल देता है और उत्तरों को ट्रैक करता है। DNS केवल नामों को पतों में बदलता है।"},
  {"id":"comp-ms-office-internet-106","question":"In a Google search, which query restricts results to PDF documents from Indian government websites about 'digital literacy'?","options":["digital literacy site:pdf filetype:gov.in","digital literacy +pdf -gov.in","\"digital literacy\" OR pdf OR gov.in","digital literacy filetype:pdf site:gov.in"],"answer":3,"explanation":"filetype: limits the file format and site: limits the domain. The first option swaps the two operators, and '-gov.in' would exclude government sites.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Google खोज में कौन-सी क्वेरी 'digital literacy' के बारे में भारतीय सरकारी वेबसाइटों के केवल PDF दस्तावेज़ों तक परिणाम सीमित करती है?","optionsHi":["digital literacy site:pdf filetype:gov.in","digital literacy +pdf -gov.in","\"digital literacy\" OR pdf OR gov.in","digital literacy filetype:pdf site:gov.in"],"explanationHi":"filetype: फ़ाइल प्रारूप को सीमित करता है और site: डोमेन को। पहला विकल्प दोनों संक्रियकों को आपस में बदल देता है, और '-gov.in' सरकारी साइटों को बाहर कर देता।"},
  {"id":"comp-ms-office-internet-107","question":"Which part of the CIA triad of information security is the main target of a Distributed Denial-of-Service (DDoS) attack?","options":["Confidentiality","Availability","Integrity","Authenticity"],"answer":1,"explanation":"A DDoS floods a server with traffic so that legitimate users cannot reach it — an attack on availability. It does not usually steal (confidentiality) or alter (integrity) data.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"सूचना सुरक्षा की CIA त्रयी का कौन-सा भाग वितरित सेवा-अवरोध (DDoS) हमले का मुख्य लक्ष्य है?","optionsHi":["गोपनीयता (Confidentiality)","उपलब्धता (Availability)","अखंडता (Integrity)","प्रामाणिकता (Authenticity)"],"explanationHi":"DDoS सर्वर को ट्रैफ़िक से भर देता है ताकि वैध उपयोगकर्ता उस तक न पहुँच सकें — यह उपलब्धता पर हमला है। यह सामान्यतः डेटा चुराता (गोपनीयता) या बदलता (अखंडता) नहीं है।"},
  {"id":"comp-ms-office-internet-108","question":"An attacker types ' OR '1'='1 into a website's login box to bypass the password check. This is an example of:","options":["Brute-force attack","Cross-site scripting","SQL injection","Buffer overflow"],"answer":2,"explanation":"Inserting SQL code into an input field to alter the database query is SQL injection. Cross-site scripting injects scripts into web pages viewed by other users; brute force tries many passwords.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कोई हमलावर पासवर्ड जाँच को बायपास करने के लिए किसी वेबसाइट के लॉगिन बॉक्स में ' OR '1'='1 टाइप करता है। यह किसका उदाहरण है?","optionsHi":["ब्रूट-फ़ोर्स हमला","क्रॉस-साइट स्क्रिप्टिंग","SQL इंजेक्शन","बफ़र ओवरफ़्लो"],"explanationHi":"डेटाबेस क्वेरी बदलने के लिए इनपुट फ़ील्ड में SQL कोड डालना SQL इंजेक्शन है। क्रॉस-साइट स्क्रिप्टिंग अन्य उपयोगकर्ताओं द्वारा देखे जाने वाले वेब पेजों में स्क्रिप्ट डालती है; ब्रूट फ़ोर्स कई पासवर्ड आज़माता है।"},
  {"id":"comp-ms-office-internet-109","question":"A network of computers infected with malware and controlled remotely by an attacker, often used to send spam or launch DDoS attacks, is called a:","options":["Honeypot","Botnet","Intranet","Firewall"],"answer":1,"explanation":"Each infected machine is a 'bot' or 'zombie'; together they form a botnet. A honeypot is a decoy system set up by defenders to attract attackers.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"मैलवेयर से संक्रमित कंप्यूटरों का वह नेटवर्क, जिसे हमलावर दूर से नियंत्रित करता है और जिसका उपयोग अक्सर स्पैम भेजने या DDoS हमले करने में होता है, क्या कहलाता है?","optionsHi":["हनीपॉट (Honeypot)","बॉटनेट (Botnet)","इंट्रानेट (Intranet)","फ़ायरवॉल (Firewall)"],"explanationHi":"प्रत्येक संक्रमित मशीन एक 'बॉट' या 'ज़ोंबी' होती है; मिलकर वे बॉटनेट बनाती हैं। हनीपॉट रक्षकों द्वारा हमलावरों को आकर्षित करने के लिए लगाई गई नकली प्रणाली है।"},
  {"id":"comp-ms-office-internet-110","question":"A security flaw that is exploited by attackers before the software vendor has released any fix for it is called a:","options":["Zero-day vulnerability","Backdoor","Patch","False positive"],"answer":0,"explanation":"'Zero-day' means the vendor has had zero days to fix it. A patch is the fix itself; a backdoor is a hidden way of bypassing authentication.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"सॉफ़्टवेयर विक्रेता द्वारा कोई सुधार जारी किए जाने से पहले ही हमलावरों द्वारा भुनाई गई सुरक्षा खामी क्या कहलाती है?","optionsHi":["ज़ीरो-डे वल्नरेबिलिटी (Zero-day vulnerability)","बैकडोर (Backdoor)","पैच (Patch)","फ़ॉल्स पॉज़िटिव (False positive)"],"explanationHi":"'ज़ीरो-डे' का अर्थ है कि विक्रेता को उसे ठीक करने के लिए शून्य दिन मिले। पैच स्वयं सुधार है; बैकडोर प्रमाणीकरण को बायपास करने का छिपा रास्ता है।"},
  {"id":"comp-ms-office-internet-111","question":"Which of these encryption algorithms is asymmetric, using a public key and a private key?","options":["Triple DES","AES","DES","RSA"],"answer":3,"explanation":"RSA is a public-key (asymmetric) algorithm. AES, DES and 3DES are symmetric: the same secret key encrypts and decrypts.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"इनमें से कौन-सा एन्क्रिप्शन एल्गोरिदम असममित (asymmetric) है, जो सार्वजनिक कुंजी और निजी कुंजी का उपयोग करता है?","optionsHi":["Triple DES","AES","DES","RSA"],"explanationHi":"RSA सार्वजनिक-कुंजी (असममित) एल्गोरिदम है। AES, DES और 3DES सममित हैं: एक ही गुप्त कुंजी एन्क्रिप्ट और डिक्रिप्ट करती है।"},
  {"id":"comp-ms-office-internet-112","question":"Which of the following pairs of factors gives genuine two-factor authentication?","options":["A PIN and a password","A password and a security question","A password and an OTP sent to the registered mobile","A fingerprint and a face scan"],"answer":2,"explanation":"Two-factor authentication needs factors of two different kinds — here something you know (password) and something you have (phone). Password + security question or PIN + password are both 'something you know'; fingerprint + face are both 'something you are'.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"निम्नलिखित में से कौन-सा कारकों का युग्म वास्तविक द्वि-कारक प्रमाणीकरण देता है?","optionsHi":["एक PIN और एक पासवर्ड","एक पासवर्ड और एक सुरक्षा प्रश्न","एक पासवर्ड और पंजीकृत मोबाइल पर भेजा गया OTP","एक फ़िंगरप्रिंट और एक चेहरा स्कैन"],"explanationHi":"द्वि-कारक प्रमाणीकरण के लिए दो भिन्न प्रकार के कारक चाहिए — यहाँ कुछ जो आप जानते हैं (पासवर्ड) और कुछ जो आपके पास है (फ़ोन)। पासवर्ड + सुरक्षा प्रश्न या PIN + पासवर्ड दोनों 'आप जो जानते हैं' हैं; फ़िंगरप्रिंट + चेहरा दोनों 'आप जो हैं' हैं।"},
  {"id":"comp-ms-office-internet-113","question":"In Excel, the divisor is negative in =MOD(7, -3). What result does the formula give?","options":["1","-2","-1","2"],"answer":1,"explanation":"MOD(n, d) = n − d × INT(n/d) = 7 − (−3) × INT(−2.33) = 7 − (−3)(−3) = 7 − 9 = −2. The result takes the sign of the divisor, so the positive answers are traps.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में =MOD(7, -3) में भाजक ऋणात्मक है। सूत्र क्या परिणाम देता है?","optionsHi":["1","-2","-1","2"],"explanationHi":"MOD(n, d) = n − d × INT(n/d) = 7 − (−3) × INT(−2.33) = 7 − (−3)(−3) = 7 − 9 = −2। परिणाम भाजक का चिह्न लेता है, इसलिए धनात्मक उत्तर जाल हैं।"},
  {"id":"comp-ms-office-internet-114","question":"What does the Excel formula =ROUNDDOWN(-3.78, 1) return?","options":["-4","-3.8","-3.7","-3.78"],"answer":2,"explanation":"ROUNDDOWN always rounds towards zero, so -3.78 becomes -3.7. 'Down' in the sense of a smaller number (-3.8) is the trap; FLOOR-style rounding would give that.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =ROUNDDOWN(-3.78, 1) क्या लौटाता है?","optionsHi":["-4","-3.8","-3.7","-3.78"],"explanationHi":"ROUNDDOWN हमेशा शून्य की ओर पूर्णांकित करता है, इसलिए -3.78 का मान -3.7 हो जाता है। छोटी संख्या (-3.8) के अर्थ में 'नीचे' जाना जाल है; FLOOR-शैली का पूर्णांकन वह देता।"},
  {"id":"comp-ms-office-internet-115","question":"What does the Excel formula =ROUND(1250, -2) return?","options":["1300","1200","1250","1000"],"answer":0,"explanation":"Rounding to the nearest hundred, 1250 is exactly halfway; Excel's ROUND rounds halves away from zero, so the result is 1300. 1200 assumes 'round half to even' (banker's rounding), which Excel's ROUND does not use.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =ROUND(1250, -2) क्या लौटाता है?","optionsHi":["1300","1200","1250","1000"],"explanationHi":"निकटतम सैकड़े तक पूर्णांकित करने पर 1250 ठीक आधे पर है; Excel का ROUND आधे को शून्य से दूर पूर्णांकित करता है, इसलिए परिणाम 1300 है। 1200 'सम की ओर पूर्णांकन' (बैंकर्स राउंडिंग) मानता है, जिसका Excel का ROUND उपयोग नहीं करता।"},
  {"id":"comp-ms-office-internet-116","question":"What does the Excel formula =-3^2+1 return?","options":["8","-8","-10","10"],"answer":3,"explanation":"Negation is applied before the exponent in Excel: (-3)^2 + 1 = 9 + 1 = 10. Treating it as -(3^2) + 1 gives -8, the algebra-textbook answer.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =-3^2+1 क्या लौटाता है?","optionsHi":["8","-8","-10","10"],"explanationHi":"Excel में निषेध घातांक से पहले लागू होता है: (-3)^2 + 1 = 9 + 1 = 10। इसे -(3^2) + 1 मानने पर -8 आता है, जो बीजगणित की पाठ्यपुस्तक का उत्तर है।"},
  {"id":"comp-ms-office-internet-117","question":"What does the Excel formula =\"A\"&1+2 return?","options":["A12","A3","#VALUE!","A1+2"],"answer":1,"explanation":"Arithmetic operators rank above the concatenation operator &, so 1+2 is worked out first and then joined: \"A\" & 3 = \"A3\". 'A12' would need brackets: =(\"A\"&1)&2.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =\"A\"&1+2 क्या लौटाता है?","optionsHi":["A12","A3","#VALUE!","A1+2"],"explanationHi":"अंकगणितीय संक्रियक संयोजन संक्रियक & से ऊपर होते हैं, इसलिए पहले 1+2 हल होता है और फिर जोड़ा जाता है: \"A\" & 3 = \"A3\"। 'A12' के लिए कोष्ठक चाहिए: =(\"A\"&1)&2।"},
  {"id":"comp-ms-office-internet-118","question":"What does the Excel formula =FIND(\"N\", \"Banana\") return?","options":["#N/A","3","0","#VALUE!"],"answer":3,"explanation":"FIND is case-sensitive, and \"Banana\" has no capital N, so it returns #VALUE!. SEARCH, which ignores case, would return 3.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =FIND(\"N\", \"Banana\") क्या लौटाता है?","optionsHi":["#N/A","3","0","#VALUE!"],"explanationHi":"FIND अक्षर-संवेदी (case-sensitive) है, और \"Banana\" में बड़ा N नहीं है, इसलिए यह #VALUE! लौटाता है। SEARCH, जो केस को अनदेखा करता है, 3 लौटाता।"},
  {"id":"comp-ms-office-internet-119","question":"What does the Excel formula =SEARCH(\"N\", \"Banana\") return?","options":["3","#VALUE!","5","2"],"answer":0,"explanation":"SEARCH is not case-sensitive, so it finds the first 'n' at position 3 (B-a-n). FIND would have failed with #VALUE! because it is case-sensitive.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =SEARCH(\"N\", \"Banana\") क्या लौटाता है?","optionsHi":["3","#VALUE!","5","2"],"explanationHi":"SEARCH अक्षर-संवेदी नहीं है, इसलिए यह पहला 'n' स्थिति 3 पर पाता है (B-a-n)। FIND अक्षर-संवेदी होने के कारण #VALUE! के साथ विफल हो जाता।"},
  {"id":"comp-ms-office-internet-120","question":"In Excel, A1 = 5, A2 contains the TEXT \"7\" (entered as text), A3 = TRUE, A4 is blank and A5 = 3. What does =COUNT(A1:A5) return?","options":["4","3","2","5"],"answer":2,"explanation":"COUNT counts only numeric cells in a range: 5 and 3. Numbers stored as text and logical values inside a range are ignored, so 3 or 4 are traps; COUNTA would return 4.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1 = 5 है, A2 में पाठ \"7\" है (पाठ के रूप में दर्ज), A3 = TRUE है, A4 रिक्त है और A5 = 3 है। =COUNT(A1:A5) क्या लौटाता है?","optionsHi":["4","3","2","5"],"explanationHi":"COUNT रेंज में केवल संख्यात्मक सेल गिनता है: 5 और 3। पाठ के रूप में संग्रहीत संख्याएँ और रेंज के भीतर तार्किक मान अनदेखे किए जाते हैं, इसलिए 3 या 4 जाल हैं; COUNTA 4 लौटाता।"},
  {"id":"comp-ms-office-internet-121","question":"In Excel, A1 = 5 and A2 contains the text \"7\" (a number stored as text). What do =SUM(A1:A2) and =A1+A2 return respectively?","options":["12 and 5","12 and 12","5 and #VALUE!","5 and 12"],"answer":3,"explanation":"SUM over a range ignores text, giving 5. But the + operator converts numeric text into a number, so =A1+A2 gives 12.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1 = 5 है और A2 में पाठ \"7\" है (पाठ के रूप में संग्रहीत संख्या)। =SUM(A1:A2) और =A1+A2 क्रमशः क्या लौटाते हैं?","optionsHi":["12 और 5","12 और 12","5 और #VALUE!","5 और 12"],"explanationHi":"रेंज पर SUM पाठ को अनदेखा करता है, इसलिए 5 आता है। परंतु + संक्रियक संख्यात्मक पाठ को संख्या में बदल देता है, इसलिए =A1+A2 का मान 12 है।"},
  {"id":"comp-ms-office-internet-122","question":"In Excel, A1:A4 contain 1, 2, 3 and 4. What does =SUM(A1:A3,A2:A4) return?","options":["10","15","5","9"],"answer":1,"explanation":"The comma is the union operator, so both ranges are added in full and the overlapping cells A2 and A3 count twice: (1+2+3) + (2+3+4) = 15. 10 assumes the overlap is counted once.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1:A4 में 1, 2, 3 और 4 हैं। =SUM(A1:A3,A2:A4) क्या लौटाता है?","optionsHi":["10","15","5","9"],"explanationHi":"अल्पविराम (comma) संघ संक्रियक (union operator) है, इसलिए दोनों रेंज पूरी जोड़ी जाती हैं और अतिव्यापी सेल A2 व A3 दो बार गिने जाते हैं: (1+2+3) + (2+3+4) = 15। 10 यह मानता है कि अतिव्यापन एक बार गिना जाता है।"},
  {"id":"comp-ms-office-internet-123","question":"In Excel, A1:A4 contain 1, 2, 3 and 4. What does =SUM(A1:A3 A2:A4) return (note the space between the ranges)?","options":["10","15","5","#NULL!"],"answer":2,"explanation":"A space is Excel's intersection operator; the ranges overlap in A2:A3, so the result is 2 + 3 = 5. #NULL! would appear only if the ranges did not overlap at all.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1:A4 में 1, 2, 3 और 4 हैं। =SUM(A1:A3 A2:A4) क्या लौटाता है (रेंजों के बीच रिक्त स्थान पर ध्यान दें)?","optionsHi":["10","15","5","#NULL!"],"explanationHi":"रिक्त स्थान Excel का प्रतिच्छेदन संक्रियक (intersection operator) है; रेंज A2:A3 में अतिव्यापित होती हैं, इसलिए परिणाम 2 + 3 = 5 है। #NULL! तभी आता जब रेंज बिल्कुल अतिव्यापित न होतीं।"},
  {"id":"comp-ms-office-internet-124","question":"Which Excel error value appears for =SUM(A1:A3 C1:C3)?","options":["#NULL!","#REF!","#VALUE!","#N/A"],"answer":0,"explanation":"The space between the ranges is the intersection operator, and A1:A3 and C1:C3 share no cell, so Excel returns #NULL!.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"=SUM(A1:A3 C1:C3) के लिए Excel का कौन-सा त्रुटि मान दिखता है?","optionsHi":["#NULL!","#REF!","#VALUE!","#N/A"],"explanationHi":"रेंजों के बीच का रिक्त स्थान प्रतिच्छेदन संक्रियक है, और A1:A3 तथा C1:C3 में कोई सेल साझा नहीं है, इसलिए Excel #NULL! लौटाता है।"},
  {"id":"comp-ms-office-internet-125","question":"The formula =$A1*B$2 is in cell C3. When it is copied to cell E5, it becomes:","options":["=$A3*D$2","=$A1*D$2","=$C3*D$4","=$A3*B$4"],"answer":0,"explanation":"Moving two columns right and two rows down: in $A1 the column is locked and the row changes (1 → 3); in B$2 the row is locked and the column changes (B → D).","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"सूत्र =$A1*B$2 सेल C3 में है। इसे सेल E5 में कॉपी करने पर यह क्या बन जाता है?","optionsHi":["=$A3*D$2","=$A1*D$2","=$C3*D$4","=$A3*B$4"],"explanationHi":"दो कॉलम दाईं ओर और दो पंक्ति नीचे जाने पर: $A1 में कॉलम लॉक है और पंक्ति बदलती है (1 → 3); B$2 में पंक्ति लॉक है और कॉलम बदलता है (B → D)।"},
  {"id":"comp-ms-office-internet-126","question":"What does the Excel formula =DATE(2024, 2, 30) return?","options":["2 March 2024","#NUM!","29 February 2024","1 March 2024"],"answer":3,"explanation":"DATE rolls extra days over into the next month. February 2024 has 29 days (leap year), so day 30 becomes 1 March 2024. 2 March would be correct for a non-leap year.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =DATE(2024, 2, 30) क्या लौटाता है?","optionsHi":["2 मार्च 2024","#NUM!","29 फ़रवरी 2024","1 मार्च 2024"],"explanationHi":"DATE अतिरिक्त दिनों को अगले महीने में ले जाता है। फ़रवरी 2024 में 29 दिन हैं (अधिवर्ष), इसलिए दिन 30 बदलकर 1 मार्च 2024 हो जाता है। 2 मार्च गैर-अधिवर्ष के लिए सही होता।"},
  {"id":"comp-ms-office-internet-127","question":"What does the Excel formula =DATE(2023, 13, 1) return?","options":["1 December 2023","#NUM!","1 January 2024","13 January 2023"],"answer":2,"explanation":"A month number above 12 rolls over into the next year: month 13 of 2023 is January 2024. Excel does not raise an error for it.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel का सूत्र =DATE(2023, 13, 1) क्या लौटाता है?","optionsHi":["1 दिसंबर 2023","#NUM!","1 जनवरी 2024","13 जनवरी 2023"],"explanationHi":"12 से बड़ी माह संख्या अगले वर्ष में चली जाती है: 2023 का माह 13 जनवरी 2024 है। Excel इसके लिए त्रुटि नहीं देता।"},
  {"id":"comp-ms-office-internet-128","question":"In Excel, the column immediately after column AZ is BA. What is the column number of AZ, and which column is number 100?","options":["52; CU","52; CV","51; CV","78; DV"],"answer":1,"explanation":"AZ = 1×26 + 26 = 52. For 100: 100 = 3×26 + 22, i.e. third letter C and 22nd letter V → CV.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में कॉलम AZ के ठीक बाद वाला कॉलम BA है। AZ की कॉलम संख्या क्या है, और संख्या 100 कौन-सा कॉलम है?","optionsHi":["52; CU","52; CV","51; CV","78; DV"],"explanationHi":"AZ = 1×26 + 26 = 52। 100 के लिए: 100 = 3×26 + 22, अर्थात तीसरा अक्षर C और बाईसवाँ अक्षर V → CV।"},
  {"id":"comp-ms-office-internet-129","question":"In Excel, A1 = 75. What does =IF(A1>=40, IF(A1>=75, \"Distinction\", \"Pass\"), \"Fail\") return?","options":["FALSE","Pass","Fail","Distinction"],"answer":3,"explanation":"75 ≥ 40 is TRUE, so the inner IF runs; 75 ≥ 75 is also TRUE (the test is 'greater than or equal'), giving \"Distinction\". Reading >= as > leads to the trap \"Pass\".","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1 = 75 है। =IF(A1>=40, IF(A1>=75, \"Distinction\", \"Pass\"), \"Fail\") क्या लौटाता है?","optionsHi":["FALSE","Pass","Fail","Distinction"],"explanationHi":"75 ≥ 40 TRUE है, इसलिए भीतरी IF चलता है; 75 ≥ 75 भी TRUE है (परीक्षण 'बड़ा या बराबर' है), जो \"Distinction\" देता है। >= को > पढ़ने से जाल वाला उत्तर \"Pass\" मिलता है।"},
  {"id":"comp-ms-office-internet-130","question":"In Excel, A2:A5 contain the names Asha, Ravi, Meena, Tarun and B2:B5 contain 82, 67, 91, 74. What does =INDEX(B2:B5, MATCH(\"Meena\", A2:A5, 0)) return?","options":["67","3","91","Meena"],"answer":2,"explanation":"MATCH finds \"Meena\" at position 3 of A2:A5 (exact match, type 0), and INDEX returns the 3rd value of B2:B5, which is 91. 3 is only MATCH's output.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A2:A5 में नाम Asha, Ravi, Meena, Tarun हैं और B2:B5 में 82, 67, 91, 74 हैं। =INDEX(B2:B5, MATCH(\"Meena\", A2:A5, 0)) क्या लौटाता है?","optionsHi":["67","3","91","Meena"],"explanationHi":"MATCH, A2:A5 की स्थिति 3 पर \"Meena\" पाता है (सटीक मिलान, टाइप 0), और INDEX, B2:B5 का तीसरा मान लौटाता है, जो 91 है। 3 केवल MATCH का आउटपुट है।"},
  {"id":"comp-ms-office-internet-131","question":"In Excel, A1 = 0.256. What does =TEXT(A1, \"0.0%\") return?","options":["0.3%","25.6%","26%","2.6%"],"answer":1,"explanation":"The % in the format code multiplies the value by 100 and adds a percent sign; \"0.0\" keeps one decimal place: 25.6%. Ignoring the multiplication gives 0.3%.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में A1 = 0.256 है। =TEXT(A1, \"0.0%\") क्या लौटाता है?","optionsHi":["0.3%","25.6%","26%","2.6%"],"explanationHi":"फ़ॉर्मेट कोड में % मान को 100 से गुणा करता है और प्रतिशत चिह्न जोड़ता है; \"0.0\" एक दशमलव स्थान रखता है: 25.6%। गुणा को अनदेखा करने पर 0.3% आता है।"},
  {"id":"comp-ms-office-internet-132","question":"In Excel, what does =IFERROR(1/0, \"Check\") & \"!\" return?","options":["Check!","#DIV/0!","#DIV/0!!","Check"],"answer":0,"explanation":"1/0 is an error, so IFERROR returns \"Check\"; the & operator then joins \"!\" to give \"Check!\".","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Excel में =IFERROR(1/0, \"Check\") & \"!\" क्या लौटाता है?","optionsHi":["Check!","#DIV/0!","#DIV/0!!","Check"],"explanationHi":"1/0 त्रुटि है, इसलिए IFERROR \"Check\" लौटाता है; फिर & संक्रियक \"!\" जोड़कर \"Check!\" देता है।"},
  {"id":"comp-ms-office-internet-133","question":"Which of the following Excel formulas does NOT return an error?","options":["=\"5\"*2","=\"abc\"*2","=SQRT(-4)","=VLOOKUP(99,{1,\"a\";2,\"b\"},2,FALSE)"],"answer":0,"explanation":"\"5\"*2 converts the numeric text to 5 and returns 10. \"abc\"*2 gives #VALUE!, SQRT of a negative number gives #NUM!, and an exact-match VLOOKUP that finds nothing gives #N/A.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"निम्नलिखित में से कौन-सा Excel सूत्र त्रुटि नहीं लौटाता?","optionsHi":["=\"5\"*2","=\"abc\"*2","=SQRT(-4)","=VLOOKUP(99,{1,\"a\";2,\"b\"},2,FALSE)"],"explanationHi":"\"5\"*2 संख्यात्मक पाठ को 5 में बदल देता है और 10 लौटाता है। \"abc\"*2 #VALUE! देता है, ऋणात्मक संख्या का SQRT #NUM! देता है, और कुछ न पाने वाला सटीक-मिलान VLOOKUP #N/A देता है।"},
  {"id":"comp-ms-office-internet-134","question":"The same key combination does different things in different Office programs. What does Ctrl + D do in MS Word, MS Excel and MS PowerPoint respectively?","options":["Fills down; opens the Font dialog; deletes the slide","Opens the Font dialog; fills down; duplicates the selected slide or object","Duplicates; fills down; opens the Font dialog","Opens the Font dialog; deletes the row; duplicates the slide"],"answer":1,"explanation":"In Word, Ctrl + D opens the Font dialog; in Excel it copies the top cell of a selection down (Fill Down); in PowerPoint it duplicates the selected slide or object.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एक ही कुंजी संयोजन अलग-अलग Office प्रोग्रामों में अलग कार्य करता है। MS Word, MS Excel और MS PowerPoint में Ctrl + D क्रमशः क्या करता है?","optionsHi":["नीचे भरता है; Font डायलॉग खोलता है; स्लाइड हटाता है","Font डायलॉग खोलता है; नीचे भरता है; चयनित स्लाइड या ऑब्जेक्ट की प्रतिलिपि बनाता है","प्रतिलिपि बनाता है; नीचे भरता है; Font डायलॉग खोलता है","Font डायलॉग खोलता है; पंक्ति हटाता है; स्लाइड की प्रतिलिपि बनाता है"],"explanationHi":"Word में Ctrl + D Font डायलॉग खोलता है; Excel में यह चयन के सबसे ऊपरी सेल को नीचे की ओर कॉपी करता है (Fill Down); PowerPoint में यह चयनित स्लाइड या ऑब्जेक्ट की प्रतिलिपि बनाता है।"},
  {"id":"comp-ms-office-internet-135","question":"In MS Word, which pair of shortcuts increases and decreases the font size of the selected text by exactly 1 point?","options":["Alt + ] and Alt + [","Ctrl + Shift + > and Ctrl + Shift + <","Ctrl + + and Ctrl + -","Ctrl + ] and Ctrl + ["],"answer":3,"explanation":"Ctrl + ] and Ctrl + [ change the size by one point. Ctrl + Shift + > and < jump to the next or previous size in the font-size list (e.g. 12 → 14), which is the trap.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में शॉर्टकटों का कौन-सा युग्म चयनित टेक्स्ट का फ़ॉन्ट आकार ठीक 1 पॉइंट बढ़ाता और घटाता है?","optionsHi":["Alt + ] और Alt + [","Ctrl + Shift + > और Ctrl + Shift + <","Ctrl + + और Ctrl + -","Ctrl + ] और Ctrl + ["],"explanationHi":"Ctrl + ] और Ctrl + [ आकार को एक पॉइंट बदलते हैं। Ctrl + Shift + > और < फ़ॉन्ट-आकार सूची में अगले या पिछले आकार पर कूद जाते हैं (जैसे 12 → 14), जो जाल है।"},
  {"id":"comp-ms-office-internet-136","question":"In MS Word, Shift + Enter, Ctrl + Enter and Ctrl + Shift + Enter insert, respectively:","options":["A column break, a page break and a line break","A page break, a line break and a section break","A line break, a page break and a column break","A paragraph break, a column break and a page break"],"answer":2,"explanation":"Shift + Enter = manual line break (same paragraph); Ctrl + Enter = page break; Ctrl + Shift + Enter = column break.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में Shift + Enter, Ctrl + Enter और Ctrl + Shift + Enter क्रमशः क्या डालते हैं?","optionsHi":["कॉलम ब्रेक, पेज ब्रेक और लाइन ब्रेक","पेज ब्रेक, लाइन ब्रेक और सेक्शन ब्रेक","लाइन ब्रेक, पेज ब्रेक और कॉलम ब्रेक","अनुच्छेद ब्रेक, कॉलम ब्रेक और पेज ब्रेक"],"explanationHi":"Shift + Enter = मैन्युअल लाइन ब्रेक (उसी अनुच्छेद में); Ctrl + Enter = पेज ब्रेक; Ctrl + Shift + Enter = कॉलम ब्रेक।"},
  {"id":"comp-ms-office-internet-137","question":"In MS Word, which type of section break should be used to change from one-column to two-column layout in the middle of a page, without starting a new page?","options":["Continuous","Next Page","Even Page","Odd Page"],"answer":0,"explanation":"A Continuous section break starts a new section on the same page, so the column layout can change mid-page. Next Page, Even Page and Odd Page breaks all force the new section onto another page.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में, नया पेज शुरू किए बिना पेज के बीच में एक-कॉलम लेआउट से दो-कॉलम लेआउट में बदलने के लिए किस प्रकार का सेक्शन ब्रेक उपयोग करना चाहिए?","optionsHi":["Continuous","Next Page","Even Page","Odd Page"],"explanationHi":"Continuous सेक्शन ब्रेक उसी पेज पर नया सेक्शन शुरू करता है, इसलिए कॉलम लेआउट पेज के बीच में बदला जा सकता है। Next Page, Even Page और Odd Page ब्रेक नए सेक्शन को दूसरे पेज पर ले जाते हैं।"},
  {"id":"comp-ms-office-internet-138","question":"In Word's Mail Merge, which statement is correct?","options":["Merge fields are typed manually as plain text between angle brackets","The data source must be another Word document; Excel lists cannot be used","The main document holds the fixed text and merge fields, while the data source supplies the values that change for each recipient","Mail Merge can only produce letters, not envelopes or labels"],"answer":2,"explanation":"The main document contains constant text plus merge fields; the data source (Excel sheet, Access table, Outlook contacts or a Word table) holds the variable data. Typing «Name» by hand does not create a working field, and Mail Merge can also make envelopes, labels and e-mails.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Word के Mail Merge में कौन-सा कथन सही है?","optionsHi":["मर्ज फ़ील्ड कोण कोष्ठकों के बीच सादे पाठ के रूप में हाथ से टाइप किए जाते हैं","डेटा स्रोत कोई दूसरा Word दस्तावेज़ ही होना चाहिए; Excel सूचियों का उपयोग नहीं किया जा सकता","मुख्य दस्तावेज़ में स्थिर पाठ और मर्ज फ़ील्ड होते हैं, जबकि डेटा स्रोत प्रत्येक प्राप्तकर्ता के लिए बदलने वाले मान देता है","Mail Merge केवल पत्र बना सकता है, लिफ़ाफ़े या लेबल नहीं"],"explanationHi":"मुख्य दस्तावेज़ में स्थिर पाठ और मर्ज फ़ील्ड होते हैं; डेटा स्रोत (Excel शीट, Access तालिका, Outlook संपर्क या Word तालिका) में परिवर्तनशील डेटा होता है। «Name» को हाथ से टाइप करने से कार्यशील फ़ील्ड नहीं बनता, और Mail Merge लिफ़ाफ़े, लेबल और ई-मेल भी बना सकता है।"},
  {"id":"comp-ms-office-internet-139","question":"During a PowerPoint slide show, what happens when you type 7 and then press Enter?","options":["The show advances seven slides","The show jumps directly to slide 7","The pen colour changes","The screen zooms to 70%"],"answer":1,"explanation":"Typing a slide number and pressing Enter jumps straight to that slide. Ctrl + P switches the pointer to a pen during a show.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"PowerPoint स्लाइड शो के दौरान 7 टाइप करके Enter दबाने पर क्या होता है?","optionsHi":["शो सात स्लाइड आगे बढ़ जाता है","शो सीधे स्लाइड 7 पर पहुँच जाता है","पेन का रंग बदल जाता है","स्क्रीन 70% तक ज़ूम हो जाती है"],"explanationHi":"स्लाइड संख्या टाइप करके Enter दबाने पर सीधे उसी स्लाइड पर पहुँच जाते हैं। शो के दौरान Ctrl + P पॉइंटर को पेन में बदल देता है।"},
  {"id":"comp-ms-office-internet-140","question":"Which statement about PowerPoint transitions and animations is correct?","options":["Animations can be added only in Slide Master view","A transition applies to text boxes and an animation to whole slides","Both terms mean the same effect","A transition is an effect applied when moving from one slide to the next; an animation is applied to an object within a slide"],"answer":3,"explanation":"Transitions work between slides; animations make individual objects (text, pictures, charts) enter, exit or move. They are set from separate tabs.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"PowerPoint के ट्रांज़िशन और एनिमेशन के बारे में कौन-सा कथन सही है?","optionsHi":["एनिमेशन केवल Slide Master व्यू में जोड़े जा सकते हैं","ट्रांज़िशन टेक्स्ट बॉक्सों पर और एनिमेशन पूरी स्लाइडों पर लागू होता है","दोनों शब्दों का अर्थ एक ही प्रभाव है","ट्रांज़िशन एक स्लाइड से अगली स्लाइड पर जाते समय लगने वाला प्रभाव है; एनिमेशन स्लाइड के भीतर किसी ऑब्जेक्ट पर लागू होता है"],"explanationHi":"ट्रांज़िशन स्लाइडों के बीच काम करते हैं; एनिमेशन अलग-अलग ऑब्जेक्ट (पाठ, चित्र, चार्ट) को प्रवेश कराते, बाहर निकालते या चलाते हैं। इन्हें अलग-अलग टैब से सेट किया जाता है।"},
  {"id":"comp-ms-office-internet-141","question":"Match the protocol with its default port: 1. Telnet 2. IMAP 3. POP3 over SSL (POP3S) 4. RDP; a. 3389 b. 995 c. 23 d. 143","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":2,"explanation":"Telnet uses 23, IMAP 143, POP3S 995 and Remote Desktop Protocol 3389. Note that IMAPS (993) and POP3S (995) are easily confused.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"प्रोटोकॉल को उसके डिफ़ॉल्ट पोर्ट से सुमेलित कीजिए: 1. Telnet 2. IMAP 3. POP3 over SSL (POP3S) 4. RDP; a. 3389 b. 995 c. 23 d. 143","optionsHi":["1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"explanationHi":"Telnet 23 का, IMAP 143 का, POP3S 995 का और Remote Desktop Protocol 3389 का उपयोग करता है। ध्यान दें कि IMAPS (993) और POP3S (995) में आसानी से भ्रम हो जाता है।"},
  {"id":"comp-ms-office-internet-142","question":"Ignoring overheads, roughly how long will it take to download a 1 GB file (1 GB = 1024 MB) on a 20 Mbps connection?","options":["About 6.8 minutes","About 51 seconds","About 3.4 minutes","About 54 minutes"],"answer":0,"explanation":"1 GB = 1024 MB × 8 = 8192 megabits; 8192 ÷ 20 = 409.6 seconds ≈ 6.8 minutes. 51 seconds forgets to convert bytes into bits.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"अतिरिक्त भार (overheads) को अनदेखा करते हुए, 20 Mbps कनेक्शन पर 1 GB (1 GB = 1024 MB) की फ़ाइल डाउनलोड करने में लगभग कितना समय लगेगा?","optionsHi":["लगभग 6.8 मिनट","लगभग 51 सेकंड","लगभग 3.4 मिनट","लगभग 54 मिनट"],"explanationHi":"1 GB = 1024 MB × 8 = 8192 मेगाबिट; 8192 ÷ 20 = 409.6 सेकंड ≈ 6.8 मिनट। 51 सेकंड में बाइट को बिट में बदलना भूल जाया गया है।"},
  {"id":"comp-ms-office-internet-143","question":"Ravi wants to send a confidential file to Neha using public-key cryptography so that only Neha can read it. Which key should be used to encrypt the file?","options":["Neha's private key","Ravi's public key","Ravi's private key","Neha's public key"],"answer":3,"explanation":"For confidentiality, encrypt with the recipient's public key; only the recipient's private key can decrypt it. Encrypting with Ravi's private key is how a digital signature is made — it proves origin but anyone with Ravi's public key can read it.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"Ravi, Neha को सार्वजनिक-कुंजी क्रिप्टोग्राफ़ी से एक गोपनीय फ़ाइल भेजना चाहता है ताकि केवल Neha ही उसे पढ़ सके। फ़ाइल को एन्क्रिप्ट करने के लिए किस कुंजी का उपयोग करना चाहिए?","optionsHi":["Neha की निजी कुंजी","Ravi की सार्वजनिक कुंजी","Ravi की निजी कुंजी","Neha की सार्वजनिक कुंजी"],"explanationHi":"गोपनीयता के लिए प्राप्तकर्ता की सार्वजनिक कुंजी से एन्क्रिप्ट करें; केवल प्राप्तकर्ता की निजी कुंजी ही उसे डिक्रिप्ट कर सकती है। Ravi की निजी कुंजी से एन्क्रिप्ट करना डिजिटल हस्ताक्षर बनाने का तरीका है — यह उत्पत्ति सिद्ध करता है, पर Ravi की सार्वजनिक कुंजी वाला कोई भी उसे पढ़ सकता है।"},
  {"id":"comp-ms-office-internet-144","question":"To verify the digital signature on a document signed by a bank, the receiver uses:","options":["The bank's private key","The bank's public key","The receiver's private key","A shared secret password"],"answer":1,"explanation":"A signature is created with the signer's private key and verified with the signer's public key, usually obtained from a digital certificate issued by a Certifying Authority. The private key is never shared.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"किसी बैंक द्वारा हस्ताक्षरित दस्तावेज़ पर डिजिटल हस्ताक्षर सत्यापित करने के लिए प्राप्तकर्ता किसका उपयोग करता है?","optionsHi":["बैंक की निजी कुंजी","बैंक की सार्वजनिक कुंजी","प्राप्तकर्ता की निजी कुंजी","साझा गुप्त पासवर्ड"],"explanationHi":"हस्ताक्षर हस्ताक्षरकर्ता की निजी कुंजी से बनाया जाता है और हस्ताक्षरकर्ता की सार्वजनिक कुंजी से सत्यापित किया जाता है, जो सामान्यतः प्रमाणन प्राधिकरण (Certifying Authority) द्वारा जारी डिजिटल प्रमाणपत्र से प्राप्त होती है। निजी कुंजी कभी साझा नहीं की जाती।"},
  {"id":"comp-ms-office-internet-145","question":"How many hexadecimal characters long is a SHA-256 hash value when written out?","options":["32","64","256","128"],"answer":1,"explanation":"SHA-256 produces a 256-bit digest; each hex character represents 4 bits, so 256 ÷ 4 = 64 characters. 32 hex characters is the length of an MD5 (128-bit) hash.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"SHA-256 हैश मान लिखे जाने पर कितने हेक्साडेसिमल अक्षरों का होता है?","optionsHi":["32","64","256","128"],"explanationHi":"SHA-256 256-बिट का डाइजेस्ट बनाता है; प्रत्येक हेक्स अक्षर 4 बिट दर्शाता है, इसलिए 256 ÷ 4 = 64 अक्षर। 32 हेक्स अक्षर MD5 (128-बिट) हैश की लंबाई है।"},
  {"id":"comp-ms-office-internet-146","question":"How many of these statements about HTTPS are correct? I. It uses TLS to encrypt data between browser and server. II. Its default port is 443. III. The padlock icon proves the website belongs to a trustworthy organisation. IV. It hides the website address from the user's internet service provider.","options":["Only two","Only three","Only one","All four"],"answer":0,"explanation":"I and II are correct. III is wrong — the padlock only shows an encrypted connection with a valid certificate; phishing sites can have one too. IV is wrong — the ISP can still see which domain is visited (through DNS and the TLS handshake), even if not the page content.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"HTTPS के बारे में इनमें से कितने कथन सही हैं? I. यह ब्राउज़र और सर्वर के बीच डेटा को एन्क्रिप्ट करने के लिए TLS का उपयोग करता है। II. इसका डिफ़ॉल्ट पोर्ट 443 है। III. पैडलॉक आइकन सिद्ध करता है कि वेबसाइट किसी विश्वसनीय संगठन की है। IV. यह उपयोगकर्ता के इंटरनेट सेवा प्रदाता से वेबसाइट का पता छिपा देता है।","optionsHi":["केवल दो","केवल तीन","केवल एक","सभी चार"],"explanationHi":"I और II सही हैं। III गलत है — पैडलॉक केवल वैध प्रमाणपत्र के साथ एन्क्रिप्टेड कनेक्शन दिखाता है; फ़िशिंग साइटों के पास भी यह हो सकता है। IV गलत है — ISP अब भी देख सकता है कि कौन-सा डोमेन खोला गया (DNS और TLS हैंडशेक के ज़रिए), भले ही पेज की सामग्री न देख सके।"},
  {"id":"comp-ms-office-internet-147","question":"How many of these statements about browsing are correct? I. A private/incognito window does not save history or cookies after it is closed. II. Incognito mode hides your browsing from your employer's network. III. Third-party cookies are commonly used for cross-site ad tracking. IV. Clearing the browser cache removes saved copies of web pages and images.","options":["All four","Only two","Only three","Only one"],"answer":2,"explanation":"I, III and IV are correct. II is wrong: incognito mode only avoids storing data on the local device; the network administrator, ISP and the visited websites can still see the traffic.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"ब्राउज़िंग के बारे में इनमें से कितने कथन सही हैं? I. प्राइवेट/इन्कॉग्निटो विंडो बंद होने के बाद इतिहास या कुकी सहेजती नहीं है। II. इन्कॉग्निटो मोड आपकी ब्राउज़िंग को आपके नियोक्ता के नेटवर्क से छिपा देता है। III. थर्ड-पार्टी कुकी का उपयोग आम तौर पर साइटों के पार विज्ञापन ट्रैकिंग के लिए होता है। IV. ब्राउज़र कैश साफ़ करने से वेब पेजों और चित्रों की सहेजी गई प्रतियाँ हट जाती हैं।","optionsHi":["सभी चार","केवल दो","केवल तीन","केवल एक"],"explanationHi":"I, III और IV सही हैं। II गलत है: इन्कॉग्निटो मोड केवल स्थानीय उपकरण पर डेटा संग्रहीत करने से बचता है; नेटवर्क व्यवस्थापक, ISP और देखी गई वेबसाइटें अब भी ट्रैफ़िक देख सकती हैं।"},
  {"id":"comp-ms-office-internet-148","question":"Under the IT Act, 2000, which section prescribes punishment that may extend to imprisonment for life for cyber terrorism?","options":["Section 43","Section 66C","Section 66D","Section 66F"],"answer":3,"explanation":"Section 66F covers cyber terrorism, punishable with imprisonment up to life. 66C is identity theft and 66D cheating by personation using a computer resource; Section 43 provides compensation (a civil remedy), not imprisonment.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"IT अधिनियम, 2000 के अंतर्गत कौन-सी धारा साइबर आतंकवाद के लिए आजीवन कारावास तक के दंड का प्रावधान करती है?","optionsHi":["धारा 43","धारा 66C","धारा 66D","धारा 66F"],"explanationHi":"धारा 66F साइबर आतंकवाद को कवर करती है, जिसका दंड आजीवन कारावास तक है। 66C पहचान की चोरी है और 66D कंप्यूटर संसाधन द्वारा छद्मवेश से धोखाधड़ी है; धारा 43 मुआवज़े (दीवानी उपचार) का प्रावधान करती है, कारावास का नहीं।"},
  {"id":"comp-ms-office-internet-149","question":"A fraudster convinces a mobile operator to issue a new SIM for a victim's number, then uses the OTPs received on it to empty the victim's bank account. This is known as:","options":["SIM swap fraud","Vishing","Juice jacking","Pharming"],"answer":0,"explanation":"In SIM swap (SIM cloning) fraud the criminal takes control of the victim's number, so bank OTPs reach him. Vishing is fraud by phone call and needs the victim to reveal details; juice jacking uses USB charging ports.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कोई धोखेबाज़ मोबाइल ऑपरेटर को पीड़ित के नंबर के लिए नया सिम जारी करने के लिए मना लेता है, फिर उस पर प्राप्त OTP का उपयोग करके पीड़ित का बैंक खाता खाली कर देता है। इसे क्या कहते हैं?","optionsHi":["सिम स्वैप धोखाधड़ी (SIM swap fraud)","विशिंग (Vishing)","जूस जैकिंग (Juice jacking)","फ़ार्मिंग (Pharming)"],"explanationHi":"सिम स्वैप (सिम क्लोनिंग) धोखाधड़ी में अपराधी पीड़ित के नंबर पर नियंत्रण पा लेता है, इसलिए बैंक OTP उसी तक पहुँचते हैं। विशिंग फ़ोन कॉल द्वारा धोखाधड़ी है और इसमें पीड़ित से विवरण बताने की ज़रूरत होती है; जूस जैकिंग USB चार्जिंग पोर्ट का उपयोग करती है।"},
  {"id":"comp-ms-office-internet-150","question":"Assertion (A): A firewall alone cannot protect a user who opens a malicious e-mail attachment. Reason (R): A firewall filters network traffic by rules, but the attachment arrives through permitted e-mail traffic and runs on the user's machine.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A firewall allows e-mail traffic because it is legitimate; the malicious code runs only when the user opens it. That is exactly why A holds, so R explains A. Antivirus and user awareness are needed in addition.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"अभिकथन (A): कोई फ़ायरवॉल अकेले उस उपयोगकर्ता की रक्षा नहीं कर सकता जो दुर्भावनापूर्ण ई-मेल अटैचमेंट खोलता है। कारण (R): फ़ायरवॉल नियमों के आधार पर नेटवर्क ट्रैफ़िक फ़िल्टर करता है, पर अटैचमेंट अनुमत ई-मेल ट्रैफ़िक के ज़रिए आता है और उपयोगकर्ता की मशीन पर चलता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है लेकिन R असत्य है","A असत्य है लेकिन R सत्य है"],"explanationHi":"फ़ायरवॉल ई-मेल ट्रैफ़िक की अनुमति देता है क्योंकि वह वैध है; दुर्भावनापूर्ण कोड तभी चलता है जब उपयोगकर्ता उसे खोलता है। यही कारण है कि A सही है, इसलिए R, A की व्याख्या करता है। इसके अतिरिक्त एंटीवायरस और उपयोगकर्ता की जागरूकता चाहिए।"},
  {"id":"comp-ms-office-internet-151","question":"What does the Excel formula =MROUND(17, 5) return?","options":["20","3","17","15"],"answer":3,"explanation":"MROUND rounds to the NEAREST multiple of 5. 17 is 2 away from 15 and 3 away from 20, so the result is 15. 3 is just how many times 5 fits into 17.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =MROUND(17, 5) क्या लौटाता है?","optionsHi":["20","3","17","15"],"explanationHi":"MROUND 5 के निकटतम गुणज तक पूर्णांकित करता है। 17, 15 से 2 दूर है और 20 से 3 दूर है, इसलिए परिणाम 15 है। 3 केवल यह है कि 17 में 5 कितनी बार समाता है।"},
  {"id":"comp-ms-office-internet-152","question":"What does the Excel formula =CEILING(4.1, 2) + FLOOR(7.9, 2) return?","options":["12","14","10","11"],"answer":0,"explanation":"CEILING(4.1, 2) rounds up to the next multiple of 2, giving 6; FLOOR(7.9, 2) rounds down to a multiple of 2, giving 6; so 6 + 6 = 12. Rounding 7.9 up to 8 gives 14, rounding 4.1 down to 4 gives 10, and treating CEILING as a plain round-up to a whole number (5) gives 11.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =CEILING(4.1, 2) + FLOOR(7.9, 2) क्या लौटाता है?","optionsHi":["12","14","10","11"],"explanationHi":"CEILING(4.1, 2) 2 के अगले गुणज तक ऊपर पूर्णांकित करता है, जिससे 6 मिलता है; FLOOR(7.9, 2) 2 के गुणज तक नीचे पूर्णांकित करता है, जिससे 6 मिलता है; इसलिए 6 + 6 = 12। 7.9 को ऊपर 8 करने पर 14, 4.1 को नीचे 4 करने पर 10, और CEILING को पूर्ण संख्या (5) तक साधारण ऊपर-पूर्णांकन मानने पर 11 मिलता है।"},
  {"id":"comp-ms-office-internet-153","question":"In Excel, A1 = 10, A2 is empty, A3 = 0 and A4 = 20. What does =AVERAGE(A1:A4) return?","options":["7.5","15","10","#DIV/0!"],"answer":2,"explanation":"AVERAGE ignores empty cells but counts a 0 as a value, so it gives (10 + 0 + 20) ÷ 3 = 10. 7.5 treats the blank as 0; 15 ignores the zero as well.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1 = 10 है, A2 रिक्त है, A3 = 0 है और A4 = 20 है। =AVERAGE(A1:A4) क्या लौटाता है?","optionsHi":["7.5","15","10","#DIV/0!"],"explanationHi":"AVERAGE रिक्त सेलों को अनदेखा करता है पर 0 को मान के रूप में गिनता है, इसलिए यह (10 + 0 + 20) ÷ 3 = 10 देता है। 7.5 रिक्त को 0 मानता है; 15 शून्य को भी अनदेखा कर देता है।"},
  {"id":"comp-ms-office-internet-154","question":"In Excel, A1 = 5, A2 = Yes, A3 is empty, A4 holds the formula =\"\", A5 = 0 and A6 is empty. What do =COUNTA(A1:A6) and =COUNTBLANK(A1:A6) return?","options":["3 and 3","4 and 2","3 and 2","4 and 3"],"answer":3,"explanation":"COUNTA counts every non-empty cell, and A4 contains a formula, so 5, Yes, the formula and 0 make 4. COUNTBLANK counts truly empty cells AND cells showing empty text, so A3, A4 and A6 make 3; a 0 is not blank.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1 = 5 है, A2 = Yes है, A3 रिक्त है, A4 में सूत्र =\"\" है, A5 = 0 है और A6 रिक्त है। =COUNTA(A1:A6) और =COUNTBLANK(A1:A6) क्रमशः क्या लौटाते हैं?","optionsHi":["3 और 3","4 और 2","3 और 2","4 और 3"],"explanationHi":"COUNTA हर गैर-रिक्त सेल गिनता है, और A4 में सूत्र है, इसलिए 5, Yes, सूत्र और 0 मिलकर 4 होते हैं। COUNTBLANK वास्तव में रिक्त सेल और रिक्त पाठ दिखाने वाले सेल दोनों गिनता है, इसलिए A3, A4 और A6 मिलकर 3 होते हैं; 0 रिक्त नहीं है।"},
  {"id":"comp-ms-office-internet-155","question":"What does the Excel formula =SUBSTITUTE(\"banana\", \"a\", \"o\", 2) return?","options":["bonono","banona","bonana","banano"],"answer":1,"explanation":"The fourth argument tells SUBSTITUTE to change only the 2nd occurrence of 'a', which is the one after 'ban', giving banona. Without that argument every 'a' would change (bonono).","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =SUBSTITUTE(\"banana\", \"a\", \"o\", 2) क्या लौटाता है?","optionsHi":["bonono","banona","bonana","banano"],"explanationHi":"चौथा तर्क SUBSTITUTE को केवल 'a' की दूसरी बार आने वाली घटना बदलने को कहता है, जो 'ban' के बाद वाली है, जिससे banona मिलता है। इस तर्क के बिना हर 'a' बदल जाता (bonono)।"},
  {"id":"comp-ms-office-internet-156","question":"What does the Excel formula =REPLACE(\"ABCDEF\", 2, 3, \"x\") return?","options":["AxCDEF","AxDEF","ABxEF","AxEF"],"answer":3,"explanation":"REPLACE removes 3 characters starting at position 2 (B, C, D) and puts 'x' in their place: A + x + EF = AxEF. It works by position, unlike SUBSTITUTE, which works by matching text.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =REPLACE(\"ABCDEF\", 2, 3, \"x\") क्या लौटाता है?","optionsHi":["AxCDEF","AxDEF","ABxEF","AxEF"],"explanationHi":"REPLACE स्थिति 2 से शुरू करके 3 अक्षर (B, C, D) हटाता है और उनकी जगह 'x' रखता है: A + x + EF = AxEF। यह स्थिति के आधार पर काम करता है, जबकि SUBSTITUTE पाठ के मिलान के आधार पर।"},
  {"id":"comp-ms-office-internet-157","question":"A user types =1+1=2 into an Excel cell. What does the cell show?","options":["TRUE","2","FALSE","#VALUE!"],"answer":0,"explanation":"The first = starts the formula; arithmetic is done before comparison, so 1+1 gives 2 and then 2=2 is tested, which gives TRUE.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"कोई उपयोगकर्ता Excel सेल में =1+1=2 टाइप करता है। सेल क्या दिखाता है?","optionsHi":["TRUE","2","FALSE","#VALUE!"],"explanationHi":"पहला = सूत्र शुरू करता है; तुलना से पहले अंकगणित होता है, इसलिए 1+1 से 2 मिलता है और फिर 2=2 की जाँच होती है, जो TRUE देती है।"},
  {"id":"comp-ms-office-internet-158","question":"1 January 2024 was a Monday. What does =WEEKDAY(DATE(2024, 1, 1)) return in Excel?","options":["1","2","0","7"],"answer":1,"explanation":"With no second argument, WEEKDAY numbers the days from Sunday = 1 to Saturday = 7, so Monday is 2. Getting 1 assumes the week starts on Monday.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"1 जनवरी 2024 सोमवार था। Excel में =WEEKDAY(DATE(2024, 1, 1)) क्या लौटाता है?","optionsHi":["1","2","0","7"],"explanationHi":"दूसरे तर्क के बिना WEEKDAY दिनों को रविवार = 1 से शनिवार = 7 तक क्रमांकित करता है, इसलिए सोमवार 2 है। 1 मिलना यह मानना है कि सप्ताह सोमवार से शुरू होता है।"},
  {"id":"comp-ms-office-internet-159","question":"What date does the Excel formula =EDATE(DATE(2024, 1, 31), 1) return?","options":["2 March 2024","28 February 2024","29 February 2024","#VALUE!, because 31 February does not exist"],"answer":2,"explanation":"EDATE moves the date by whole months and, when the day does not exist, uses the last day of the target month. February 2024 has 29 days (leap year), so the result is 29 February 2024. DATE(2024,2,31) would roll over to 2 March instead.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =EDATE(DATE(2024, 1, 31), 1) कौन-सी तारीख़ लौटाता है?","optionsHi":["2 मार्च 2024","28 फ़रवरी 2024","29 फ़रवरी 2024","#VALUE!, क्योंकि 31 फ़रवरी मौजूद नहीं है"],"explanationHi":"EDATE तारीख़ को पूरे महीनों से खिसकाता है और जब वह दिन मौजूद नहीं होता, तो लक्ष्य महीने का अंतिम दिन लेता है। फ़रवरी 2024 में 29 दिन हैं (अधिवर्ष), इसलिए परिणाम 29 फ़रवरी 2024 है। DATE(2024,2,31) बदले में 2 मार्च पर चला जाता।"},
  {"id":"comp-ms-office-internet-160","question":"What date does the Excel formula =EOMONTH(DATE(2023, 2, 10), 0) return?","options":["31 January 2023","28 February 2023","29 February 2023","31 March 2023"],"answer":1,"explanation":"EOMONTH gives the last day of the month that is the given number of months away; 0 means the same month, February 2023, whose last day is the 28th because 2023 is not a leap year. An offset of −1 would give 31 January.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =EOMONTH(DATE(2023, 2, 10), 0) कौन-सी तारीख़ लौटाता है?","optionsHi":["31 जनवरी 2023","28 फ़रवरी 2023","29 फ़रवरी 2023","31 मार्च 2023"],"explanationHi":"EOMONTH दिए गए महीनों की संख्या दूर वाले महीने का अंतिम दिन देता है; 0 का अर्थ वही महीना, फ़रवरी 2023, है, जिसका अंतिम दिन 28 है क्योंकि 2023 अधिवर्ष नहीं है। ऑफ़सेट −1 होने पर 31 जनवरी मिलती।"},
  {"id":"comp-ms-office-internet-161","question":"A cell contains the number 0.75 and is then formatted as a time. What does it show?","options":["7:30 AM","9:00 AM","6:00 PM","7:50 PM"],"answer":2,"explanation":"Excel stores a time as a fraction of a 24-hour day: 0.75 × 24 = 18 hours, i.e. 6:00 PM. 7:30 reads the decimal digits as hours and minutes.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी सेल में संख्या 0.75 है और फिर उसे समय के रूप में फ़ॉर्मेट किया जाता है। वह क्या दिखाता है?","optionsHi":["7:30 AM","9:00 AM","6:00 PM","7:50 PM"],"explanationHi":"Excel समय को 24 घंटे के दिन के अंश के रूप में संग्रहीत करता है: 0.75 × 24 = 18 घंटे, अर्थात 6:00 PM। 7:30 दशमलव अंकों को घंटे और मिनट पढ़ लेता है।"},
  {"id":"comp-ms-office-internet-162","question":"Column A holds regions and column C holds sales for rows 2 to 10. Which formula correctly totals the sales of the 'North' region?","options":["=SUMIF(C2:C10, \"North\", A2:A10)","=SUMIFS(A2:A10, \"North\", C2:C10)","=SUMIFS(C2:C10, \"North\", A2:A10)","=SUMIF(A2:A10, \"North\", C2:C10)"],"answer":3,"explanation":"SUMIF takes (criteria range, criteria, sum range). SUMIFS puts the sum range FIRST and then pairs of (criteria range, criteria), so a correct SUMIFS would be =SUMIFS(C2:C10, A2:A10, \"North\"); both SUMIFS options given break that order.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"कॉलम A में क्षेत्र हैं और कॉलम C में पंक्ति 2 से 10 तक बिक्री है। कौन-सा सूत्र 'North' क्षेत्र की बिक्री का सही योग करता है?","optionsHi":["=SUMIF(C2:C10, \"North\", A2:A10)","=SUMIFS(A2:A10, \"North\", C2:C10)","=SUMIFS(C2:C10, \"North\", A2:A10)","=SUMIF(A2:A10, \"North\", C2:C10)"],"explanationHi":"SUMIF (मानदंड रेंज, मानदंड, योग रेंज) लेता है। SUMIFS में योग रेंज पहले आती है और फिर (मानदंड रेंज, मानदंड) के जोड़े, इसलिए सही SUMIFS =SUMIFS(C2:C10, A2:A10, \"North\") होता; दिए गए दोनों SUMIFS विकल्प इस क्रम को तोड़ते हैं।"},
  {"id":"comp-ms-office-internet-163","question":"The lookup value 'X' does exist in the first column of A1:C10. What does =VLOOKUP(\"X\", A1:C10, 4, FALSE) return?","options":["#N/A","The value in column D of the matching row","#REF!","#VALUE!"],"answer":2,"explanation":"The table A1:C10 has only 3 columns, so asking for column 4 points outside it and gives #REF!. #N/A appears only when the lookup value cannot be found.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"खोज मान 'X' A1:C10 के पहले कॉलम में मौजूद है। =VLOOKUP(\"X\", A1:C10, 4, FALSE) क्या लौटाता है?","optionsHi":["#N/A","मिलान वाली पंक्ति के कॉलम D का मान","#REF!","#VALUE!"],"explanationHi":"तालिका A1:C10 में केवल 3 कॉलम हैं, इसलिए कॉलम 4 माँगना उसके बाहर इंगित करता है और #REF! देता है। #N/A तभी आता है जब खोज मान न मिले।"},
  {"id":"comp-ms-office-internet-164","question":"Match each Excel formula with the error it gives: 1. =10/0 2. =\"abc\"*2 3. =SQRT(-1) 4. =MATCH(\"Z\", {\"A\",\"B\"}, 0); a. #NUM! b. #N/A c. #DIV/0! d. #VALUE!","options":["1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"Division by zero gives #DIV/0!, arithmetic on text gives #VALUE!, an impossible numeric result such as the square root of a negative gives #NUM!, and an exact match that is not found gives #N/A.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"प्रत्येक Excel सूत्र को उसकी देने वाली त्रुटि से सुमेलित कीजिए: 1. =10/0 2. =\"abc\"*2 3. =SQRT(-1) 4. =MATCH(\"Z\", {\"A\",\"B\"}, 0); a. #NUM! b. #N/A c. #DIV/0! d. #VALUE!","optionsHi":["1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"explanationHi":"शून्य से भाग #DIV/0! देता है, पाठ पर अंकगणित #VALUE! देता है, ऋणात्मक संख्या के वर्गमूल जैसा असंभव संख्यात्मक परिणाम #NUM! देता है, और न मिलने वाला सटीक मिलान #N/A देता है।"},
  {"id":"comp-ms-office-internet-165","question":"In Excel, A1 = 2 and A2 = 5. Both cells are selected and the fill handle is dragged down to A5. What value appears in A5?","options":["11","5","14","17"],"answer":2,"explanation":"With two cells selected, Excel continues their step (+3): 2, 5, 8, 11, 14, so A5 = 14. 5 would appear only if a single cell were copied down.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1 = 2 और A2 = 5 है। दोनों सेल चयनित हैं और फ़िल हैंडल को A5 तक नीचे खींचा जाता है। A5 में कौन-सा मान दिखता है?","optionsHi":["11","5","14","17"],"explanationHi":"दो सेल चयनित होने पर Excel उनके अंतर (+3) को आगे बढ़ाता है: 2, 5, 8, 11, 14, इसलिए A5 = 14। 5 तभी दिखता जब केवल एक सेल को नीचे कॉपी किया जाता।"},
  {"id":"comp-ms-office-internet-166","question":"In Excel, A1 contains the text 'Jan'. Its fill handle is dragged down to A14. What does A14 contain?","options":["Jan","Mar","Dec","Feb"],"answer":3,"explanation":"Excel recognises month names as a built-in list and repeats it: A1–A12 run Jan to Dec, A13 is Jan again and A14 is Feb.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1 में पाठ 'Jan' है। उसके फ़िल हैंडल को A14 तक नीचे खींचा जाता है। A14 में क्या होगा?","optionsHi":["Jan","Mar","Dec","Feb"],"explanationHi":"Excel माह के नामों को अंतर्निहित सूची के रूप में पहचानता है और उसे दोहराता है: A1–A12 में Jan से Dec आते हैं, A13 फिर Jan है और A14 Feb है।"},
  {"id":"comp-ms-office-internet-167","question":"A workbook has sheets named Jan, Feb, Mar and Apr in that tab order. What does =SUM(Jan:Mar!B5) add up?","options":["Cell B5 on the Jan, Feb and Mar sheets","Cells B5 on the Jan and Mar sheets only","All cells from Jan!A1 to Mar!B5","Cell B5 on every sheet in the workbook"],"answer":0,"explanation":"Jan:Mar!B5 is a 3-D reference: the same cell, B5, on every sheet from Jan to Mar in tab order, including Feb in between. Apr lies outside the range.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक वर्कबुक में शीट Jan, Feb, Mar और Apr इसी टैब क्रम में हैं। =SUM(Jan:Mar!B5) किसका योग करता है?","optionsHi":["Jan, Feb और Mar शीटों का सेल B5","केवल Jan और Mar शीटों का सेल B5","Jan!A1 से Mar!B5 तक के सभी सेल","वर्कबुक की हर शीट का सेल B5"],"explanationHi":"Jan:Mar!B5 त्रि-आयामी (3-D) संदर्भ है: टैब क्रम में Jan से Mar तक हर शीट का वही सेल B5, बीच की Feb सहित। Apr इस रेंज के बाहर है।"},
  {"id":"comp-ms-office-internet-168","question":"In an Excel sheet, what does the shortcut Ctrl + End do?","options":["Moves to the last cell of the used range: the last used row and last used column","Moves to cell A1","Moves to row 1,048,576 of the current column","Moves to the end of the text inside the current cell"],"answer":0,"explanation":"Ctrl + End jumps to the bottom-right corner of the area that has ever held data; Ctrl + Home goes back to A1. Editing within a cell uses End on its own.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel शीट में शॉर्टकट Ctrl + End क्या करता है?","optionsHi":["प्रयुक्त रेंज के अंतिम सेल पर ले जाता है: अंतिम प्रयुक्त पंक्ति और अंतिम प्रयुक्त कॉलम","सेल A1 पर ले जाता है","वर्तमान कॉलम की पंक्ति 1,048,576 पर ले जाता है","वर्तमान सेल के भीतर पाठ के अंत पर ले जाता है"],"explanationHi":"Ctrl + End उस क्षेत्र के निचले-दाएँ कोने पर पहुँचाता है जिसमें कभी डेटा रहा हो; Ctrl + Home वापस A1 पर ले जाता है। सेल के भीतर संपादन में केवल End का उपयोग होता है।"},
  {"id":"comp-ms-office-internet-169","question":"A user types '123 (with a leading apostrophe) into an Excel cell. What happens?","options":["The cell shows '123 and is treated as a formula","123 is stored as text and is left-aligned by default","123 is stored as a number and is right-aligned","Excel shows a #VALUE! error"],"answer":1,"explanation":"A leading apostrophe makes Excel store the entry as text; the apostrophe is hidden, and text is left-aligned by default while numbers align to the right.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"कोई उपयोगकर्ता Excel सेल में '123 (आरंभ में एपॉस्ट्रॉफ़ के साथ) टाइप करता है। क्या होता है?","optionsHi":["सेल '123 दिखाता है और उसे सूत्र माना जाता है","123 पाठ के रूप में संग्रहीत होता है और डिफ़ॉल्ट रूप से बाईं ओर संरेखित होता है","123 संख्या के रूप में संग्रहीत होता है और दाईं ओर संरेखित होता है","Excel #VALUE! त्रुटि दिखाता है"],"explanationHi":"आरंभ का एपॉस्ट्रॉफ़ Excel को प्रविष्टि पाठ के रूप में संग्रहीत करने को कहता है; एपॉस्ट्रॉफ़ छिपा रहता है, और पाठ डिफ़ॉल्ट रूप से बाईं ओर संरेखित होता है जबकि संख्याएँ दाईं ओर।"},
  {"id":"comp-ms-office-internet-170","question":"In Excel's standard (1900) date system, a cell containing the number 45 is formatted as a date. Which date does it show?","options":["45 days after today","15 February 1900","14 February 1900","1 January 1945"],"answer":2,"explanation":"Dates are serial numbers with 1 = 1 January 1900. Serial 31 is 31 January, so serial 45 is 14 days into February: 14 February 1900. 15 February is the off-by-one trap of counting from serial 0.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel की मानक (1900) तिथि प्रणाली में, संख्या 45 वाला सेल तिथि के रूप में फ़ॉर्मेट किया जाता है। वह कौन-सी तिथि दिखाता है?","optionsHi":["आज से 45 दिन बाद","15 फ़रवरी 1900","14 फ़रवरी 1900","1 जनवरी 1945"],"explanationHi":"तिथियाँ क्रमांक होती हैं जिनमें 1 = 1 जनवरी 1900। क्रमांक 31 31 जनवरी है, इसलिए क्रमांक 45 फ़रवरी में 14 दिन आगे है: 14 फ़रवरी 1900। 15 फ़रवरी क्रमांक 0 से गिनने की एक-अंक की चूक वाला जाल है।"},
  {"id":"comp-ms-office-internet-171","question":"What does the Excel formula =INT(-3.5) return?","options":["−3","−4","−3.5","#NUM!, because INT needs a positive number"],"answer":1,"explanation":"INT rounds DOWN to the next smaller integer, and for negatives that means away from zero: −3.5 becomes −4. TRUNC(−3.5) would just cut off the decimal and give −3; INT accepts negative numbers.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =INT(-3.5) क्या लौटाता है?","optionsHi":["−3","−4","−3.5","#NUM!, क्योंकि INT को धनात्मक संख्या चाहिए"],"explanationHi":"INT अगले छोटे पूर्णांक तक नीचे पूर्णांकित करता है, और ऋणात्मक संख्याओं के लिए इसका अर्थ शून्य से दूर जाना है: −3.5 बदलकर −4 हो जाता है। TRUNC(−3.5) केवल दशमलव काट देता और −3 देता; INT ऋणात्मक संख्याएँ स्वीकार करता है।"},
  {"id":"comp-ms-office-internet-172","question":"What does the Excel formula =ROUND(-2.5, 0) return?","options":["−2","−2.5","−3","#NUM!"],"answer":2,"explanation":"Excel's ROUND sends an exact half away from zero, so −2.5 becomes −3. −2 is the trap from 'round half to even' (banker's rounding), which ROUND does not use; negative numbers are allowed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =ROUND(-2.5, 0) क्या लौटाता है?","optionsHi":["−2","−2.5","−3","#NUM!"],"explanationHi":"Excel का ROUND ठीक आधे को शून्य से दूर भेजता है, इसलिए −2.5 बदलकर −3 हो जाता है। −2 'सम की ओर पूर्णांकन' (बैंकर्स राउंडिंग) का जाल है, जिसका ROUND उपयोग नहीं करता; ऋणात्मक संख्याएँ मान्य हैं।"},
  {"id":"comp-ms-office-internet-173","question":"What does the Excel formula =EVEN(-3) + ODD(4) return?","options":["3","1","9","#NUM!"],"answer":1,"explanation":"EVEN and ODD round AWAY from zero: EVEN(−3) = −4 and ODD(4) = 5, so the sum is 1. Rounding −3 towards zero to −2 gives the trap 3; both functions accept negative numbers.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =EVEN(-3) + ODD(4) क्या लौटाता है?","optionsHi":["3","1","9","#NUM!"],"explanationHi":"EVEN और ODD शून्य से दूर पूर्णांकित करते हैं: EVEN(−3) = −4 और ODD(4) = 5, इसलिए योग 1 है। −3 को शून्य की ओर −2 तक पूर्णांकित करने पर जाल वाला उत्तर 3 मिलता है; दोनों फ़ंक्शन ऋणात्मक संख्याएँ स्वीकार करते हैं।"},
  {"id":"comp-ms-office-internet-174","question":"What does the Excel formula =EXACT(PROPER(\"rAM kUMAR\"), \"Ram Kumar\") return?","options":["FALSE","Ram Kumar","TRUE","#VALUE!"],"answer":2,"explanation":"PROPER turns 'rAM kUMAR' into 'Ram Kumar' (first letter of each word capital, the rest small). EXACT is case-sensitive and returns TRUE because the two texts now match exactly.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =EXACT(PROPER(\"rAM kUMAR\"), \"Ram Kumar\") क्या लौटाता है?","optionsHi":["FALSE","Ram Kumar","TRUE","#VALUE!"],"explanationHi":"PROPER 'rAM kUMAR' को 'Ram Kumar' बना देता है (हर शब्द का पहला अक्षर बड़ा, बाकी छोटे)। EXACT अक्षर-संवेदी है और TRUE लौटाता है क्योंकि अब दोनों पाठ ठीक-ठीक मेल खाते हैं।"},
  {"id":"comp-ms-office-internet-175","question":"A commission rate is stored in F1. The formula =B2*F1 must be copied both down the column and across to other columns, always using F1. How should F1 be written?","options":["Row locked only: F$1","Column locked only: $F1","Fully relative: F1","Fully absolute: $F$1"],"answer":3,"explanation":"Copying down changes the row and copying across changes the column, so both must be locked: $F$1. F$1 locks only the row and would drift to G1, H1 when copied across.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"कमीशन दर F1 में संग्रहीत है। सूत्र =B2*F1 को कॉलम में नीचे और अन्य कॉलमों की ओर आड़े, दोनों तरह कॉपी करना है, और हर बार F1 ही उपयोग होना चाहिए। F1 को कैसे लिखा जाना चाहिए?","optionsHi":["केवल पंक्ति लॉक: F$1","केवल कॉलम लॉक: $F1","पूर्णतः सापेक्ष: F1","पूर्णतः निरपेक्ष: $F$1"],"explanationHi":"नीचे कॉपी करने पर पंक्ति बदलती है और आड़े कॉपी करने पर कॉलम बदलता है, इसलिए दोनों लॉक होने चाहिए: $F$1। F$1 केवल पंक्ति लॉक करता है और आड़े कॉपी करने पर G1, H1 की ओर खिसक जाता।"},
  {"id":"comp-ms-office-internet-176","question":"In MS Word, which shortcut formats the selected text as superscript, as for the '2' in x²?","options":["Ctrl + Shift + =","Ctrl + =","Ctrl + Shift + S","Alt + Shift + ="],"answer":0,"explanation":"Ctrl + Shift + = (Ctrl + plus) makes superscript, while Ctrl + = makes subscript, as in H₂O. Pressing the same shortcut again removes the formatting.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"MS Word में कौन-सा शॉर्टकट चयनित टेक्स्ट को उर्ध्वलेख (superscript) के रूप में फ़ॉर्मेट करता है, जैसे x² में '2'?","optionsHi":["Ctrl + Shift + =","Ctrl + =","Ctrl + Shift + S","Alt + Shift + ="],"explanationHi":"Ctrl + Shift + = (Ctrl + प्लस) उर्ध्वलेख बनाता है, जबकि Ctrl + = अधोलेख बनाता है, जैसे H₂O में। वही शॉर्टकट दोबारा दबाने पर फ़ॉर्मेटिंग हट जाती है।"},
  {"id":"comp-ms-office-internet-177","question":"In MS Word, the text 'Rbi Policy' is selected and the All Caps format (Ctrl + Shift + A) is applied. What happens?","options":["The letters are permanently retyped as capitals, like using Caps Lock","It shows as RBI POLICY, but the stored text is unchanged, so removing the format brings back 'Rbi Policy'","The text changes to small capitals","Each press cycles the case through lower, UPPER and Title Case"],"answer":1,"explanation":"All Caps is a character FORMAT: the display changes but the typed letters stay as they were. Shift + F3 is the command that actually changes the case and cycles through the options.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"MS Word में टेक्स्ट 'Rbi Policy' चयनित है और All Caps फ़ॉर्मेट (Ctrl + Shift + A) लागू किया जाता है। क्या होता है?","optionsHi":["अक्षर स्थायी रूप से Caps Lock की तरह बड़े अक्षरों में दोबारा टाइप हो जाते हैं","यह RBI POLICY दिखता है, पर संग्रहीत पाठ नहीं बदलता, इसलिए फ़ॉर्मेट हटाने पर 'Rbi Policy' लौट आता है","टेक्स्ट छोटे कैपिटल (small capitals) में बदल जाता है","हर बार दबाने पर केस lower, UPPER और Title Case के बीच बदलता है"],"explanationHi":"All Caps एक अक्षर फ़ॉर्मेट है: प्रदर्शन बदलता है पर टाइप किए गए अक्षर जैसे थे वैसे रहते हैं। Shift + F3 वह आदेश है जो वास्तव में केस बदलता है और विकल्पों में घूमता है।"},
  {"id":"comp-ms-office-internet-178","question":"In MS Word, which shortcut removes the manual paragraph formatting of a paragraph (such as extra indents and spacing) while leaving its bold and italic character formatting untouched?","options":["Ctrl + Space","Ctrl + E","Ctrl + Z","Ctrl + Q"],"answer":3,"explanation":"Ctrl + Q resets direct paragraph formatting; Ctrl + Space resets direct CHARACTER formatting such as bold and italic. Ctrl + E centres the paragraph, and Ctrl + Z undoes only the last action.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"MS Word में कौन-सा शॉर्टकट किसी अनुच्छेद की मैन्युअल अनुच्छेद फ़ॉर्मेटिंग (जैसे अतिरिक्त इंडेंट और अंतराल) हटाता है, जबकि उसके बोल्ड और इटैलिक अक्षर फ़ॉर्मेटिंग को अछूता छोड़ देता है?","optionsHi":["Ctrl + Space","Ctrl + E","Ctrl + Z","Ctrl + Q"],"explanationHi":"Ctrl + Q सीधी अनुच्छेद फ़ॉर्मेटिंग रीसेट करता है; Ctrl + Space बोल्ड और इटैलिक जैसी सीधी अक्षर फ़ॉर्मेटिंग रीसेट करता है। Ctrl + E अनुच्छेद को केंद्र में संरेखित करता है, और Ctrl + Z केवल अंतिम क्रिया को पूर्ववत करता है।"},
  {"id":"comp-ms-office-internet-179","question":"What does the shortcut Ctrl + T do to the current paragraph in MS Word?","options":["Creates a hanging indent","Inserts a table","Opens the Tabs dialog box","Turns Track Changes on"],"answer":0,"explanation":"In Word, Ctrl + T gives a hanging indent (all lines except the first move in); Ctrl + M indents the whole paragraph. The trap is Excel, where Ctrl + T turns a range into a table.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"MS Word में शॉर्टकट Ctrl + T वर्तमान अनुच्छेद के साथ क्या करता है?","optionsHi":["हैंगिंग इंडेंट बनाता है","तालिका डालता है","Tabs डायलॉग बॉक्स खोलता है","Track Changes चालू करता है"],"explanationHi":"Word में Ctrl + T हैंगिंग इंडेंट देता है (पहली पंक्ति को छोड़कर सभी पंक्तियाँ भीतर चली जाती हैं); Ctrl + M पूरे अनुच्छेद को इंडेंट करता है। जाल Excel है, जहाँ Ctrl + T रेंज को तालिका में बदलता है।"},
  {"id":"comp-ms-office-internet-180","question":"In a Word document, '₹ 500' keeps splitting so that '₹' ends one line and '500' starts the next. Which shortcut should be used in place of the ordinary space to keep them together?","options":["Shift + Enter","Ctrl + Space","Ctrl + Shift + Space","Ctrl + Enter"],"answer":2,"explanation":"Ctrl + Shift + Space inserts a non-breaking space, which Word never breaks across lines. Shift + Enter forces a line break, Ctrl + Space clears character formatting, and Ctrl + Enter inserts a page break.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Word दस्तावेज़ में '₹ 500' बार-बार इस तरह बँट जाता है कि '₹' एक पंक्ति के अंत में और '500' अगली पंक्ति के आरंभ में आता है। उन्हें साथ रखने के लिए साधारण रिक्त स्थान की जगह कौन-सा शॉर्टकट उपयोग करना चाहिए?","optionsHi":["Shift + Enter","Ctrl + Space","Ctrl + Shift + Space","Ctrl + Enter"],"explanationHi":"Ctrl + Shift + Space नॉन-ब्रेकिंग स्पेस डालता है, जिसे Word पंक्तियों के बीच कभी नहीं तोड़ता। Shift + Enter लाइन ब्रेक बलपूर्वक डालता है, Ctrl + Space अक्षर फ़ॉर्मेटिंग साफ़ करता है, और Ctrl + Enter पेज ब्रेक डालता है।"},
  {"id":"comp-ms-office-internet-181","question":"A user wants to copy the formatting of one heading onto several other headings scattered through a long Word document. What is the quickest way with Format Painter?","options":["Double-click Format Painter so it stays on, click each heading, then press Esc","Single-click Format Painter once and it stays on until the document is closed","Single-click Format Painter separately before each heading; double-clicking does nothing","Select all the headings first and then click Format Painter"],"answer":0,"explanation":"A single click applies the formatting once and then switches off; a double click locks Format Painter on for repeated use until Esc is pressed or the button is clicked again.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"एक उपयोगकर्ता किसी लंबे Word दस्तावेज़ में बिखरे कई अन्य शीर्षकों पर एक शीर्षक की फ़ॉर्मेटिंग कॉपी करना चाहता है। Format Painter से सबसे तेज़ तरीका क्या है?","optionsHi":["Format Painter पर डबल-क्लिक करें ताकि वह चालू रहे, हर शीर्षक पर क्लिक करें, फिर Esc दबाएँ","Format Painter पर एक बार क्लिक करें और वह दस्तावेज़ बंद होने तक चालू रहता है","हर शीर्षक से पहले अलग-अलग Format Painter पर सिंगल-क्लिक करें; डबल-क्लिक कुछ नहीं करता","पहले सभी शीर्षक चयनित करें और फिर Format Painter पर क्लिक करें"],"explanationHi":"एक क्लिक फ़ॉर्मेटिंग को एक बार लागू करके बंद हो जाता है; डबल क्लिक Format Painter को बार-बार उपयोग के लिए तब तक चालू रखता है जब तक Esc दबाया न जाए या बटन फिर क्लिक न किया जाए।"},
  {"id":"comp-ms-office-internet-182","question":"Word's automatic Table of Contents picks up its entries mainly from:","options":["All text formatted in bold","Paragraphs formatted with the built-in Heading styles","Bookmarks inserted in the document","Any text whose font size is larger than 14 points"],"answer":1,"explanation":"The automatic TOC is built from Heading 1, Heading 2 and similar styles (outline levels), so headings that only LOOK big and bold but use no heading style are missed.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Word की स्वचालित विषय-सूची (Table of Contents) अपनी प्रविष्टियाँ मुख्यतः कहाँ से लेती है?","optionsHi":["बोल्ड में फ़ॉर्मेट किए गए सभी पाठ से","अंतर्निहित Heading शैलियों से फ़ॉर्मेट किए गए अनुच्छेदों से","दस्तावेज़ में डाले गए बुकमार्कों से","ऐसे किसी भी पाठ से जिसका फ़ॉन्ट आकार 14 पॉइंट से बड़ा हो"],"explanationHi":"स्वचालित TOC Heading 1, Heading 2 और ऐसी ही शैलियों (आउटलाइन स्तरों) से बनती है, इसलिए जो शीर्षक केवल बड़े और बोल्ड दिखते हैं पर Heading शैली का उपयोग नहीं करते, छूट जाते हैं।"},
  {"id":"comp-ms-office-internet-183","question":"In MS Word, what does the shortcut Alt + Ctrl + D do?","options":["Inserts a footnote at the bottom of the current page","Inserts the current date as a field","Inserts an endnote at the end of the document","Duplicates the current paragraph"],"answer":2,"explanation":"Alt + Ctrl + D inserts an endnote, collected at the end of the document (or section); Alt + Ctrl + F inserts a footnote at the bottom of the page, and Alt + Shift + D inserts the date.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"MS Word में शॉर्टकट Alt + Ctrl + D क्या करता है?","optionsHi":["वर्तमान पेज के नीचे फ़ुटनोट डालता है","वर्तमान तारीख़ को फ़ील्ड के रूप में डालता है","दस्तावेज़ के अंत में एंडनोट डालता है","वर्तमान अनुच्छेद की प्रतिलिपि बनाता है"],"explanationHi":"Alt + Ctrl + D एंडनोट डालता है, जो दस्तावेज़ (या सेक्शन) के अंत में एकत्र होता है; Alt + Ctrl + F पेज के नीचे फ़ुटनोट डालता है, और Alt + Shift + D तारीख़ डालता है।"},
  {"id":"comp-ms-office-internet-184","question":"A report's cover page must show no header, while every other page shows the bank's name in the header. Which Word option does this without section breaks?","options":["Delete the header text on page 1 only","Different Odd and Even Pages","Link to Previous","Different First Page"],"answer":3,"explanation":"'Different First Page' gives the first page of the section its own (here, empty) header. Deleting the header on page 1 would delete it everywhere, because all pages share it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी रिपोर्ट के आवरण पृष्ठ पर कोई हेडर नहीं दिखना चाहिए, जबकि हर अन्य पृष्ठ के हेडर में बैंक का नाम दिखना चाहिए। Word का कौन-सा विकल्प सेक्शन ब्रेक के बिना यह करता है?","optionsHi":["केवल पेज 1 का हेडर पाठ हटाना","Different Odd and Even Pages","Link to Previous","Different First Page"],"explanationHi":"'Different First Page' सेक्शन के पहले पेज को अपना (यहाँ खाली) हेडर देता है। पेज 1 का हेडर हटाने पर वह हर जगह हट जाता, क्योंकि सभी पेज उसे साझा करते हैं।"},
  {"id":"comp-ms-office-internet-185","question":"A portrait Word report must show one wide table on a single landscape page in the middle, with all other pages staying portrait. What is the correct method?","options":["Put a Next Page section break before and after the table, then set only that section to Landscape","Put page breaks (Ctrl + Enter) before and after the table, then set Landscape","Put column breaks around the table, then set Landscape","Select the table and set Landscape with 'Apply to: Whole document'"],"answer":0,"explanation":"Orientation is a section property, so the table needs its own section starting on a new page. Page and column breaks do not create sections, so changing orientation would affect the whole document.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक पोर्ट्रेट Word रिपोर्ट में बीच में एक चौड़ी तालिका एक लैंडस्केप पेज पर दिखानी है, जबकि अन्य सभी पेज पोर्ट्रेट रहें। सही तरीका क्या है?","optionsHi":["तालिका से पहले और बाद में Next Page सेक्शन ब्रेक डालें, फिर केवल उस सेक्शन को Landscape करें","तालिका से पहले और बाद में पेज ब्रेक (Ctrl + Enter) डालें, फिर Landscape करें","तालिका के चारों ओर कॉलम ब्रेक डालें, फिर Landscape करें","तालिका चयनित करें और 'Apply to: Whole document' के साथ Landscape करें"],"explanationHi":"ओरिएंटेशन सेक्शन का गुण है, इसलिए तालिका को नए पेज से शुरू होने वाला अपना सेक्शन चाहिए। पेज और कॉलम ब्रेक सेक्शन नहीं बनाते, इसलिए ओरिएंटेशन बदलने से पूरा दस्तावेज़ प्रभावित होता।"},
  {"id":"comp-ms-office-internet-186","question":"Typing 'teh' followed by a space in Word turns it into 'the' at once. Which feature does this?","options":["Spell check (F7)","AutoCorrect","Thesaurus","Find and Replace"],"answer":1,"explanation":"AutoCorrect replaces entries from its list as you type. Spell check only underlines or suggests corrections; it does not change words as you type.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"Word में 'teh' टाइप करके रिक्त स्थान दबाने पर वह तुरंत 'the' हो जाता है। यह कौन-सी सुविधा करती है?","optionsHi":["स्पेल चेक (F7)","AutoCorrect","Thesaurus","Find and Replace"],"explanationHi":"AutoCorrect टाइप करते समय अपनी सूची की प्रविष्टियों से शब्द बदल देता है। स्पेल चेक केवल रेखांकित करता है या सुधार सुझाता है; वह टाइप करते समय शब्द नहीं बदलता।"},
  {"id":"comp-ms-office-internet-187","question":"A Word document contains the sentence: 'The bank and the Bank of Baroda are near the banking hub.' Find is run for bank with both 'Match case' and 'Find whole words only' switched on. How many matches are found?","options":["1","2","3","0"],"answer":0,"explanation":"Match case rules out 'Bank', and whole words only rules out 'banking', leaving just the lower-case word 'bank'. With neither option on, all three would match.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक Word दस्तावेज़ में यह वाक्य है: 'The bank and the Bank of Baroda are near the banking hub.' 'Match case' और 'Find whole words only' दोनों चालू करके bank के लिए Find चलाया जाता है। कितने मिलान मिलते हैं?","optionsHi":["1","2","3","0"],"explanationHi":"Match case 'Bank' को बाहर कर देता है, और whole words only 'banking' को, जिससे केवल छोटे अक्षरों वाला शब्द 'bank' बचता है। दोनों में से कोई विकल्प चालू न होता तो तीनों मिलते।"},
  {"id":"comp-ms-office-internet-188","question":"A letter must keep basic formatting such as bold, fonts and alignment, and still open in almost any word processor, not only in MS Word. Which format suits this best?","options":[".txt",".docm",".rtf",".dotx"],"answer":2,"explanation":"Rich Text Format (.rtf) stores basic formatting in a widely supported form. .txt keeps no formatting, .docm is a macro-enabled Word document and .dotx is a Word template.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी पत्र को बोल्ड, फ़ॉन्ट और संरेखण जैसी बुनियादी फ़ॉर्मेटिंग बनाए रखनी है, और फिर भी लगभग किसी भी वर्ड प्रोसेसर में खुलना है, केवल MS Word में नहीं। कौन-सा प्रारूप इसके लिए सबसे उपयुक्त है?","optionsHi":[".txt",".docm",".rtf",".dotx"],"explanationHi":"रिच टेक्स्ट फ़ॉर्मेट (.rtf) बुनियादी फ़ॉर्मेटिंग को व्यापक रूप से समर्थित रूप में संग्रहीत करता है। .txt कोई फ़ॉर्मेटिंग नहीं रखता, .docm मैक्रो-सक्षम Word दस्तावेज़ है और .dotx Word टेम्पलेट है।"},
  {"id":"comp-ms-office-internet-189","question":"In MS Word, F7 starts the spelling and grammar check. What does Shift + F7 open?","options":["Word count","The Thesaurus, which suggests synonyms","The Translate tool","The Find and Replace box"],"answer":1,"explanation":"Shift + F7 opens the Thesaurus for the selected word. Word count is Ctrl + Shift + G, and Find and Replace is Ctrl + H.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"MS Word में F7 वर्तनी और व्याकरण जाँच शुरू करता है। Shift + F7 क्या खोलता है?","optionsHi":["Word count","Thesaurus, जो पर्यायवाची सुझाता है","Translate टूल","Find and Replace बॉक्स"],"explanationHi":"Shift + F7 चयनित शब्द के लिए Thesaurus खोलता है। Word count Ctrl + Shift + G है, और Find and Replace Ctrl + H है।"},
  {"id":"comp-ms-office-internet-190","question":"With Word's Show/Hide ¶ button switched on, which marks represent a space and a tab character?","options":["A pilcrow (¶) for a space and a raised dot (·) for a tab","A right arrow (→) for a space and a pilcrow (¶) for a tab","A degree sign (°) for a space and a return arrow (↵) for a tab","A raised dot (·) for a space and a right arrow (→) for a tab"],"answer":3,"explanation":"Show/Hide displays non-printing characters: a raised dot for each space, an arrow for each tab and ¶ at the end of each paragraph. These marks never print.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Word का Show/Hide ¶ बटन चालू होने पर, रिक्त स्थान और टैब वर्ण के लिए कौन-से चिह्न दिखते हैं?","optionsHi":["रिक्त स्थान के लिए पिलक्रो (¶) और टैब के लिए ऊपर उठा बिंदु (·)","रिक्त स्थान के लिए दायाँ तीर (→) और टैब के लिए पिलक्रो (¶)","रिक्त स्थान के लिए डिग्री चिह्न (°) और टैब के लिए रिटर्न तीर (↵)","रिक्त स्थान के लिए ऊपर उठा बिंदु (·) और टैब के लिए दायाँ तीर (→)"],"explanationHi":"Show/Hide अमुद्रणीय वर्ण दिखाता है: हर रिक्त स्थान के लिए ऊपर उठा बिंदु, हर टैब के लिए तीर और हर अनुच्छेद के अंत में ¶। ये चिह्न कभी प्रिंट नहीं होते।"},
  {"id":"comp-ms-office-internet-191","question":"During a PowerPoint slide show, what does pressing W (or the comma key) do?","options":["Turns the screen white until another key is pressed","Turns the screen black until another key is pressed","Switches the pointer to a pen","Ends the slide show"],"answer":0,"explanation":"W or comma blanks the screen to white, while B or full stop blanks it to black; pressing the key again returns to the slide. Esc ends the show.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint स्लाइड शो के दौरान W (या कॉमा कुंजी) दबाने पर क्या होता है?","optionsHi":["दूसरी कुंजी दबाए जाने तक स्क्रीन सफ़ेद हो जाती है","दूसरी कुंजी दबाए जाने तक स्क्रीन काली हो जाती है","पॉइंटर पेन में बदल जाता है","स्लाइड शो समाप्त हो जाता है"],"explanationHi":"W या कॉमा स्क्रीन को सफ़ेद कर देता है, जबकि B या फ़ुल स्टॉप उसे काला कर देता है; वही कुंजी दोबारा दबाने पर स्लाइड लौट आती है। Esc शो को समाप्त करता है।"},
  {"id":"comp-ms-office-internet-192","question":"In PowerPoint, an object already on the slide must spin or pulse to draw attention, without entering or leaving the slide. Which type of animation is this?","options":["Entrance","Exit","Emphasis","Motion path"],"answer":2,"explanation":"Emphasis effects act on an object that is already visible. Entrance brings it on, exit takes it off, and a motion path moves it along a drawn route.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint में, स्लाइड पर पहले से मौजूद किसी ऑब्जेक्ट को ध्यान खींचने के लिए घूमना या स्पंदित होना है, स्लाइड में आए या गए बिना। यह किस प्रकार का एनिमेशन है?","optionsHi":["Entrance","Exit","Emphasis","Motion path"],"explanationHi":"Emphasis प्रभाव पहले से दिखाई दे रहे ऑब्जेक्ट पर काम करते हैं। Entrance उसे लाता है, Exit उसे हटाता है, और Motion path उसे खींचे गए मार्ग पर चलाता है।"},
  {"id":"comp-ms-office-internet-193","question":"A PowerPoint show is set up as 'Browsed at a kiosk (full screen)' for a branch lobby display. Which statement about it is correct?","options":["Each slide advances only when a visitor clicks the mouse","It plays once and then returns to Normal view","It works only in Presenter View on two monitors","It loops continuously until Esc is pressed, and mouse clicks do not advance slides, so timings must be set"],"answer":3,"explanation":"Kiosk mode loops automatically and ignores clicks for advancing (only hyperlinks and action buttons work), so slide timings or buttons are needed or the show stays on one slide.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी शाखा के लॉबी डिस्प्ले के लिए PowerPoint शो को 'Browsed at a kiosk (full screen)' के रूप में सेट किया गया है। इसके बारे में कौन-सा कथन सही है?","optionsHi":["हर स्लाइड तभी आगे बढ़ती है जब कोई आगंतुक माउस क्लिक करे","यह एक बार चलकर Normal व्यू पर लौट आता है","यह केवल दो मॉनिटरों पर Presenter View में काम करता है","यह Esc दबाए जाने तक लगातार लूप में चलता है, और माउस क्लिक से स्लाइड आगे नहीं बढ़ती, इसलिए टाइमिंग सेट करनी होती है"],"explanationHi":"Kiosk मोड अपने आप लूप में चलता है और आगे बढ़ाने के लिए क्लिक को अनदेखा करता है (केवल हाइपरलिंक और एक्शन बटन काम करते हैं), इसलिए स्लाइड टाइमिंग या बटन चाहिए, वरना शो एक ही स्लाइड पर रुका रहता है।"},
  {"id":"comp-ms-office-internet-194","question":"When printing PowerPoint handouts, which 'slides per page' layout also prints ruled lines beside each slide for the audience to take notes?","options":["1 slide","3 slides","6 slides","9 slides"],"answer":1,"explanation":"Only the 3-slides-per-page handout layout places lines for notes next to each slide. The other layouts simply fit more or fewer thumbnails on the page.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint हैंडआउट प्रिंट करते समय, 'slides per page' का कौन-सा लेआउट श्रोताओं के नोट्स लेने के लिए हर स्लाइड के बगल में रेखाएँ भी प्रिंट करता है?","optionsHi":["1 slide","3 slides","6 slides","9 slides"],"explanationHi":"केवल प्रति पेज 3 स्लाइड वाला हैंडआउट लेआउट हर स्लाइड के बगल में नोट्स के लिए रेखाएँ रखता है। अन्य लेआउट केवल पेज पर अधिक या कम थंबनेल समाते हैं।"},
  {"id":"comp-ms-office-internet-195","question":"A slide in a PowerPoint presentation is marked as 'Hide Slide'. Which statement is correct?","options":["It is skipped during the slide show but stays in the file and can still be reached through a hyperlink","It is permanently deleted when the file is saved","It is shown during the slide show but not printed","It appears only in Slide Sorter view and can never be shown"],"answer":0,"explanation":"Hiding a slide only skips it in the normal flow of the show; it is still saved and editable, and a hyperlink or action button can jump to it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint प्रस्तुति की एक स्लाइड 'Hide Slide' के रूप में चिह्नित है। कौन-सा कथन सही है?","optionsHi":["स्लाइड शो के दौरान उसे छोड़ दिया जाता है पर वह फ़ाइल में बनी रहती है और हाइपरलिंक के ज़रिए फिर भी पहुँची जा सकती है","फ़ाइल सेव होने पर वह स्थायी रूप से हट जाती है","स्लाइड शो के दौरान दिखती है पर प्रिंट नहीं होती","वह केवल Slide Sorter व्यू में दिखती है और कभी दिखाई नहीं जा सकती"],"explanationHi":"स्लाइड छिपाने से वह केवल शो के सामान्य प्रवाह में छूटती है; वह फिर भी सेव रहती है और संपादन योग्य होती है, और हाइपरलिंक या एक्शन बटन उस तक कूद सकता है।"},
  {"id":"comp-ms-office-internet-196","question":"In PowerPoint's Presenter View with two screens, what does the audience see compared with the presenter?","options":["Both see the speaker notes","The audience sees only the current slide, while the presenter also sees the notes, the next slide and a timer","The audience sees all slides as thumbnails","The presenter sees only the slide, while the audience sees the notes"],"answer":1,"explanation":"Presenter View keeps notes, the upcoming slide and timing tools on the presenter's screen; the projector shows only the slide itself.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"दो स्क्रीन वाले PowerPoint के Presenter View में, प्रस्तुतकर्ता की तुलना में श्रोता क्या देखते हैं?","optionsHi":["दोनों स्पीकर नोट्स देखते हैं","श्रोता केवल वर्तमान स्लाइड देखते हैं, जबकि प्रस्तुतकर्ता नोट्स, अगली स्लाइड और टाइमर भी देखता है","श्रोता सभी स्लाइडें थंबनेल के रूप में देखते हैं","प्रस्तुतकर्ता केवल स्लाइड देखता है, जबकि श्रोता नोट्स देखते हैं"],"explanationHi":"Presenter View नोट्स, आगामी स्लाइड और समय के उपकरण प्रस्तुतकर्ता की स्क्रीन पर रखता है; प्रोजेक्टर केवल स्लाइड ही दिखाता है।"},
  {"id":"comp-ms-office-internet-197","question":"Which PowerPoint feature lets you run through a presentation while it records how long each slide stays on screen, so that it can later advance automatically?","options":["Rehearse Timings","Record Macro","Slide Master","Custom Slide Show"],"answer":0,"explanation":"Rehearse Timings stores the time spent on each slide and can use it for automatic advancing. A custom show is just a chosen subset of slides.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint की कौन-सी सुविधा आपको प्रस्तुति चलाने देती है जबकि वह हर स्लाइड के स्क्रीन पर रुकने का समय रिकॉर्ड करती है, ताकि वह बाद में अपने आप आगे बढ़ सके?","optionsHi":["Rehearse Timings","Record Macro","Slide Master","Custom Slide Show"],"explanationHi":"Rehearse Timings हर स्लाइड पर बिताया गया समय संग्रहीत करता है और उसे स्वचालित रूप से आगे बढ़ाने में उपयोग कर सकता है। Custom show केवल चुनी हुई स्लाइडों का उपसमूह है।"},
  {"id":"comp-ms-office-internet-198","question":"In PowerPoint, the title font is changed on the Slide MASTER (the top thumbnail), and the background is changed on just ONE of the layouts below it. What is the result?","options":["Both changes apply only to the slide currently open","Both changes apply to every slide in the presentation","The font changes on all slides, but the background changes only on slides using that layout","The background changes on all slides, but the font changes only on slides using that layout"],"answer":2,"explanation":"Changes on the master pass down to every layout and so to all slides; a change on a single layout affects only the slides built on that layout.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint में, शीर्षक फ़ॉन्ट Slide MASTER (सबसे ऊपरी थंबनेल) पर बदला जाता है, और पृष्ठभूमि उसके नीचे के केवल एक लेआउट पर बदली जाती है। परिणाम क्या होगा?","optionsHi":["दोनों परिवर्तन केवल वर्तमान में खुली स्लाइड पर लागू होते हैं","दोनों परिवर्तन प्रस्तुति की हर स्लाइड पर लागू होते हैं","फ़ॉन्ट सभी स्लाइडों पर बदलता है, पर पृष्ठभूमि केवल उस लेआउट वाली स्लाइडों पर बदलती है","पृष्ठभूमि सभी स्लाइडों पर बदलती है, पर फ़ॉन्ट केवल उस लेआउट वाली स्लाइडों पर बदलता है"],"explanationHi":"मास्टर पर किए गए परिवर्तन हर लेआउट तक और इस प्रकार सभी स्लाइडों तक पहुँचते हैं; किसी एक लेआउट पर किया गया परिवर्तन केवल उसी लेआउट पर बनी स्लाइडों को प्रभावित करता है।"},
  {"id":"comp-ms-office-internet-199","question":"In PowerPoint, which tool copies the animation effects of one object and applies them to another object in a single step?","options":["Format Painter","Slide Master","Paste Special","Animation Painter"],"answer":3,"explanation":"Animation Painter copies animation settings (effect, timing, duration) just as Format Painter copies formatting. Format Painter does not carry animations.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint में कौन-सा टूल एक ऑब्जेक्ट के एनिमेशन प्रभावों को कॉपी करके एक ही चरण में दूसरे ऑब्जेक्ट पर लागू करता है?","optionsHi":["Format Painter","Slide Master","Paste Special","Animation Painter"],"explanationHi":"Animation Painter एनिमेशन सेटिंग (प्रभाव, समय, अवधि) कॉपी करता है, जैसे Format Painter फ़ॉर्मेटिंग कॉपी करता है। Format Painter एनिमेशन साथ नहीं ले जाता।"},
  {"id":"comp-ms-office-internet-200","question":"In PowerPoint, a picture should appear only when the presenter clicks a particular button-shaped shape, not on any ordinary click of the slide. Which animation setting does this?","options":["Start: After Previous","Start: With Previous","Loop until next click","A trigger set to 'On click of' that shape"],"answer":3,"explanation":"A trigger links the animation to a click on a chosen object, so it runs only when that object is clicked. After/With Previous start effects automatically in the normal sequence.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"PowerPoint में, कोई चित्र केवल तब दिखना चाहिए जब प्रस्तुतकर्ता किसी विशेष बटन-आकार के शेप पर क्लिक करे, स्लाइड पर किसी सामान्य क्लिक पर नहीं। कौन-सी एनिमेशन सेटिंग यह करती है?","optionsHi":["Start: After Previous","Start: With Previous","Loop until next click","उस शेप के लिए 'On click of' पर सेट ट्रिगर"],"explanationHi":"ट्रिगर एनिमेशन को चुने हुए ऑब्जेक्ट पर क्लिक से जोड़ता है, इसलिए वह तभी चलता है जब वह ऑब्जेक्ट क्लिक किया जाए। After/With Previous प्रभावों को सामान्य क्रम में अपने आप शुरू करते हैं।"},
  {"id":"comp-ms-office-internet-201","question":"Asha e-mails a circular To: Ravi, Cc: Meena and Bcc: Tarun. Meena clicks 'Reply All'. Who receives Meena's reply?","options":["Asha and Ravi","Asha, Ravi and Tarun","Only Asha","Ravi and Tarun"],"answer":0,"explanation":"Bcc addresses are hidden from the other recipients, so Meena's mail program does not know Tarun was included; Reply All goes to the sender (Asha) and the visible To/Cc recipients (Ravi).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Asha एक परिपत्र ई-मेल करती है To: Ravi, Cc: Meena और Bcc: Tarun। Meena 'Reply All' पर क्लिक करती है। Meena का उत्तर किसे मिलता है?","optionsHi":["Asha और Ravi","Asha, Ravi और Tarun","केवल Asha","Ravi और Tarun"],"explanationHi":"Bcc पते अन्य प्राप्तकर्ताओं से छिपे रहते हैं, इसलिए Meena के मेल प्रोग्राम को पता नहीं होता कि Tarun शामिल था; Reply All भेजने वाले (Asha) और दिखाई देने वाले To/Cc प्राप्तकर्ताओं (Ravi) को जाता है।"},
  {"id":"comp-ms-office-internet-202","question":"You receive an e-mail with a PDF attached. What normally happens to the attachment when you click Reply and when you click Forward?","options":["Both Reply and Forward include it","Reply leaves it out; Forward includes it","Reply includes it; Forward leaves it out","Neither includes it unless it is attached again"],"answer":1,"explanation":"Replying goes back to someone who already has the file, so attachments are dropped; forwarding sends the message to someone new, so attachments are kept.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"आपको एक PDF अटैचमेंट वाला ई-मेल मिलता है। Reply क्लिक करने पर और Forward क्लिक करने पर अटैचमेंट के साथ सामान्यतः क्या होता है?","optionsHi":["Reply और Forward दोनों उसे शामिल करते हैं","Reply उसे छोड़ देता है; Forward उसे शामिल करता है","Reply उसे शामिल करता है; Forward उसे छोड़ देता है","दोनों उसे शामिल नहीं करते जब तक उसे दोबारा संलग्न न किया जाए"],"explanationHi":"उत्तर देने पर मेल उस व्यक्ति के पास जाता है जिसके पास पहले से फ़ाइल है, इसलिए अटैचमेंट हटा दिए जाते हैं; फ़ॉरवर्ड करने पर संदेश नए व्यक्ति को जाता है, इसलिए अटैचमेंट रखे जाते हैं।"},
  {"id":"comp-ms-office-internet-203","question":"An officer reads office mail on both a phone and a laptop and wants read/unread status and folders to stay the same on both, with the mail kept on the server. Which protocol should the mail client use?","options":["POP3","SMTP","IMAP","FTP"],"answer":2,"explanation":"IMAP keeps messages and folders on the server and syncs their state across devices. POP3 usually downloads mail to one device (often deleting it from the server), and SMTP only sends mail.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक अधिकारी कार्यालय का मेल फ़ोन और लैपटॉप दोनों पर पढ़ता है और चाहता है कि पढ़ा/अपठित स्थिति और फ़ोल्डर दोनों पर एक जैसे रहें, मेल सर्वर पर ही रहे। मेल क्लाइंट को कौन-सा प्रोटोकॉल उपयोग करना चाहिए?","optionsHi":["POP3","SMTP","IMAP","FTP"],"explanationHi":"IMAP संदेश और फ़ोल्डर सर्वर पर रखता है और उनकी स्थिति उपकरणों में सिंक करता है। POP3 सामान्यतः मेल को एक उपकरण में डाउनलोड करता है (अक्सर उसे सर्वर से हटाकर), और SMTP केवल मेल भेजता है।"},
  {"id":"comp-ms-office-internet-204","question":"Which pair of protocols does a mail client typically use to SEND a message and to RECEIVE messages from its mailbox?","options":["IMAP to send, SMTP to receive","HTTP to send, FTP to receive","POP3 to send, IMAP to receive","SMTP to send, IMAP or POP3 to receive"],"answer":3,"explanation":"SMTP pushes mail out to servers; IMAP or POP3 retrieves mail from the user's mailbox. Neither IMAP nor POP3 sends mail.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"मेल क्लाइंट सामान्यतः संदेश भेजने (SEND) और अपने मेलबॉक्स से संदेश प्राप्त करने (RECEIVE) के लिए प्रोटोकॉलों के किस युग्म का उपयोग करता है?","optionsHi":["भेजने के लिए IMAP, प्राप्त करने के लिए SMTP","भेजने के लिए HTTP, प्राप्त करने के लिए FTP","भेजने के लिए POP3, प्राप्त करने के लिए IMAP","भेजने के लिए SMTP, प्राप्त करने के लिए IMAP या POP3"],"explanationHi":"SMTP मेल को सर्वरों तक भेजता है; IMAP या POP3 उपयोगकर्ता के मेलबॉक्स से मेल प्राप्त करते हैं। न IMAP और न POP3 मेल भेजता है।"},
  {"id":"comp-ms-office-internet-205","question":"Which standard lets an e-mail carry attachments such as images and PDFs, and text in scripts like Hindi, even though basic e-mail was designed for plain ASCII text?","options":["MIME","SMTP","HTML","POP3"],"answer":0,"explanation":"MIME (Multipurpose Internet Mail Extensions) encodes attachments and non-ASCII text inside the message. SMTP only transports the message, and HTML formats its body.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"कौन-सा मानक ई-मेल को छवियों और PDF जैसे अटैचमेंट तथा हिंदी जैसी लिपियों के पाठ को ले जाने देता है, जबकि बुनियादी ई-मेल सादे ASCII पाठ के लिए बनाया गया था?","optionsHi":["MIME","SMTP","HTML","POP3"],"explanationHi":"MIME (Multipurpose Internet Mail Extensions) अटैचमेंट और गैर-ASCII पाठ को संदेश के भीतर एन्कोड करता है। SMTP केवल संदेश को पहुँचाता है, और HTML उसके मुख्य भाग को फ़ॉर्मेट करता है।"},
  {"id":"comp-ms-office-internet-206","question":"In the e-mail address loans.desk@branch.examplebank.in, which part is the domain name?","options":["loans.desk","branch.examplebank.in","examplebank","in"],"answer":1,"explanation":"Everything after @ is the domain that receives the mail (branch.examplebank.in); the part before @ is the mailbox (user) name, and '.in' alone is only the top-level domain.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"ई-मेल पते loans.desk@branch.examplebank.in में कौन-सा भाग डोमेन नाम है?","optionsHi":["loans.desk","branch.examplebank.in","examplebank","in"],"explanationHi":"@ के बाद का सब कुछ वह डोमेन है जो मेल प्राप्त करता है (branch.examplebank.in); @ से पहले का भाग मेलबॉक्स (उपयोगकर्ता) नाम है, और अकेला '.in' केवल शीर्ष-स्तरीय डोमेन है।"},
  {"id":"comp-ms-office-internet-207","question":"How many of these statements about e-mail are correct? I. SMTP on its own does not check that the From address really belongs to the sender. II. SPF and DKIM help a receiving server detect mail with a forged sender. III. A message can show a bank's genuine address in its From line even if someone else sent it. IV. The display name shown beside an address can be set to anything by the sender.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct: SMTP does not verify the sender, SPF and DKIM help detect forgery, the From field can be spoofed to show a genuine bank address, and the display name can be set to anything.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"ई-मेल के बारे में इनमें से कितने कथन सही हैं? I. SMTP स्वयं यह जाँच नहीं करता कि From पता वास्तव में भेजने वाले का है। II. SPF और DKIM प्राप्तकर्ता सर्वर को जाली प्रेषक वाला मेल पहचानने में मदद करते हैं। III. कोई संदेश अपनी From पंक्ति में बैंक का असली पता दिखा सकता है, भले ही उसे किसी और ने भेजा हो। IV. पते के बगल में दिखने वाला प्रदर्शित नाम प्रेषक द्वारा कुछ भी रखा जा सकता है।","optionsHi":["एक","दो","तीन","चार"],"explanationHi":"चारों सही हैं: SMTP प्रेषक का सत्यापन नहीं करता, SPF और DKIM जालसाज़ी पहचानने में मदद करते हैं, From फ़ील्ड को बैंक का असली पता दिखाने के लिए जाली बनाया जा सकता है, और प्रदर्शित नाम कुछ भी रखा जा सकता है।"},
  {"id":"comp-ms-office-internet-208","question":"How many of these statements about browser cookies are correct? I. A session cookie is normally deleted when the browser is closed. II. A persistent cookie stays until its expiry date or until the user deletes it. III. A third-party cookie is set by a domain other than the site shown in the address bar, often for ad tracking. IV. Cookies are small programs that run on your computer and can infect it.","options":["One","Two","Four","Three"],"answer":3,"explanation":"I, II and III are correct. IV is false: cookies are small text files of data, not programs, so they cannot run or infect a computer, although they can raise privacy concerns.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"ब्राउज़र कुकी के बारे में इनमें से कितने कथन सही हैं? I. सेशन कुकी सामान्यतः ब्राउज़र बंद होने पर हटा दी जाती है। II. स्थायी (persistent) कुकी अपनी समाप्ति तिथि तक या उपयोगकर्ता द्वारा हटाए जाने तक बनी रहती है। III. थर्ड-पार्टी कुकी अड्रेस बार में दिखने वाली साइट से भिन्न किसी डोमेन द्वारा सेट की जाती है, अक्सर विज्ञापन ट्रैकिंग के लिए। IV. कुकी छोटे प्रोग्राम होते हैं जो आपके कंप्यूटर पर चलते हैं और उसे संक्रमित कर सकते हैं।","optionsHi":["एक","दो","चार","तीन"],"explanationHi":"I, II और III सही हैं। IV असत्य है: कुकी डेटा की छोटी टेक्स्ट फ़ाइलें हैं, प्रोग्राम नहीं, इसलिए वे कंप्यूटर पर चल या उसे संक्रमित नहीं कर सकतीं, हालाँकि वे निजता संबंधी चिंताएँ बढ़ा सकती हैं।"},
  {"id":"comp-ms-office-internet-209","question":"Match the HTTP status code with its meaning: 1. 301 2. 403 3. 500 4. 503; a. server temporarily unable to handle the request, e.g. overloaded b. page moved permanently to a new address c. access to the page is forbidden d. internal error on the server","options":["1-b, 2-d, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-a, 2-c, 3-d, 4-b","1-b, 2-c, 3-a, 4-d"],"answer":1,"explanation":"3xx codes are redirects (301 = moved permanently), 4xx are client-side problems (403 = forbidden), and 5xx are server-side problems (500 = internal server error, 503 = service unavailable).","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"HTTP स्टेटस कोड को उसके अर्थ से सुमेलित कीजिए: 1. 301 2. 403 3. 500 4. 503; a. सर्वर अस्थायी रूप से अनुरोध संभालने में असमर्थ, जैसे अतिभारित b. पेज स्थायी रूप से नए पते पर चला गया c. पेज तक पहुँच निषिद्ध है d. सर्वर पर आंतरिक त्रुटि","optionsHi":["1-b, 2-d, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-a, 2-c, 3-d, 4-b","1-b, 2-c, 3-a, 4-d"],"explanationHi":"3xx कोड रीडायरेक्ट हैं (301 = स्थायी रूप से स्थानांतरित), 4xx क्लाइंट-पक्ष की समस्याएँ हैं (403 = निषिद्ध), और 5xx सर्वर-पक्ष की समस्याएँ हैं (500 = आंतरिक सर्वर त्रुटि, 503 = सेवा अनुपलब्ध)।"},
  {"id":"comp-ms-office-internet-210","question":"Match each item with what it is: 1. Mozilla Firefox 2. Apache HTTP Server 3. Google Search 4. Wikipedia; a. web browser b. web server software c. search engine d. website","options":["1-c, 2-b, 3-a, 4-d","1-a, 2-d, 3-c, 4-b","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-c, 4-d"],"answer":2,"explanation":"A browser (Firefox) displays pages, server software (Apache) delivers them, a search engine (Google Search) indexes and finds them, and a website (Wikipedia) is a collection of pages.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"प्रत्येक मद को उसके स्वरूप से सुमेलित कीजिए: 1. Mozilla Firefox 2. Apache HTTP Server 3. Google Search 4. Wikipedia; a. वेब ब्राउज़र b. वेब सर्वर सॉफ़्टवेयर c. सर्च इंजन d. वेबसाइट","optionsHi":["1-c, 2-b, 3-a, 4-d","1-a, 2-d, 3-c, 4-b","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-c, 4-d"],"explanationHi":"ब्राउज़र (Firefox) पेज दिखाता है, सर्वर सॉफ़्टवेयर (Apache) उन्हें पहुँचाता है, सर्च इंजन (Google Search) उन्हें इंडेक्स करके खोजता है, और वेबसाइट (Wikipedia) पेजों का संग्रह है।"},
  {"id":"comp-ms-office-internet-211","question":"A bank lets its approved vendors log in to a restricted part of its private network to check purchase orders. This arrangement is called:","options":["The internet","An intranet","A LAN","An extranet"],"answer":3,"explanation":"An intranet serves only the organisation's own staff; extending controlled access to outside partners such as vendors makes it an extranet.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"कोई बैंक अपने अनुमोदित विक्रेताओं को खरीद आदेश जाँचने के लिए अपने निजी नेटवर्क के एक प्रतिबंधित भाग में लॉग इन करने देता है। इस व्यवस्था को क्या कहते हैं?","optionsHi":["इंटरनेट","इंट्रानेट","LAN","एक्स्ट्रानेट"],"explanationHi":"इंट्रानेट केवल संगठन के अपने कर्मचारियों के लिए होता है; विक्रेताओं जैसे बाहरी भागीदारों को नियंत्रित पहुँच देने पर वह एक्स्ट्रानेट बन जाता है।"},
  {"id":"comp-ms-office-internet-212","question":"An internet plan is advertised at 100 Mbps. A download manager shows speed in MB/s (megabytes per second). Ignoring overheads, what is the highest reading you can expect?","options":["100 MB/s","12.5 MB/s","800 MB/s","1.25 MB/s"],"answer":1,"explanation":"Mbps is megaBITS per second and 1 byte = 8 bits, so 100 ÷ 8 = 12.5 MB/s. 800 MB/s multiplies instead of dividing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक इंटरनेट प्लान 100 Mbps का विज्ञापित है। एक डाउनलोड मैनेजर गति MB/s (मेगाबाइट प्रति सेकंड) में दिखाता है। अतिरिक्त भार को अनदेखा करें तो अधिकतम कितनी रीडिंग की अपेक्षा कर सकते हैं?","optionsHi":["100 MB/s","12.5 MB/s","800 MB/s","1.25 MB/s"],"explanationHi":"Mbps मेगाबिट प्रति सेकंड है और 1 बाइट = 8 बिट, इसलिए 100 ÷ 8 = 12.5 MB/s। 800 MB/s भाग देने के बजाय गुणा करता है।"},
  {"id":"comp-ms-office-internet-213","question":"On a web page, what happens when a user clicks a hyperlink of the form mailto:support@examplebank.in?","options":["The default e-mail program opens a new message addressed to that address","The page sends an e-mail automatically without the user seeing it","The browser downloads the support team's contact card","The browser opens the bank's home page"],"answer":0,"explanation":"The mailto: scheme hands the address to the user's default mail client, which opens a new, unsent message; nothing is sent until the user clicks Send.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"वेब पेज पर, जब उपयोगकर्ता mailto:support@examplebank.in रूप के हाइपरलिंक पर क्लिक करता है तो क्या होता है?","optionsHi":["डिफ़ॉल्ट ई-मेल प्रोग्राम उस पते पर संबोधित नया संदेश खोलता है","पेज उपयोगकर्ता को दिखाए बिना अपने आप ई-मेल भेज देता है","ब्राउज़र सहायता टीम का संपर्क कार्ड डाउनलोड करता है","ब्राउज़र बैंक का होम पेज खोलता है"],"explanationHi":"mailto: स्कीम पते को उपयोगकर्ता के डिफ़ॉल्ट मेल क्लाइंट को सौंप देती है, जो नया, न भेजा गया संदेश खोलता है; जब तक उपयोगकर्ता Send पर क्लिक न करे, कुछ नहीं भेजा जाता।"},
  {"id":"comp-ms-office-internet-214","question":"Assertion (A): Viewing a typical web page involves both HTML and HTTP. Reason (R): HTML is the protocol that carries pages from the server, and HTTP is the language in which pages are written.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true, but R swaps the roles: HTTP is the transfer protocol and HTML is the markup language used to write the page.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"अभिकथन (A): किसी सामान्य वेब पेज को देखने में HTML और HTTP दोनों शामिल होते हैं। कारण (R): HTML वह प्रोटोकॉल है जो सर्वर से पेज लाता है, और HTTP वह भाषा है जिसमें पेज लिखे जाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है लेकिन R असत्य है","A असत्य है लेकिन R सत्य है"],"explanationHi":"A सत्य है, पर R भूमिकाएँ आपस में बदल देता है: HTTP स्थानांतरण प्रोटोकॉल है और HTML पेज लिखने की मार्कअप भाषा है।"},
  {"id":"comp-ms-office-internet-215","question":"A DNS resolver with an empty cache must find the IP address of www.example.in. In which order does it query the DNS hierarchy?","options":["Authoritative server for example.in → .in TLD server → root server","The .in TLD server → root server → authoritative server for example.in","Root server → authoritative server for example.in → .in TLD server","Root server → .in TLD server → authoritative server for example.in"],"answer":3,"explanation":"The root server refers the resolver to the .in TLD servers, which refer it to the authoritative server for example.in, which finally returns the address. Each level only knows the next level down.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"खाली कैश वाले DNS रिज़ॉल्वर को www.example.in का IP पता खोजना है। वह DNS पदानुक्रम से किस क्रम में पूछताछ करता है?","optionsHi":["example.in का प्राधिकारी सर्वर → .in TLD सर्वर → रूट सर्वर","पहले .in TLD सर्वर → रूट सर्वर → example.in का प्राधिकारी सर्वर","रूट सर्वर → example.in का प्राधिकारी सर्वर → .in TLD सर्वर","रूट सर्वर → .in TLD सर्वर → example.in का प्राधिकारी सर्वर"],"explanationHi":"रूट सर्वर रिज़ॉल्वर को .in TLD सर्वरों के पास भेजता है, जो उसे example.in के प्राधिकारी सर्वर के पास भेजते हैं, जो अंत में पता लौटाता है। हर स्तर केवल अगले निचले स्तर को जानता है।"},
  {"id":"comp-ms-office-internet-216","question":"Which section of the Information Technology Act, 2000, which punished sending 'offensive' messages through a computer or communication device, was struck down by the Supreme Court in Shreya Singhal v. Union of India (2015)?","options":["Section 66","Section 66A","Section 66C","Section 69A"],"answer":1,"explanation":"The Court held Section 66A unconstitutional as vague and a violation of free speech. In the same case it upheld Section 69A, the government's power to block online content.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"सूचना प्रौद्योगिकी अधिनियम, 2000 की कौन-सी धारा, जो कंप्यूटर या संचार उपकरण से 'आपत्तिजनक' संदेश भेजने को दंडित करती थी, श्रेया सिंघल बनाम भारत संघ (2015) में सर्वोच्च न्यायालय द्वारा रद्द की गई?","optionsHi":["धारा 66","धारा 66A","धारा 66C","धारा 69A"],"explanationHi":"न्यायालय ने धारा 66A को अस्पष्ट और वाक्-स्वतंत्रता का उल्लंघन मानकर असंवैधानिक ठहराया। उसी मामले में उसने धारा 69A को बरकरार रखा, जो ऑनलाइन सामग्री को अवरुद्ध करने की सरकार की शक्ति है।"},
  {"id":"comp-ms-office-internet-217","question":"Match the section of the IT Act, 2000 with what it deals with: 1. Section 43 2. Section 66D 3. Section 66E 4. Section 67; a. cheating by personation using a computer resource b. publishing obscene material in electronic form c. penalty and compensation for damage to a computer system, such as unauthorised access d. violation of privacy by capturing or publishing private images","options":["1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-a, 4-b","1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-b, 4-d"],"answer":0,"explanation":"Section 43 covers civil penalty and compensation for damage to computers, 66D cheating by personation (common in online frauds), 66E violation of privacy and 67 obscene material in electronic form.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"IT अधिनियम, 2000 की धारा को उसके विषय से सुमेलित कीजिए: 1. धारा 43 2. धारा 66D 3. धारा 66E 4. धारा 67; a. कंप्यूटर संसाधन द्वारा छद्मवेश से धोखाधड़ी b. इलेक्ट्रॉनिक रूप में अश्लील सामग्री प्रकाशित करना c. कंप्यूटर प्रणाली को क्षति, जैसे अनधिकृत पहुँच, के लिए दंड और मुआवज़ा d. निजी चित्रों को खींचकर या प्रकाशित करके निजता का उल्लंघन","optionsHi":["1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-a, 4-b","1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-b, 4-d"],"explanationHi":"धारा 43 कंप्यूटरों को क्षति के लिए दीवानी दंड और मुआवज़े को कवर करती है, 66D छद्मवेश से धोखाधड़ी (ऑनलाइन धोखाधड़ी में आम), 66E निजता का उल्लंघन और 67 इलेक्ट्रॉनिक रूप में अश्लील सामग्री।"},
  {"id":"comp-ms-office-internet-218","question":"Which body is India's national nodal agency for responding to computer security incidents, set up under Section 70B of the IT Act?","options":["NCIIPC","Indian Cyber Crime Coordination Centre (I4C)","CERT-In","National Informatics Centre (NIC)"],"answer":2,"explanation":"CERT-In (Indian Computer Emergency Response Team) is the Section 70B agency. NCIIPC, under Section 70A, protects critical information infrastructure, and I4C coordinates cyber-crime policing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"IT अधिनियम की धारा 70B के अंतर्गत स्थापित, कंप्यूटर सुरक्षा घटनाओं पर प्रतिक्रिया देने वाली भारत की राष्ट्रीय नोडल एजेंसी कौन-सी है?","optionsHi":["NCIIPC","भारतीय साइबर अपराध समन्वय केंद्र (I4C)","CERT-In","राष्ट्रीय सूचना विज्ञान केंद्र (NIC)"],"explanationHi":"CERT-In (भारतीय कंप्यूटर आपातकालीन प्रतिक्रिया दल) धारा 70B की एजेंसी है। NCIIPC, धारा 70A के अंतर्गत, महत्वपूर्ण सूचना अवसंरचना की रक्षा करता है, और I4C साइबर अपराध पुलिसिंग का समन्वय करता है।"},
  {"id":"comp-ms-office-internet-219","question":"A rogue bank programmer secretly diverts a few paise from the interest of thousands of accounts into his own account, hoping the tiny amounts go unnoticed. This is a:","options":["Logic bomb","Data diddling attack","Pharming attack","Salami attack"],"answer":3,"explanation":"A salami attack steals tiny 'slices' from many accounts so that no single loss is noticed. Data diddling changes data before or while it is entered, and a logic bomb waits for a trigger condition.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक बेईमान बैंक प्रोग्रामर हज़ारों खातों के ब्याज से कुछ पैसे चुपके से अपने खाते में भेज देता है, इस आशा में कि छोटी रकमें किसी की नज़र में नहीं आएँगी। यह है:","optionsHi":["लॉजिक बम (Logic bomb)","डेटा डिडलिंग हमला (Data diddling)","फ़ार्मिंग हमला (Pharming)","सलामी हमला (Salami attack)"],"explanationHi":"सलामी हमला कई खातों से छोटे-छोटे 'टुकड़े' चुराता है ताकि कोई एक हानि नज़र में न आए। डेटा डिडलिंग डेटा को दर्ज करने से पहले या दर्ज करते समय बदल देता है, और लॉजिक बम किसी ट्रिगर शर्त की प्रतीक्षा करता है।"},
  {"id":"comp-ms-office-internet-220","question":"Malware secretly records every key pressed on a cyber-café computer, capturing users' net-banking passwords. Which safeguard offered by many bank websites helps most against this?","options":["Turning on the browser's pop-up blocker","An on-screen virtual keyboard for entering the password","Clearing cookies after logging out","Using the private/incognito window"],"answer":1,"explanation":"A keylogger captures keystrokes, so typing the password by clicking on an on-screen virtual keyboard defeats it. Incognito mode and clearing cookies do not stop malware already installed on the machine.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"कोई मैलवेयर साइबर कैफ़े के कंप्यूटर पर दबाई गई हर कुंजी को चुपके से रिकॉर्ड करता है और उपयोगकर्ताओं के नेट-बैंकिंग पासवर्ड पकड़ लेता है। कई बैंक वेबसाइटों द्वारा दी गई कौन-सी सुरक्षा व्यवस्था इसके विरुद्ध सबसे अधिक सहायक है?","optionsHi":["ब्राउज़र का पॉप-अप ब्लॉकर चालू करना","पासवर्ड दर्ज करने के लिए ऑन-स्क्रीन वर्चुअल कीबोर्ड","लॉग आउट के बाद कुकी साफ़ करना","प्राइवेट/इन्कॉग्निटो विंडो का उपयोग"],"explanationHi":"कीलॉगर कीस्ट्रोक पकड़ता है, इसलिए ऑन-स्क्रीन वर्चुअल कीबोर्ड पर क्लिक करके पासवर्ड टाइप करना उसे विफल कर देता है। इन्कॉग्निटो मोड और कुकी साफ़ करना मशीन पर पहले से इंस्टॉल मैलवेयर को नहीं रोकते।"},
  {"id":"comp-ms-office-internet-221","question":"Attackers take millions of username-password pairs leaked from a shopping site and automatically try them on bank login pages, succeeding wherever people reused passwords. This attack is called:","options":["Brute-force attack","Dictionary attack","Credential stuffing","Session hijacking"],"answer":2,"explanation":"Credential stuffing replays real leaked credentials on other services; it works only because of password reuse. Brute-force and dictionary attacks GUESS passwords instead of using known ones.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"हमलावर किसी शॉपिंग साइट से लीक हुए लाखों यूज़रनेम-पासवर्ड जोड़े लेकर उन्हें स्वचालित रूप से बैंक लॉगिन पेजों पर आज़माते हैं, और जहाँ भी लोगों ने पासवर्ड दोहराए हैं वहाँ सफल हो जाते हैं। इस हमले को कहते हैं:","optionsHi":["ब्रूट-फ़ोर्स हमला","डिक्शनरी हमला","क्रेडेंशियल स्टफ़िंग (Credential stuffing)","सेशन हाइजैकिंग"],"explanationHi":"क्रेडेंशियल स्टफ़िंग लीक हुए असली क्रेडेंशियल को अन्य सेवाओं पर दोहराता है; यह केवल पासवर्ड दोहराने के कारण काम करता है। ब्रूट-फ़ोर्स और डिक्शनरी हमले ज्ञात पासवर्ड के बजाय पासवर्ड का अनुमान लगाते हैं।"},
  {"id":"comp-ms-office-internet-222","question":"An 8-character password can use either only lower-case letters (26 symbols) or upper-case letters, lower-case letters and digits (62 symbols). Roughly how many times larger is the second set of possible passwords?","options":["About 2.4 times","About 19 times","About 36 times","About 1,046 times"],"answer":3,"explanation":"The counts are 26⁸ and 62⁸, so the ratio is (62/26)⁸ ≈ 2.385⁸ ≈ 1,046. 2.4 forgets that the ratio is raised to the power 8, once for each character.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक 8-अक्षर के पासवर्ड में या तो केवल छोटे अक्षर (26 प्रतीक) हो सकते हैं या बड़े अक्षर, छोटे अक्षर और अंक (62 प्रतीक)। दूसरा संभावित पासवर्डों का समुच्चय लगभग कितने गुना बड़ा है?","optionsHi":["लगभग 2.4 गुना","लगभग 19 गुना","लगभग 36 गुना","लगभग 1,046 गुना"],"explanationHi":"संख्याएँ 26⁸ और 62⁸ हैं, इसलिए अनुपात (62/26)⁸ ≈ 2.385⁸ ≈ 1,046 है। 2.4 यह भूल जाता है कि अनुपात की घात 8 होती है, हर अक्षर के लिए एक बार।"},
  {"id":"comp-ms-office-internet-223","question":"Which measure best lets a branch recover its files after ransomware encrypts every drive on its network and demands payment?","options":["Restoring from recent backups kept offline or otherwise isolated from the network","Restoring from a backup drive that stays permanently connected to the same network","Paying the ransom, since the key is always provided","Renaming the encrypted files back to their original extensions"],"answer":0,"explanation":"Ransomware encrypts everything it can reach, including connected backup drives, so only offline or isolated backups are safe. Paying gives no guarantee of a key, and renaming does not decrypt anything.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"जब रैनसमवेयर किसी शाखा के नेटवर्क की हर ड्राइव एन्क्रिप्ट कर दे और भुगतान माँगे, तो कौन-सा उपाय उसे अपनी फ़ाइलें पुनः प्राप्त करने में सबसे अच्छी मदद करता है?","optionsHi":["नेटवर्क से ऑफ़लाइन या अन्यथा अलग रखे गए हालिया बैकअप से पुनर्स्थापित करना","उसी नेटवर्क से स्थायी रूप से जुड़ी बैकअप ड्राइव से पुनर्स्थापित करना","फिरौती चुकाना, क्योंकि कुंजी हमेशा दी जाती है","एन्क्रिप्टेड फ़ाइलों का नाम बदलकर उनके मूल एक्सटेंशन पर लौटाना"],"explanationHi":"रैनसमवेयर हर उस चीज़ को एन्क्रिप्ट करता है जिस तक वह पहुँच सके, जुड़ी हुई बैकअप ड्राइव सहित, इसलिए केवल ऑफ़लाइन या अलग रखे गए बैकअप ही सुरक्षित हैं। भुगतान करने से कुंजी की कोई गारंटी नहीं मिलती, और नाम बदलने से कुछ डिक्रिप्ट नहीं होता।"},
  {"id":"comp-ms-office-internet-224","question":"An attacker posts a comment containing hidden JavaScript on a bank's poorly coded feedback page. The script then runs in the browsers of other customers who view the page, stealing their session cookies. This is:","options":["SQL injection","Cross-site scripting (XSS)","Clickjacking","A DDoS attack"],"answer":1,"explanation":"XSS injects a malicious script into a page so it runs in OTHER users' browsers. SQL injection targets the database behind the site, and clickjacking hides a real button under a fake one.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"कोई हमलावर किसी बैंक के खराब कोड वाले फ़ीडबैक पेज पर छिपी JavaScript वाली टिप्पणी पोस्ट करता है। फिर वह स्क्रिप्ट उस पेज को देखने वाले अन्य ग्राहकों के ब्राउज़रों में चलती है और उनकी सेशन कुकी चुरा लेती है। यह है:","optionsHi":["SQL इंजेक्शन","क्रॉस-साइट स्क्रिप्टिंग (XSS)","क्लिकजैकिंग (Clickjacking)","DDoS हमला"],"explanationHi":"XSS किसी पेज में दुर्भावनापूर्ण स्क्रिप्ट डालता है ताकि वह अन्य उपयोगकर्ताओं के ब्राउज़रों में चले। SQL इंजेक्शन साइट के पीछे के डेटाबेस को निशाना बनाता है, और क्लिकजैकिंग असली बटन को नकली बटन के नीचे छिपा देती है।"},
  {"id":"comp-ms-office-internet-225","question":"In a web search engine, how should you search for pages containing the exact phrase home loan but NOT the word interest?","options":["Put home loan in double quotes and add -interest","Put home loan in double quotes and add the word interest after it","Type home loan interest without any operators","Put interest in double quotes and add -home loan"],"answer":0,"explanation":"Double quotes force the exact phrase, and a minus sign placed directly before a word excludes pages containing it. Adding the word interest without the minus sign would include it instead of excluding it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी वेब सर्च इंजन में, उन पेजों को कैसे खोजेंगे जिनमें ठीक यही वाक्यांश home loan हो पर शब्द interest न हो?","optionsHi":["home loan को डबल कोट्स में रखें और -interest जोड़ें","home loan को डबल कोट्स में रखें और उसके बाद शब्द interest जोड़ें","बिना किसी संक्रियक के home loan interest टाइप करें","interest को डबल कोट्स में रखें और -home loan जोड़ें"],"explanationHi":"डबल कोट्स सटीक वाक्यांश को बाध्य करते हैं, और किसी शब्द के ठीक पहले लगा ऋण चिह्न उस शब्द वाले पेजों को बाहर कर देता है। ऋण चिह्न के बिना शब्द interest जोड़ने पर वह बाहर होने के बजाय शामिल हो जाता।"},
  {"id":"comp-ms-office-internet-226","question":"A customer gets a text message: 'Your KYC expires today. Update now at this link or your account will be blocked.' This fraud attempt is an example of:","options":["Vishing","Smishing","Whaling","Pharming"],"answer":1,"explanation":"Smishing is phishing by SMS. Vishing uses voice calls, whaling targets top executives, and pharming redirects a genuine web address to a fake site.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"किसी ग्राहक को टेक्स्ट संदेश मिलता है: 'Your KYC expires today. Update now at this link or your account will be blocked.' यह धोखाधड़ी का प्रयास किसका उदाहरण है?","optionsHi":["विशिंग (Vishing)","स्मिशिंग (Smishing)","व्हेलिंग (Whaling)","फ़ार्मिंग (Pharming)"],"explanationHi":"स्मिशिंग SMS द्वारा फ़िशिंग है। विशिंग वॉयस कॉल का उपयोग करती है, व्हेलिंग शीर्ष अधिकारियों को निशाना बनाती है, और फ़ार्मिंग असली वेब पते को नकली साइट पर भेज देती है।"},
  {"id":"comp-ms-office-internet-227","question":"A data-entry clerk alters the amounts on vouchers just before keying them into the system, and changes them back later to hide the fraud. This cyber crime is called:","options":["Salami attack","Logic bomb","Data diddling","Email spoofing"],"answer":2,"explanation":"Data diddling is the unauthorised changing of data before or during its entry into a computer. A salami attack instead skims tiny amounts from many accounts.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक डेटा-एंट्री क्लर्क वाउचरों को सिस्टम में दर्ज करने से ठीक पहले उनकी राशियाँ बदल देता है, और धोखाधड़ी छिपाने के लिए बाद में उन्हें वापस बदल देता है। इस साइबर अपराध को क्या कहते हैं?","optionsHi":["सलामी हमला (Salami attack)","लॉजिक बम (Logic bomb)","डेटा डिडलिंग (Data diddling)","ई-मेल स्पूफ़िंग (Email spoofing)"],"explanationHi":"डेटा डिडलिंग कंप्यूटर में डेटा दर्ज करने से पहले या उस दौरान उसे अनधिकृत रूप से बदलना है। सलामी हमला इसके बजाय कई खातों से छोटी रकमें चुराता है।"},
  {"id":"comp-ms-office-internet-228","question":"Which type of malware buries itself deep in the operating system and hides its own files and processes so that antivirus tools and Task Manager cannot see it?","options":["Adware","Worm","Ransomware","Rootkit"],"answer":3,"explanation":"A rootkit's defining feature is concealment at a deep (often kernel) level, which lets other malicious activity stay hidden. Worms spread, ransomware encrypts, and adware shows ads.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किस प्रकार का मैलवेयर ऑपरेटिंग सिस्टम में गहराई में समा जाता है और अपनी फ़ाइलों व प्रक्रियाओं को इस तरह छिपाता है कि एंटीवायरस उपकरण और Task Manager उसे नहीं देख पाते?","optionsHi":["एडवेयर (Adware)","वर्म (Worm)","रैनसमवेयर (Ransomware)","रूटकिट (Rootkit)"],"explanationHi":"रूटकिट की परिभाषित विशेषता गहरे (अक्सर कर्नेल) स्तर पर छिपाव है, जो अन्य दुर्भावनापूर्ण गतिविधियों को छिपाए रखता है। वर्म फैलते हैं, रैनसमवेयर एन्क्रिप्ट करता है, और एडवेयर विज्ञापन दिखाता है।"},
  {"id":"comp-ms-office-internet-229","question":"A bank's security team deliberately sets up a decoy server that looks vulnerable, so that attackers are drawn to it and their methods can be studied. Such a system is called a:","options":["Honeypot","Firewall","Proxy server","Sandbox"],"answer":0,"explanation":"A honeypot is bait with no real business use, so any traffic to it is suspicious. A sandbox instead runs untrusted programs in isolation, and a firewall filters traffic.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी बैंक की सुरक्षा टीम जानबूझकर एक नकली सर्वर बनाती है जो असुरक्षित दिखता है, ताकि हमलावर उसकी ओर खिंचें और उनके तरीकों का अध्ययन किया जा सके। ऐसी प्रणाली क्या कहलाती है?","optionsHi":["हनीपॉट (Honeypot)","फ़ायरवॉल (Firewall)","प्रॉक्सी सर्वर (Proxy server)","सैंडबॉक्स (Sandbox)"],"explanationHi":"हनीपॉट एक चारा है जिसका कोई वास्तविक व्यावसायिक उपयोग नहीं होता, इसलिए उस तक आने वाला कोई भी ट्रैफ़िक संदिग्ध होता है। सैंडबॉक्स इसके बजाय अविश्वसनीय प्रोग्रामों को अलग वातावरण में चलाता है, और फ़ायरवॉल ट्रैफ़िक फ़िल्टर करता है।"},
  {"id":"comp-ms-office-internet-230","question":"Why can an antivirus that relies only on signature-based detection miss a brand-new virus?","options":["Because new viruses are always encrypted with SSL","Because its database does not yet contain the pattern (signature) of the new virus","Because signature-based scanners check only e-mail attachments","Because it scans only files larger than 1 MB"],"answer":1,"explanation":"Signature scanning matches files against known malware patterns, so unseen (zero-day) malware has no signature yet. Heuristic and behaviour-based detection look for suspicious ACTIONS to close this gap.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"केवल हस्ताक्षर (signature) आधारित पहचान पर निर्भर एंटीवायरस बिल्कुल नए वायरस को क्यों चूक सकता है?","optionsHi":["क्योंकि नए वायरस हमेशा SSL से एन्क्रिप्टेड होते हैं","क्योंकि उसके डेटाबेस में अभी नए वायरस का पैटर्न (हस्ताक्षर) नहीं है","क्योंकि हस्ताक्षर-आधारित स्कैनर केवल ई-मेल अटैचमेंट जाँचते हैं","क्योंकि वह केवल 1 MB से बड़ी फ़ाइलें स्कैन करता है"],"explanationHi":"हस्ताक्षर स्कैनिंग फ़ाइलों को ज्ञात मैलवेयर पैटर्न से मिलाती है, इसलिए अदृष्ट (ज़ीरो-डे) मैलवेयर का अभी कोई हस्ताक्षर नहीं होता। इस अंतर को पाटने के लिए ह्यूरिस्टिक और व्यवहार-आधारित पहचान संदिग्ध क्रियाओं को खोजती है।"},
  {"id":"comp-ms-office-internet-231","question":"A branch takes a full backup on Sunday and an incremental backup each night from Monday to Thursday. Its server crashes on Friday morning. How many backup sets must be restored to get back Thursday night's data?","options":["2","4","1","5"],"answer":3,"explanation":"Each incremental backup holds only the changes since the PREVIOUS backup, so you need Sunday's full backup plus all four incrementals: 5 sets. With differential backups, Sunday's full plus Thursday's differential (2 sets) would be enough.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक शाखा रविवार को पूर्ण बैकअप और सोमवार से गुरुवार तक हर रात इन्क्रीमेंटल बैकअप लेती है। उसका सर्वर शुक्रवार सुबह क्रैश हो जाता है। गुरुवार रात तक का डेटा वापस पाने के लिए कितने बैकअप सेट पुनर्स्थापित करने होंगे?","optionsHi":["2","4","1","5"],"explanationHi":"हर इन्क्रीमेंटल बैकअप में केवल पिछले बैकअप के बाद के परिवर्तन होते हैं, इसलिए रविवार का पूर्ण बैकअप और चारों इन्क्रीमेंटल चाहिए: 5 सेट। डिफ़रेंशियल बैकअप होते तो रविवार का पूर्ण और गुरुवार का डिफ़रेंशियल (2 सेट) पर्याप्त होता।"},
  {"id":"comp-ms-office-internet-232","question":"What does a digital certificate, issued by a Certifying Authority, mainly do?","options":["Binds a public key to the verified identity of its owner","Stores the owner's private key for safe-keeping","Encrypts the whole hard disk of the owner","Blocks viruses from the owner's e-mail"],"answer":0,"explanation":"A certificate is the CA's signed statement that a given public key belongs to a given person or website. The private key never leaves its owner.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"प्रमाणन प्राधिकरण (Certifying Authority) द्वारा जारी डिजिटल प्रमाणपत्र मुख्यतः क्या करता है?","optionsHi":["सार्वजनिक कुंजी को उसके स्वामी की सत्यापित पहचान से बाँधता है","स्वामी की निजी कुंजी को सुरक्षित रखने के लिए संग्रहीत करता है","स्वामी की पूरी हार्ड डिस्क को एन्क्रिप्ट करता है","स्वामी के ई-मेल से वायरस को रोकता है"],"explanationHi":"प्रमाणपत्र CA का हस्ताक्षरित कथन है कि कोई सार्वजनिक कुंजी किसी विशेष व्यक्ति या वेबसाइट की है। निजी कुंजी अपने स्वामी के पास से कभी बाहर नहीं जाती।"},
  {"id":"comp-ms-office-internet-233","question":"A web page shows a 'Play video' button, but an invisible frame from another site is laid over it. Clicking it actually presses a hidden 'Confirm transfer' button. This attack is:","options":["Pharming","Clickjacking","Cross-site scripting","Typosquatting"],"answer":1,"explanation":"Clickjacking (UI redressing) tricks the user into clicking something different from what they see, using transparent layers. Typosquatting uses misspelt domain names.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी वेब पेज पर 'Play video' बटन दिखता है, पर उस पर दूसरी साइट का अदृश्य फ़्रेम बिछा है। उस पर क्लिक करने से वास्तव में छिपा हुआ 'Confirm transfer' बटन दब जाता है। यह हमला है:","optionsHi":["फ़ार्मिंग (Pharming)","क्लिकजैकिंग (Clickjacking)","क्रॉस-साइट स्क्रिप्टिंग","टाइपोस्क्वैटिंग (Typosquatting)"],"explanationHi":"क्लिकजैकिंग (UI रिड्रेसिंग) पारदर्शी परतों का उपयोग करके उपयोगकर्ता को जो वह देखता है उससे भिन्न चीज़ पर क्लिक करने के लिए छलती है। टाइपोस्क्वैटिंग गलत वर्तनी वाले डोमेन नामों का उपयोग करती है।"},
  {"id":"comp-ms-office-internet-234","question":"A bank's office PCs become very slow, with fans running loudly, though no files are damaged. Investigation finds a hidden script using their processors to mine cryptocurrency for an outsider. This is called:","options":["Ransomware","Spyware","Cryptojacking","A logic bomb"],"answer":2,"explanation":"Cryptojacking secretly uses the victim's computing power to mine cryptocurrency; its usual symptom is heavy CPU load, not stolen or encrypted files.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी बैंक के कार्यालय के PC बहुत धीमे हो जाते हैं और पंखे ज़ोर से चलते हैं, जबकि कोई फ़ाइल क्षतिग्रस्त नहीं है। जाँच में पता चलता है कि एक छिपी स्क्रिप्ट उनके प्रोसेसरों का उपयोग किसी बाहरी व्यक्ति के लिए क्रिप्टोकरेंसी माइन करने में कर रही है। इसे क्या कहते हैं?","optionsHi":["रैनसमवेयर (Ransomware)","स्पाईवेयर (Spyware)","क्रिप्टोजैकिंग (Cryptojacking)","लॉजिक बम (Logic bomb)"],"explanationHi":"क्रिप्टोजैकिंग पीड़ित की कंप्यूटिंग शक्ति का चुपके से क्रिप्टोकरेंसी माइन करने में उपयोग करती है; इसका सामान्य लक्षण भारी CPU लोड है, चुराई या एन्क्रिप्ट की गई फ़ाइलें नहीं।"},
  {"id":"comp-ms-office-internet-235","question":"Match the file extension with its file type: 1. .xlsm 2. .xltx 3. .potx 4. .dotx; a. Excel template b. Word template c. PowerPoint template d. macro-enabled Excel workbook","options":["1-a, 2-d, 3-c, 4-b","1-d, 2-a, 3-b, 4-c","1-d, 2-c, 3-a, 4-b","1-d, 2-a, 3-c, 4-b"],"answer":3,"explanation":"In Office formats, a final 'm' means macro-enabled and 't' in 'xlt/pot/dot' means template: xl = Excel, pot = PowerPoint template, dot = Word template.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"फ़ाइल एक्सटेंशन को उसके फ़ाइल प्रकार से सुमेलित कीजिए: 1. .xlsm 2. .xltx 3. .potx 4. .dotx; a. Excel टेम्पलेट b. Word टेम्पलेट c. PowerPoint टेम्पलेट d. मैक्रो-सक्षम Excel वर्कबुक","optionsHi":["1-a, 2-d, 3-c, 4-b","1-d, 2-a, 3-b, 4-c","1-d, 2-c, 3-a, 4-b","1-d, 2-a, 3-c, 4-b"],"explanationHi":"Office प्रारूपों में, अंतिम 'm' का अर्थ मैक्रो-सक्षम है और 'xlt/pot/dot' में 't' का अर्थ टेम्पलेट है: xl = Excel, pot = PowerPoint टेम्पलेट, dot = Word टेम्पलेट।"},
  {"id":"comp-ms-office-internet-236","question":"An Excel workbook with three sheets, formulas and coloured cells is saved as a .csv file. What is kept in the CSV file?","options":["Only the active sheet, with the formulas' current values, and no formatting","All three sheets, with formulas and colours","All three sheets, values only, no formatting","Only the active sheet, with formulas and colours"],"answer":0,"explanation":"CSV is plain text with comma-separated values: it holds one sheet, stores results rather than formulas, and cannot store formatting, which is why Excel warns that features will be lost.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"तीन शीट, सूत्र और रंगीन सेल वाली एक Excel वर्कबुक को .csv फ़ाइल के रूप में सेव किया जाता है। CSV फ़ाइल में क्या रखा जाता है?","optionsHi":["केवल सक्रिय शीट, सूत्रों के वर्तमान मानों के साथ, बिना फ़ॉर्मेटिंग के","तीनों शीट, सूत्रों और रंगों के साथ","तीनों शीट, केवल मान, बिना फ़ॉर्मेटिंग के","केवल सक्रिय शीट, सूत्रों और रंगों के साथ"],"explanationHi":"CSV अल्पविराम-पृथक मानों वाला सादा पाठ है: उसमें एक शीट होती है, सूत्रों के बजाय परिणाम संग्रहीत होते हैं, और फ़ॉर्मेटिंग संग्रहीत नहीं हो सकती, इसीलिए Excel चेतावनी देता है कि सुविधाएँ खो जाएँगी।"},
  {"id":"comp-ms-office-internet-237","question":"Match each Excel feature with its use: 1. Data Validation 2. Conditional Formatting 3. PivotTable 4. Remove Duplicates; a. summarising thousands of rows by branch and month b. allowing only dates within a range to be entered c. colouring a cell red when the balance falls below the minimum d. deleting repeated account numbers","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-b, 2-c, 3-d, 4-a"],"answer":1,"explanation":"Data Validation restricts what may be entered, Conditional Formatting changes appearance based on values, a PivotTable summarises large data, and Remove Duplicates deletes repeated rows.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"प्रत्येक Excel सुविधा को उसके उपयोग से सुमेलित कीजिए: 1. Data Validation 2. Conditional Formatting 3. PivotTable 4. Remove Duplicates; a. हज़ारों पंक्तियों का शाखा और माह के अनुसार सार बनाना b. केवल किसी सीमा के भीतर की तारीख़ें दर्ज करने देना c. शेष राशि न्यूनतम से नीचे जाने पर सेल को लाल रंगना d. दोहराए गए खाता क्रमांक हटाना","optionsHi":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-b, 2-c, 3-d, 4-a"],"explanationHi":"Data Validation यह सीमित करता है कि क्या दर्ज किया जा सकता है, Conditional Formatting मानों के आधार पर रूप बदलता है, PivotTable बड़े डेटा का सार बनाता है, और Remove Duplicates दोहराई गई पंक्तियाँ हटाता है।"},
  {"id":"comp-ms-office-internet-238","question":"A planner wants to save 'best case', 'likely case' and 'worst case' sets of several input values (interest rate, growth, costs) and switch between them to compare results. Which Excel tool is designed for this?","options":["Goal Seek","Data Validation","Scenario Manager","Flash Fill"],"answer":2,"explanation":"Scenario Manager stores named sets of input values and shows each one's effect, even as a summary report. Goal Seek works backwards from one target result by changing a single input.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक योजनाकार कई इनपुट मानों (ब्याज दर, वृद्धि, लागत) के 'सर्वोत्तम स्थिति', 'संभावित स्थिति' और 'सबसे खराब स्थिति' वाले सेट सहेजना और परिणामों की तुलना के लिए उनके बीच बदलना चाहता है। Excel का कौन-सा टूल इसी के लिए बना है?","optionsHi":["Goal Seek","Data Validation","Scenario Manager","Flash Fill"],"explanationHi":"Scenario Manager इनपुट मानों के नामित सेट संग्रहीत करता है और प्रत्येक का प्रभाव, सार रिपोर्ट के रूप में भी, दिखाता है। Goal Seek एक लक्ष्य परिणाम से उल्टा चलकर एक इनपुट को बदलता है।"},
  {"id":"comp-ms-office-internet-239","question":"Match each requirement with the most suitable Excel chart: 1. share of each loan type in the total loan book 2. change in monthly deposits over 24 months 3. relationship between customers' income and loan amount for 200 customers; a. Scatter (XY) chart b. Line chart c. Pie chart","options":["1-b, 2-c, 3-a","1-c, 2-a, 3-b","1-a, 2-b, 3-c","1-c, 2-b, 3-a"],"answer":3,"explanation":"A pie shows parts of one whole, a line shows a trend over time, and a scatter plot shows how two numeric variables relate across many points.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"प्रत्येक आवश्यकता को सबसे उपयुक्त Excel चार्ट से सुमेलित कीजिए: 1. कुल ऋण बही में प्रत्येक ऋण प्रकार का हिस्सा 2. 24 माह में मासिक जमा में परिवर्तन 3. 200 ग्राहकों की आय और ऋण राशि के बीच संबंध; a. Scatter (XY) चार्ट b. Line चार्ट c. Pie चार्ट","optionsHi":["1-b, 2-c, 3-a","1-c, 2-a, 3-b","1-a, 2-b, 3-c","1-c, 2-b, 3-a"],"explanationHi":"पाई चार्ट एक संपूर्ण के हिस्से दिखाता है, लाइन चार्ट समय के साथ प्रवृत्ति दिखाता है, और स्कैटर प्लॉट दिखाता है कि दो संख्यात्मक चर कई बिंदुओं में कैसे संबंधित हैं।"},
  {"id":"comp-ms-office-internet-240","question":"In Excel's default 1900 date system, A1 holds the time 9:00 and B1 holds 11:00. What does the cell with =A1-B1, formatted as time, display?","options":["##### because a negative time cannot be displayed","#VALUE!","#NUM!","−2:00"],"answer":0,"explanation":"The result is a negative fraction of a day, and the 1900 date system cannot show negative dates or times, so the cell fills with #####. It is not an error value: the number −0.0833 is still stored.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel की डिफ़ॉल्ट 1900 तिथि प्रणाली में, A1 में समय 9:00 है और B1 में 11:00 है। =A1-B1 वाला सेल, समय के रूप में फ़ॉर्मेट होने पर, क्या दिखाता है?","optionsHi":["##### क्योंकि ऋणात्मक समय नहीं दिखाया जा सकता","#VALUE!","#NUM!","−2:00"],"explanationHi":"परिणाम दिन का ऋणात्मक अंश है, और 1900 तिथि प्रणाली ऋणात्मक तिथियाँ या समय नहीं दिखा सकती, इसलिए सेल ##### से भर जाता है। यह त्रुटि मान नहीं है: संख्या −0.0833 फिर भी संग्रहीत है।"},
  {"id":"comp-ms-office-internet-241","question":"In Excel, A2:A7 contain North, South, North, East, North, South and B2:B7 contain 500, 300, 800, 200, 450, 900. What does =COUNTIFS(A2:A7, \"North\", B2:B7, \">450\") return?","options":["3","2","4","6"],"answer":1,"explanation":"COUNTIFS needs BOTH conditions on the same row: the North rows hold 500, 800 and 450, and only 500 and 800 are greater than 450, giving 2. 3 wrongly treats >450 as >=450.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A2:A7 में North, South, North, East, North, South हैं और B2:B7 में 500, 300, 800, 200, 450, 900 हैं। =COUNTIFS(A2:A7, \"North\", B2:B7, \">450\") क्या लौटाता है?","optionsHi":["3","2","4","6"],"explanationHi":"COUNTIFS को एक ही पंक्ति में दोनों शर्तें चाहिए: North वाली पंक्तियों में 500, 800 और 450 हैं, और केवल 500 तथा 800, 450 से बड़े हैं, जो 2 देता है। 3 गलती से >450 को >=450 मानता है।"},
  {"id":"comp-ms-office-internet-242","question":"In Excel, A1:A5 contain 50, 80, 80, 60 and 70. What does =RANK(60, A1:A5) return?","options":["3","2","5","4"],"answer":3,"explanation":"RANK sorts in descending order by default and tied values share a rank but still use up places: 80 and 80 are both rank 1, 70 is rank 3, so 60 is rank 4. 3 is the 'dense' rank that skips no places.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1:A5 में 50, 80, 80, 60 और 70 हैं। =RANK(60, A1:A5) क्या लौटाता है?","optionsHi":["3","2","5","4"],"explanationHi":"RANK डिफ़ॉल्ट रूप से अवरोही क्रम में क्रमबद्ध करता है और बराबर मान एक रैंक साझा करते हैं पर स्थान फिर भी घेरते हैं: 80 और 80 दोनों रैंक 1 हैं, 70 रैंक 3 है, इसलिए 60 रैंक 4 है। 3 वह 'घना' (dense) रैंक है जो कोई स्थान नहीं छोड़ता।"},
  {"id":"comp-ms-office-internet-243","question":"What does the Excel formula =RIGHT(\"IFSC0001234\", LEN(\"IFSC0001234\")-4) return?","options":["IFSC","1234","0001234","C0001234"],"answer":2,"explanation":"LEN gives 11, so RIGHT takes the last 11 − 4 = 7 characters: 0001234, i.e. everything after the first four letters. 1234 would need RIGHT(…, 4).","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel का सूत्र =RIGHT(\"IFSC0001234\", LEN(\"IFSC0001234\")-4) क्या लौटाता है?","optionsHi":["IFSC","1234","0001234","C0001234"],"explanationHi":"LEN 11 देता है, इसलिए RIGHT अंतिम 11 − 4 = 7 अक्षर लेता है: 0001234, अर्थात पहले चार अक्षरों के बाद का सब कुछ। 1234 के लिए RIGHT(…, 4) चाहिए।"},
  {"id":"comp-ms-office-internet-244","question":"In Excel, A1 = 60 and B1 = 45. What does =IF(OR(AND(A1>50, B1>50), A1>55), \"Pass\", \"Fail\") return?","options":["Pass","Fail","TRUE","#VALUE!"],"answer":0,"explanation":"AND(60>50, 45>50) is FALSE, but A1>55 is TRUE, so OR(FALSE, TRUE) is TRUE and IF returns 'Pass'. Stopping at the false AND gives the trap 'Fail'.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1 = 60 और B1 = 45 है। =IF(OR(AND(A1>50, B1>50), A1>55), \"Pass\", \"Fail\") क्या लौटाता है?","optionsHi":["Pass","Fail","TRUE","#VALUE!"],"explanationHi":"AND(60>50, 45>50) FALSE है, पर A1>55 TRUE है, इसलिए OR(FALSE, TRUE) TRUE है और IF 'Pass' लौटाता है। असत्य AND पर रुक जाने से जाल वाला उत्तर 'Fail' मिलता है।"},
  {"id":"comp-ms-office-internet-245","question":"In Excel, A1:C3 hold 10, 20, 30 in row 1; 40, 50, 60 in row 2; and 70, 80, 90 in row 3. What does =INDEX(A1:C3, 2, 3) return?","options":["80","50","30","60"],"answer":3,"explanation":"INDEX takes the row number first and then the column: row 2, column 3 is cell C2, which holds 60. 80 comes from swapping them (row 3, column 2).","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1:C3 में पंक्ति 1 में 10, 20, 30; पंक्ति 2 में 40, 50, 60; और पंक्ति 3 में 70, 80, 90 हैं। =INDEX(A1:C3, 2, 3) क्या लौटाता है?","optionsHi":["80","50","30","60"],"explanationHi":"INDEX पहले पंक्ति संख्या और फिर कॉलम लेता है: पंक्ति 2, कॉलम 3 सेल C2 है, जिसमें 60 है। 80 उन्हें आपस में बदलने (पंक्ति 3, कॉलम 2) से आता है।"},
  {"id":"comp-ms-office-internet-246","question":"In Excel, A1:A6 contain Anand, Kiran, Manoj, Rohan, Divya and Chandan. What does =COUNTIF(A1:A6, \"*an\") return?","options":["5","1","3","4"],"answer":2,"explanation":"The * wildcard stands for any characters, so \"*an\" means 'ends with an': Kiran, Rohan and Chandan, giving 3. 5 counts names that merely CONTAIN 'an', and 1 counts names that start with it.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"Excel में A1:A6 में Anand, Kiran, Manoj, Rohan, Divya और Chandan हैं। =COUNTIF(A1:A6, \"*an\") क्या लौटाता है?","optionsHi":["5","1","3","4"],"explanationHi":"* वाइल्डकार्ड किन्हीं भी अक्षरों के लिए है, इसलिए \"*an\" का अर्थ है 'an पर समाप्त': Kiran, Rohan और Chandan, जो 3 देते हैं। 5 उन नामों को गिनता है जिनमें केवल 'an' आता है, और 1 उन्हें गिनता है जो उससे शुरू होते हैं।"},
  {"id":"comp-ms-office-internet-247","question":"Which Excel formula gives the monthly EMI on a loan of ₹5,00,000 at 12% per annum for 5 years, with monthly payments?","options":["=PMT(12%, 5, 500000)","=PMT(12%/12, 5, 500000)","=PMT(12%, 5*12, 500000)","=PMT(12%/12, 5*12, 500000)"],"answer":3,"explanation":"The rate and the number of periods must both be monthly: 12%/12 = 1% per month for 60 months. The result is about −11,122; PMT shows it as negative because it is money paid out.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"मासिक भुगतानों के साथ, ₹5,00,000 के ऋण पर 12% वार्षिक दर से 5 वर्ष के लिए मासिक EMI कौन-सा Excel सूत्र देता है?","optionsHi":["=PMT(12%, 5, 500000)","=PMT(12%/12, 5, 500000)","=PMT(12%, 5*12, 500000)","=PMT(12%/12, 5*12, 500000)"],"explanationHi":"दर और अवधियों की संख्या दोनों मासिक होनी चाहिए: 12%/12 = 1% प्रति माह, 60 माह के लिए। परिणाम लगभग −11,122 है; PMT इसे ऋणात्मक दिखाता है क्योंकि यह बाहर जाने वाला धन है।"},
  {"id":"comp-ms-office-internet-248","question":"An Excel sheet must let users type only in B2:B10 while every other cell stays read-only. Which method works?","options":["Unlock B2:B10 in Format Cells, then protect the sheet","Lock B2:B10 in Format Cells, then protect the sheet","Protect the sheet first; Excel then lets you pick the editable cells automatically","Hide all other rows and columns"],"answer":0,"explanation":"Every cell is formatted 'Locked' by default, but locking takes effect only when the sheet is protected. So unlock the cells that should stay editable, then protect the sheet.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक Excel शीट में उपयोगकर्ता केवल B2:B10 में टाइप कर सकें और बाकी हर सेल केवल-पठन रहे। कौन-सा तरीका काम करता है?","optionsHi":["Format Cells में B2:B10 को अनलॉक करें, फिर शीट को सुरक्षित (protect) करें","Format Cells में B2:B10 को लॉक करें, फिर शीट को सुरक्षित करें","पहले शीट को सुरक्षित करें; तब Excel संपादन योग्य सेल अपने आप चुनने देता है","अन्य सभी पंक्तियाँ और कॉलम छिपा दें"],"explanationHi":"हर सेल डिफ़ॉल्ट रूप से 'Locked' फ़ॉर्मेट होता है, पर लॉकिंग तभी प्रभावी होती है जब शीट सुरक्षित हो। इसलिए जिन सेलों को संपादन योग्य रखना है उन्हें अनलॉक करें, फिर शीट सुरक्षित करें।"},
  {"id":"comp-ms-office-internet-249","question":"In MS Excel, what does Ctrl + R do when a range such as A1:E1 is selected?","options":["Right-aligns the text in the selected cells","Copies the contents of the leftmost cell into the other selected cells to its right","Repeats the last action","Opens the Replace dialog box"],"answer":1,"explanation":"In Excel, Ctrl + R is Fill Right, just as Ctrl + D is Fill Down. The trap comes from Word, where Ctrl + R right-aligns a paragraph.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"MS Excel में, A1:E1 जैसी रेंज चयनित होने पर Ctrl + R क्या करता है?","optionsHi":["चयनित सेलों के पाठ को दाएँ संरेखित करता है","सबसे बाएँ सेल की सामग्री को उसके दाईं ओर के अन्य चयनित सेलों में कॉपी करता है","अंतिम क्रिया दोहराता है","Replace डायलॉग बॉक्स खोलता है"],"explanationHi":"Excel में Ctrl + R, Fill Right है, ठीक जैसे Ctrl + D, Fill Down है। जाल Word से आता है, जहाँ Ctrl + R अनुच्छेद को दाएँ संरेखित करता है।"},
  {"id":"comp-ms-office-internet-250","question":"While editing a long Excel formula, a user selects the part SUM(B2:B5) in the formula bar and presses F9. What happens?","options":["The whole workbook is recalculated and the formula is unchanged","The selected part is turned into an absolute reference","The selected part is replaced by its calculated value inside the formula","Excel shows an error, because F9 works only outside edit mode"],"answer":2,"explanation":"Pressing F9 in edit mode evaluates the selected part and puts its result into the formula, which is useful for checking; pressing Esc cancels the change. F4, not F9, toggles absolute references.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"किसी लंबे Excel सूत्र को संपादित करते समय, उपयोगकर्ता फ़ॉर्मूला बार में भाग SUM(B2:B5) को चयनित करता है और F9 दबाता है। क्या होता है?","optionsHi":["पूरी वर्कबुक पुनर्गणना होती है और सूत्र अपरिवर्तित रहता है","चयनित भाग निरपेक्ष संदर्भ में बदल जाता है","चयनित भाग सूत्र के भीतर उसके परिकलित मान से बदल जाता है","Excel त्रुटि दिखाता है, क्योंकि F9 केवल संपादन मोड के बाहर काम करता है"],"explanationHi":"संपादन मोड में F9 दबाने से चयनित भाग का मूल्यांकन होता है और उसका परिणाम सूत्र में आ जाता है, जो जाँच के लिए उपयोगी है; Esc दबाने से परिवर्तन रद्द हो जाता है। निरपेक्ष संदर्भ F4 बदलता है, F9 नहीं।"},
  {"id":"comp-ms-office-internet-251","question":"A user enters =SUM(A1:A5) into cell A1 itself. What happens?","options":["Excel shows #REF!","Excel adds A2:A5 and silently ignores A1","Excel shows #VALUE!","Excel warns of a circular reference, because the formula depends on its own cell"],"answer":3,"explanation":"A formula that refers, directly or indirectly, to its own cell creates a circular reference; Excel warns about it and usually shows 0 instead of looping forever.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"कोई उपयोगकर्ता सेल A1 में ही =SUM(A1:A5) दर्ज करता है। क्या होता है?","optionsHi":["Excel #REF! दिखाता है","Excel A2:A5 जोड़ता है और A1 को चुपचाप अनदेखा करता है","Excel #VALUE! दिखाता है","Excel वृत्तीय संदर्भ (circular reference) की चेतावनी देता है, क्योंकि सूत्र अपने ही सेल पर निर्भर है"],"explanationHi":"जो सूत्र प्रत्यक्ष या अप्रत्यक्ष रूप से अपने ही सेल का संदर्भ देता है, वह वृत्तीय संदर्भ बनाता है; Excel उसकी चेतावनी देता है और सामान्यतः अनंत लूप के बजाय 0 दिखाता है।"},
  {"id":"comp-ms-office-internet-252","question":"What does the Excel formula =QUOTIENT(-7, 2) + MOD(-7, 2) return?","options":["-3","-4","-5","-2"],"answer":3,"explanation":"QUOTIENT truncates towards zero, so QUOTIENT(-7, 2) = -3, while MOD takes the sign of the divisor, so MOD(-7, 2) = 1. The sum is -3 + 1 = -2.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel का सूत्र =QUOTIENT(-7, 2) + MOD(-7, 2) क्या लौटाता है?","optionsHi":["-3","-4","-5","-2"],"explanationHi":"QUOTIENT शून्य की ओर काटता है, इसलिए QUOTIENT(-7, 2) = -3, जबकि MOD भाजक का चिह्न लेता है, इसलिए MOD(-7, 2) = 1। योग -3 + 1 = -2 है।"},
  {"id":"comp-ms-office-internet-253","question":"What does the Excel formula =COUNT(1, \"2\", \"a\", TRUE) return, where all four values are typed directly as arguments?","options":["1","3","2","4"],"answer":1,"explanation":"When typed directly as arguments, COUNT also counts a number written as text (\"2\") and a logical value (TRUE); only \"a\" is skipped, giving 3. Inside a referenced range, text and TRUE would be ignored.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =COUNT(1, \"2\", \"a\", TRUE) क्या लौटाता है, जहाँ चारों मान सीधे तर्क (argument) के रूप में टाइप किए गए हैं?","optionsHi":["1","3","2","4"],"explanationHi":"सीधे तर्क के रूप में टाइप करने पर COUNT पाठ के रूप में लिखी संख्या (\"2\") और तार्किक मान (TRUE) को भी गिनता है; केवल \"a\" छूटता है, जिससे 3 मिलता है। संदर्भित रेंज के भीतर पाठ और TRUE अनदेखे किए जाते।"},
  {"id":"comp-ms-office-internet-254","question":"In Excel, A1 = TRUE, A2 = 2 and A3 holds the text \"3\". What do =SUM(A1:A3) and =SUM(TRUE, 2, \"3\") return respectively?","options":["6 and 6","2 and 2","2 and 6","6 and 2"],"answer":2,"explanation":"SUM ignores logical values and numbers stored as text inside a range, so the first gives 2. Typed directly as arguments, TRUE counts as 1 and \"3\" as 3, so the second gives 6.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 = TRUE, A2 = 2 है और A3 में पाठ \"3\" है। =SUM(A1:A3) और =SUM(TRUE, 2, \"3\") क्रमशः क्या लौटाते हैं?","optionsHi":["6 और 6","2 और 2","2 और 6","6 और 2"],"explanationHi":"SUM रेंज के भीतर तार्किक मानों और पाठ के रूप में संग्रहीत संख्याओं को अनदेखा करता है, इसलिए पहला 2 देता है। सीधे तर्क के रूप में टाइप करने पर TRUE 1 गिना जाता है और \"3\" 3, इसलिए दूसरा 6 देता है।"},
  {"id":"comp-ms-office-internet-255","question":"What does the Excel formula =(5>3) + (2>4) + TRUE return?","options":["2","1","TRUE","#VALUE!"],"answer":0,"explanation":"In arithmetic, Excel treats TRUE as 1 and FALSE as 0. (5>3) is TRUE, (2>4) is FALSE, so the result is 1 + 0 + 1 = 2.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL","questionHi":"Excel का सूत्र =(5>3) + (2>4) + TRUE क्या लौटाता है?","optionsHi":["2","1","TRUE","#VALUE!"],"explanationHi":"अंकगणित में Excel TRUE को 1 और FALSE को 0 मानता है। (5>3) TRUE है, (2>4) FALSE है, इसलिए परिणाम 1 + 0 + 1 = 2 है।"},
  {"id":"comp-ms-office-internet-256","question":"What does the Excel formula =DAY(DATE(2024, 3, 0)) return?","options":["28","31","29","#NUM!"],"answer":2,"explanation":"Day 0 of a month is the last day of the previous month, so DATE(2024, 3, 0) is 29 February 2024 (a leap year), and DAY gives 29.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =DAY(DATE(2024, 3, 0)) क्या लौटाता है?","optionsHi":["28","31","29","#NUM!"],"explanationHi":"किसी माह का दिन 0 पिछले माह का अंतिम दिन होता है, इसलिए DATE(2024, 3, 0) 29 फ़रवरी 2024 (अधिवर्ष) है, और DAY 29 देता है।"},
  {"id":"comp-ms-office-internet-257","question":"What does =DATEDIF(DATE(2000, 5, 15), DATE(2024, 5, 14), \"Y\") return in Excel?","options":["24","22","#NUM!","23"],"answer":3,"explanation":"The \"Y\" unit counts only complete years. The 24th anniversary falls on 15 May 2024, one day after the end date, so only 23 full years have passed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में =DATEDIF(DATE(2000, 5, 15), DATE(2024, 5, 14), \"Y\") क्या लौटाता है?","optionsHi":["24","22","#NUM!","23"],"explanationHi":"\"Y\" इकाई केवल पूरे वर्ष गिनती है। चौबीसवीं वर्षगाँठ 15 मई 2024 को पड़ती है, जो अंतिम तिथि के एक दिन बाद है, इसलिए केवल 23 पूरे वर्ष बीते हैं।"},
  {"id":"comp-ms-office-internet-258","question":"1 January 2024 was a Monday. What does =NETWORKDAYS(DATE(2024, 1, 1), DATE(2024, 1, 14)) return in Excel?","options":["9","10","12","14"],"answer":1,"explanation":"NETWORKDAYS counts Monday-to-Friday days with both end dates included. 1 to 14 January is exactly two full weeks, so 2 × 5 = 10 working days.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"1 जनवरी 2024 सोमवार था। Excel में =NETWORKDAYS(DATE(2024, 1, 1), DATE(2024, 1, 14)) क्या लौटाता है?","optionsHi":["9","10","12","14"],"explanationHi":"NETWORKDAYS दोनों अंतिम तिथियाँ शामिल करके सोमवार से शुक्रवार तक के दिन गिनता है। 1 से 14 जनवरी ठीक दो पूरे सप्ताह हैं, इसलिए 2 × 5 = 10 कार्य-दिवस।"},
  {"id":"comp-ms-office-internet-259","question":"In Excel, A1:D1 contain Q1, Q2, Q3, Q4 and A2:D2 contain 120, 150, 90, 200. What does =HLOOKUP(\"Q3\", A1:D2, 2, FALSE) return?","options":["150","90","200","#N/A"],"answer":1,"explanation":"HLOOKUP finds Q3 in the top row (column C) and returns the value from row 2 of that column, which is 90.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CHSL","questionHi":"Excel में A1:D1 में Q1, Q2, Q3, Q4 हैं और A2:D2 में 120, 150, 90, 200 हैं। =HLOOKUP(\"Q3\", A1:D2, 2, FALSE) क्या लौटाता है?","optionsHi":["150","90","200","#N/A"],"explanationHi":"HLOOKUP शीर्ष पंक्ति में Q3 पाता है (कॉलम C) और उस कॉलम की पंक्ति 2 का मान लौटाता है, जो 90 है।"},
  {"id":"comp-ms-office-internet-260","question":"3 January 2024 was a Wednesday. What does =CHOOSE(WEEKDAY(DATE(2024, 1, 3)), \"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\") return?","options":["Wed","Tue","Thu","Mon"],"answer":0,"explanation":"With its default type, WEEKDAY numbers Sunday as 1, so a Wednesday gives 4, and CHOOSE picks the 4th item, \"Wed\". Answering Tue assumes Monday = 1.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"3 जनवरी 2024 बुधवार था। =CHOOSE(WEEKDAY(DATE(2024, 1, 3)), \"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\") क्या लौटाता है?","optionsHi":["Wed","Tue","Thu","Mon"],"explanationHi":"डिफ़ॉल्ट प्रकार के साथ WEEKDAY रविवार को 1 क्रमांक देता है, इसलिए बुधवार 4 देता है, और CHOOSE चौथा आइटम चुनता है, \"Wed\"। Tue उत्तर देना यह मानता है कि सोमवार = 1।"},
  {"id":"comp-ms-office-internet-261","question":"What does the Excel formula =MEDIAN(23, 4, 42, 15, 8, 16) return?","options":["28.5","18","15.5","15"],"answer":2,"explanation":"Sorted, the values are 4, 8, 15, 16, 23, 42. With an even count, the median is the average of the middle two: (15 + 16) / 2 = 15.5. 18 is the mean, and 28.5 comes from not sorting first.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL","questionHi":"Excel का सूत्र =MEDIAN(23, 4, 42, 15, 8, 16) क्या लौटाता है?","optionsHi":["28.5","18","15.5","15"],"explanationHi":"क्रमबद्ध करने पर मान 4, 8, 15, 16, 23, 42 हैं। सम संख्या होने पर माध्यिका बीच के दो मानों का औसत है: (15 + 16) / 2 = 15.5। 18 माध्य (mean) है, और 28.5 पहले क्रमबद्ध न करने से आता है।"},
  {"id":"comp-ms-office-internet-262","question":"In Excel, A1 contains \"Rohit Kumar Sharma\". What does =MID(A1, FIND(\" \", A1) + 1, FIND(\" \", A1, FIND(\" \", A1) + 1) - FIND(\" \", A1) - 1) return?","options":["Sharma","Kumar Sharma","umar S","Kumar"],"answer":3,"explanation":"The first space is at position 6 and the second at 12. MID starts at 7 and takes 12 - 6 - 1 = 5 characters, giving the middle name \"Kumar\".","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 में \"Rohit Kumar Sharma\" है। =MID(A1, FIND(\" \", A1) + 1, FIND(\" \", A1, FIND(\" \", A1) + 1) - FIND(\" \", A1) - 1) क्या लौटाता है?","optionsHi":["Sharma","Kumar Sharma","umar S","Kumar"],"explanationHi":"पहला रिक्त स्थान स्थिति 6 पर और दूसरा 12 पर है। MID 7 से शुरू करके 12 - 6 - 1 = 5 अक्षर लेता है, जो मध्य नाम \"Kumar\" देता है।"},
  {"id":"comp-ms-office-internet-263","question":"A2:A7 contain North, South, North, North, East, South; B2:B7 contain 5, 8, 12, 3, 9, 10; C2:C7 contain 100, 200, 300, 400, 500, 600. What does =SUMIFS(C2:C7, A2:A7, \"North\", B2:B7, \">4\") return?","options":["400","800","1700","300"],"answer":0,"explanation":"Both conditions must hold in the same row: North rows have B values 5, 12 and 3, and only 5 and 12 are above 4, so 100 + 300 = 400. 800 ignores the second condition.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"A2:A7 में North, South, North, North, East, South हैं; B2:B7 में 5, 8, 12, 3, 9, 10 हैं; C2:C7 में 100, 200, 300, 400, 500, 600 हैं। =SUMIFS(C2:C7, A2:A7, \"North\", B2:B7, \">4\") क्या लौटाता है?","optionsHi":["400","800","1700","300"],"explanationHi":"दोनों शर्तें एक ही पंक्ति में पूरी होनी चाहिए: North पंक्तियों के B मान 5, 12 और 3 हैं, और केवल 5 तथा 12, 4 से ऊपर हैं, इसलिए 100 + 300 = 400। 800 दूसरी शर्त को अनदेखा करता है।"},
  {"id":"comp-ms-office-internet-264","question":"In Excel, A1:A6 contain Ram, Raja, Ravi, Rani, Rajiv and Roy. What does =COUNTIF(A1:A6, \"Ra??\") return?","options":["5","4","3","2"],"answer":2,"explanation":"Each ? stands for exactly one character, so \"Ra??\" matches four-letter names starting with Ra: Raja, Ravi and Rani. \"Ra*\" would have matched 5, adding Ram and Rajiv.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में A1:A6 में Ram, Raja, Ravi, Rani, Rajiv और Roy हैं। =COUNTIF(A1:A6, \"Ra??\") क्या लौटाता है?","optionsHi":["5","4","3","2"],"explanationHi":"प्रत्येक ? ठीक एक अक्षर के लिए है, इसलिए \"Ra??\" Ra से शुरू होने वाले चार-अक्षर वाले नामों से मेल खाता है: Raja, Ravi और Rani। \"Ra*\" 5 से मेल खाता, जिसमें Ram और Rajiv जुड़ जाते।"},
  {"id":"comp-ms-office-internet-265","question":"In Excel, A1 = 45, A2 holds the text \"90\", A3 = TRUE, A4 = 60 and A5 is blank. What does =MAX(A1:A5) return?","options":["90","1","60","0"],"answer":2,"explanation":"When MAX reads a range, it ignores text (even number-like text), logical values and blanks, so only 45 and 60 are compared.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"Excel में A1 = 45 है, A2 में पाठ \"90\" है, A3 = TRUE है, A4 = 60 है और A5 रिक्त है। =MAX(A1:A5) क्या लौटाता है?","optionsHi":["90","1","60","0"],"explanationHi":"जब MAX रेंज पढ़ता है, तो वह पाठ (संख्या जैसे दिखने वाले पाठ को भी), तार्किक मानों और रिक्त सेलों को अनदेखा करता है, इसलिए केवल 45 और 60 की तुलना होती है।"},
  {"id":"comp-ms-office-internet-266","question":"What does the Excel formula =ROUNDUP(2.001, 0) + ROUNDDOWN(2.999, 0) return?","options":["4","5","6","3"],"answer":1,"explanation":"ROUNDUP always moves away from zero (2.001 to 3) and ROUNDDOWN always towards zero (2.999 to 2), whatever the next digit, so 3 + 2 = 5.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"Excel का सूत्र =ROUNDUP(2.001, 0) + ROUNDDOWN(2.999, 0) क्या लौटाता है?","optionsHi":["4","5","6","3"],"explanationHi":"ROUNDUP हमेशा शून्य से दूर जाता है (2.001 से 3) और ROUNDDOWN हमेशा शून्य की ओर (2.999 से 2), अगला अंक चाहे जो हो, इसलिए 3 + 2 = 5।"},
  {"id":"comp-ms-office-internet-267","question":"What does the Excel formula =ISNUMBER(\"5\") + ISNUMBER(5) + ISTEXT(\"5\") return?","options":["3","1","#VALUE!","2"],"answer":3,"explanation":"\"5\" in quotes is text, so ISNUMBER(\"5\") is FALSE (0) and ISTEXT(\"5\") is TRUE (1); ISNUMBER(5) is TRUE (1). The sum is 2.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =ISNUMBER(\"5\") + ISNUMBER(5) + ISTEXT(\"5\") क्या लौटाता है?","optionsHi":["3","1","#VALUE!","2"],"explanationHi":"उद्धरण चिह्नों में \"5\" पाठ है, इसलिए ISNUMBER(\"5\") FALSE (0) है और ISTEXT(\"5\") TRUE (1) है; ISNUMBER(5) TRUE (1) है। योग 2 है।"},
  {"id":"comp-ms-office-internet-268","question":"What do =IF(\"abc\"=\"ABC\", \"Same\", \"Different\") and =IF(EXACT(\"abc\", \"ABC\"), \"Same\", \"Different\") return respectively?","options":["Same and Same","Different and Different","Different and Same","Same and Different"],"answer":3,"explanation":"The = operator compares text without regard to case, so the first gives Same. EXACT is case-sensitive, so the second gives Different.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"=IF(\"abc\"=\"ABC\", \"Same\", \"Different\") और =IF(EXACT(\"abc\", \"ABC\"), \"Same\", \"Different\") क्रमशः क्या लौटाते हैं?","optionsHi":["Same और Same","Different और Different","Different और Same","Same और Different"],"explanationHi":"= संक्रियक पाठ की तुलना अक्षर-भेद की परवाह किए बिना करता है, इसलिए पहला Same देता है। EXACT अक्षर-संवेदी है, इसलिए दूसरा Different देता है।"},
  {"id":"comp-ms-office-internet-269","question":"In Excel, A1 holds the date 31 January 2024. Which date does =A1 + 30 show?","options":["2 March 2024","1 March 2024","29 February 2024","28 February 2024"],"answer":1,"explanation":"Adding a number to a date adds days. 2024 is a leap year, so 31 January + 29 days is 29 February and + 30 days is 1 March 2024.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"Excel में A1 में तारीख़ 31 जनवरी 2024 है। =A1 + 30 कौन-सी तारीख़ दिखाता है?","optionsHi":["2 मार्च 2024","1 मार्च 2024","29 फ़रवरी 2024","28 फ़रवरी 2024"],"explanationHi":"किसी तारीख़ में संख्या जोड़ने पर दिन जुड़ते हैं। 2024 अधिवर्ष है, इसलिए 31 जनवरी + 29 दिन 29 फ़रवरी है और + 30 दिन 1 मार्च 2024 है।"},
  {"id":"comp-ms-office-internet-270","question":"In Excel, A1 contains 2.5 but is formatted with 0 decimal places, so it shows 3. What does =A1*2 return?","options":["5","6","3","4"],"answer":0,"explanation":"Number formatting changes only the display; the stored value is still 2.5, so the formula gives 5. Using the shown value would give 6.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में A1 में 2.5 है, पर उसे 0 दशमलव स्थान के साथ फ़ॉर्मेट किया गया है, इसलिए वह 3 दिखाता है। =A1*2 क्या लौटाता है?","optionsHi":["5","6","3","4"],"explanationHi":"संख्या फ़ॉर्मेटिंग केवल प्रदर्शन बदलती है; संग्रहीत मान अब भी 2.5 है, इसलिए सूत्र 5 देता है। दिखाए गए मान का उपयोग करने पर 6 मिलता।"},
  {"id":"comp-ms-office-internet-271","question":"In Excel, A1 contains the number 12.50, formatted to show two decimal places. What does =LEN(A1) return?","options":["5","2","4","#VALUE!"],"answer":2,"explanation":"LEN works on the stored value, 12.5, not on the formatted display, so it counts \"12.5\", which is 4 characters.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 में संख्या 12.50 है, जिसे दो दशमलव स्थान दिखाने के लिए फ़ॉर्मेट किया गया है। =LEN(A1) क्या लौटाता है?","optionsHi":["5","2","4","#VALUE!"],"explanationHi":"LEN संग्रहीत मान 12.5 पर काम करता है, फ़ॉर्मेट किए गए प्रदर्शन पर नहीं, इसलिए वह \"12.5\" गिनता है, जो 4 अक्षर है।"},
  {"id":"comp-ms-office-internet-272","question":"A2:A6 contain Amit, Bina, Chirag, Deepa, Esha and B2:B6 contain 78, 91, 85, 91, 66. What does =INDEX(A2:A6, MATCH(MAX(B2:B6), B2:B6, 0)) return?","options":["Bina","Deepa","91","#N/A"],"answer":0,"explanation":"MAX gives 91, and MATCH with 0 returns the position of the FIRST 91, which is 2, so INDEX gives Bina even though Deepa has the same mark.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"A2:A6 में Amit, Bina, Chirag, Deepa, Esha हैं और B2:B6 में 78, 91, 85, 91, 66 हैं। =INDEX(A2:A6, MATCH(MAX(B2:B6), B2:B6, 0)) क्या लौटाता है?","optionsHi":["Bina","Deepa","91","#N/A"],"explanationHi":"MAX 91 देता है, और 0 के साथ MATCH पहले 91 की स्थिति लौटाता है, जो 2 है, इसलिए INDEX Bina देता है, भले ही Deepa के अंक भी वही हैं।"},
  {"id":"comp-ms-office-internet-273","question":"In Excel's default 1900 date system, what does the formula =\"Due: \" & DATE(2024, 1, 1) return?","options":["Due: 01-01-2024","Due: 1 Jan 2024","#VALUE!","Due: 45292"],"answer":3,"explanation":"The & operator joins the underlying serial number of the date, which for 1 January 2024 is 45292; the date format is lost. TEXT(DATE(2024,1,1), \"dd-mm-yyyy\") would keep it readable.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel की डिफ़ॉल्ट 1900 तिथि प्रणाली में, सूत्र =\"Due: \" & DATE(2024, 1, 1) क्या लौटाता है?","optionsHi":["Due: 01-01-2024","Due: 1 Jan 2024","#VALUE!","Due: 45292"],"explanationHi":"& संक्रियक तारीख़ का अंतर्निहित क्रमांक जोड़ता है, जो 1 जनवरी 2024 के लिए 45292 है; तारीख़ का फ़ॉर्मेट खो जाता है। TEXT(DATE(2024,1,1), \"dd-mm-yyyy\") उसे पठनीय रखता।"},
  {"id":"comp-ms-office-internet-274","question":"What does the Excel formula =ROUND(15.5, 0) + ROUND(-15.5, 0) return?","options":["1","32","31","0"],"answer":3,"explanation":"Excel's ROUND sends a 5 away from zero on both sides, so 15.5 becomes 16 and -15.5 becomes -16, giving 0. Answering 1 assumes -15.5 rounds up to -15.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =ROUND(15.5, 0) + ROUND(-15.5, 0) क्या लौटाता है?","optionsHi":["1","32","31","0"],"explanationHi":"Excel का ROUND दोनों ओर 5 को शून्य से दूर भेजता है, इसलिए 15.5 बदलकर 16 और -15.5 बदलकर -16 हो जाता है, जिससे 0 मिलता है। 1 उत्तर यह मानता है कि -15.5 ऊपर -15 की ओर पूर्णांकित होता है।"},
  {"id":"comp-ms-office-internet-275","question":"How many capital letters are there in the result of the Excel formula =PROPER(\"o'neil mcDONALD\")?","options":["2","3","4","5"],"answer":1,"explanation":"PROPER capitalises the first letter of the text and every letter that follows a non-letter (an apostrophe counts), and lower-cases the rest, giving O'Neil Mcdonald: capitals O, N and M.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel के सूत्र =PROPER(\"o'neil mcDONALD\") के परिणाम में कितने बड़े अक्षर (capital letters) हैं?","optionsHi":["2","3","4","5"],"explanationHi":"PROPER पाठ के पहले अक्षर और हर उस अक्षर को बड़ा करता है जो किसी गैर-अक्षर (एपॉस्ट्रॉफ़ भी गिना जाता है) के बाद आता है, और बाकी को छोटा करता है, जिससे O'Neil Mcdonald मिलता है: बड़े अक्षर O, N और M।"},
  {"id":"comp-ms-office-internet-276","question":"Which formula correctly adds C2:C7 only for rows where A2:A7 is \"North\" and B2:B7 is greater than 4?","options":["=SUMIFS(C2:C7, A2:A7, \"North\", B2:B7, \">4\")","=SUMIFS(A2:A7, \"North\", B2:B7, \">4\", C2:C7)","=SUMIF(A2:A7, \"North\", C2:C7, B2:B7, \">4\")","=SUMIFS(C2:C7, \"North\", A2:A7, \">4\", B2:B7)"],"answer":0,"explanation":"SUMIFS puts the sum range first, then criteria range and criterion pairs, with text and comparison criteria in quotes. SUMIF takes only one condition, with the sum range last.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"कौन-सा सूत्र C2:C7 को केवल उन पंक्तियों के लिए सही जोड़ता है जहाँ A2:A7 \"North\" है और B2:B7, 4 से बड़ा है?","optionsHi":["=SUMIFS(C2:C7, A2:A7, \"North\", B2:B7, \">4\")","=SUMIFS(A2:A7, \"North\", B2:B7, \">4\", C2:C7)","=SUMIF(A2:A7, \"North\", C2:C7, B2:B7, \">4\")","=SUMIFS(C2:C7, \"North\", A2:A7, \">4\", B2:B7)"],"explanationHi":"SUMIFS में योग रेंज पहले आती है, फिर मानदंड रेंज और मानदंड के जोड़े, जिसमें पाठ और तुलना वाले मानदंड उद्धरण चिह्नों में होते हैं। SUMIF केवल एक शर्त लेता है, जिसमें योग रेंज अंत में होती है।"},
  {"id":"comp-ms-office-internet-277","question":"What does the Excel formula =FV(10%, 2, 0, -1000) return?","options":["1331","1200","1210","1100"],"answer":2,"explanation":"FV compounds the present value: 1000 × 1.1² = 1210. The PV is entered as negative (money paid out), so the future value comes out positive.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel का सूत्र =FV(10%, 2, 0, -1000) क्या लौटाता है?","optionsHi":["1331","1200","1210","1100"],"explanationHi":"FV वर्तमान मान पर चक्रवृद्धि करता है: 1000 × 1.1² = 1210। PV ऋणात्मक दर्ज किया जाता है (बाहर जाने वाला धन), इसलिए भविष्य मान धनात्मक आता है।"},
  {"id":"comp-ms-office-internet-278","question":"In Excel, the range A1:A10 is selected, the word Pending is typed and Ctrl + Enter is pressed. What happens?","options":["Pending is entered into all ten selected cells at once","Pending is entered into A1 and the cursor moves down to A2","A line break is inserted inside A1 after the word Pending","Pending is entered into A1 and the selection is cleared"],"answer":0,"explanation":"Ctrl + Enter fills every cell of the current selection with the same entry. Alt + Enter is the shortcut that adds a line break inside one cell.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में रेंज A1:A10 चयनित है, शब्द Pending टाइप किया जाता है और Ctrl + Enter दबाया जाता है। क्या होता है?","optionsHi":["Pending एक साथ सभी दस चयनित सेलों में दर्ज हो जाता है","Pending A1 में दर्ज होता है और कर्सर नीचे A2 पर चला जाता है","शब्द Pending के बाद A1 के भीतर लाइन ब्रेक डल जाता है","Pending A1 में दर्ज होता है और चयन साफ़ हो जाता है"],"explanationHi":"Ctrl + Enter वर्तमान चयन के हर सेल में वही प्रविष्टि भरता है। Alt + Enter वह शॉर्टकट है जो एक सेल के भीतर लाइन ब्रेक जोड़ता है।"},
  {"id":"comp-ms-office-internet-279","question":"In Excel, A1 contains =B1*2. With A2 selected, the user presses Ctrl + ' (apostrophe) and then Enter. What does A2 now contain?","options":["=B2*2, adjusted to the new row","Only the value of A1, not the formula","=B1*2, exactly as in A1","=$B$1*2, with the reference made absolute"],"answer":2,"explanation":"Ctrl + ' copies the formula of the cell above without adjusting its references, unlike Ctrl + D (fill down), which would give =B2*2.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 में =B1*2 है। A2 चयनित होने पर उपयोगकर्ता Ctrl + ' (एपॉस्ट्रॉफ़) और फिर Enter दबाता है। A2 में अब क्या है?","optionsHi":["=B2*2, नई पंक्ति के अनुसार समायोजित","केवल A1 का मान, सूत्र नहीं","=B1*2, ठीक A1 की तरह","=$B$1*2, संदर्भ निरपेक्ष बनाकर"],"explanationHi":"Ctrl + ' ऊपर के सेल का सूत्र उसके संदर्भ समायोजित किए बिना कॉपी करता है, जबकि Ctrl + D (फ़िल डाउन) =B2*2 देता।"},
  {"id":"comp-ms-office-internet-280","question":"Which pair of Excel shortcuts hides the selected rows and the selected columns respectively?","options":["Ctrl + 0 and Ctrl + 9","Ctrl + 9 and Ctrl + 0","Ctrl + 8 and Ctrl + 9","Ctrl + 5 and Ctrl + 6"],"answer":1,"explanation":"Ctrl + 9 hides rows and Ctrl + 0 hides columns; Ctrl + Shift + 9 unhides rows. Ctrl + 5 applies strikethrough and Ctrl + 8 shows or hides outline symbols.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"Excel के शॉर्टकटों का कौन-सा युग्म क्रमशः चयनित पंक्तियों और चयनित कॉलमों को छिपाता है?","optionsHi":["Ctrl + 0 और Ctrl + 9","Ctrl + 9 और Ctrl + 0","Ctrl + 8 और Ctrl + 9","Ctrl + 5 और Ctrl + 6"],"explanationHi":"Ctrl + 9 पंक्तियाँ छिपाता है और Ctrl + 0 कॉलम; Ctrl + Shift + 9 पंक्तियाँ दिखाता है। Ctrl + 5 स्ट्राइकथ्रू लगाता है और Ctrl + 8 आउटलाइन प्रतीकों को दिखाता या छिपाता है।"},
  {"id":"comp-ms-office-internet-281","question":"In Excel, which shortcuts select the entire row and the entire column of the active cell respectively?","options":["Ctrl + Space and Shift + Space","Ctrl + Shift + Right and Ctrl + Shift + Down","Alt + Space and Ctrl + Shift + Space","Shift + Space and Ctrl + Space"],"answer":3,"explanation":"Shift + Space selects the whole row and Ctrl + Space the whole column. Ctrl + Shift + arrow only extends the selection to the end of the data block.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में कौन-से शॉर्टकट क्रमशः सक्रिय सेल की पूरी पंक्ति और पूरा कॉलम चयनित करते हैं?","optionsHi":["Ctrl + Space और Shift + Space","Ctrl + Shift + Right और Ctrl + Shift + Down","Alt + Space और Ctrl + Shift + Space","Shift + Space और Ctrl + Space"],"explanationHi":"Shift + Space पूरी पंक्ति चयनित करता है और Ctrl + Space पूरा कॉलम। Ctrl + Shift + तीर चयन को केवल डेटा ब्लॉक के अंत तक बढ़ाता है।"},
  {"id":"comp-ms-office-internet-282","question":"In Excel, A1 contains 0.075. It is selected and Ctrl + Shift + % is pressed. What does the cell show?","options":["8%","7.5%","0.075%","75%"],"answer":0,"explanation":"Ctrl + Shift + % applies the Percentage format with no decimal places, so 0.075 (that is, 7.5%) is displayed rounded as 8%, though the stored value is unchanged.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 में 0.075 है। उसे चयनित करके Ctrl + Shift + % दबाया जाता है। सेल क्या दिखाता है?","optionsHi":["8%","7.5%","0.075%","75%"],"explanationHi":"Ctrl + Shift + % बिना दशमलव स्थान के Percentage फ़ॉर्मेट लागू करता है, इसलिए 0.075 (अर्थात 7.5%) पूर्णांकित होकर 8% दिखता है, हालाँकि संग्रहीत मान अपरिवर्तित रहता है।"},
  {"id":"comp-ms-office-internet-283","question":"In MS Excel, what does pressing Shift + F11 do?","options":["Creates a chart of the data on a new chart sheet","Opens the Save As dialog box for the workbook","Opens the Visual Basic editor for macros","Inserts a new worksheet into the workbook"],"answer":3,"explanation":"Shift + F11 inserts a new worksheet. F11 alone makes a chart sheet, F12 opens Save As and Alt + F11 opens the VBA editor.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"MS Excel में Shift + F11 दबाने पर क्या होता है?","optionsHi":["नई चार्ट शीट पर डेटा का चार्ट बनता है","वर्कबुक के लिए Save As डायलॉग बॉक्स खुलता है","मैक्रो के लिए Visual Basic एडिटर खुलता है","वर्कबुक में नई वर्कशीट डल जाती है"],"explanationHi":"Shift + F11 नई वर्कशीट डालता है। अकेला F11 चार्ट शीट बनाता है, F12 Save As खोलता है और Alt + F11 VBA एडिटर खोलता है।"},
  {"id":"comp-ms-office-internet-284","question":"In MS Excel, which shortcut moves to the next worksheet tab in the same workbook?","options":["Ctrl + Page Up","Alt + Page Down","Ctrl + Page Down","Ctrl + Tab"],"answer":2,"explanation":"Ctrl + Page Down goes to the next sheet and Ctrl + Page Up to the previous one. Alt + Page Down scrolls one screen right, and Ctrl + Tab switches between open workbooks.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"MS Excel में कौन-सा शॉर्टकट उसी वर्कबुक में अगले वर्कशीट टैब पर जाता है?","optionsHi":["Ctrl + Page Up","Alt + Page Down","Ctrl + Page Down","Ctrl + Tab"],"explanationHi":"Ctrl + Page Down अगली शीट पर और Ctrl + Page Up पिछली शीट पर जाता है। Alt + Page Down एक स्क्रीन दाईं ओर स्क्रॉल करता है, और Ctrl + Tab खुली वर्कबुकों के बीच बदलता है।"},
  {"id":"comp-ms-office-internet-285","question":"In Excel, a user fills cell B2 with yellow, then selects D7 and presses F4 while NOT editing any formula. What happens?","options":["D7 is changed into the absolute reference $D$7","D7 is filled yellow too, as F4 repeats the last action","Nothing happens, as F4 works only inside a formula","The workbook closes, as it would with Ctrl + F4"],"answer":1,"explanation":"Outside formula editing, F4 (like Ctrl + Y) repeats the last action. It cycles $ signs only while a reference is being edited in a formula.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में, उपयोगकर्ता सेल B2 को पीले रंग से भरता है, फिर D7 चयनित करके F4 दबाता है, जबकि वह कोई सूत्र संपादित नहीं कर रहा है। क्या होता है?","optionsHi":["D7 निरपेक्ष संदर्भ $D$7 में बदल जाता है","D7 भी पीला भर जाता है, क्योंकि F4 अंतिम क्रिया दोहराता है","कुछ नहीं होता, क्योंकि F4 केवल सूत्र के भीतर काम करता है","वर्कबुक बंद हो जाती है, जैसे Ctrl + F4 से होती"],"explanationHi":"सूत्र संपादन के बाहर F4 (Ctrl + Y की तरह) अंतिम क्रिया दोहराता है। यह $ चिह्नों को तभी चक्रीय रूप से बदलता है जब सूत्र में कोई संदर्भ संपादित हो रहा हो।"},
  {"id":"comp-ms-office-internet-286","question":"What does the shortcut Shift + F3 do in MS Word and in MS Excel respectively?","options":["Opens Insert Function in Word; changes case in Excel","Changes the case of selected text in both programs","Finds the next match in Word; opens Name Manager in Excel","Changes case in Word; opens Insert Function in Excel"],"answer":3,"explanation":"The same key does different jobs: in Word Shift + F3 cycles the case of selected text, while in Excel it opens the Insert Function dialog.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"शॉर्टकट Shift + F3 MS Word और MS Excel में क्रमशः क्या करता है?","optionsHi":["Word में Insert Function खोलता है; Excel में केस बदलता है","दोनों प्रोग्रामों में चयनित टेक्स्ट का केस बदलता है","Word में अगला मिलान ढूँढता है; Excel में Name Manager खोलता है","Word में केस बदलता है; Excel में Insert Function खोलता है"],"explanationHi":"वही कुंजी अलग-अलग कार्य करती है: Word में Shift + F3 चयनित टेक्स्ट का केस चक्रीय रूप से बदलता है, जबकि Excel में यह Insert Function डायलॉग खोलता है।"},
  {"id":"comp-ms-office-internet-287","question":"Which of these can make an Excel cell display ##### ? I. The column is too narrow for the number. II. The cell holds a negative date or time value. III. The formula divides a number by zero. IV. The formula refers to a deleted cell.","options":["Only I","Only I and II","Only I, II and III","All four of them"],"answer":1,"explanation":"##### appears when a number does not fit the column or when a date/time works out negative. Dividing by zero gives #DIV/0! and a deleted reference gives #REF!.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"इनमें से कौन-से कारण Excel सेल में ##### दिखा सकते हैं? I. संख्या के लिए कॉलम बहुत संकरा है। II. सेल में ऋणात्मक तारीख़ या समय का मान है। III. सूत्र किसी संख्या को शून्य से भाग देता है। IV. सूत्र किसी हटाए गए सेल का संदर्भ देता है।","optionsHi":["केवल I","केवल I और II","केवल I, II और III","चारों"],"explanationHi":"##### तब दिखता है जब संख्या कॉलम में नहीं समाती या जब तारीख़/समय ऋणात्मक निकलता है। शून्य से भाग #DIV/0! देता है और हटाया गया संदर्भ #REF! देता है।"},
  {"id":"comp-ms-office-internet-288","question":"In Excel, D1 contains =B1+C1. The cell is CUT (Ctrl + X) and pasted into F5. What formula does F5 now contain?","options":["=D5+E5","=B5+C5","=B1+C1","=D1+E1"],"answer":2,"explanation":"Moving a formula by cut and paste keeps its references exactly as they were. Copying it to F5 instead would have shifted them two columns right and four rows down, giving =D5+E5.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में D1 में =B1+C1 है। सेल को कट (Ctrl + X) करके F5 में पेस्ट किया जाता है। अब F5 में कौन-सा सूत्र है?","optionsHi":["=D5+E5","=B5+C5","=B1+C1","=D1+E1"],"explanationHi":"कट और पेस्ट से सूत्र को ले जाने पर उसके संदर्भ ठीक वैसे ही रहते हैं जैसे थे। उसे F5 में कॉपी करने पर वे दो कॉलम दाईं ओर और चार पंक्ति नीचे खिसक जाते, जिससे =D5+E5 मिलता।"},
  {"id":"comp-ms-office-internet-289","question":"In Excel, A10 contains =SUM(A1:A9). A new row is then inserted above row 5. What is the formula now and where is it?","options":["=SUM(A1:A10) in cell A11","=SUM(A1:A9) in cell A11","=SUM(A1:A10) in cell A10","=SUM(A2:A10) in cell A11"],"answer":0,"explanation":"Inserting a row inside the range pushes the formula down to A11 and expands the range it refers to, so it still covers all the original cells plus the new row.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A10 में =SUM(A1:A9) है। फिर पंक्ति 5 के ऊपर एक नई पंक्ति डाली जाती है। अब सूत्र क्या है और कहाँ है?","optionsHi":["=SUM(A1:A10), सेल A11 में","=SUM(A1:A9), सेल A11 में","=SUM(A1:A10), सेल A10 में","=SUM(A2:A10), सेल A11 में"],"explanationHi":"रेंज के भीतर पंक्ति डालने से सूत्र नीचे A11 में चला जाता है और उसका संदर्भित रेंज फैल जाता है, इसलिए वह अब भी सभी मूल सेलों और नई पंक्ति को कवर करता है।"},
  {"id":"comp-ms-office-internet-290","question":"A formula must use cell B4 of another sheet whose name is Sales 2024 (with a space). What must be done to the sheet name in the reference?","options":["Put it in single quotes before the ! sign","Put it in double quotes before the ! sign","Put it in square brackets before the cell","Put a $ sign before it to fix the sheet"],"answer":0,"explanation":"A sheet name with spaces must be enclosed in single quotes, as in ='Sales 2024'!B4. Square brackets are used for a workbook name in external references.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"किसी सूत्र में किसी अन्य शीट के सेल B4 का उपयोग करना है जिसका नाम Sales 2024 (रिक्त स्थान सहित) है। संदर्भ में शीट के नाम के साथ क्या करना होगा?","optionsHi":["उसे ! चिह्न से पहले एकल उद्धरण चिह्नों में रखें","उसे ! चिह्न से पहले दोहरे उद्धरण चिह्नों में रखें","उसे सेल से पहले वर्गाकार कोष्ठकों में रखें","शीट को स्थिर करने के लिए उससे पहले $ चिह्न लगाएँ"],"explanationHi":"रिक्त स्थान वाले शीट नाम को एकल उद्धरण चिह्नों में रखना होता है, जैसे ='Sales 2024'!B4। वर्गाकार कोष्ठक बाहरी संदर्भों में वर्कबुक के नाम के लिए उपयोग होते हैं।"},
  {"id":"comp-ms-office-internet-291","question":"In Excel, cell F1 is given the name Rate, and C2 contains =B2*Rate. C2 is copied to C3 and to D2. Which cell do the copies use for Rate?","options":["F2 in C3 and G1 in D2, like a relative one","F1 in both copies, like an absolute reference","F2 in C3 but F1 in D2, like a mixed reference","Neither, both copies show a #NAME? error"],"answer":1,"explanation":"A name defined for a single cell refers to it absolutely ($F$1 by default), so every copy of the formula keeps pointing to F1.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में सेल F1 को नाम Rate दिया गया है, और C2 में =B2*Rate है। C2 को C3 और D2 में कॉपी किया जाता है। प्रतियाँ Rate के लिए किस सेल का उपयोग करती हैं?","optionsHi":["सापेक्ष की तरह, F2 (C3 में) और G1 (D2 में)","निरपेक्ष संदर्भ की तरह, दोनों प्रतियों में F1","मिश्रित संदर्भ की तरह, F2 (C3 में) पर F1 (D2 में)","कोई नहीं, दोनों प्रतियाँ #NAME? त्रुटि दिखाती हैं"],"explanationHi":"एकल सेल के लिए परिभाषित नाम उसका निरपेक्ष संदर्भ देता है (डिफ़ॉल्ट रूप से $F$1), इसलिए सूत्र की हर प्रति F1 की ओर ही इंगित करती रहती है।"},
  {"id":"comp-ms-office-internet-292","question":"In Excel, cell B2 contains =A1. It is copied and pasted into cell B1. What does B1 then contain?","options":["=A1","=B1, a circular reference","=A2","=#REF!"],"answer":3,"explanation":"Copying one row up shifts the relative reference A1 up by one row to a row 0, which does not exist, so Excel writes the #REF! error into the formula.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में सेल B2 में =A1 है। उसे कॉपी करके सेल B1 में पेस्ट किया जाता है। B1 में अब क्या है?","optionsHi":["=A1","=B1, एक वृत्तीय संदर्भ","=A2","=#REF!"],"explanationHi":"एक पंक्ति ऊपर कॉपी करने पर सापेक्ष संदर्भ A1 एक पंक्ति ऊपर खिसककर पंक्ति 0 पर पहुँचता है, जो मौजूद नहीं है, इसलिए Excel सूत्र में #REF! त्रुटि लिख देता है।"},
  {"id":"comp-ms-office-internet-293","question":"A user wants Excel to store one-half as the number 0.5 but show it as the fraction 1/2. What should be typed into the cell?","options":["1/2","'1/2 (with an apostrophe first)","0 1/2 (zero, a space, then 1/2)","=1/2 (as a formula)"],"answer":2,"explanation":"Typing a zero and a space before 1/2 makes Excel enter the fraction 0.5 with a fraction format. Plain 1/2 is read as a date, '1/2 becomes text and =1/2 shows 0.5.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"कोई उपयोगकर्ता चाहता है कि Excel आधे को संख्या 0.5 के रूप में संग्रहीत करे पर उसे भिन्न 1/2 के रूप में दिखाए। सेल में क्या टाइप करना चाहिए?","optionsHi":["1/2","'1/2 (पहले एपॉस्ट्रॉफ़ के साथ)","0 1/2 (शून्य, एक रिक्त स्थान, फिर 1/2)","=1/2 (सूत्र के रूप में)"],"explanationHi":"1/2 से पहले शून्य और रिक्त स्थान टाइप करने से Excel भिन्न फ़ॉर्मेट के साथ भिन्न 0.5 दर्ज करता है। सादा 1/2 तारीख़ पढ़ा जाता है, '1/2 पाठ बन जाता है और =1/2 0.5 दिखाता है।"},
  {"id":"comp-ms-office-internet-294","question":"In Excel, only A1 (containing 1) is selected and its fill handle is dragged to A5. This is done once normally and once while holding Ctrl. What does A5 show each time?","options":["5 normally, and 1 with Ctrl held","5 both times, as a series","1 normally, and 5 with Ctrl held","1 both times, as a copy"],"answer":2,"explanation":"Dragging a single number copies it, while holding Ctrl makes a series 1, 2, 3, 4, 5. With two numbers selected, a plain drag would continue the series.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में केवल A1 (जिसमें 1 है) चयनित है और उसका फ़िल हैंडल A5 तक खींचा जाता है। यह एक बार सामान्य रूप से और एक बार Ctrl दबाए रखकर किया जाता है। हर बार A5 क्या दिखाता है?","optionsHi":["सामान्य रूप से 5, और Ctrl दबाए रखने पर 1","दोनों बार 5, श्रेणी के रूप में","सामान्य रूप से 1, और Ctrl दबाए रखने पर 5","दोनों बार 1, प्रति के रूप में"],"explanationHi":"एक संख्या को खींचने पर वह कॉपी होती है, जबकि Ctrl दबाए रखने पर श्रेणी 1, 2, 3, 4, 5 बनती है। दो संख्याएँ चयनित होने पर सादा खींचना श्रेणी को जारी रखता।"},
  {"id":"comp-ms-office-internet-295","question":"All salaries in C2:C50 must be raised by 10% in place, without a helper column. A user types 1.1 in a spare cell and copies it. What should be done next?","options":["Select C2:C50, open Paste Special and choose Multiply","Select C2:C50, open Paste Special and choose Add","Select C2:C50, open Paste Special and choose Values","Select C2:C50 and press Ctrl + V to paste directly"],"answer":0,"explanation":"Paste Special with the Multiply operation multiplies each target cell by the copied 1.1. Add would only increase each salary by 1.1 rupees, and a plain paste would overwrite them.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"C2:C50 के सभी वेतन बिना सहायक कॉलम के उसी स्थान पर 10% बढ़ाने हैं। उपयोगकर्ता किसी खाली सेल में 1.1 टाइप करके उसे कॉपी करता है। आगे क्या करना चाहिए?","optionsHi":["C2:C50 चयनित करें, Paste Special खोलें और Multiply चुनें","C2:C50 चयनित करें, Paste Special खोलें और Add चुनें","C2:C50 चयनित करें, Paste Special खोलें और Values चुनें","C2:C50 चयनित करें और सीधे पेस्ट करने के लिए Ctrl + V दबाएँ"],"explanationHi":"Multiply संक्रिया वाला Paste Special हर लक्ष्य सेल को कॉपी किए गए 1.1 से गुणा करता है। Add हर वेतन को केवल 1.1 रुपये बढ़ाता, और सादा पेस्ट उन्हें अधिलेखित कर देता।"},
  {"id":"comp-ms-office-internet-296","question":"A column holds names written as Sharma, Amit. Which Excel feature splits them into separate surname and first-name columns at the comma in one operation?","options":["Merge and Center","Wrap Text","Consolidate","Text to Columns"],"answer":3,"explanation":"Data > Text to Columns splits each cell at a delimiter such as a comma. Merge and Center joins cells, Wrap Text only wraps lines, and Consolidate combines data from several ranges.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"एक कॉलम में Sharma, Amit के रूप में लिखे नाम हैं। Excel की कौन-सी सुविधा उन्हें अल्पविराम पर एक ही संक्रिया में अलग उपनाम और पहले-नाम वाले कॉलमों में बाँट देती है?","optionsHi":["Merge and Center","Wrap Text","Consolidate","Text to Columns"],"explanationHi":"Data > Text to Columns हर सेल को अल्पविराम जैसे सीमांकक (delimiter) पर बाँटता है। Merge and Center सेलों को जोड़ता है, Wrap Text केवल पंक्तियाँ लपेटता है, और Consolidate कई रेंजों के डेटा को मिलाता है।"},
  {"id":"comp-ms-office-internet-297","question":"A loan officer wants a grid showing the EMI from one PMT formula for interest rates of 8%, 9%, 10% and 11% at once. Which What-If Analysis tool does this?","options":["Goal Seek","Data Table","Scenario Manager","Remove Duplicates"],"answer":1,"explanation":"A Data Table recalculates one formula for a list of input values and fills a grid. Goal Seek works backwards from a single target result, and Scenario Manager stores named sets of inputs.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक ऋण अधिकारी एक PMT सूत्र से ब्याज दर 8%, 9%, 10% और 11% के लिए एक साथ EMI दिखाने वाली ग्रिड चाहता है। कौन-सा What-If Analysis टूल यह करता है?","optionsHi":["Goal Seek","Data Table","Scenario Manager","Remove Duplicates"],"explanationHi":"Data Table एक सूत्र को इनपुट मानों की सूची के लिए पुनर्गणना करके ग्रिड भर देता है। Goal Seek एक लक्ष्य परिणाम से उल्टा चलता है, और Scenario Manager इनपुट के नामित सेट संग्रहीत करता है।"},
  {"id":"comp-ms-office-internet-298","question":"Which Excel feature draws a tiny line or column chart inside a single cell to show the trend of the values in that row?","options":["Data Bars","Sparklines","Slicers","Trendline"],"answer":1,"explanation":"Sparklines are mini charts inside a cell showing a trend across several values. Data Bars shade each cell by its own single value, and Slicers are buttons for filtering.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel की कौन-सी सुविधा उस पंक्ति के मानों की प्रवृत्ति दिखाने के लिए एक ही सेल के भीतर छोटा लाइन या कॉलम चार्ट बनाती है?","optionsHi":["Data Bars","Sparklines","Slicers","Trendline"],"explanationHi":"Sparklines सेल के भीतर के छोटे चार्ट हैं जो कई मानों में प्रवृत्ति दिखाते हैं। Data Bars हर सेल को उसके अपने एक मान के अनुसार रंगते हैं, और Slicers फ़िल्टर करने के बटन हैं।"},
  {"id":"comp-ms-office-internet-299","question":"A sales list in B2:B10 is filtered to show only North rows. Which formula totals only the rows that are now visible?","options":["=SUBTOTAL(9, B2:B10)","=SUM(B2:B10)","=SUBTOTAL(1, B2:B10)","=SUMIF(B2:B10, \">0\")"],"answer":0,"explanation":"SUBTOTAL with function number 9 (sum) ignores rows hidden by a filter. SUM and SUMIF add every row, and SUBTOTAL(1, …) would give an average instead.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"B2:B10 में बिक्री सूची को केवल North पंक्तियाँ दिखाने के लिए फ़िल्टर किया गया है। कौन-सा सूत्र केवल अब दिखाई दे रही पंक्तियों का योग करता है?","optionsHi":["=SUBTOTAL(9, B2:B10)","=SUM(B2:B10)","=SUBTOTAL(1, B2:B10)","=SUMIF(B2:B10, \">0\")"],"explanationHi":"फ़ंक्शन संख्या 9 (योग) वाला SUBTOTAL फ़िल्टर द्वारा छिपाई गई पंक्तियों को अनदेखा करता है। SUM और SUMIF हर पंक्ति जोड़ते हैं, और SUBTOTAL(1, …) इसके बजाय औसत देता।"},
  {"id":"comp-ms-office-internet-300","question":"In Excel, what does =IF(A1>5, Yes, No) return when A1 = 8?","options":["Yes","#VALUE!","#N/A","#NAME?"],"answer":3,"explanation":"Text in a formula must be inside double quotes. Without them Excel treats Yes and No as undefined names and returns #NAME?.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"Excel में, जब A1 = 8 हो तो =IF(A1>5, Yes, No) क्या लौटाता है?","optionsHi":["Yes","#VALUE!","#N/A","#NAME?"],"explanationHi":"सूत्र में पाठ दोहरे उद्धरण चिह्नों के भीतर होना चाहिए। उनके बिना Excel Yes और No को अपरिभाषित नाम मानता है और #NAME? लौटाता है।"},
  {"id":"comp-ms-office-internet-301","question":"An Excel workbook is set to Manual calculation, so formulas do not update after an input is changed. Which key recalculates all open workbooks?","options":["F2","F4","F9","F7"],"answer":2,"explanation":"F9 recalculates formulas. F2 edits the active cell, F4 toggles references or repeats the last action, and F7 runs the spell check.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"एक Excel वर्कबुक Manual calculation पर सेट है, इसलिए इनपुट बदलने के बाद सूत्र अपडेट नहीं होते। कौन-सी कुंजी सभी खुली वर्कबुकों की पुनर्गणना करती है?","optionsHi":["F2","F4","F9","F7"],"explanationHi":"F9 सूत्रों की पुनर्गणना करता है। F2 सक्रिय सेल को संपादित करता है, F4 संदर्भ बदलता है या अंतिम क्रिया दोहराता है, और F7 स्पेल चेक चलाता है।"},
  {"id":"comp-ms-office-internet-302","question":"In MS Excel, what does pressing Ctrl + T with any cell of a data range selected do?","options":["Applies a hanging indent to the text in the active cell","Converts the range into a Table with filters and banded rows","Opens the Find and Replace dialog on the Replace tab","Turns on Track Changes for the whole worksheet"],"answer":1,"explanation":"In Excel, Ctrl + T (like Ctrl + L) creates a Table with filter buttons, banded rows and automatic expansion. In Word the same key gives a hanging indent.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Excel में, डेटा रेंज का कोई भी सेल चयनित होने पर Ctrl + T दबाने से क्या होता है?","optionsHi":["सक्रिय सेल के पाठ पर हैंगिंग इंडेंट लगता है","रेंज फ़िल्टर और बैंडेड पंक्तियों वाली Table में बदल जाती है","Find and Replace डायलॉग Replace टैब पर खुलता है","पूरी वर्कशीट के लिए Track Changes चालू हो जाता है"],"explanationHi":"Excel में Ctrl + T (Ctrl + L की तरह) फ़िल्टर बटन, बैंडेड पंक्तियों और स्वचालित विस्तार वाली Table बनाता है। Word में वही कुंजी हैंगिंग इंडेंट देती है।"},
  {"id":"comp-ms-office-internet-303","question":"In MS Word, selected text in a centred paragraph is bold, italic, red and 16 pt (all applied by hand). What happens when Ctrl + Space is pressed?","options":["The bold, italic, colour and size go back to the style default, and the paragraph stays centred","The paragraph loses its centring, but the bold, italic, colour and size stay as they are","Both the character formatting and the centring are removed in one go","A non-breaking space replaces the selected text"],"answer":0,"explanation":"Ctrl + Space removes manual CHARACTER formatting only. Ctrl + Q is the shortcut that removes manual paragraph formatting such as alignment and indents.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word में, केंद्र-संरेखित अनुच्छेद में चयनित टेक्स्ट बोल्ड, इटैलिक, लाल और 16 pt है (सब हाथ से लगाया गया)। Ctrl + Space दबाने पर क्या होता है?","optionsHi":["बोल्ड, इटैलिक, रंग और आकार शैली के डिफ़ॉल्ट पर लौट जाते हैं, और अनुच्छेद केंद्र में ही रहता है","अनुच्छेद का केंद्र संरेखण चला जाता है, पर बोल्ड, इटैलिक, रंग और आकार जैसे हैं वैसे रहते हैं","अक्षर फ़ॉर्मेटिंग और केंद्र संरेखण दोनों एक साथ हट जाते हैं","चयनित टेक्स्ट की जगह नॉन-ब्रेकिंग स्पेस आ जाता है"],"explanationHi":"Ctrl + Space केवल मैन्युअल अक्षर फ़ॉर्मेटिंग हटाता है। Ctrl + Q वह शॉर्टकट है जो संरेखण और इंडेंट जैसी मैन्युअल अनुच्छेद फ़ॉर्मेटिंग हटाता है।"},
  {"id":"comp-ms-office-internet-304","question":"Match the MS Word shortcut with what it applies: 1. Ctrl + Shift + N 2. Ctrl + Alt + 1 3. Ctrl + Shift + L 4. Ctrl + Shift + K; a. Heading 1 style b. Small caps c. Normal style d. List Bullet style","options":["1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-c, 2-d, 3-a, 4-b"],"answer":1,"explanation":"Ctrl + Shift + N gives the Normal style, Ctrl + Alt + 1 gives Heading 1, Ctrl + Shift + L gives the List Bullet style and Ctrl + Shift + K gives small capitals.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word शॉर्टकट को उसके लागू करने वाले प्रभाव से सुमेलित कीजिए: 1. Ctrl + Shift + N 2. Ctrl + Alt + 1 3. Ctrl + Shift + L 4. Ctrl + Shift + K; a. Heading 1 शैली b. Small caps c. Normal शैली d. List Bullet शैली","optionsHi":["1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-c, 2-d, 3-a, 4-b"],"explanationHi":"Ctrl + Shift + N Normal शैली देता है, Ctrl + Alt + 1 Heading 1 देता है, Ctrl + Shift + L List Bullet शैली देता है और Ctrl + Shift + K छोटे कैपिटल (small capitals) देता है।"},
  {"id":"comp-ms-office-internet-305","question":"In MS Word, the shortcut Ctrl + Shift + W is applied to the selected words Fixed Deposit Rates. What is the result?","options":["The whole selection gets a double underline, spaces included","The whole selection gets a single wavy red underline","Each word is underlined but the spaces between them are not","The document is closed after asking to save the changes"],"answer":2,"explanation":"Ctrl + Shift + W gives a words-only underline. Ctrl + Shift + D gives a double underline, and Ctrl + W (without Shift) closes the document.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Word में चयनित शब्दों Fixed Deposit Rates पर शॉर्टकट Ctrl + Shift + W लगाया जाता है। परिणाम क्या होगा?","optionsHi":["पूरे चयन पर, रिक्त स्थान सहित, दोहरी अधोरेखा लग जाती है","पूरे चयन पर एकल लहरदार लाल अधोरेखा लग जाती है","हर शब्द रेखांकित होता है पर उनके बीच के रिक्त स्थान नहीं","बदलाव सेव करने के बारे में पूछकर दस्तावेज़ बंद हो जाता है"],"explanationHi":"Ctrl + Shift + W केवल शब्दों की अधोरेखा देता है। Ctrl + Shift + D दोहरी अधोरेखा देता है, और Ctrl + W (बिना Shift के) दस्तावेज़ बंद करता है।"},
  {"id":"comp-ms-office-internet-306","question":"Match the MS Word key with its effect on fields: 1. F9 2. Alt + F9 3. Ctrl + Shift + F9 4. Ctrl + F9; a. inserts a pair of empty field braces b. turns the field into plain text that no longer updates c. switches all fields between codes and results d. updates the selected fields","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"F9 updates fields, Alt + F9 toggles field codes for the whole document, Ctrl + Shift + F9 unlinks fields into fixed text, and Ctrl + F9 inserts empty field braces.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word कुंजी को फ़ील्ड पर उसके प्रभाव से सुमेलित कीजिए: 1. F9 2. Alt + F9 3. Ctrl + Shift + F9 4. Ctrl + F9; a. खाली फ़ील्ड कोष्ठकों का जोड़ा डालता है b. फ़ील्ड को सादे पाठ में बदल देता है जो अब अपडेट नहीं होता c. सभी फ़ील्ड को कोड और परिणाम के बीच बदलता है d. चयनित फ़ील्ड अपडेट करता है","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"explanationHi":"F9 फ़ील्ड अपडेट करता है, Alt + F9 पूरे दस्तावेज़ के फ़ील्ड कोड को चालू/बंद करता है, Ctrl + Shift + F9 फ़ील्ड को अलग करके स्थिर पाठ बना देता है, और Ctrl + F9 खाली फ़ील्ड कोष्ठक डालता है।"},
  {"id":"comp-ms-office-internet-307","question":"After new headings are added to a long Word report, its automatic Table of Contents still shows the old headings and page numbers. What is the quickest fix?","options":["Press Ctrl + Enter at the start of the table of contents","Retype the new headings into the table of contents","Press Ctrl + Z until the table of contents changes","Click in the table of contents and press F9 to update it"],"answer":3,"explanation":"A Table of Contents is a field, so it changes only when updated (F9 or Update Table), where you can refresh page numbers only or the entire table.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"किसी लंबी Word रिपोर्ट में नए शीर्षक जोड़ने के बाद भी उसकी स्वचालित विषय-सूची पुराने शीर्षक और पेज नंबर दिखाती है। सबसे तेज़ समाधान क्या है?","optionsHi":["विषय-सूची के आरंभ में Ctrl + Enter दबाएँ","नए शीर्षकों को विषय-सूची में दोबारा टाइप करें","विषय-सूची बदलने तक Ctrl + Z दबाते रहें","विषय-सूची में क्लिक करें और उसे अपडेट करने के लिए F9 दबाएँ"],"explanationHi":"विषय-सूची एक फ़ील्ड है, इसलिए वह अपडेट करने पर ही बदलती है (F9 या Update Table), जहाँ आप केवल पेज नंबर या पूरी तालिका ताज़ा कर सकते हैं।"},
  {"id":"comp-ms-office-internet-308","question":"Which of these statements about formulas in an MS Word table are correct? I. =SUM(ABOVE) in a cell adds the numbers above it in that column. II. The result recalculates automatically as soon as a number above it is changed. III. Table cells can be referred to in A1 style, with columns as letters and rows as numbers.","options":["I and II only","I and III only","I, II and III","III only"],"answer":1,"explanation":"Word table formulas support ABOVE, LEFT and A1-style cell references, but the result is a field that does not recalculate by itself; you must update it with F9.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word तालिका में सूत्रों के बारे में इनमें से कौन-से कथन सही हैं? I. किसी सेल में =SUM(ABOVE) उस कॉलम में उसके ऊपर की संख्याएँ जोड़ता है। II. ऊपर की कोई संख्या बदलते ही परिणाम अपने आप पुनर्गणना हो जाता है। III. तालिका के सेलों को A1 शैली में संदर्भित किया जा सकता है, जिसमें कॉलम अक्षर और पंक्तियाँ संख्याएँ होती हैं।","optionsHi":["केवल I और II","केवल I और III","I, II और III","केवल III"],"explanationHi":"Word तालिका के सूत्र ABOVE, LEFT और A1-शैली के सेल संदर्भों का समर्थन करते हैं, पर परिणाम एक फ़ील्ड है जो अपने आप पुनर्गणना नहीं होता; उसे F9 से अपडेट करना पड़ता है।"},
  {"id":"comp-ms-office-internet-309","question":"A Word document has an empty line between every pair of paragraphs, made by pressing Enter twice. Using Find and Replace, what should be found and what should it be replaced with to remove these empty lines?","options":["Find ^t^t and replace with ^t","Find ^p and replace with ^t","Find ^p^p and replace with ^p","Find ^l^l and replace with ^p"],"answer":2,"explanation":"In Word's Find and Replace, ^p stands for a paragraph mark (Enter), ^t for a tab and ^l for a manual line break, so two paragraph marks are replaced by one.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक Word दस्तावेज़ में हर दो अनुच्छेदों के बीच एक खाली पंक्ति है, जो Enter दो बार दबाने से बनी है। Find and Replace में इन खाली पंक्तियों को हटाने के लिए क्या खोजना चाहिए और उसे किससे बदलना चाहिए?","optionsHi":["^t^t खोजें और ^t से बदलें","^p खोजें और ^t से बदलें","^p^p खोजें और ^p से बदलें","^l^l खोजें और ^p से बदलें"],"explanationHi":"Word के Find and Replace में ^p अनुच्छेद चिह्न (Enter) के लिए, ^t टैब के लिए और ^l मैन्युअल लाइन ब्रेक के लिए है, इसलिए दो अनुच्छेद चिह्न एक से बदले जाते हैं।"},
  {"id":"comp-ms-office-internet-310","question":"In Word's Find dialog, Use wildcards is ticked and b?t is searched in the line: bat boat bit bet but. How many matches are found?","options":["3","5","4","1"],"answer":2,"explanation":"With wildcards on, ? stands for exactly one character, so b?t matches bat, bit, bet and but: four matches. Boat has two letters between b and t; * would have matched it.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Word के Find डायलॉग में Use wildcards चुना गया है और पंक्ति: bat boat bit bet but में b?t खोजा जाता है। कितने मिलान मिलते हैं?","optionsHi":["3","5","4","1"],"explanationHi":"वाइल्डकार्ड चालू होने पर ? ठीक एक अक्षर के लिए है, इसलिए b?t, bat, bit, bet और but से मेल खाता है: चार मिलान। Boat में b और t के बीच दो अक्षर हैं; * उससे मेल खाता।"},
  {"id":"comp-ms-office-internet-311","question":"In a book being typed in MS Word for double-sided printing, every chapter must begin on a right-hand page, even if a blank page is needed before it. Which break should be placed before each chapter?","options":["Section break (Continuous)","Section break (Next Page)","Section break (Odd Page)","Column break"],"answer":2,"explanation":"In double-sided printing, right-hand pages are odd-numbered. An Odd Page section break starts the next section on the next odd page and leaves a blank even page if needed.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Word में टाइप की जा रही किसी पुस्तक के दोतरफ़ा (double-sided) प्रिंट के लिए हर अध्याय दाहिने हाथ वाले पेज पर शुरू होना चाहिए, चाहे उससे पहले खाली पेज की ज़रूरत पड़े। हर अध्याय से पहले कौन-सा ब्रेक डालना चाहिए?","optionsHi":["सेक्शन ब्रेक (Continuous)","सेक्शन ब्रेक (Next Page)","सेक्शन ब्रेक (Odd Page)","कॉलम ब्रेक"],"explanationHi":"दोतरफ़ा प्रिंट में दाहिने हाथ वाले पेज विषम संख्या वाले होते हैं। Odd Page सेक्शन ब्रेक अगले सेक्शन को अगले विषम पेज पर शुरू करता है और ज़रूरत पड़ने पर एक खाली सम पेज छोड़ देता है।"},
  {"id":"comp-ms-office-internet-312","question":"In a double-sided Word report, page numbers must appear at the outer edge of each page: the right side on odd pages and the left side on even pages. Which header/footer option makes this possible?","options":["Different Odd and Even Pages","Different First Page","Mirror Margins in Page Setup","Link to Previous"],"answer":0,"explanation":"Different Odd and Even Pages gives separate footers for odd and even pages, so the number can be right-aligned on one and left-aligned on the other. Mirror Margins changes margins, not footers.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी दोतरफ़ा Word रिपोर्ट में पेज नंबर हर पेज के बाहरी किनारे पर दिखने चाहिए: विषम पेजों पर दाईं ओर और सम पेजों पर बाईं ओर। हेडर/फ़ुटर का कौन-सा विकल्प यह संभव बनाता है?","optionsHi":["Different Odd and Even Pages","Different First Page","Page Setup में Mirror Margins","Link to Previous"],"explanationHi":"Different Odd and Even Pages विषम और सम पेजों के लिए अलग फ़ुटर देता है, इसलिए नंबर एक पर दाएँ और दूसरे पर बाएँ संरेखित किया जा सकता है। Mirror Margins मार्जिन बदलता है, फ़ुटर नहीं।"},
  {"id":"comp-ms-office-internet-313","question":"A Word document has two sections. The user types a new header in section 2, but the header of section 1 also changes to match. What must be done?","options":["Turn on Different First Page in the header of section 1","Turn off Link to Previous in the header of section 2","Replace the section break with a manual page break","Turn on Different Odd and Even Pages in section 2"],"answer":1,"explanation":"By default, each section's header is linked to the previous section's header. Breaking Link to Previous in section 2 lets the two sections have different headers.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक Word दस्तावेज़ में दो सेक्शन हैं। उपयोगकर्ता सेक्शन 2 में नया हेडर टाइप करता है, पर सेक्शन 1 का हेडर भी उसी के अनुसार बदल जाता है। क्या करना चाहिए?","optionsHi":["सेक्शन 1 के हेडर में Different First Page चालू करें","सेक्शन 2 के हेडर में Link to Previous बंद करें","सेक्शन ब्रेक को मैन्युअल पेज ब्रेक से बदलें","सेक्शन 2 में Different Odd and Even Pages चालू करें"],"explanationHi":"डिफ़ॉल्ट रूप से हर सेक्शन का हेडर पिछले सेक्शन के हेडर से जुड़ा होता है। सेक्शन 2 में Link to Previous तोड़ने से दोनों सेक्शनों के हेडर अलग हो सकते हैं।"},
  {"id":"comp-ms-office-internet-314","question":"A magazine article in MS Word must start with a large first letter that drops down across the first three lines of the paragraph. Which feature does this?","options":["WordArt","Small Caps","Text Box","Drop Cap"],"answer":3,"explanation":"Drop Cap (Insert tab) enlarges the first letter and sinks it into the paragraph over a set number of lines. Small Caps only changes lower-case letters into small capitals.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk","questionHi":"MS Word में किसी पत्रिका के लेख की शुरुआत बड़े पहले अक्षर से होनी चाहिए जो अनुच्छेद की पहली तीन पंक्तियों में नीचे उतरता हो। कौन-सी सुविधा यह करती है?","optionsHi":["WordArt","Small Caps","Text Box","Drop Cap"],"explanationHi":"Drop Cap (Insert टैब) पहले अक्षर को बड़ा करके निर्धारित पंक्तियों की संख्या तक अनुच्छेद में धँसा देता है। Small Caps केवल छोटे अक्षरों को छोटे कैपिटल में बदलता है।"},
  {"id":"comp-ms-office-internet-315","question":"A Word mail merge uses an Excel list of 500 customers, but letters are needed only for customers whose balance is below ₹1,000. The Excel file must not be changed. What should be done?","options":["Filter the recipient list on the balance field in Edit Recipient List","Delete the unwanted rows from the Excel file before merging","Merge all 500 letters and then delete the unwanted ones","Insert a Next Record field after the balance in the main document"],"answer":0,"explanation":"Edit Recipient List lets you filter (or untick) records by a field such as balance, so only matching records are merged, without touching the data source.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक Word मेल मर्ज 500 ग्राहकों की Excel सूची का उपयोग करता है, पर पत्र केवल उन ग्राहकों के लिए चाहिए जिनकी शेष राशि ₹1,000 से कम है। Excel फ़ाइल बदली नहीं जानी चाहिए। क्या करना चाहिए?","optionsHi":["Edit Recipient List में शेष राशि फ़ील्ड पर प्राप्तकर्ता सूची फ़िल्टर करें","मर्ज करने से पहले Excel फ़ाइल से अनचाही पंक्तियाँ हटा दें","सभी 500 पत्र मर्ज करें और फिर अनचाहे हटा दें","मुख्य दस्तावेज़ में शेष राशि के बाद Next Record फ़ील्ड डालें"],"explanationHi":"Edit Recipient List आपको शेष राशि जैसे फ़ील्ड के आधार पर रिकॉर्ड फ़िल्टर करने (या अचयनित करने) देता है, इसलिए डेटा स्रोत को छुए बिना केवल मेल खाते रिकॉर्ड मर्ज होते हैं।"},
  {"id":"comp-ms-office-internet-316","question":"A report in Word numbers its pictures as Figure 1, Figure 2 and so on, using Insert Caption. Which feature then builds a list of all the figures with their page numbers?","options":["Table of Contents","Table of Figures","Index","Bibliography"],"answer":1,"explanation":"Table of Figures (References tab) is built from captions. A Table of Contents is built from heading styles and an Index from marked index entries.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Word की एक रिपोर्ट अपने चित्रों को Insert Caption से Figure 1, Figure 2 आदि क्रमांकित करती है। कौन-सी सुविधा फिर सभी चित्रों की उनके पेज नंबरों सहित सूची बनाती है?","optionsHi":["Table of Contents","Table of Figures","Index","Bibliography"],"explanationHi":"Table of Figures (References टैब) कैप्शन से बनती है। Table of Contents शीर्षक शैलियों से और Index चिह्नित सूचकांक प्रविष्टियों से बनता है।"},
  {"id":"comp-ms-office-internet-317","question":"In MS Word, which shortcut marks the selected word as an entry for the index at the back of the document?","options":["Alt + Shift + O","Alt + Ctrl + F","Alt + Shift + X","Alt + Ctrl + D"],"answer":2,"explanation":"Alt + Shift + X opens Mark Index Entry. Alt + Shift + O marks a table-of-contents entry, while Alt + Ctrl + F and Alt + Ctrl + D insert a footnote and an endnote.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word में कौन-सा शॉर्टकट चयनित शब्द को दस्तावेज़ के अंत के सूचकांक (index) की प्रविष्टि के रूप में चिह्नित करता है?","optionsHi":["Alt + Shift + O","Alt + Ctrl + F","Alt + Shift + X","Alt + Ctrl + D"],"explanationHi":"Alt + Shift + X Mark Index Entry खोलता है। Alt + Shift + O विषय-सूची की प्रविष्टि चिह्नित करता है, जबकि Alt + Ctrl + F और Alt + Ctrl + D फ़ुटनोट और एंडनोट डालते हैं।"},
  {"id":"comp-ms-office-internet-318","question":"An officer has two versions of a circular saved as separate Word files, and Track Changes was never turned on. Which feature shows every difference between them as tracked changes?","options":["Restrict Editing (Review tab)","Accept All Changes (Review tab)","Inspect Document (File tab)","Compare (Review tab)"],"answer":3,"explanation":"Review > Compare takes an original and a revised file and produces a document showing the differences as tracked changes. Accept All only works on changes already tracked.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक अधिकारी के पास किसी परिपत्र के दो संस्करण अलग-अलग Word फ़ाइलों में सेव हैं, और Track Changes कभी चालू नहीं किया गया था। कौन-सी सुविधा उनके बीच हर अंतर को ट्रैक किए गए परिवर्तनों के रूप में दिखाती है?","optionsHi":["Restrict Editing (Review टैब)","Accept All Changes (Review टैब)","Inspect Document (File टैब)","Compare (Review टैब)"],"explanationHi":"Review > Compare मूल और संशोधित फ़ाइल लेकर ऐसा दस्तावेज़ बनाता है जो अंतरों को ट्रैक किए गए परिवर्तनों के रूप में दिखाता है। Accept All केवल पहले से ट्रैक किए गए परिवर्तनों पर काम करता है।"},
  {"id":"comp-ms-office-internet-319","question":"In MS Word, text is selected and Ctrl + Shift + H is pressed. What happens to it?","options":["It is highlighted in yellow, like with the Highlighter tool","It is changed into a heading in the Navigation pane","It becomes hidden text, not shown unless formatting marks are on","It is replaced with the next match of the Replace box"],"answer":2,"explanation":"Ctrl + Shift + H applies the Hidden font format: the text disappears from view (and normally from print) but shows with a dotted underline when Show/Hide ¶ is on.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word में टेक्स्ट चयनित है और Ctrl + Shift + H दबाया जाता है। उसका क्या होता है?","optionsHi":["वह Highlighter टूल की तरह पीले रंग में हाइलाइट हो जाता है","वह Navigation पेन में शीर्षक बन जाता है","वह छिपा हुआ पाठ बन जाता है, जो फ़ॉर्मेटिंग चिह्न चालू हुए बिना नहीं दिखता","उसकी जगह Replace बॉक्स का अगला मिलान आ जाता है"],"explanationHi":"Ctrl + Shift + H Hidden फ़ॉन्ट फ़ॉर्मेट लगाता है: पाठ दृश्य से (और सामान्यतः प्रिंट से) गायब हो जाता है, पर Show/Hide ¶ चालू होने पर बिंदीदार अधोरेखा के साथ दिखता है।"},
  {"id":"comp-ms-office-internet-320","question":"Which view in MS Word shows a document as a hierarchy of headings, so that a whole section can be promoted, demoted or moved together with its text?","options":["Outline view","Draft view","Web Layout view","Read Mode"],"answer":0,"explanation":"Outline view displays heading levels and lets you move or promote a heading with everything under it. Draft view is a plain typing view without headers or most graphics.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"MS Word का कौन-सा व्यू दस्तावेज़ को शीर्षकों के पदानुक्रम के रूप में दिखाता है, ताकि पूरे अनुभाग को उसके पाठ सहित ऊपर, नीचे या स्थानांतरित किया जा सके?","optionsHi":["Outline व्यू","Draft व्यू","Web Layout व्यू","Read Mode"],"explanationHi":"Outline व्यू शीर्षक स्तर दिखाता है और किसी शीर्षक को उसके नीचे की हर चीज़ के साथ स्थानांतरित या ऊपर उठाने देता है। Draft व्यू हेडर और अधिकांश ग्राफ़िक्स के बिना सादा टाइपिंग व्यू है।"},
  {"id":"comp-ms-office-internet-321","question":"A list in Word has codes at the start of each line (such as A101, B202). How can just the first four characters of every line be selected as a vertical block?","options":["Triple-click in the first line, then drag down the list","Hold Ctrl and click on each line in turn","Hold Shift and press the Down arrow key","Hold Alt and drag down over the first four characters"],"answer":3,"explanation":"Alt + drag makes a rectangular (column) selection. A triple-click selects a paragraph, Ctrl + click selects a sentence, and Shift + Down selects whole lines.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Word में एक सूची की हर पंक्ति के आरंभ में कोड हैं (जैसे A101, B202)। हर पंक्ति के केवल पहले चार अक्षरों को ऊर्ध्वाधर ब्लॉक के रूप में कैसे चयनित करें?","optionsHi":["पहली पंक्ति में ट्रिपल-क्लिक करें, फिर सूची में नीचे खींचें","Ctrl दबाकर हर पंक्ति पर बारी-बारी से क्लिक करें","Shift दबाकर नीचे तीर कुंजी दबाएँ","Alt दबाकर पहले चार अक्षरों पर नीचे की ओर खींचें"],"explanationHi":"Alt + खींचना आयताकार (कॉलम) चयन बनाता है। ट्रिपल-क्लिक अनुच्छेद चयनित करता है, Ctrl + क्लिक वाक्य चयनित करता है, और Shift + नीचे तीर पूरी पंक्तियाँ चयनित करता है।"},
  {"id":"comp-ms-office-internet-322","question":"In MS Word the cursor is inside a word in the middle of a sentence. F8 is pressed three times. What is selected now?","options":["The current word","The whole sentence","The whole paragraph","The whole document"],"answer":1,"explanation":"The first F8 turns on extend mode, the second selects the word, the third the sentence, then the paragraph and finally the whole document.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word में कर्सर किसी वाक्य के बीच के शब्द के भीतर है। F8 तीन बार दबाया जाता है। अब क्या चयनित है?","optionsHi":["वर्तमान शब्द","पूरा वाक्य","पूरा अनुच्छेद","पूरा दस्तावेज़"],"explanationHi":"पहला F8 विस्तार मोड चालू करता है, दूसरा शब्द चयनित करता है, तीसरा वाक्य, फिर अनुच्छेद और अंत में पूरा दस्तावेज़।"},
  {"id":"comp-ms-office-internet-323","question":"In a Word report, a heading keeps appearing alone at the bottom of a page while its first paragraph starts on the next page. Which paragraph option should be set on the heading?","options":["Widow/Orphan control","Page break before","Keep with next","Keep lines together"],"answer":2,"explanation":"Keep with next keeps a paragraph on the same page as the next one. Widow/Orphan control works on single lines of one paragraph, and Keep lines together stops one paragraph from splitting.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी Word रिपोर्ट में एक शीर्षक बार-बार पेज के नीचे अकेला आ जाता है जबकि उसका पहला अनुच्छेद अगले पेज पर शुरू होता है। शीर्षक पर कौन-सा अनुच्छेद विकल्प सेट करना चाहिए?","optionsHi":["Widow/Orphan control","Page break before","Keep with next","Keep lines together"],"explanationHi":"Keep with next किसी अनुच्छेद को अगले अनुच्छेद के साथ उसी पेज पर रखता है। Widow/Orphan control एक अनुच्छेद की अकेली पंक्तियों पर काम करता है, और Keep lines together एक अनुच्छेद को बँटने से रोकता है।"},
  {"id":"comp-ms-office-internet-324","question":"A Word table spreads over four pages. Which option makes its column titles appear again at the top of each page?","options":["Repeat Header Rows","Merge Cells","Allow row to break across pages","AutoFit to Contents"],"answer":0,"explanation":"Repeat Header Rows (Table Layout) repeats the marked first row(s) on every page the table runs onto. Allow row to break only controls whether one row may split.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"एक Word तालिका चार पेजों में फैली है। कौन-सा विकल्प उसके कॉलम शीर्षकों को हर पेज के ऊपर दोबारा दिखाता है?","optionsHi":["Repeat Header Rows","Merge Cells","Allow row to break across pages","AutoFit to Contents"],"explanationHi":"Repeat Header Rows (Table Layout) चिह्नित पहली पंक्ति(यों) को तालिका के हर पेज पर दोहराता है। Allow row to break केवल यह नियंत्रित करता है कि एक पंक्ति बँट सकती है या नहीं।"},
  {"id":"comp-ms-office-internet-325","question":"By default, a picture inserted into an MS Word document is placed with which text wrapping?","options":["Top and Bottom","Tight","In Front of Text","In Line with Text"],"answer":3,"explanation":"Unless the default is changed in Options, Word inserts a picture In Line with Text, so it behaves like a big character. Top and Bottom, Tight and In Front of Text make it a floating object.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"MS Word दस्तावेज़ में डाला गया चित्र डिफ़ॉल्ट रूप से किस टेक्स्ट रैपिंग के साथ रखा जाता है?","optionsHi":["Top and Bottom","Tight","In Front of Text","In Line with Text"],"explanationHi":"जब तक Options में डिफ़ॉल्ट न बदला जाए, Word चित्र को In Line with Text डालता है, इसलिए वह बड़े अक्षर की तरह व्यवहार करता है। Top and Bottom, Tight और In Front of Text उसे तैरता हुआ ऑब्जेक्ट बनाते हैं।"},
  {"id":"comp-ms-office-internet-326","question":"Match the MS Word shortcut with the symbol it inserts: 1. Ctrl + Alt + C 2. Ctrl + Alt + R 3. Ctrl + Alt + T; a. ™ (trademark) b. © (copyright) c. ® (registered)","options":["1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b"],"answer":1,"explanation":"Ctrl + Alt + C inserts ©, Ctrl + Alt + R inserts ® and Ctrl + Alt + T inserts ™. AutoCorrect also turns (c), (r) and (tm) into these symbols.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Word शॉर्टकट को उसके डाले गए प्रतीक से सुमेलित कीजिए: 1. Ctrl + Alt + C 2. Ctrl + Alt + R 3. Ctrl + Alt + T; a. ™ (ट्रेडमार्क) b. © (कॉपीराइट) c. ® (पंजीकृत)","optionsHi":["1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b"],"explanationHi":"Ctrl + Alt + C © डालता है, Ctrl + Alt + R ® डालता है और Ctrl + Alt + T ™ डालता है। AutoCorrect भी (c), (r) और (tm) को इन प्रतीकों में बदल देता है।"},
  {"id":"comp-ms-office-internet-327","question":"A user records a macro in MS Word and keeps the default choice of where to store it. Why can the macro be used in every new document afterwards?","options":["It is stored inside the current document and copied to others when opened","It is stored in the Normal.dotm template that all new documents are based on","It is stored as a separate .docm file that Word opens with each document","It is stored in the Quick Access Toolbar, which keeps a copy of the code"],"answer":1,"explanation":"Word's default location for a recorded macro is All Documents (Normal.dotm), the global template behind every new blank document. A .docm keeps macros only inside that file.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक उपयोगकर्ता MS Word में मैक्रो रिकॉर्ड करता है और उसे कहाँ संग्रहीत करना है इसका डिफ़ॉल्ट विकल्प रखता है। बाद में मैक्रो हर नए दस्तावेज़ में क्यों उपयोग किया जा सकता है?","optionsHi":["वह वर्तमान दस्तावेज़ के भीतर संग्रहीत होता है और खोलने पर दूसरों में कॉपी हो जाता है","वह Normal.dotm टेम्पलेट में संग्रहीत होता है, जिस पर सभी नए दस्तावेज़ आधारित होते हैं","वह अलग .docm फ़ाइल के रूप में संग्रहीत होता है जिसे Word हर दस्तावेज़ के साथ खोलता है","वह Quick Access Toolbar में संग्रहीत होता है, जो कोड की प्रति रखता है"],"explanationHi":"रिकॉर्ड किए गए मैक्रो का Word में डिफ़ॉल्ट स्थान All Documents (Normal.dotm) है, जो हर नए खाली दस्तावेज़ के पीछे का वैश्विक टेम्पलेट है। .docm मैक्रो केवल उसी फ़ाइल के भीतर रखता है।"},
  {"id":"comp-ms-office-internet-328","question":"On a PowerPoint slide the title appears on a click. A chart must then appear by itself 2 seconds after the title's animation ends, with no further click. How should the chart's animation be set?","options":["Start: After Previous, with a Delay of 2 seconds","Start: With Previous, with a Duration of 2 seconds","Start: On Click, with a Delay of 2 seconds","Start: With Previous, with no delay at all"],"answer":0,"explanation":"After Previous starts an effect when the one before it ends, and Delay adds the wait. With Previous starts at the same moment as the title, and On Click still needs a click.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"PowerPoint स्लाइड पर शीर्षक क्लिक करने पर आता है। शीर्षक के एनिमेशन के समाप्त होने के 2 सेकंड बाद एक चार्ट अपने आप, बिना किसी और क्लिक के, आना चाहिए। चार्ट के एनिमेशन को कैसे सेट करना चाहिए?","optionsHi":["Start: After Previous, 2 सेकंड के Delay के साथ","Start: With Previous, 2 सेकंड की Duration के साथ","Start: On Click, 2 सेकंड के Delay के साथ","Start: With Previous, बिल्कुल बिना विलंब के"],"explanationHi":"After Previous प्रभाव को तब शुरू करता है जब उससे पहले वाला समाप्त हो, और Delay प्रतीक्षा जोड़ता है। With Previous शीर्षक के साथ ही उसी क्षण शुरू होता है, और On Click को फिर भी क्लिक चाहिए।"},
  {"id":"comp-ms-office-internet-329","question":"In PowerPoint, a logo already shown on a slide must fade away from the slide when the presenter clicks. Which group of animation effects should be used?","options":["Entrance","Emphasis","Transition","Exit"],"answer":3,"explanation":"Exit effects make an object leave the slide. Entrance effects bring it in, Emphasis effects act on it while it stays, and a transition acts between slides, not on one object.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"PowerPoint में, स्लाइड पर पहले से दिख रहा लोगो प्रस्तुतकर्ता के क्लिक करने पर स्लाइड से धीरे-धीरे गायब होना चाहिए। एनिमेशन प्रभावों के किस समूह का उपयोग करना चाहिए?","optionsHi":["Entrance","Emphasis","Transition","Exit"],"explanationHi":"Exit प्रभाव किसी ऑब्जेक्ट को स्लाइड से हटाते हैं। Entrance प्रभाव उसे लाते हैं, Emphasis प्रभाव उसके रहते हुए उस पर काम करते हैं, और ट्रांज़िशन स्लाइडों के बीच काम करता है, एक ऑब्जेक्ट पर नहीं।"},
  {"id":"comp-ms-office-internet-330","question":"In PowerPoint, a car picture must travel across a map slide along a curved route drawn by the presenter. Which kind of animation does this?","options":["Emphasis (Spin)","Motion Path","Entrance (Fly In)","Morph transition"],"answer":1,"explanation":"A Motion Path moves an object along a line or a custom path you draw. Fly In only brings the object in from an edge, and Spin rotates it in place.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"PowerPoint में, एक कार का चित्र नक्शे वाली स्लाइड पर प्रस्तुतकर्ता द्वारा खींचे गए घुमावदार मार्ग से गुज़रना चाहिए। यह किस प्रकार का एनिमेशन करता है?","optionsHi":["Emphasis (Spin)","Motion Path","Entrance (Fly In)","Morph ट्रांज़िशन"],"explanationHi":"Motion Path किसी ऑब्जेक्ट को रेखा या आपके खींचे कस्टम मार्ग पर चलाता है। Fly In ऑब्जेक्ट को केवल किनारे से अंदर लाता है, और Spin उसे अपनी जगह घुमाता है।"},
  {"id":"comp-ms-office-internet-331","question":"Match the key pressed during a PowerPoint slide show with its effect: 1. Ctrl + P 2. E 3. Ctrl + H 4. Esc; a. ends the slide show b. hides the mouse pointer c. erases the ink drawn on the slide d. changes the pointer into a pen","options":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":2,"explanation":"In a slide show, Ctrl + P gives a pen, E erases the ink on the slide, Ctrl + H hides the pointer and Esc ends the show.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"PowerPoint स्लाइड शो के दौरान दबाई गई कुंजी को उसके प्रभाव से सुमेलित कीजिए: 1. Ctrl + P 2. E 3. Ctrl + H 4. Esc; a. स्लाइड शो समाप्त करता है b. माउस पॉइंटर छिपाता है c. स्लाइड पर खींची गई स्याही मिटाता है d. पॉइंटर को पेन में बदलता है","optionsHi":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"explanationHi":"स्लाइड शो में Ctrl + P पेन देता है, E स्लाइड की स्याही मिटाता है, Ctrl + H पॉइंटर छिपाता है और Esc शो समाप्त करता है।"},
  {"id":"comp-ms-office-internet-332","question":"During a PowerPoint slide show on slide 12 of 30, what do the Home and End keys do?","options":["Home jumps to slide 1 and End jumps to slide 30","Home jumps to slide 11 and End jumps to slide 13","Home ends the show and End returns to Normal view","Home shows a black screen and End shows a white one"],"answer":0,"explanation":"In a slide show, Home goes to the first slide and End to the last. The previous and next slides use keys such as P/N, arrows or Page Up/Page Down.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"30 में से स्लाइड 12 पर PowerPoint स्लाइड शो के दौरान Home और End कुंजियाँ क्या करती हैं?","optionsHi":["Home स्लाइड 1 पर और End स्लाइड 30 पर कूदता है","Home स्लाइड 11 पर और End स्लाइड 13 पर कूदता है","Home शो समाप्त करता है और End Normal व्यू पर लौटाता है","Home काली स्क्रीन दिखाता है और End सफ़ेद"],"explanationHi":"स्लाइड शो में Home पहली स्लाइड पर और End अंतिम स्लाइड पर जाता है। पिछली और अगली स्लाइडों के लिए P/N, तीर या Page Up/Page Down जैसी कुंजियाँ हैं।"},
  {"id":"comp-ms-office-internet-333","question":"A trainer wants the printed handouts of a PowerPoint deck to carry the bank's logo and a footer on every handout page, without changing the slides themselves. Where should this be set up?","options":["Slide Master","Notes Master","Handout Master","Slide Sorter view"],"answer":2,"explanation":"The Handout Master controls the layout of printed handout pages. The Slide Master changes the slides, and the Notes Master changes printed notes pages.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक प्रशिक्षक चाहता है कि PowerPoint डेक के मुद्रित हैंडआउट के हर पेज पर बैंक का लोगो और फ़ुटर हो, स्लाइडों को बदले बिना। यह कहाँ सेट किया जाना चाहिए?","optionsHi":["Slide Master","Notes Master","Handout Master","Slide Sorter व्यू"],"explanationHi":"Handout Master मुद्रित हैंडआउट पेजों का लेआउट नियंत्रित करता है। Slide Master स्लाइडें बदलता है, और Notes Master मुद्रित नोट्स पेज बदलता है।"},
  {"id":"comp-ms-office-internet-334","question":"Which PowerPoint view shows each slide at the top of a page with its speaker notes below it, exactly as it will look when notes are printed?","options":["Normal view","Slide Sorter view","Outline view","Notes Page view"],"answer":3,"explanation":"Notes Page view shows the printable page with a slide and its notes, and lets you add graphics to the notes. Normal view shows notes only in a small pane.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"PowerPoint का कौन-सा व्यू हर स्लाइड को पेज के ऊपर और उसके नीचे उसके स्पीकर नोट्स के साथ दिखाता है, ठीक वैसे जैसे नोट्स छपने पर दिखेंगे?","optionsHi":["Normal व्यू","Slide Sorter व्यू","Outline व्यू","Notes Page व्यू"],"explanationHi":"Notes Page व्यू स्लाइड और उसके नोट्स वाला मुद्रण योग्य पेज दिखाता है, और नोट्स में ग्राफ़िक्स जोड़ने देता है। Normal व्यू नोट्स केवल छोटे पेन में दिखाता है।"},
  {"id":"comp-ms-office-internet-335","question":"A 40-slide deck is shown to the board, but only slides 3, 8, 15 and 22 are needed for a branch meeting. Without deleting or hiding anything, which feature lets these be presented as a separate show?","options":["Rehearse Timings","Custom Slide Show","Slide Sorter view","Reuse Slides"],"answer":1,"explanation":"A Custom Slide Show is a named list of chosen slides in any order that can be run on its own, while the full deck stays unchanged.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"बोर्ड को 40-स्लाइड का डेक दिखाया जाता है, पर शाखा की बैठक के लिए केवल स्लाइड 3, 8, 15 और 22 चाहिए। कुछ हटाए या छिपाए बिना, कौन-सी सुविधा इन्हें अलग शो के रूप में प्रस्तुत करने देती है?","optionsHi":["Rehearse Timings","Custom Slide Show","Slide Sorter व्यू","Reuse Slides"],"explanationHi":"Custom Slide Show चुनी हुई स्लाइडों की नामित सूची है, किसी भी क्रम में, जिसे अलग से चलाया जा सकता है, जबकि पूरा डेक अपरिवर्तित रहता है।"},
  {"id":"comp-ms-office-internet-336","question":"A presenter wants a PowerPoint show with manual slide changes to start again from the first slide after the last one, and to keep repeating until Esc is pressed. Which Set Up Show option does this?","options":["Browsed at a kiosk (full screen)","Show without animation","Use Presenter View","Loop continuously until Esc"],"answer":3,"explanation":"Loop continuously until Esc repeats the show. Kiosk mode also loops but ignores ordinary clicks, so a presenter could not advance the slides by hand.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक प्रस्तुतकर्ता चाहता है कि मैन्युअल स्लाइड बदलाव वाला PowerPoint शो अंतिम स्लाइड के बाद पहली स्लाइड से फिर शुरू हो, और Esc दबाए जाने तक दोहराता रहे। Set Up Show का कौन-सा विकल्प यह करता है?","optionsHi":["Browsed at a kiosk (full screen)","Show without animation","Use Presenter View","Loop continuously until Esc"],"explanationHi":"Loop continuously until Esc शो को दोहराता है। Kiosk मोड भी लूप करता है पर सामान्य क्लिक को अनदेखा करता है, इसलिए प्रस्तुतकर्ता स्लाइडें हाथ से आगे नहीं बढ़ा पाता।"},
  {"id":"comp-ms-office-internet-337","question":"A song inserted on the first slide of a PowerPoint photo album stops as soon as the next slide appears. Which audio setting keeps it playing over the following slides?","options":["Play Across Slides","Hide During Show","Rewind after Playing","Start: On Click"],"answer":0,"explanation":"Play Across Slides (part of Play in Background) keeps the sound going when slides change. Hide During Show only hides the sound icon.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"PowerPoint फ़ोटो एल्बम की पहली स्लाइड पर डाला गया गीत अगली स्लाइड आते ही रुक जाता है। कौन-सी ऑडियो सेटिंग उसे आगे की स्लाइडों पर भी बजाए रखती है?","optionsHi":["Play Across Slides","Hide During Show","Rewind after Playing","Start: On Click"],"explanationHi":"Play Across Slides (Play in Background का भाग) स्लाइड बदलने पर भी ध्वनि जारी रखता है। Hide During Show केवल ध्वनि आइकन छिपाता है।"},
  {"id":"comp-ms-office-internet-338","question":"A PowerPoint deck plays linked video files kept in another folder. It must be carried to another computer so that everything still plays. Which option gathers the deck and its linked files together?","options":["Save As PowerPoint Show (.ppsx)","Package Presentation for CD","Save As PDF document","Compress Pictures"],"answer":1,"explanation":"Package Presentation for CD copies the presentation with its linked files into a folder or CD. A .ppsx only changes how the file opens and does not collect linked media.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक PowerPoint डेक किसी अन्य फ़ोल्डर में रखी लिंक की गई वीडियो फ़ाइलें चलाता है। उसे दूसरे कंप्यूटर पर ले जाना है ताकि सब कुछ फिर भी चले। कौन-सा विकल्प डेक और उसकी लिंक की गई फ़ाइलों को एक साथ इकट्ठा करता है?","optionsHi":["Save As PowerPoint Show (.ppsx)","Package Presentation for CD","Save As PDF document","Compress Pictures"],"explanationHi":"Package Presentation for CD प्रस्तुति को उसकी लिंक की गई फ़ाइलों के साथ फ़ोल्डर या CD में कॉपी करता है। .ppsx केवल फ़ाइल के खुलने का तरीका बदलता है और लिंक किया मीडिया इकट्ठा नहीं करता।"},
  {"id":"comp-ms-office-internet-339","question":"In PowerPoint, one slide has text typed in its title and content placeholders and also some text inside a text box drawn with the Text Box tool. Which text appears in Outline view?","options":["Only the text inside the separately drawn text box","All the text on the slide, from every source","Only the text in the title and content placeholders","None of it, because Outline view shows thumbnails"],"answer":2,"explanation":"Outline view lists only text in the layout's title and body placeholders. Text in a manually added text box does not appear there, which is why placeholders are preferred.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"PowerPoint में, एक स्लाइड के शीर्षक और सामग्री प्लेसहोल्डरों में टाइप किया गया पाठ है और Text Box टूल से खींचे गए टेक्स्ट बॉक्स के भीतर भी कुछ पाठ है। Outline व्यू में कौन-सा पाठ दिखता है?","optionsHi":["केवल अलग से खींचे गए टेक्स्ट बॉक्स के भीतर का पाठ","स्लाइड का सारा पाठ, हर स्रोत से","केवल शीर्षक और सामग्री प्लेसहोल्डरों का पाठ","इनमें से कोई नहीं, क्योंकि Outline व्यू थंबनेल दिखाता है"],"explanationHi":"Outline व्यू केवल लेआउट के शीर्षक और मुख्य भाग प्लेसहोल्डरों का पाठ सूचीबद्ध करता है। हाथ से जोड़े गए टेक्स्ट बॉक्स का पाठ वहाँ नहीं दिखता, इसीलिए प्लेसहोल्डरों को प्राथमिकता दी जाती है।"},
  {"id":"comp-ms-office-internet-340","question":"In PowerPoint, a shape is set up so that a new slide opens as soon as the pointer moves over it during the show, without clicking. Which setting is used?","options":["Action Settings on the Mouse Click tab","Action Settings on the Mouse Over tab","A trigger set on the shape's own animation","A transition set to advance After a time"],"answer":1,"explanation":"Action Settings has two tabs: Mouse Click acts on a click, and Mouse Over acts when the pointer simply passes over the object.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"PowerPoint में, किसी शेप को इस तरह सेट किया गया है कि शो के दौरान पॉइंटर उस पर जाते ही, क्लिक किए बिना, नई स्लाइड खुल जाए। कौन-सी सेटिंग उपयोग होती है?","optionsHi":["Mouse Click टैब पर Action Settings","Mouse Over टैब पर Action Settings","शेप के अपने एनिमेशन पर सेट ट्रिगर","समय के बाद आगे बढ़ने (After) पर सेट ट्रांज़िशन"],"explanationHi":"Action Settings में दो टैब हैं: Mouse Click क्लिक पर काम करता है, और Mouse Over तब काम करता है जब पॉइंटर केवल ऑब्जेक्ट के ऊपर से गुज़रता है।"},
  {"id":"comp-ms-office-internet-341","question":"In MS PowerPoint, which pair of shortcuts groups the selected objects and ungroups a group respectively?","options":["Ctrl + Shift + G and Ctrl + G","Ctrl + G and Ctrl + U","Ctrl + G and Ctrl + Shift + G","Alt + G and Alt + Shift + G"],"answer":2,"explanation":"Ctrl + G groups and Ctrl + Shift + G ungroups selected objects. Ctrl + U is underline.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"MS PowerPoint में शॉर्टकटों का कौन-सा युग्म क्रमशः चयनित ऑब्जेक्टों को समूहित (group) करता है और समूह को असमूहित (ungroup) करता है?","optionsHi":["Ctrl + Shift + G और Ctrl + G","Ctrl + G और Ctrl + U","Ctrl + G और Ctrl + Shift + G","Alt + G और Alt + Shift + G"],"explanationHi":"Ctrl + G समूहित करता है और Ctrl + Shift + G चयनित ऑब्जेक्टों को असमूहित करता है। Ctrl + U अधोरेखा है।"},
  {"id":"comp-ms-office-internet-342","question":"In PowerPoint, the Oval tool is selected. Which key should be held while dragging so that the shape is drawn as a perfect circle?","options":["Shift","Ctrl","Alt","Tab"],"answer":0,"explanation":"Holding Shift keeps the width and height equal (a circle or square). Ctrl draws the shape outward from the centre, and Alt turns off snapping to the grid.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"PowerPoint में Oval टूल चयनित है। शेप को एकदम पूर्ण वृत्त के रूप में बनाने के लिए खींचते समय कौन-सी कुंजी दबाए रखनी चाहिए?","optionsHi":["Shift","Ctrl","Alt","Tab"],"explanationHi":"Shift दबाए रखने से चौड़ाई और ऊँचाई बराबर रहती हैं (वृत्त या वर्ग)। Ctrl शेप को केंद्र से बाहर की ओर बनाता है, और Alt ग्रिड पर स्नैपिंग बंद करता है।"},
  {"id":"comp-ms-office-internet-343","question":"Five icons are placed roughly in a row on a PowerPoint slide. Which command makes the gaps between them exactly equal, keeping the first and last icons where they are?","options":["Align Center to the slide","Align Middle to the slide","Group, then Align Left","Distribute Horizontally"],"answer":3,"explanation":"Distribute Horizontally spaces three or more objects evenly between the outer two. Align Center and Align Middle line objects up along one axis but do not equalise gaps.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"PowerPoint स्लाइड पर पाँच आइकन लगभग एक पंक्ति में रखे हैं। कौन-सा आदेश उनके बीच के अंतर को ठीक बराबर करता है, पहले और अंतिम आइकन को उनकी जगह पर रखते हुए?","optionsHi":["स्लाइड के सापेक्ष Align Center","स्लाइड के सापेक्ष Align Middle","Group करें, फिर Align Left","Distribute Horizontally"],"explanationHi":"Distribute Horizontally तीन या अधिक ऑब्जेक्टों को बाहरी दो के बीच समान रूप से फैलाता है। Align Center और Align Middle ऑब्जेक्टों को एक अक्ष पर पंक्तिबद्ध करते हैं पर अंतर बराबर नहीं करते।"},
  {"id":"comp-ms-office-internet-344","question":"A PowerPoint slide uses the Title and Content arrangement, but the presenter wants two side-by-side content boxes on it instead. What should be changed for that slide?","options":["Its theme","Its transition","Its layout","Its slide size"],"answer":2,"explanation":"A layout decides which placeholders a slide has and where (for example Two Content). A theme controls colours, fonts and effects for the whole deck.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"एक PowerPoint स्लाइड Title and Content व्यवस्था का उपयोग करती है, पर प्रस्तुतकर्ता उस पर इसके बजाय दो अगल-बगल सामग्री बॉक्स चाहता है। उस स्लाइड के लिए क्या बदलना चाहिए?","optionsHi":["उसकी थीम","उसका ट्रांज़िशन","उसका लेआउट","उसका स्लाइड आकार"],"explanationHi":"लेआउट तय करता है कि स्लाइड में कौन-से प्लेसहोल्डर हों और कहाँ हों (जैसे Two Content)। थीम पूरे डेक के रंग, फ़ॉन्ट और प्रभाव नियंत्रित करती है।"},
  {"id":"comp-ms-office-internet-345","question":"In PowerPoint, slide numbers must appear on every slide except the title slide. Which option does this?","options":["Insert > Header & Footer > Slide number with Don't show on title slide ticked","Insert > Slide Number on each slide, then delete it from the title slide each time","View > Slide Master > Different First Page ticked for the title layout","Design > Slide Size > Start numbering at 2 for the presentation"],"answer":0,"explanation":"The Header & Footer dialog has a Slide number box and a Don't show on title slide option. Different First Page is a Word header option, not a PowerPoint one.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"PowerPoint में, स्लाइड नंबर शीर्षक स्लाइड को छोड़कर हर स्लाइड पर दिखने चाहिए। कौन-सा विकल्प यह करता है?","optionsHi":["Insert > Header & Footer > Slide number, Don't show on title slide चुनकर","हर स्लाइड पर Insert > Slide Number, फिर हर बार शीर्षक स्लाइड से उसे हटाकर","View > Slide Master > शीर्षक लेआउट के लिए Different First Page चुनकर","Design > Slide Size > प्रस्तुति के लिए Start numbering at 2"],"explanationHi":"Header & Footer डायलॉग में Slide number बॉक्स और Don't show on title slide विकल्प है। Different First Page Word का हेडर विकल्प है, PowerPoint का नहीं।"},
  {"id":"comp-ms-office-internet-346","question":"Which PowerPoint feature runs the show and saves the presenter's voice narration, ink and laser-pointer gestures with the slide timings?","options":["Rehearse Timings","Record Slide Show","Custom Slide Show","Set Up Slide Show"],"answer":1,"explanation":"Record Slide Show captures narration, ink and pointer along with timings. Rehearse Timings records only how long each slide stays on screen.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"PowerPoint की कौन-सी सुविधा शो चलाती है और प्रस्तुतकर्ता की आवाज़ की कथन-रिकॉर्डिंग, स्याही और लेज़र-पॉइंटर की गतिविधियों को स्लाइड टाइमिंग के साथ सेव करती है?","optionsHi":["Rehearse Timings","Record Slide Show","Custom Slide Show","Set Up Slide Show"],"explanationHi":"Record Slide Show टाइमिंग के साथ कथन, स्याही और पॉइंटर को पकड़ता है। Rehearse Timings केवल यह दर्ज करता है कि हर स्लाइड कितनी देर स्क्रीन पर रहती है।"},
  {"id":"comp-ms-office-internet-347","question":"An Excel chart is pasted into a PowerPoint deck as a LINKED object, and another copy is pasted as an EMBEDDED object. The Excel file's figures are then changed. What happens?","options":["The embedded chart updates to the new figures; the linked one keeps the old data","Both charts update, since both of them came from the same Excel file","Neither chart changes, since pasting breaks every tie to Excel","The linked chart can update to the new figures; the embedded one keeps the old data"],"answer":3,"explanation":"A linked object points to the source file and can be refreshed from it. An embedded object carries its own copy of the data inside the presentation and does not follow the source.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक Excel चार्ट PowerPoint डेक में LINKED ऑब्जेक्ट के रूप में पेस्ट किया गया है, और दूसरी प्रति EMBEDDED ऑब्जेक्ट के रूप में। फिर Excel फ़ाइल के आँकड़े बदल दिए जाते हैं। क्या होता है?","optionsHi":["एम्बेडेड चार्ट नए आँकड़ों में अपडेट हो जाता है; लिंक वाला पुराना डेटा रखता है","दोनों चार्ट अपडेट हो जाते हैं, क्योंकि दोनों एक ही Excel फ़ाइल से आए हैं","कोई चार्ट नहीं बदलता, क्योंकि पेस्ट करने से Excel से हर संबंध टूट जाता है","लिंक वाला चार्ट नए आँकड़ों में अपडेट हो सकता है; एम्बेडेड पुराना डेटा रखता है"],"explanationHi":"लिंक किया गया ऑब्जेक्ट स्रोत फ़ाइल की ओर इंगित करता है और उससे ताज़ा किया जा सकता है। एम्बेडेड ऑब्जेक्ट प्रस्तुति के भीतर डेटा की अपनी प्रति रखता है और स्रोत का अनुसरण नहीं करता।"},
  {"id":"comp-ms-office-internet-348","question":"Up to how many copied items can the Office Clipboard (Home tab > Clipboard pane) hold at a time in MS Office applications?","options":["12","32","Only one","24"],"answer":3,"explanation":"The Office Clipboard keeps up to 24 items; copying a 25th removes the oldest. The ordinary Windows clipboard paste (Ctrl + V) uses only the latest item.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Office अनुप्रयोगों में Office Clipboard (Home टैब > Clipboard पेन) एक समय में अधिकतम कितने कॉपी किए गए आइटम रख सकता है?","optionsHi":["12","32","केवल एक","24"],"explanationHi":"Office Clipboard अधिकतम 24 आइटम रखता है; 25वाँ कॉपी करने पर सबसे पुराना हट जाता है। साधारण Windows क्लिपबोर्ड पेस्ट (Ctrl + V) केवल नवीनतम आइटम का उपयोग करता है।"},
  {"id":"comp-ms-office-internet-349","question":"In MS Office programs such as Word and Excel, what does pressing Ctrl + F1 do?","options":["Opens the Help window for the program","Opens the Print preview of the file","Shows or hides (collapses) the ribbon","Starts the spelling and grammar check"],"answer":2,"explanation":"Ctrl + F1 collapses or expands the ribbon. F1 alone opens Help, Ctrl + F2 shows print preview and F7 runs the spelling check.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"Word और Excel जैसे MS Office प्रोग्रामों में Ctrl + F1 दबाने पर क्या होता है?","optionsHi":["प्रोग्राम की Help विंडो खुलती है","फ़ाइल का Print preview खुलता है","रिबन दिखता या छिपता (संक्षिप्त होता) है","स्पेलिंग और व्याकरण जाँच शुरू होती है"],"explanationHi":"Ctrl + F1 रिबन को संक्षिप्त या विस्तृत करता है। अकेला F1 Help खोलता है, Ctrl + F2 प्रिंट पूर्वावलोकन दिखाता है और F7 स्पेल चेक चलाता है।"},
  {"id":"comp-ms-office-internet-350","question":"In MS Office programs, what happens when the Alt key is pressed and released?","options":["Small letters (KeyTips) appear on the ribbon for keyboard access","The program switches to the next open window of the same file","The selected text is changed to the alternate font of the theme","The ribbon is hidden until the mouse is moved to the top again"],"answer":0,"explanation":"Pressing Alt shows KeyTips, letters you can type to open a tab and then a command (for example Alt, H for the Home tab), so the ribbon can be used without a mouse.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"MS Office प्रोग्रामों में Alt कुंजी दबाकर छोड़ने पर क्या होता है?","optionsHi":["रिबन पर कीबोर्ड पहुँच के लिए छोटे अक्षर (KeyTips) दिखते हैं","प्रोग्राम उसी फ़ाइल की अगली खुली विंडो पर चला जाता है","चयनित टेक्स्ट थीम के वैकल्पिक फ़ॉन्ट में बदल जाता है","माउस दोबारा ऊपर ले जाए जाने तक रिबन छिप जाता है"],"explanationHi":"Alt दबाने पर KeyTips दिखते हैं, अक्षर जिन्हें टाइप करके टैब और फिर आदेश खोला जा सकता है (जैसे Home टैब के लिए Alt, H), ताकि रिबन का उपयोग बिना माउस के हो सके।"},
  {"id":"comp-ms-office-internet-351","question":"A Word file downloaded as an e-mail attachment opens with a yellow bar saying the file is read-only for safety until Enable Editing is clicked. Which Office feature is this?","options":["Restrict Editing","Protected View","Mark as Final","Compatibility Mode"],"answer":1,"explanation":"Protected View opens files from the internet or attachments in a read-only sandbox so that harmful content cannot run. Mark as Final is set by the author, not by the file's origin.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"ई-मेल अटैचमेंट के रूप में डाउनलोड की गई Word फ़ाइल पीली पट्टी के साथ खुलती है, जो कहती है कि Enable Editing क्लिक किए जाने तक फ़ाइल सुरक्षा के लिए केवल-पठन है। यह Office की कौन-सी सुविधा है?","optionsHi":["Restrict Editing","Protected View","Mark as Final","Compatibility Mode"],"explanationHi":"Protected View इंटरनेट या अटैचमेंट की फ़ाइलों को केवल-पठन सैंडबॉक्स में खोलता है ताकि हानिकारक सामग्री न चल सके। Mark as Final लेखक द्वारा सेट किया जाता है, फ़ाइल की उत्पत्ति से नहीं।"},
  {"id":"comp-ms-office-internet-352","question":"Which statement about AutoRecover in MS Office is correct?","options":["It saves the original file itself after every change, so Ctrl + S is never needed","It saves recovery copies at intervals but does not replace a normal save","It keeps every earlier version of the file permanently, even after a normal close","It works only for files that have been saved in the older .doc or .xls formats"],"answer":1,"explanation":"AutoRecover stores temporary recovery information (every 10 minutes by default) to restore work after a crash; if you close without saving, normal changes can still be lost.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"MS Office में AutoRecover के बारे में कौन-सा कथन सही है?","optionsHi":["यह हर परिवर्तन के बाद मूल फ़ाइल को ही सेव कर देता है, इसलिए Ctrl + S की कभी ज़रूरत नहीं","यह अंतराल पर रिकवरी प्रतियाँ सेव करता है पर सामान्य सेव की जगह नहीं लेता","यह फ़ाइल के हर पुराने संस्करण को स्थायी रूप से रखता है, सामान्य रूप से बंद करने के बाद भी","यह केवल पुराने .doc या .xls प्रारूपों में सेव की गई फ़ाइलों के लिए काम करता है"],"explanationHi":"AutoRecover क्रैश के बाद कार्य बहाल करने के लिए अस्थायी रिकवरी जानकारी संग्रहीत करता है (डिफ़ॉल्ट रूप से हर 10 मिनट); यदि आप बिना सेव किए बंद कर दें, तो सामान्य परिवर्तन फिर भी खो सकते हैं।"},
  {"id":"comp-ms-office-internet-353","question":"Which of these is NOT a private IPv4 address?","options":["10.255.1.1","192.168.100.1","172.32.5.1","172.20.0.5"],"answer":2,"explanation":"The private ranges are 10.0.0.0 to 10.255.255.255, 172.16.0.0 to 172.31.255.255 and 192.168.0.0 to 192.168.255.255. 172.32.5.1 lies just outside the 172.16 to 172.31 block, so it is public.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"इनमें से कौन-सा निजी (private) IPv4 पता नहीं है?","optionsHi":["10.255.1.1","192.168.100.1","172.32.5.1","172.20.0.5"],"explanationHi":"निजी रेंज 10.0.0.0 से 10.255.255.255, 172.16.0.0 से 172.31.255.255 और 192.168.0.0 से 192.168.255.255 हैं। 172.32.5.1 172.16 से 172.31 ब्लॉक के ठीक बाहर है, इसलिए यह सार्वजनिक है।"},
  {"id":"comp-ms-office-internet-354","question":"A technician runs ping 127.0.0.1 on a computer and gets replies. What has this test checked?","options":["The default gateway router that connects the LAN to the internet","The DNS server set up by the internet service provider","The first computer on the same local area network","The computer's own TCP/IP software, without using the network"],"answer":3,"explanation":"127.0.0.1 is the loopback address: packets never leave the machine, so a reply only shows that its own TCP/IP stack works.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक तकनीशियन किसी कंप्यूटर पर ping 127.0.0.1 चलाता है और उत्तर पाता है। इस परीक्षण ने क्या जाँचा है?","optionsHi":["डिफ़ॉल्ट गेटवे राउटर जो LAN को इंटरनेट से जोड़ता है","इंटरनेट सेवा प्रदाता द्वारा सेट किया गया DNS सर्वर","उसी स्थानीय क्षेत्र नेटवर्क का पहला कंप्यूटर","कंप्यूटर का अपना TCP/IP सॉफ़्टवेयर, नेटवर्क का उपयोग किए बिना"],"explanationHi":"127.0.0.1 लूपबैक पता है: पैकेट मशीन से बाहर कभी नहीं जाते, इसलिए उत्तर केवल यह दिखाता है कि उसका अपना TCP/IP स्टैक काम करता है।"},
  {"id":"comp-ms-office-internet-355","question":"A Windows PC set to obtain an IP address automatically shows the address 169.254.23.7 and cannot reach the internet. What is the most likely reason?","options":["It got no reply from a DHCP server, so it gave itself an address","It has been given a public IP address directly by the ISP","It is using the loopback address to test its own network card","It is connected to a network that uses only IPv6 addresses"],"answer":0,"explanation":"Addresses in 169.254.0.0/16 are self-assigned (APIPA, link-local) when no DHCP server answers; they work only on the local link, not on the internet.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"IP पता स्वचालित रूप से प्राप्त करने के लिए सेट एक Windows PC पता 169.254.23.7 दिखाता है और इंटरनेट तक नहीं पहुँच सकता। सबसे संभावित कारण क्या है?","optionsHi":["उसे DHCP सर्वर से कोई उत्तर नहीं मिला, इसलिए उसने स्वयं को पता दे दिया","उसे ISP द्वारा सीधे सार्वजनिक IP पता दिया गया है","वह अपने नेटवर्क कार्ड का परीक्षण करने के लिए लूपबैक पते का उपयोग कर रहा है","वह ऐसे नेटवर्क से जुड़ा है जो केवल IPv6 पतों का उपयोग करता है"],"explanationHi":"169.254.0.0/16 के पते स्व-आवंटित (APIPA, link-local) होते हैं जब कोई DHCP सर्वर उत्तर नहीं देता; वे केवल स्थानीय लिंक पर काम करते हैं, इंटरनेट पर नहीं।"},
  {"id":"comp-ms-office-internet-356","question":"How many usable host addresses does an IPv4 subnet with prefix /26 provide?","options":["64","62","30","126"],"answer":1,"explanation":"A /26 leaves 32 - 26 = 6 host bits, so 2^6 = 64 addresses, minus the network and broadcast addresses, leaving 62 usable hosts.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"प्रीफ़िक्स /26 वाला IPv4 सबनेट कितने प्रयोग योग्य होस्ट पते देता है?","optionsHi":["64","62","30","126"],"explanationHi":"/26 में 32 - 26 = 6 होस्ट बिट बचते हैं, इसलिए 2^6 = 64 पते, जिनमें से नेटवर्क और ब्रॉडकास्ट पते घटाने पर 62 प्रयोग योग्य होस्ट बचते हैं।"},
  {"id":"comp-ms-office-internet-357","question":"In the network 192.168.10.0 with subnet mask 255.255.255.0, which is the broadcast address?","options":["192.168.10.0","192.168.10.254","192.168.10.255","192.168.10.1"],"answer":2,"explanation":"With a /24 mask the last octet is the host part. All host bits set to 1 gives the broadcast address .255; .0 is the network address and .1 to .254 are usable hosts.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"सबनेट मास्क 255.255.255.0 वाले नेटवर्क 192.168.10.0 में ब्रॉडकास्ट पता कौन-सा है?","optionsHi":["192.168.10.0","192.168.10.254","192.168.10.255","192.168.10.1"],"explanationHi":"/24 मास्क के साथ अंतिम ऑक्टेट होस्ट भाग है। सभी होस्ट बिट 1 होने पर ब्रॉडकास्ट पता .255 मिलता है; .0 नेटवर्क पता है और .1 से .254 प्रयोग योग्य होस्ट हैं।"},
  {"id":"comp-ms-office-internet-358","question":"Under classful IPv4 addressing, the address 150.12.4.9 belongs to which class?","options":["Class B","Class A","Class C","Class D"],"answer":0,"explanation":"The first octet decides the class: 1 to 126 is Class A, 128 to 191 Class B, 192 to 223 Class C and 224 to 239 Class D (multicast). 150 falls in Class B.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"क्लासफ़ुल IPv4 एड्रेसिंग के अंतर्गत, पता 150.12.4.9 किस क्लास का है?","optionsHi":["क्लास B","क्लास A","क्लास C","क्लास D"],"explanationHi":"पहला ऑक्टेट क्लास तय करता है: 1 से 126 क्लास A, 128 से 191 क्लास B, 192 से 223 क्लास C और 224 से 239 क्लास D (मल्टीकास्ट) है। 150 क्लास B में आता है।"},
  {"id":"comp-ms-office-internet-359","question":"In what order are the four DHCP messages exchanged when a computer joins a network and gets an IP address?","options":["Request, Offer, Discover, Acknowledge","Discover, Offer, Request, Acknowledge","Discover, Request, Offer, Acknowledge","Offer, Discover, Request, Acknowledge"],"answer":1,"explanation":"DHCP follows DORA: the client broadcasts Discover, servers send Offer, the client Requests one offer, and the server Acknowledges it.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"जब कोई कंप्यूटर नेटवर्क से जुड़कर IP पता पाता है, तो चार DHCP संदेशों का आदान-प्रदान किस क्रम में होता है?","optionsHi":["Request, Offer, Discover, Acknowledge","Discover, Offer, Request, Acknowledge","Discover, Request, Offer, Acknowledge","Offer, Discover, Request, Acknowledge"],"explanationHi":"DHCP DORA का अनुसरण करता है: क्लाइंट Discover ब्रॉडकास्ट करता है, सर्वर Offer भेजते हैं, क्लाइंट एक ऑफ़र के लिए Request करता है, और सर्वर उसे Acknowledge करता है।"},
  {"id":"comp-ms-office-internet-360","question":"Which sequence of segments opens a TCP connection (the three-way handshake)?","options":["SYN, ACK, SYN-ACK","ACK, SYN-ACK, SYN","SYN, SYN-ACK, FIN","SYN, SYN-ACK, ACK"],"answer":3,"explanation":"The client sends SYN, the server replies SYN-ACK, and the client confirms with ACK. FIN is used to close a connection, not open it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"खंडों (segments) का कौन-सा क्रम TCP कनेक्शन खोलता है (थ्री-वे हैंडशेक)?","optionsHi":["SYN, ACK, SYN-ACK","ACK, SYN-ACK, SYN","SYN, SYN-ACK, FIN","SYN, SYN-ACK, ACK"],"explanationHi":"क्लाइंट SYN भेजता है, सर्वर SYN-ACK से उत्तर देता है, और क्लाइंट ACK से पुष्टि करता है। FIN कनेक्शन बंद करने के लिए है, खोलने के लिए नहीं।"},
  {"id":"comp-ms-office-internet-361","question":"Which pair of applications usually relies on UDP rather than TCP?","options":["File transfer by FTP and remote login by SSH","Live video calls and DNS lookups","Sending mail by SMTP and reading it by IMAP","Web pages over HTTP/1.1 and file transfer by FTP"],"answer":1,"explanation":"UDP is connectionless and fast, suiting real-time voice or video and short DNS queries, where an occasional lost packet is better than a delay. FTP, SSH, SMTP, IMAP and HTTP/1.1 use TCP.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"अनुप्रयोगों का कौन-सा युग्म सामान्यतः TCP के बजाय UDP पर निर्भर करता है?","optionsHi":["FTP से फ़ाइल स्थानांतरण और SSH से रिमोट लॉगिन","लाइव वीडियो कॉल और DNS लुकअप","SMTP से मेल भेजना और IMAP से पढ़ना","HTTP/1.1 पर वेब पेज और FTP से फ़ाइल स्थानांतरण"],"explanationHi":"UDP कनेक्शन-रहित और तेज़ है, जो रीयल-टाइम आवाज़ या वीडियो और छोटे DNS प्रश्नों के लिए उपयुक्त है, जहाँ कभी-कभार पैकेट खो जाना देरी से बेहतर है। FTP, SSH, SMTP, IMAP और HTTP/1.1 TCP का उपयोग करते हैं।"},
  {"id":"comp-ms-office-internet-362","question":"Match the networking device with the OSI layer it mainly works at: 1. Hub 2. Switch 3. Router; a. Network layer b. Physical layer c. Data link layer","options":["1-c, 2-b, 3-a","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-a, 2-c, 3-b"],"answer":2,"explanation":"A hub just repeats electrical signals (Physical), a switch forwards frames by MAC address (Data link), and a router forwards packets by IP address (Network).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"नेटवर्किंग उपकरण को उस OSI लेयर से सुमेलित कीजिए जिस पर वह मुख्यतः काम करता है: 1. Hub 2. Switch 3. Router; a. नेटवर्क लेयर b. फ़िज़िकल लेयर c. डेटा लिंक लेयर","optionsHi":["1-c, 2-b, 3-a","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-a, 2-c, 3-b"],"explanationHi":"हब केवल विद्युत संकेतों को दोहराता है (फ़िज़िकल), स्विच MAC पते से फ़्रेम आगे भेजता है (डेटा लिंक), और राउटर IP पते से पैकेट आगे भेजता है (नेटवर्क)।"},
  {"id":"comp-ms-office-internet-363","question":"Which layer of the OSI model handles data translation, encryption and compression, so that both systems can understand the data format?","options":["Session layer","Application layer","Transport layer","Presentation layer"],"answer":3,"explanation":"The Presentation layer (layer 6) deals with format conversion, encryption and compression. The Session layer manages dialogues, and the Transport layer handles end-to-end delivery.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"OSI मॉडल की कौन-सी लेयर डेटा अनुवाद, एन्क्रिप्शन और संपीड़न संभालती है, ताकि दोनों सिस्टम डेटा का प्रारूप समझ सकें?","optionsHi":["सेशन लेयर","एप्लिकेशन लेयर","ट्रांसपोर्ट लेयर","प्रेज़ेंटेशन लेयर"],"explanationHi":"प्रेज़ेंटेशन लेयर (लेयर 6) प्रारूप रूपांतरण, एन्क्रिप्शन और संपीड़न संभालती है। सेशन लेयर संवाद प्रबंधित करती है, और ट्रांसपोर्ट लेयर अंत-से-अंत वितरण संभालती है।"},
  {"id":"comp-ms-office-internet-364","question":"The ping command checks whether a host is reachable by sending echo request messages of which protocol?","options":["ICMP","ARP","SNMP","SMTP"],"answer":0,"explanation":"Ping sends ICMP Echo Request messages and waits for Echo Replies. ARP finds MAC addresses, SNMP manages network devices and SMTP sends e-mail.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"ping कमांड किस प्रोटोकॉल के echo request संदेश भेजकर जाँचती है कि कोई होस्ट पहुँच योग्य है या नहीं?","optionsHi":["ICMP","ARP","SNMP","SMTP"],"explanationHi":"Ping ICMP Echo Request संदेश भेजता है और Echo Reply की प्रतीक्षा करता है। ARP MAC पते खोजता है, SNMP नेटवर्क उपकरण प्रबंधित करता है और SMTP ई-मेल भेजता है।"},
  {"id":"comp-ms-office-internet-365","question":"On a Windows computer, which command shows each router (hop) that packets pass through on their way to a website?","options":["ipconfig","nslookup","tracert","netstat"],"answer":2,"explanation":"tracert (traceroute) lists every hop with its delay. ipconfig shows the PC's own IP settings, nslookup queries DNS, and netstat lists current connections.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"Windows कंप्यूटर पर कौन-सा कमांड किसी वेबसाइट तक जाते समय पैकेटों द्वारा पार किए जाने वाले हर राउटर (हॉप) को दिखाता है?","optionsHi":["ipconfig","nslookup","tracert","netstat"],"explanationHi":"tracert (traceroute) हर हॉप को उसके विलंब के साथ सूचीबद्ध करता है। ipconfig PC की अपनी IP सेटिंग दिखाता है, nslookup DNS से पूछताछ करता है, और netstat वर्तमान कनेक्शन सूचीबद्ध करता है।"},
  {"id":"comp-ms-office-internet-366","question":"Match the DNS record type with what it holds: 1. A 2. AAAA 3. MX 4. CNAME; a. an alias that points to another domain name b. the mail server for the domain c. an IPv6 address d. an IPv4 address","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"An A record maps a name to an IPv4 address and AAAA to an IPv6 address; MX names the mail server; CNAME makes one name an alias of another.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"DNS रिकॉर्ड प्रकार को उसमें रखी जानकारी से सुमेलित कीजिए: 1. A 2. AAAA 3. MX 4. CNAME; a. उपनाम (alias) जो किसी अन्य डोमेन नाम की ओर इंगित करता है b. डोमेन का मेल सर्वर c. IPv6 पता d. IPv4 पता","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a"],"explanationHi":"A रिकॉर्ड नाम को IPv4 पते से और AAAA IPv6 पते से जोड़ता है; MX मेल सर्वर का नाम देता है; CNAME एक नाम को दूसरे का उपनाम बनाता है।"},
  {"id":"comp-ms-office-internet-367","question":"Match the service with its default port number: 1. DNS 2. DHCP server 3. SNMP 4. NTP; a. 123 b. 161 c. 53 d. 67","options":["1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"DNS uses port 53, a DHCP server listens on 67 (the client uses 68), SNMP uses 161 and NTP (time synchronisation) uses 123.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"सेवा को उसके डिफ़ॉल्ट पोर्ट नंबर से सुमेलित कीजिए: 1. DNS 2. DHCP सर्वर 3. SNMP 4. NTP; a. 123 b. 161 c. 53 d. 67","optionsHi":["1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"explanationHi":"DNS पोर्ट 53 का उपयोग करता है, DHCP सर्वर 67 पर सुनता है (क्लाइंट 68 का उपयोग करता है), SNMP 161 का और NTP (समय सिंक्रोनाइज़ेशन) 123 का उपयोग करता है।"},
  {"id":"comp-ms-office-internet-368","question":"Classic FTP opens two TCP connections. Which default ports does it use for them (in active mode)?","options":["20 for control, 21 for data","22 for control, 21 for data","25 for control, 20 for data","21 for control, 20 for data"],"answer":3,"explanation":"FTP sends commands over the control connection on port 21 and, in active mode, transfers files over a data connection from port 20. Port 22 is SSH and 25 is SMTP.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"क्लासिक FTP दो TCP कनेक्शन खोलता है। (सक्रिय मोड में) वह उनके लिए कौन-से डिफ़ॉल्ट पोर्ट उपयोग करता है?","optionsHi":["नियंत्रण के लिए 20, डेटा के लिए 21","नियंत्रण के लिए 22, डेटा के लिए 21","नियंत्रण के लिए 25, डेटा के लिए 20","नियंत्रण के लिए 21, डेटा के लिए 20"],"explanationHi":"FTP आदेश नियंत्रण कनेक्शन पर पोर्ट 21 से भेजता है और, सक्रिय मोड में, फ़ाइलें पोर्ट 20 से डेटा कनेक्शन पर स्थानांतरित करता है। पोर्ट 22 SSH है और 25 SMTP है।"},
  {"id":"comp-ms-office-internet-369","question":"Assertion (A): A net-banking site uses a session cookie to keep a customer logged in while moving from page to page. Reason (R): HTTP is a stateless protocol, so the server treats each request on its own unless something identifies the user.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because HTTP keeps no memory between requests, sites send a session ID in a cookie with every request to recognise the logged-in user. So R explains A.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"अभिकथन (A): कोई नेट-बैंकिंग साइट पेज-दर-पेज जाते समय ग्राहक को लॉग इन रखने के लिए सेशन कुकी का उपयोग करती है। कारण (R): HTTP एक स्टेटलेस प्रोटोकॉल है, इसलिए जब तक कुछ उपयोगकर्ता की पहचान न कराए, सर्वर हर अनुरोध को अलग मानता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"क्योंकि HTTP अनुरोधों के बीच कोई स्मृति नहीं रखता, साइटें लॉग-इन उपयोगकर्ता को पहचानने के लिए हर अनुरोध के साथ कुकी में सेशन ID भेजती हैं। इसलिए R, A की व्याख्या करता है।"},
  {"id":"comp-ms-office-internet-370","question":"A website's login form is sent using the HTTP GET method instead of POST. What is the main risk?","options":["GET requests can never be encrypted, even when the site uses HTTPS","GET can send only numbers, so the password must be numeric","The username and password become part of the URL, history and server logs","GET opens a separate TCP port for every field of the form"],"answer":2,"explanation":"GET adds form data to the URL as a query string, which is saved in browser history, bookmarks and logs. POST sends it in the request body; HTTPS encrypts both on the wire.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी वेबसाइट का लॉगिन फ़ॉर्म POST के बजाय HTTP GET विधि से भेजा जाता है। मुख्य जोखिम क्या है?","optionsHi":["GET अनुरोध कभी एन्क्रिप्ट नहीं हो सकते, भले ही साइट HTTPS का उपयोग करे","GET केवल संख्याएँ भेज सकता है, इसलिए पासवर्ड संख्यात्मक होना चाहिए","यूज़रनेम और पासवर्ड URL, इतिहास और सर्वर लॉग का हिस्सा बन जाते हैं","GET फ़ॉर्म के हर फ़ील्ड के लिए अलग TCP पोर्ट खोलता है"],"explanationHi":"GET फ़ॉर्म डेटा को क्वेरी स्ट्रिंग के रूप में URL में जोड़ता है, जो ब्राउज़र इतिहास, बुकमार्क और लॉग में सहेजा जाता है। POST उसे अनुरोध के मुख्य भाग में भेजता है; HTTPS तार पर दोनों को एन्क्रिप्ट करता है।"},
  {"id":"comp-ms-office-internet-371","question":"Eight branch routers are joined in a full mesh, each connected directly to every other. How many links are needed, and how many ports does each router use for them?","options":["56 links; 7 ports on each router","28 links; 7 ports on each router","28 links; 8 ports on each router","64 links; 8 ports on each router"],"answer":1,"explanation":"A full mesh of n devices needs n(n - 1)/2 = 8 × 7 / 2 = 28 links, and each device connects to the other n - 1 = 7. Counting 56 counts every link twice.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"आठ शाखा राउटर पूर्ण मेश (full mesh) में जुड़े हैं, हर एक सीधे अन्य हर एक से जुड़ा है। कितने लिंक चाहिए, और उनके लिए प्रत्येक राउटर कितने पोर्ट उपयोग करता है?","optionsHi":["56 लिंक; प्रत्येक राउटर पर 7 पोर्ट","28 लिंक; प्रत्येक राउटर पर 7 पोर्ट","28 लिंक; प्रत्येक राउटर पर 8 पोर्ट","64 लिंक; प्रत्येक राउटर पर 8 पोर्ट"],"explanationHi":"n उपकरणों के पूर्ण मेश के लिए n(n - 1)/2 = 8 × 7 / 2 = 28 लिंक चाहिए, और हर उपकरण अन्य n - 1 = 7 से जुड़ता है। 56 गिनना हर लिंक को दो बार गिनना है।"},
  {"id":"comp-ms-office-internet-372","question":"Which statement about a star topology LAN is correct?","options":["If any one cable breaks the whole LAN stops, but the central switch can fail safely","Data passes through every node in turn, so one failed node stops the whole ring","All nodes share one backbone cable, so a break in it splits the network in two","If the central switch fails the whole LAN stops, but one broken cable cuts off only one node"],"answer":3,"explanation":"In a star each node has its own cable to the central device, so a single cable affects one node, but the centre is a single point of failure. The other options describe ring and bus.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"स्टार टोपोलॉजी LAN के बारे में कौन-सा कथन सही है?","optionsHi":["यदि कोई एक केबल टूटे तो पूरा LAN रुक जाता है, पर केंद्रीय स्विच सुरक्षित रूप से विफल हो सकता है","डेटा बारी-बारी से हर नोड से गुज़रता है, इसलिए एक विफल नोड पूरी रिंग रोक देता है","सभी नोड एक बैकबोन केबल साझा करते हैं, इसलिए उसमें टूट नेटवर्क को दो भागों में बाँट देती है","यदि केंद्रीय स्विच विफल हो तो पूरा LAN रुक जाता है, पर एक टूटी केबल केवल एक नोड को अलग करती है"],"explanationHi":"स्टार में हर नोड की केंद्रीय उपकरण तक अपनी केबल होती है, इसलिए एक केबल एक नोड को प्रभावित करती है, पर केंद्र विफलता का एकल बिंदु है। अन्य विकल्प रिंग और बस का वर्णन करते हैं।"},
  {"id":"comp-ms-office-internet-373","question":"Match the communication with its transmission mode: 1. Walkie-talkie 2. Telephone call 3. FM radio broadcast; a. Simplex b. Half-duplex c. Full-duplex","options":["1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b","1-b, 2-a, 3-c"],"answer":0,"explanation":"A walkie-talkie works both ways but one at a time (half-duplex), a phone call both ways at once (full-duplex), and FM radio only one way (simplex).","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"संचार को उसके संप्रेषण मोड से सुमेलित कीजिए: 1. वॉकी-टॉकी 2. टेलीफ़ोन कॉल 3. FM रेडियो प्रसारण; a. सिम्प्लेक्स (Simplex) b. हाफ़-डुप्लेक्स (Half-duplex) c. फ़ुल-डुप्लेक्स (Full-duplex)","optionsHi":["1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b","1-b, 2-a, 3-c"],"explanationHi":"वॉकी-टॉकी दोनों दिशाओं में पर एक समय में एक ओर से काम करता है (हाफ़-डुप्लेक्स), फ़ोन कॉल दोनों दिशाओं में एक साथ (फ़ुल-डुप्लेक्स), और FM रेडियो केवल एक दिशा में (सिम्प्लेक्स)।"},
  {"id":"comp-ms-office-internet-374","question":"Match the technology with its IEEE standard: 1. Wired Ethernet 2. Wi-Fi 3. Bluetooth; a. 802.11 b. 802.3 c. 802.15","options":["1-a, 2-b, 3-c","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-a, 3-b"],"answer":1,"explanation":"Ethernet is IEEE 802.3, wireless LAN (Wi-Fi) is 802.11, and Bluetooth was standardised under the personal area network group 802.15.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"तकनीक को उसके IEEE मानक से सुमेलित कीजिए: 1. वायर्ड Ethernet 2. Wi-Fi 3. Bluetooth; a. 802.11 b. 802.3 c. 802.15","optionsHi":["1-a, 2-b, 3-c","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-a, 3-b"],"explanationHi":"Ethernet IEEE 802.3 है, वायरलेस LAN (Wi-Fi) 802.11 है, और Bluetooth को व्यक्तिगत क्षेत्र नेटवर्क समूह 802.15 के अंतर्गत मानकीकृत किया गया।"},
  {"id":"comp-ms-office-internet-375","question":"Which statement about a MAC address is correct?","options":["It is 32 bits long and written as 4 decimal numbers","It is 48 bits long and written as 6 decimal numbers","It is 48 bits long and written as 12 hexadecimal digits","It is 128 bits long and written as 32 hexadecimal digits"],"answer":2,"explanation":"A MAC address is a 48-bit hardware address, written as six pairs of hex digits such as 00:1A:2B:3C:4D:5E. 32 bits in dotted decimal describes IPv4, and 128 bits IPv6.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MAC पते के बारे में कौन-सा कथन सही है?","optionsHi":["यह 32 बिट लंबा होता है और 4 दशमलव संख्याओं के रूप में लिखा जाता है","यह 48 बिट लंबा होता है और 6 दशमलव संख्याओं के रूप में लिखा जाता है","यह 48 बिट लंबा होता है और 12 हेक्साडेसिमल अंकों के रूप में लिखा जाता है","यह 128 बिट लंबा होता है और 32 हेक्साडेसिमल अंकों के रूप में लिखा जाता है"],"explanationHi":"MAC पता 48-बिट हार्डवेयर पता है, जो हेक्स अंकों के छह जोड़ों के रूप में लिखा जाता है, जैसे 00:1A:2B:3C:4D:5E। डॉटेड दशमलव में 32 बिट IPv4 का वर्णन है, और 128 बिट IPv6 का।"},
  {"id":"comp-ms-office-internet-376","question":"An officer travelling on a hotel's public Wi-Fi must open the bank's internal applications safely. Which technology builds an encrypted tunnel to the bank's network across the internet?","options":["NAT (Network Address Translation)","DHCP (Dynamic Host Configuration)","DNS (Domain Name System)","VPN (Virtual Private Network)"],"answer":3,"explanation":"A VPN encrypts all traffic between the device and the bank's VPN gateway, so others on the hotel Wi-Fi cannot read it. NAT, DHCP and DNS handle addressing and naming, not encryption.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी होटल के सार्वजनिक Wi-Fi पर यात्रा कर रहे अधिकारी को बैंक के आंतरिक अनुप्रयोगों को सुरक्षित रूप से खोलना है। कौन-सी तकनीक इंटरनेट के पार बैंक के नेटवर्क तक एन्क्रिप्टेड सुरंग बनाती है?","optionsHi":["NAT (Network Address Translation)","DHCP (Dynamic Host Configuration)","DNS (Domain Name System)","VPN (Virtual Private Network)"],"explanationHi":"VPN उपकरण और बैंक के VPN गेटवे के बीच सारा ट्रैफ़िक एन्क्रिप्ट करता है, इसलिए होटल Wi-Fi पर अन्य लोग उसे नहीं पढ़ सकते। NAT, DHCP और DNS पता-निर्धारण और नामकरण संभालते हैं, एन्क्रिप्शन नहीं।"},
  {"id":"comp-ms-office-internet-377","question":"Which network device only regenerates a weakened signal so that a cable can run further, without reading any address in the data?","options":["Bridge","Repeater","Switch","Router"],"answer":1,"explanation":"A repeater works at the Physical layer and just amplifies or regenerates signals. A bridge and a switch forward by MAC address, and a router by IP address.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"कौन-सा नेटवर्क उपकरण केवल कमज़ोर पड़े संकेत को पुनः उत्पन्न करता है ताकि केबल आगे तक चल सके, डेटा में कोई पता पढ़े बिना?","optionsHi":["ब्रिज (Bridge)","रिपीटर (Repeater)","स्विच (Switch)","राउटर (Router)"],"explanationHi":"रिपीटर फ़िज़िकल लेयर पर काम करता है और केवल संकेतों को प्रवर्धित या पुनः उत्पन्न करता है। ब्रिज और स्विच MAC पते से आगे भेजते हैं, और राउटर IP पते से।"},
  {"id":"comp-ms-office-internet-378","question":"Two office buildings are linked by cable that must pass next to heavy electrical machinery. Why is optical fibre the best choice?","options":["It carries light, so electrical interference does not affect it","It carries larger currents, so the signal is never weakened","It is cheaper and easier to join than copper twisted pair","It needs no repeaters or amplifiers over any distance at all"],"answer":0,"explanation":"Optical fibre sends data as light pulses through glass, so it is immune to electromagnetic interference. It is usually costlier to install and join, and long links still need amplification.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"दो कार्यालय भवन ऐसी केबल से जोड़े गए हैं जिसे भारी विद्युत मशीनरी के पास से गुज़रना है। ऑप्टिकल फ़ाइबर सबसे अच्छा विकल्प क्यों है?","optionsHi":["यह प्रकाश ले जाता है, इसलिए विद्युत व्यवधान उस पर असर नहीं डालता","यह बड़ी धाराएँ ले जाता है, इसलिए संकेत कभी कमज़ोर नहीं होता","यह कॉपर ट्विस्टेड पेयर से सस्ता और जोड़ने में आसान है","इसे किसी भी दूरी तक रिपीटर या एम्प्लीफ़ायर की ज़रूरत नहीं पड़ती"],"explanationHi":"ऑप्टिकल फ़ाइबर डेटा को काँच में प्रकाश स्पंदों के रूप में भेजता है, इसलिए वह विद्युत-चुंबकीय व्यवधान से अप्रभावित रहता है। इसे लगाना और जोड़ना सामान्यतः महँगा है, और लंबे लिंकों को फिर भी प्रवर्धन चाहिए।"},
  {"id":"comp-ms-office-internet-379","question":"When a browser opens an HTTPS banking site, how are symmetric and asymmetric encryption used?","options":["Symmetric encryption sets up the keys, then asymmetric encryption protects all the data","Only asymmetric encryption is used, because it is faster than symmetric for bulk data","Asymmetric keys set up a shared session key, then symmetric encryption protects the data","Only symmetric encryption is used, with a key printed on the site's certificate"],"answer":2,"explanation":"Public-key (asymmetric) methods are slow, so TLS uses them only to authenticate the server and agree a session key; the bulk data is then encrypted with a fast symmetric cipher such as AES.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जब ब्राउज़र HTTPS बैंकिंग साइट खोलता है, तब सममित और असममित एन्क्रिप्शन का उपयोग कैसे होता है?","optionsHi":["सममित एन्क्रिप्शन कुंजियाँ स्थापित करता है, फिर असममित एन्क्रिप्शन सारे डेटा को सुरक्षित करता है","केवल असममित एन्क्रिप्शन उपयोग होता है, क्योंकि वह बड़े डेटा के लिए सममित से तेज़ है","असममित कुंजियाँ साझा सेशन कुंजी स्थापित करती हैं, फिर सममित एन्क्रिप्शन डेटा को सुरक्षित करता है","केवल सममित एन्क्रिप्शन उपयोग होता है, जिसकी कुंजी साइट के प्रमाणपत्र पर छपी होती है"],"explanationHi":"सार्वजनिक-कुंजी (असममित) विधियाँ धीमी हैं, इसलिए TLS उनका उपयोग केवल सर्वर को प्रमाणित करने और सेशन कुंजी तय करने के लिए करता है; बड़ा डेटा फिर AES जैसे तेज़ सममित सिफ़र से एन्क्रिप्ट किया जाता है।"},
  {"id":"comp-ms-office-internet-380","question":"A well-run website stores a hash of each password, not the password itself. Why does this protect users if the database is stolen?","options":["A hash is encrypted with the user's own key, which the thief cannot get","A hash is one-way, so the password cannot simply be decrypted from it","A hash changes every day, so a stolen copy expires within a few hours","A hash is stored on a separate server that attackers cannot reach"],"answer":1,"explanation":"A cryptographic hash cannot be reversed; at login the site hashes the typed password and compares the results. Attackers can only guess passwords and hash each guess.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक अच्छी तरह चलने वाली वेबसाइट प्रत्येक पासवर्ड का हैश संग्रहीत करती है, पासवर्ड स्वयं नहीं। यदि डेटाबेस चोरी हो जाए तो यह उपयोगकर्ताओं की रक्षा क्यों करता है?","optionsHi":["हैश उपयोगकर्ता की अपनी कुंजी से एन्क्रिप्ट होता है, जो चोर नहीं पा सकता","हैश एकतरफ़ा होता है, इसलिए उससे पासवर्ड को सीधे डिक्रिप्ट नहीं किया जा सकता","हैश हर दिन बदलता है, इसलिए चोरी की प्रति कुछ घंटों में समाप्त हो जाती है","हैश अलग सर्वर पर संग्रहीत होता है जहाँ हमलावर नहीं पहुँच सकते"],"explanationHi":"क्रिप्टोग्राफ़िक हैश को उलटा नहीं किया जा सकता; लॉगिन पर साइट टाइप किए पासवर्ड का हैश बनाकर परिणामों की तुलना करती है। हमलावर केवल पासवर्ड का अनुमान लगाकर हर अनुमान का हैश बना सकते हैं।"},
  {"id":"comp-ms-office-internet-381","question":"Before hashing each password, a website adds a random value (a salt) that is different for every user. Which attack does this mainly defeat?","options":["Using precomputed rainbow tables of hashes","Phishing e-mails that ask for the password","Keyloggers that record the typed password","Shoulder surfing while the password is typed"],"answer":0,"explanation":"A unique salt makes the same password hash differently for each user, so a precomputed table of hashes is useless. Salting cannot stop a password being captured before it is hashed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"प्रत्येक पासवर्ड को हैश करने से पहले, कोई वेबसाइट एक यादृच्छिक मान (salt) जोड़ती है जो हर उपयोगकर्ता के लिए अलग होता है। यह मुख्यतः किस हमले को विफल करता है?","optionsHi":["हैश की पूर्व-परिकलित रेनबो तालिकाओं का उपयोग","पासवर्ड माँगने वाले फ़िशिंग ई-मेल","टाइप किया गया पासवर्ड रिकॉर्ड करने वाले कीलॉगर","पासवर्ड टाइप करते समय शोल्डर सर्फ़िंग"],"explanationHi":"अनूठा salt एक ही पासवर्ड को हर उपयोगकर्ता के लिए अलग तरह से हैश कराता है, इसलिए हैश की पूर्व-परिकलित तालिका बेकार हो जाती है। हैश करने से पहले पासवर्ड के पकड़े जाने को salting नहीं रोक सकती।"},
  {"id":"comp-ms-office-internet-382","question":"An attacker tries passwords such as password123, india@2020 and qwerty taken from a list of common words, rather than every possible combination. What is this called, and what stops it on a login page?","options":["A brute-force attack, stopped by turning off cookies in the browser","A credential-stuffing attack, stopped by a shorter session timeout","A rainbow-table attack, stopped by salting the stored hashes","A dictionary attack, stopped by a lockout after a few failures"],"answer":3,"explanation":"A dictionary attack tries likely words and leaked passwords; brute force tries every combination. Lockouts or delays after failed logins limit both kinds of online guessing.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कोई हमलावर हर संभव संयोजन के बजाय सामान्य शब्दों की सूची से password123, india@2020 और qwerty जैसे पासवर्ड आज़माता है। इसे क्या कहते हैं, और लॉगिन पेज पर इसे क्या रोकता है?","optionsHi":["ब्रूट-फ़ोर्स हमला, जिसे ब्राउज़र में कुकी बंद करके रोका जाता है","क्रेडेंशियल-स्टफ़िंग हमला, जिसे छोटे सेशन टाइमआउट से रोका जाता है","रेनबो-टेबल हमला, जिसे संग्रहीत हैश में salt जोड़कर रोका जाता है","डिक्शनरी हमला, जिसे कुछ विफलताओं के बाद लॉकआउट से रोका जाता है"],"explanationHi":"डिक्शनरी हमला संभावित शब्द और लीक हुए पासवर्ड आज़माता है; ब्रूट फ़ोर्स हर संयोजन आज़माता है। विफल लॉगिन के बाद लॉकआउट या विलंब दोनों प्रकार के ऑनलाइन अनुमान को सीमित करते हैं।"},
  {"id":"comp-ms-office-internet-383","question":"On a café's free Wi-Fi, an attacker places himself between users and the router, quietly reading and changing the traffic passing through. What is this attack called?","options":["Man-in-the-middle attack","Denial-of-service attack","Brute-force attack","Logic bomb attack"],"answer":0,"explanation":"In a man-in-the-middle attack the attacker relays and can alter traffic between two parties. HTTPS with valid certificates (and not ignoring certificate warnings) defends against it.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"किसी कैफ़े के मुफ़्त Wi-Fi पर, कोई हमलावर स्वयं को उपयोगकर्ताओं और राउटर के बीच रख लेता है और बीच से गुज़रते ट्रैफ़िक को चुपचाप पढ़ता और बदलता है। इस हमले को क्या कहते हैं?","optionsHi":["मैन-इन-द-मिडिल हमला (Man-in-the-middle attack)","सेवा-अवरोध हमला (Denial-of-service attack)","ब्रूट-फ़ोर्स हमला","लॉजिक बम हमला"],"explanationHi":"मैन-इन-द-मिडिल हमले में हमलावर दो पक्षों के बीच ट्रैफ़िक को आगे भेजता है और बदल भी सकता है। वैध प्रमाणपत्रों वाला HTTPS (और प्रमाणपत्र की चेतावनियों को अनदेखा न करना) इससे बचाता है।"},
  {"id":"comp-ms-office-internet-384","question":"An outsider without an ID card walks into a bank's server room by following closely behind an employee who opened the door with his own card. This is called:","options":["Shoulder surfing","Tailgating","Dumpster diving","Pharming"],"answer":1,"explanation":"Tailgating (piggybacking) is physical entry by following an authorised person. Shoulder surfing is watching someone type, and dumpster diving is searching thrown-away papers.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"पहचान पत्र के बिना कोई बाहरी व्यक्ति किसी कर्मचारी के ठीक पीछे चलकर बैंक के सर्वर रूम में घुस जाता है, जिसने अपने कार्ड से दरवाज़ा खोला था। इसे क्या कहते हैं?","optionsHi":["शोल्डर सर्फ़िंग (Shoulder surfing)","टेलगेटिंग (Tailgating)","डंपस्टर डाइविंग (Dumpster diving)","फ़ार्मिंग (Pharming)"],"explanationHi":"टेलगेटिंग (पिगीबैकिंग) अधिकृत व्यक्ति के पीछे चलकर भौतिक प्रवेश है। शोल्डर सर्फ़िंग किसी को टाइप करते देखना है, और डंपस्टर डाइविंग फेंके गए कागज़ों में खोजना है।"},
  {"id":"comp-ms-office-internet-385","question":"USB drives labelled Salary Revision 2024 are left in a bank's car park. An employee plugs one in out of curiosity, and malware installs itself. Which social engineering trick is this?","options":["Pretexting","Tailgating","Baiting","Vishing"],"answer":2,"explanation":"Baiting uses a tempting item, such as a free download or a found USB drive, to make the victim run malware. Pretexting relies on a made-up story told to the victim.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"बैंक की कार पार्किंग में Salary Revision 2024 लिखे USB ड्राइव छोड़ दिए जाते हैं। एक कर्मचारी जिज्ञासावश एक को लगा देता है, और मैलवेयर अपने आप इंस्टॉल हो जाता है। यह कौन-सी सोशल इंजीनियरिंग चाल है?","optionsHi":["प्रीटेक्स्टिंग (Pretexting)","टेलगेटिंग (Tailgating)","बेटिंग (Baiting)","विशिंग (Vishing)"],"explanationHi":"बेटिंग किसी लुभावनी वस्तु, जैसे मुफ़्त डाउनलोड या मिला हुआ USB ड्राइव, का उपयोग करके पीड़ित से मैलवेयर चलवाती है। प्रीटेक्स्टिंग पीड़ित को सुनाई गई गढ़ी हुई कहानी पर निर्भर करती है।"},
  {"id":"comp-ms-office-internet-386","question":"A caller says he is from the bank's internal audit team doing a surprise check, gives the branch manager's name correctly, and asks a clerk to read out a customer's account details 'for verification'. Which technique is mainly used?","options":["Baiting","Tailgating","Typosquatting","Pretexting"],"answer":3,"explanation":"Pretexting builds a believable invented scenario (here an audit) with insider details to get information. Baiting offers a lure, and typosquatting uses look-alike web addresses.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक फ़ोन करने वाला कहता है कि वह बैंक की आंतरिक लेखा-परीक्षा टीम से है और औचक जाँच कर रहा है, शाखा प्रबंधक का नाम सही बताता है, और एक क्लर्क से 'सत्यापन के लिए' किसी ग्राहक का खाता विवरण पढ़कर सुनाने को कहता है। मुख्यतः कौन-सी तकनीक उपयोग हो रही है?","optionsHi":["बेटिंग (Baiting)","टेलगेटिंग (Tailgating)","टाइपोस्क्वैटिंग (Typosquatting)","प्रीटेक्स्टिंग (Pretexting)"],"explanationHi":"प्रीटेक्स्टिंग जानकारी पाने के लिए अंदरूनी विवरणों के साथ विश्वसनीय गढ़ा हुआ परिदृश्य (यहाँ लेखा-परीक्षा) बनाती है। बेटिंग लालच देती है, और टाइपोस्क्वैटिंग मिलते-जुलते वेब पतों का उपयोग करती है।"},
  {"id":"comp-ms-office-internet-387","question":"Attackers who want to break into a group of banks infect a banking-industry news website that the banks' staff visit often, and wait for staff to get infected from it. This is called:","options":["A watering hole attack","A whaling attack on executives","A salami attack on accounts","A smurf attack on routers"],"answer":0,"explanation":"A watering hole attack compromises a site that the target group trusts and visits. Whaling targets senior executives by e-mail, and a salami attack skims tiny amounts.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"बैंकों के एक समूह में घुसपैठ करना चाहने वाले हमलावर बैंकिंग उद्योग की एक समाचार वेबसाइट को संक्रमित कर देते हैं, जिस पर बैंकों के कर्मचारी अक्सर जाते हैं, और कर्मचारियों के उससे संक्रमित होने की प्रतीक्षा करते हैं। इसे क्या कहते हैं?","optionsHi":["वॉटरिंग होल हमला (Watering hole attack)","अधिकारियों पर व्हेलिंग हमला","खातों पर सलामी हमला","राउटरों पर स्मर्फ़ हमला"],"explanationHi":"वॉटरिंग होल हमला ऐसी साइट से छेड़छाड़ करता है जिस पर लक्षित समूह भरोसा करता है और जाता है। व्हेलिंग ई-मेल द्वारा वरिष्ठ अधिकारियों को निशाना बनाती है, और सलामी हमला छोटी रकमें चुराता है।"},
  {"id":"comp-ms-office-internet-388","question":"A fraudster registers the web address examp1ebank.com (with the digit 1 in place of the letter l) to catch customers who mistype or misread the real address. This is called:","options":["Pharming","Typosquatting","Spoofing the MAC address","Cryptojacking"],"answer":1,"explanation":"Typosquatting registers look-alike or misspelt domain names. Pharming instead corrupts DNS so that even the correctly typed real address leads to a fake site.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"कोई धोखेबाज़ वेब पता examp1ebank.com (अक्षर l की जगह अंक 1 के साथ) पंजीकृत कराता है ताकि असली पते को गलत टाइप करने या गलत पढ़ने वाले ग्राहकों को पकड़ सके। इसे क्या कहते हैं?","optionsHi":["फ़ार्मिंग (Pharming)","टाइपोस्क्वैटिंग (Typosquatting)","MAC पते की स्पूफ़िंग","क्रिप्टोजैकिंग (Cryptojacking)"],"explanationHi":"टाइपोस्क्वैटिंग मिलते-जुलते या गलत वर्तनी वाले डोमेन नाम पंजीकृत कराती है। फ़ार्मिंग इसके बजाय DNS में छेड़छाड़ करती है ताकि सही टाइप किया गया असली पता भी नकली साइट पर ले जाए।"},
  {"id":"comp-ms-office-internet-389","question":"An attacker steals the session cookie of a customer who is logged in to net banking and uses it to act as that customer without knowing the password. This is called:","options":["Credential stuffing","Password spraying","DNS spoofing","Session hijacking"],"answer":3,"explanation":"Session hijacking reuses a valid session token to take over a logged-in session. Credential stuffing and password spraying both try passwords to log in.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कोई हमलावर नेट बैंकिंग में लॉग इन किसी ग्राहक की सेशन कुकी चुरा लेता है और पासवर्ड जाने बिना उसी ग्राहक की तरह कार्य करने में उसका उपयोग करता है। इसे क्या कहते हैं?","optionsHi":["क्रेडेंशियल स्टफ़िंग (Credential stuffing)","पासवर्ड स्प्रेइंग (Password spraying)","DNS स्पूफ़िंग (DNS spoofing)","सेशन हाइजैकिंग (Session hijacking)"],"explanationHi":"सेशन हाइजैकिंग वैध सेशन टोकन को दोबारा उपयोग करके लॉग-इन सेशन पर कब्ज़ा कर लेती है। क्रेडेंशियल स्टफ़िंग और पासवर्ड स्प्रेइंग दोनों लॉग इन करने के लिए पासवर्ड आज़माते हैं।"},
  {"id":"comp-ms-office-internet-390","question":"A Word file received by e-mail asks the user to click Enable Content. Once clicked, code inside the file downloads malware. What kind of virus is this?","options":["Boot sector virus","Polymorphic worm","Macro virus","Firmware rootkit"],"answer":2,"explanation":"A macro virus is written in the macro language of a document (such as VBA) and runs when macros are enabled. This is why Office blocks macros in files from the internet by default.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"ई-मेल से मिली एक Word फ़ाइल उपयोगकर्ता से Enable Content क्लिक करने को कहती है। क्लिक करते ही फ़ाइल के भीतर का कोड मैलवेयर डाउनलोड कर लेता है। यह किस प्रकार का वायरस है?","optionsHi":["बूट सेक्टर वायरस","पॉलीमॉर्फ़िक वर्म","मैक्रो वायरस","फ़र्मवेयर रूटकिट"],"explanationHi":"मैक्रो वायरस दस्तावेज़ की मैक्रो भाषा (जैसे VBA) में लिखा जाता है और मैक्रो सक्षम होने पर चलता है। इसीलिए Office इंटरनेट की फ़ाइलों में मैक्रो डिफ़ॉल्ट रूप से अवरुद्ध करता है।"},
  {"id":"comp-ms-office-internet-391","question":"Which kind of virus changes its own code every time it infects a new file, so that each copy looks different to signature-based antivirus?","options":["Boot sector virus","Macro virus","Resident virus","Polymorphic virus"],"answer":3,"explanation":"A polymorphic virus mutates (often by re-encrypting itself with a new key) on each infection, so no single signature matches all copies. Behaviour-based detection is needed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किस प्रकार का वायरस हर नई फ़ाइल को संक्रमित करते समय अपना कोड बदल लेता है, ताकि हस्ताक्षर-आधारित एंटीवायरस को हर प्रति अलग दिखे?","optionsHi":["बूट सेक्टर वायरस","मैक्रो वायरस","रेज़िडेंट वायरस","पॉलीमॉर्फ़िक वायरस (Polymorphic virus)"],"explanationHi":"पॉलीमॉर्फ़िक वायरस हर संक्रमण पर बदलता है (अक्सर नई कुंजी से स्वयं को पुनः एन्क्रिप्ट करके), इसलिए कोई एक हस्ताक्षर सभी प्रतियों से मेल नहीं खाता। व्यवहार-आधारित पहचान आवश्यक है।"},
  {"id":"comp-ms-office-internet-392","question":"A virus infects both the boot sector of the disk and executable program files, so it returns unless both are cleaned. It is called a:","options":["Polymorphic virus","Macro virus","Multipartite virus","Companion virus"],"answer":2,"explanation":"A multipartite virus spreads in more than one way, typically through the boot sector and through program files, which makes it hard to remove fully.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"कोई वायरस डिस्क के बूट सेक्टर और निष्पादन योग्य प्रोग्राम फ़ाइलों दोनों को संक्रमित करता है, इसलिए जब तक दोनों साफ़ न हों वह लौट आता है। इसे क्या कहते हैं?","optionsHi":["पॉलीमॉर्फ़िक वायरस","मैक्रो वायरस","मल्टीपार्टाइट वायरस (Multipartite virus)","कंपैनियन वायरस"],"explanationHi":"मल्टीपार्टाइट वायरस एक से अधिक तरीकों से फैलता है, सामान्यतः बूट सेक्टर और प्रोग्राम फ़ाइलों के ज़रिए, जिससे उसे पूरी तरह हटाना कठिन होता है।"},
  {"id":"comp-ms-office-internet-393","question":"While browsing, a flashing pop-up claims 'Your PC has 37 viruses! Buy this cleaner now', though nothing is wrong. Buying it installs malware. This is:","options":["Spyware","Scareware","Ransomware","Adware"],"answer":1,"explanation":"Scareware frightens users with fake alerts into buying or installing harmful software. Ransomware locks real files, spyware secretly watches, and adware just pushes ads.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"ब्राउज़िंग के दौरान एक टिमटिमाता पॉप-अप दावा करता है 'Your PC has 37 viruses! Buy this cleaner now', जबकि कुछ गड़बड़ नहीं है। उसे खरीदने पर मैलवेयर इंस्टॉल हो जाता है। यह है:","optionsHi":["स्पाईवेयर (Spyware)","स्केयरवेयर (Scareware)","रैनसमवेयर (Ransomware)","एडवेयर (Adware)"],"explanationHi":"स्केयरवेयर नकली चेतावनियों से उपयोगकर्ताओं को डराकर हानिकारक सॉफ़्टवेयर खरीदवाता या इंस्टॉल करवाता है। रैनसमवेयर असली फ़ाइलें लॉक करता है, स्पाईवेयर चुपके से नज़र रखता है, और एडवेयर केवल विज्ञापन थोपता है।"},
  {"id":"comp-ms-office-internet-394","question":"Arrange these malware outbreaks in chronological order: 1. WannaCry ransomware 2. Morris worm 3. ILOVEYOU e-mail worm 4. Brain virus (the first IBM PC virus)","options":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","2, 3, 4, 1"],"answer":0,"explanation":"Brain appeared in 1986, the Morris worm in 1988, ILOVEYOU in 2000 and WannaCry in 2017.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"इन मैलवेयर प्रकोपों को कालक्रमानुसार व्यवस्थित कीजिए: 1. WannaCry रैनसमवेयर 2. Morris वर्म 3. ILOVEYOU ई-मेल वर्म 4. Brain वायरस (पहला IBM PC वायरस)","optionsHi":["4, 2, 3, 1","2, 4, 3, 1","4, 3, 2, 1","2, 3, 4, 1"],"explanationHi":"Brain 1986 में आया, Morris वर्म 1988 में, ILOVEYOU 2000 में और WannaCry 2017 में।"},
  {"id":"comp-ms-office-internet-395","question":"How does a stateful inspection firewall differ from a simple packet-filtering firewall?","options":["It checks only the source and destination addresses in each packet header","It tracks open connections and allows only replies that belong to them","It scans the text of every e-mail for spelling and grammar","It encrypts all packets that leave the network by default"],"answer":1,"explanation":"A packet filter judges each packet alone by header rules. A stateful firewall keeps a table of active connections, so incoming packets are allowed only as part of an established session.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"स्टेटफ़ुल इंस्पेक्शन फ़ायरवॉल साधारण पैकेट-फ़िल्टरिंग फ़ायरवॉल से कैसे भिन्न है?","optionsHi":["वह हर पैकेट हेडर में केवल स्रोत और गंतव्य पते जाँचता है","वह खुले कनेक्शनों पर नज़र रखता है और केवल उन्हीं से संबंधित उत्तरों की अनुमति देता है","वह वर्तनी और व्याकरण के लिए हर ई-मेल का पाठ स्कैन करता है","वह नेटवर्क से बाहर जाने वाले सभी पैकेट डिफ़ॉल्ट रूप से एन्क्रिप्ट करता है"],"explanationHi":"पैकेट फ़िल्टर हेडर नियमों से हर पैकेट को अकेले परखता है। स्टेटफ़ुल फ़ायरवॉल सक्रिय कनेक्शनों की तालिका रखता है, इसलिए आने वाले पैकेट केवल स्थापित सेशन के भाग के रूप में ही स्वीकार होते हैं।"},
  {"id":"comp-ms-office-internet-396","question":"What is the main difference between an IDS and an IPS on a bank's network?","options":["An IDS blocks attacks in real time; an IPS only writes them into a log file","An IDS works only on wireless networks; an IPS works only on wired ones","An IDS checks passwords at login; an IPS checks IP addresses at the router","An IDS detects and alerts on attacks; an IPS can also block them in real time"],"answer":3,"explanation":"An Intrusion Detection System monitors and raises alarms; an Intrusion Prevention System sits in the traffic path and can drop malicious packets automatically.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी बैंक के नेटवर्क पर IDS और IPS में मुख्य अंतर क्या है?","optionsHi":["IDS हमलों को वास्तविक समय में रोकता है; IPS उन्हें केवल लॉग फ़ाइल में लिखता है","IDS केवल वायरलेस नेटवर्क पर काम करता है; IPS केवल वायर्ड पर","IDS लॉगिन पर पासवर्ड जाँचता है; IPS राउटर पर IP पते जाँचता है","IDS हमलों का पता लगाकर चेतावनी देता है; IPS उन्हें वास्तविक समय में रोक भी सकता है"],"explanationHi":"Intrusion Detection System निगरानी करता है और अलार्म देता है; Intrusion Prevention System ट्रैफ़िक के मार्ग में बैठता है और दुर्भावनापूर्ण पैकेटों को अपने आप गिरा सकता है।"},
  {"id":"comp-ms-office-internet-397","question":"A bank keeps its public website server in a separate network zone between two firewalls, so that a hacked web server cannot reach the internal core banking network directly. This zone is called a:","options":["VLAN (virtual LAN)","Honeynet (decoy network)","DMZ (demilitarised zone)","Extranet (partner network)"],"answer":2,"explanation":"A DMZ holds internet-facing servers apart from the internal LAN, with firewall rules limiting what it can reach. A honeynet is a decoy built to study attackers.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कोई बैंक अपने सार्वजनिक वेबसाइट सर्वर को दो फ़ायरवॉलों के बीच एक अलग नेटवर्क ज़ोन में रखता है, ताकि हैक हुआ वेब सर्वर आंतरिक कोर बैंकिंग नेटवर्क तक सीधे न पहुँच सके। इस ज़ोन को क्या कहते हैं?","optionsHi":["VLAN (वर्चुअल LAN)","हनीनेट (नकली नेटवर्क)","DMZ (असैन्यीकृत क्षेत्र)","एक्स्ट्रानेट (भागीदार नेटवर्क)"],"explanationHi":"DMZ इंटरनेट की ओर के सर्वरों को आंतरिक LAN से अलग रखता है, फ़ायरवॉल नियमों से यह सीमित करते हुए कि वह किस तक पहुँच सकता है। हनीनेट हमलावरों का अध्ययन करने के लिए बनाया गया चारा है।"},
  {"id":"comp-ms-office-internet-398","question":"A cashier's login can post cash transactions but cannot change interest rates or create users. Which security principle does this follow?","options":["Least privilege","Defence in depth","Non-repudiation","Security through obscurity"],"answer":0,"explanation":"The principle of least privilege gives each user only the access the job needs, limiting harm from mistakes or a stolen login. Non-repudiation means a sender cannot deny an action.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी कैशियर का लॉगिन नकद लेन-देन दर्ज कर सकता है पर ब्याज दरें नहीं बदल सकता या उपयोगकर्ता नहीं बना सकता। यह किस सुरक्षा सिद्धांत का पालन करता है?","optionsHi":["न्यूनतम विशेषाधिकार (Least privilege)","गहराई में रक्षा (Defence in depth)","अनस्वीकार्यता (Non-repudiation)","अस्पष्टता द्वारा सुरक्षा (Security through obscurity)"],"explanationHi":"न्यूनतम विशेषाधिकार का सिद्धांत हर उपयोगकर्ता को केवल उतनी पहुँच देता है जितनी काम के लिए चाहिए, जिससे गलतियों या चोरी हुए लॉगिन से होने वाली हानि सीमित रहती है। अनस्वीकार्यता का अर्थ है कि प्रेषक किसी क्रिया से इनकार नहीं कर सकता।"},
  {"id":"comp-ms-office-internet-399","question":"A bank makes its fingerprint scanners stricter so that they match more closely. What usually happens to the False Acceptance Rate (FAR) and the False Rejection Rate (FRR)?","options":["FAR rises but FRR falls","Both FAR and FRR fall","FAR falls but FRR rises","Both FAR and FRR rise"],"answer":2,"explanation":"A stricter threshold lets fewer impostors in (lower FAR) but rejects more genuine users (higher FRR). The two trade off; the point where they are equal is the crossover error rate.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"कोई बैंक अपने फ़िंगरप्रिंट स्कैनरों को अधिक कठोर बनाता है ताकि वे अधिक निकटता से मिलान करें। False Acceptance Rate (FAR) और False Rejection Rate (FRR) का सामान्यतः क्या होता है?","optionsHi":["FAR बढ़ती है पर FRR घटती है","FAR और FRR दोनों घटती हैं","FAR घटती है पर FRR बढ़ती है","FAR और FRR दोनों बढ़ती हैं"],"explanationHi":"अधिक कठोर सीमा कम धोखेबाज़ों को भीतर आने देती है (कम FAR) पर अधिक असली उपयोगकर्ताओं को अस्वीकार करती है (अधिक FRR)। दोनों में समझौता होता है; जिस बिंदु पर दोनों बराबर हों वह क्रॉसओवर एरर रेट है।"},
  {"id":"comp-ms-office-internet-400","question":"A branch takes a full backup on Sunday and a DIFFERENTIAL backup each night from Monday to Thursday. Its server crashes on Friday morning. Which backups are needed to restore all the data?","options":["Sunday's full and all four differentials","Sunday's full and Thursday's differential","Only Thursday's differential backup","Only Sunday's full backup"],"answer":1,"explanation":"Each differential holds every change since the last FULL backup, so the latest one plus the full is enough. With incremental backups, every one since the full would be needed.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक शाखा रविवार को पूर्ण बैकअप और सोमवार से गुरुवार तक हर रात DIFFERENTIAL बैकअप लेती है। उसका सर्वर शुक्रवार सुबह क्रैश हो जाता है। सारा डेटा पुनर्स्थापित करने के लिए कौन-से बैकअप चाहिए?","optionsHi":["रविवार का पूर्ण और चारों डिफ़रेंशियल","रविवार का पूर्ण और गुरुवार का डिफ़रेंशियल","केवल गुरुवार का डिफ़रेंशियल बैकअप","केवल रविवार का पूर्ण बैकअप"],"explanationHi":"हर डिफ़रेंशियल में अंतिम पूर्ण बैकअप के बाद के सभी परिवर्तन होते हैं, इसलिए नवीनतम और पूर्ण बैकअप पर्याप्त हैं। इन्क्रीमेंटल बैकअप में, पूर्ण के बाद का हर एक चाहिए होता।"},
  {"id":"comp-ms-office-internet-401","question":"Which of these statements about UPI safety are correct? I. A UPI PIN is never needed to receive money into your own account. II. Scanning a QR code is needed to receive money from a buyer. III. A genuine bank never asks a customer to share an OTP or PIN.","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":3,"explanation":"Receiving money needs no PIN and no QR scan by the receiver; fraudsters send collect requests or QR codes to 'pay' victims, which actually debit them. Banks never ask for OTP or PIN.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"UPI सुरक्षा के बारे में इनमें से कौन-से कथन सही हैं? I. अपने ही खाते में धन प्राप्त करने के लिए UPI PIN की कभी ज़रूरत नहीं होती। II. खरीदार से धन प्राप्त करने के लिए QR कोड स्कैन करना ज़रूरी है। III. कोई असली बैंक कभी ग्राहक से OTP या PIN साझा करने को नहीं कहता।","optionsHi":["केवल I और II","केवल II और III","I, II और III","केवल I और III"],"explanationHi":"धन प्राप्त करने के लिए प्राप्तकर्ता को PIN या QR स्कैन की ज़रूरत नहीं होती; धोखेबाज़ पीड़ितों को 'भुगतान' करने के नाम पर collect अनुरोध या QR कोड भेजते हैं, जो वास्तव में उनके खाते से पैसे काटते हैं। बैंक कभी OTP या PIN नहीं माँगते।"},
  {"id":"comp-ms-office-internet-402","question":"A customer gets a link: https://examplebank.in.secure-login.xyz/kyc. Which domain does this link actually lead to?","options":["secure-login.xyz","examplebank.in","in.secure-login","kyc.examplebank.in"],"answer":0,"explanation":"The registered domain is read from the right, just before the path: secure-login.xyz. examplebank.in is only a subdomain label chosen by the fraudster to look genuine.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी ग्राहक को एक लिंक मिलता है: https://examplebank.in.secure-login.xyz/kyc। यह लिंक वास्तव में किस डोमेन तक ले जाता है?","optionsHi":["secure-login.xyz","examplebank.in","in.secure-login","kyc.examplebank.in"],"explanationHi":"पंजीकृत डोमेन दाईं ओर से, पथ के ठीक पहले तक पढ़ा जाता है: secure-login.xyz। examplebank.in केवल धोखेबाज़ द्वारा असली दिखने के लिए चुना गया सबडोमेन लेबल है।"},
  {"id":"comp-ms-office-internet-403","question":"A website shows the padlock icon and https:// in the address bar. What does this prove?","options":["The site is the genuine site of the bank it claims to be","The connection is encrypted to whoever owns that domain","The site has been checked and approved by the RBI","The site contains no malware or phishing content"],"answer":1,"explanation":"The padlock shows TLS encryption to a server holding a valid certificate for that domain. Phishing sites can get certificates too, so the domain name itself must be checked.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी वेबसाइट के अड्रेस बार में पैडलॉक आइकन और https:// दिखता है। यह क्या सिद्ध करता है?","optionsHi":["साइट उसी बैंक की असली साइट है जिसका वह दावा करती है","कनेक्शन उस डोमेन के स्वामी तक एन्क्रिप्टेड है","साइट की जाँच और अनुमोदन RBI ने किया है","साइट में कोई मैलवेयर या फ़िशिंग सामग्री नहीं है"],"explanationHi":"पैडलॉक उस डोमेन के वैध प्रमाणपत्र वाले सर्वर तक TLS एन्क्रिप्शन दिखाता है। फ़िशिंग साइटें भी प्रमाणपत्र पा सकती हैं, इसलिए डोमेन नाम स्वयं जाँचना चाहिए।"},
  {"id":"comp-ms-office-internet-404","question":"A bank digitally signs a PDF statement but does not encrypt it. Which security service does the digital signature NOT give?","options":["Confidentiality","Integrity","Authentication","Non-repudiation"],"answer":0,"explanation":"A digital signature proves who signed (authentication), shows any change (integrity) and stops the signer denying it (non-repudiation). Keeping the content secret needs encryption.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"कोई बैंक किसी PDF विवरण पर डिजिटल हस्ताक्षर करता है पर उसे एन्क्रिप्ट नहीं करता। डिजिटल हस्ताक्षर कौन-सी सुरक्षा सेवा नहीं देता?","optionsHi":["गोपनीयता (Confidentiality)","अखंडता (Integrity)","प्रमाणीकरण (Authentication)","अनस्वीकार्यता (Non-repudiation)"],"explanationHi":"डिजिटल हस्ताक्षर सिद्ध करता है कि किसने हस्ताक्षर किए (प्रमाणीकरण), किसी भी परिवर्तन को दिखाता है (अखंडता) और हस्ताक्षरकर्ता को इनकार करने से रोकता है (अनस्वीकार्यता)। सामग्री को गुप्त रखने के लिए एन्क्रिप्शन चाहिए।"},
  {"id":"comp-ms-office-internet-405","question":"Asha sends an e-mail To: Ravi, Cc: Meena and Bcc: Tarun. Tarun clicks Reply All. Who receives Tarun's reply?","options":["Asha, Ravi and Meena, who now learn that Tarun had a copy","Only Asha, because a Bcc recipient cannot reply to everyone","Asha and Ravi only, because Cc recipients are left out","Asha, Ravi, Meena and Tarun himself, as a Bcc copy"],"answer":0,"explanation":"Reply All goes to the sender and every visible To and Cc address, so Ravi and Meena get it and discover Tarun was blind-copied. This is why Bcc recipients should usually reply only to the sender.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Asha ई-मेल भेजती है To: Ravi, Cc: Meena और Bcc: Tarun। Tarun 'Reply All' पर क्लिक करता है। Tarun का उत्तर किसे मिलता है?","optionsHi":["Asha, Ravi और Meena, जो अब जान जाते हैं कि Tarun के पास प्रति थी","केवल Asha, क्योंकि Bcc प्राप्तकर्ता सभी को उत्तर नहीं दे सकता","केवल Asha और Ravi, क्योंकि Cc प्राप्तकर्ता छोड़ दिए जाते हैं","Asha, Ravi, Meena और स्वयं Tarun, Bcc प्रति के रूप में"],"explanationHi":"Reply All भेजने वाले और हर दिखाई देने वाले To तथा Cc पते को जाता है, इसलिए Ravi और Meena को मिलता है और उन्हें पता चल जाता है कि Tarun को गुप्त प्रति मिली थी। इसीलिए Bcc प्राप्तकर्ताओं को सामान्यतः केवल प्रेषक को उत्तर देना चाहिए।"},
  {"id":"comp-ms-office-internet-406","question":"Which of these is a validly formed e-mail address?","options":["ravi kumar@bank.in","ravi.k@bank.co.in","ravi@@mail.bank.in","www.ravi.bank.in"],"answer":1,"explanation":"An address needs one @ separating the user name from the domain, and no spaces. A dot inside the user name and a domain such as bank.co.in are allowed.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk","questionHi":"इनमें से कौन-सा सही ढंग से बना ई-मेल पता है?","optionsHi":["ravi kumar@bank.in","ravi.k@bank.co.in","ravi@@mail.bank.in","www.ravi.bank.in"],"explanationHi":"पते में उपयोगकर्ता नाम को डोमेन से अलग करने वाला एक @ चाहिए, और कोई रिक्त स्थान नहीं। उपयोगकर्ता नाम के भीतर बिंदु और bank.co.in जैसा डोमेन मान्य हैं।"},
  {"id":"comp-ms-office-internet-407","question":"An e-mail shows From: Customer Care <care@examplebank.in>, but its Reply-To field is set to an address at another domain. What happens if the reader simply clicks Reply?","options":["The reply goes to the From address, since Reply-To is ignored","The reply goes to both addresses, as if Reply All was clicked","The reply is blocked by the mail server as a spoofed message","The reply goes to the Reply-To address, not to the From address"],"answer":3,"explanation":"Mail programs send a reply to the Reply-To address when one is set. Fraudsters use this so that replies to a genuine-looking From address reach them instead.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक ई-मेल में From: Customer Care <care@examplebank.in> दिखता है, पर उसका Reply-To फ़ील्ड किसी अन्य डोमेन के पते पर सेट है। यदि पाठक केवल Reply क्लिक करे तो क्या होता है?","optionsHi":["उत्तर From पते पर जाता है, क्योंकि Reply-To अनदेखा किया जाता है","उत्तर दोनों पतों पर जाता है, मानो Reply All क्लिक किया गया हो","उत्तर को मेल सर्वर जाली संदेश मानकर अवरुद्ध कर देता है","उत्तर Reply-To पते पर जाता है, From पते पर नहीं"],"explanationHi":"मेल प्रोग्राम Reply-To पता सेट होने पर उत्तर उसी पर भेजते हैं। धोखेबाज़ इसका उपयोग करते हैं ताकि असली दिखने वाले From पते को दिए गए उत्तर उन तक पहुँचें।"},
  {"id":"comp-ms-office-internet-408","question":"For what is TCP port 587 normally used in e-mail?","options":["A mail client downloading messages from its server with POP3","A mail client reading messages from its server over IMAP with TLS","A mail client submitting outgoing mail, with login","Mail servers passing messages to each other without any login"],"answer":2,"explanation":"Port 587 is the message submission port, where users' mail programs send outgoing mail with authentication. Server-to-server relay uses port 25, POP3 uses 110 and IMAP over TLS 993.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"ई-मेल में TCP पोर्ट 587 सामान्यतः किसलिए उपयोग होता है?","optionsHi":["मेल क्लाइंट द्वारा POP3 से अपने सर्वर से संदेश डाउनलोड करने के लिए","मेल क्लाइंट द्वारा TLS के साथ IMAP से अपने सर्वर से संदेश पढ़ने के लिए","मेल क्लाइंट द्वारा लॉगिन के साथ जाने वाला मेल जमा करने (submit) के लिए","मेल सर्वरों द्वारा बिना लॉगिन एक-दूसरे को संदेश देने के लिए"],"explanationHi":"पोर्ट 587 संदेश जमा करने का पोर्ट है, जहाँ उपयोगकर्ताओं के मेल प्रोग्राम प्रमाणीकरण के साथ जाने वाला मेल भेजते हैं। सर्वर-से-सर्वर रिले पोर्ट 25 का उपयोग करता है, POP3 110 का और TLS पर IMAP 993 का।"},
  {"id":"comp-ms-office-internet-409","question":"An e-mail sent to a misspelt address comes back automatically with a message saying it could not be delivered. This returned message is called a:","options":["Read receipt from the receiver","Non-delivery report (bounce)","Out-of-office auto-reply","Spam complaint report"],"answer":1,"explanation":"When the receiving server cannot deliver a message, for example because the mailbox does not exist, a non-delivery report or bounce is sent back to the sender.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"गलत वर्तनी वाले पते पर भेजा गया ई-मेल अपने आप इस संदेश के साथ लौट आता है कि वह वितरित नहीं हो सका। इस लौटे संदेश को क्या कहते हैं?","optionsHi":["प्राप्तकर्ता की ओर से पठन रसीद (Read receipt)","अवितरण रिपोर्ट (बाउंस) (Non-delivery report)","कार्यालय से बाहर का स्वचालित उत्तर (Out-of-office auto-reply)","स्पैम शिकायत रिपोर्ट"],"explanationHi":"जब प्राप्तकर्ता सर्वर संदेश वितरित नहीं कर पाता, जैसे मेलबॉक्स मौजूद न हो, तो अवितरण रिपोर्ट या बाउंस प्रेषक को लौटा दी जाती है।"},
  {"id":"comp-ms-office-internet-410","question":"A user writes a message in a desktop mail program and clicks Send while the laptop has no internet connection. Where does the message wait until it can be sent?","options":["Outbox","Drafts","Sent Items","Junk E-mail"],"answer":0,"explanation":"A message that has been sent but not yet delivered to the mail server waits in the Outbox; it moves to Sent Items after it leaves. Drafts holds messages not yet sent.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"एक उपयोगकर्ता डेस्कटॉप मेल प्रोग्राम में संदेश लिखता है और लैपटॉप में इंटरनेट कनेक्शन न होने पर Send क्लिक करता है। भेजे जा सकने तक संदेश कहाँ प्रतीक्षा करता है?","optionsHi":["Outbox","Drafts","Sent Items","Junk E-mail"],"explanationHi":"जो संदेश भेजा जा चुका है पर मेल सर्वर तक वितरित नहीं हुआ, वह Outbox में प्रतीक्षा करता है; बाहर जाने के बाद वह Sent Items में चला जाता है। Drafts में वे संदेश होते हैं जो अभी भेजे नहीं गए।"},
  {"id":"comp-ms-office-internet-411","question":"Which statement about webmail (such as reading mail in a browser) and a desktop mail client is correct?","options":["Webmail uses POP3 to download every message to the browser; a desktop client uses only HTTPS","Webmail needs no mail server at all, as messages travel directly between browsers","Webmail stores all messages only on the user's own computer, never on a server","Webmail uses HTTPS to the provider; a desktop client uses IMAP and SMTP"],"answer":3,"explanation":"In webmail the browser is just a web client speaking HTTP(S) to the provider's web servers, which hold the mailbox. A desktop client talks mail protocols (IMAP/POP3 to read, SMTP to send).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"वेबमेल (जैसे ब्राउज़र में मेल पढ़ना) और डेस्कटॉप मेल क्लाइंट के बारे में कौन-सा कथन सही है?","optionsHi":["वेबमेल हर संदेश को ब्राउज़र में डाउनलोड करने के लिए POP3 का उपयोग करता है; डेस्कटॉप क्लाइंट केवल HTTPS का","वेबमेल को किसी मेल सर्वर की ज़रूरत ही नहीं, क्योंकि संदेश सीधे ब्राउज़रों के बीच जाते हैं","वेबमेल सभी संदेश केवल उपयोगकर्ता के अपने कंप्यूटर पर संग्रहीत करता है, सर्वर पर कभी नहीं","वेबमेल प्रदाता तक HTTPS का उपयोग करता है; डेस्कटॉप क्लाइंट IMAP और SMTP का"],"explanationHi":"वेबमेल में ब्राउज़र केवल एक वेब क्लाइंट है जो प्रदाता के वेब सर्वरों से HTTP(S) में बात करता है, जो मेलबॉक्स रखते हैं। डेस्कटॉप क्लाइंट मेल प्रोटोकॉल (पढ़ने के लिए IMAP/POP3, भेजने के लिए SMTP) में बात करता है।"},
  {"id":"comp-ms-office-internet-412","question":"A browser keeps showing an old version of a web page even after F5 is pressed. Which shortcut forces a full reload that ignores the cached copy?","options":["Alt + F5","Shift + F10","Ctrl + F5","Ctrl + F4"],"answer":2,"explanation":"Ctrl + F5 (a hard refresh) reloads the page and fetches files from the server again instead of the browser cache. Ctrl + F4 closes the current tab.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"F5 दबाने के बाद भी ब्राउज़र किसी वेब पेज का पुराना संस्करण दिखाता रहता है। कौन-सा शॉर्टकट कैश की गई प्रति को अनदेखा करके पूरा पुनः लोड बाध्य करता है?","optionsHi":["Alt + F5","Shift + F10","Ctrl + F5","Ctrl + F4"],"explanationHi":"Ctrl + F5 (हार्ड रिफ़्रेश) पेज को पुनः लोड करता है और ब्राउज़र कैश के बजाय फ़ाइलें फिर से सर्वर से लाता है। Ctrl + F4 वर्तमान टैब बंद करता है।"},
  {"id":"comp-ms-office-internet-413","question":"Which shortcuts open a new private (incognito) window in Google Chrome and in Mozilla Firefox respectively?","options":["Ctrl + Shift + P and Ctrl + Shift + N","Ctrl + Shift + N and Ctrl + Shift + P","Ctrl + Shift + N in both browsers","Ctrl + Shift + T and Ctrl + Shift + P"],"answer":1,"explanation":"Chrome uses Ctrl + Shift + N for an Incognito window and Firefox uses Ctrl + Shift + P for a Private Window. Ctrl + Shift + T reopens a closed tab.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Google Chrome और Mozilla Firefox में क्रमशः कौन-से शॉर्टकट नई प्राइवेट (इन्कॉग्निटो) विंडो खोलते हैं?","optionsHi":["Ctrl + Shift + P और Ctrl + Shift + N","Ctrl + Shift + N और Ctrl + Shift + P","दोनों ब्राउज़रों में Ctrl + Shift + N","Ctrl + Shift + T और Ctrl + Shift + P"],"explanationHi":"Chrome Incognito विंडो के लिए Ctrl + Shift + N और Firefox Private Window के लिए Ctrl + Shift + P का उपयोग करता है। Ctrl + Shift + T बंद किया गया टैब फिर खोलता है।"},
  {"id":"comp-ms-office-internet-414","question":"A user accidentally closes a browser tab. Which shortcut reopens the most recently closed tab in common browsers?","options":["Ctrl + T","Ctrl + Shift + W","Ctrl + Z","Ctrl + Shift + T"],"answer":3,"explanation":"Ctrl + Shift + T restores the last closed tab. Ctrl + T opens a new blank tab and Ctrl + Shift + W closes the whole window.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"एक उपयोगकर्ता गलती से ब्राउज़र टैब बंद कर देता है। सामान्य ब्राउज़रों में कौन-सा शॉर्टकट हाल ही में बंद किया गया टैब फिर खोलता है?","optionsHi":["Ctrl + T","Ctrl + Shift + W","Ctrl + Z","Ctrl + Shift + T"],"explanationHi":"Ctrl + Shift + T अंतिम बंद किया गया टैब बहाल करता है। Ctrl + T नया खाली टैब खोलता है और Ctrl + Shift + W पूरी विंडो बंद करता है।"},
  {"id":"comp-ms-office-internet-415","question":"In common web browsers, which shortcut moves the cursor to the address bar and selects the URL so that a new address can be typed?","options":["Ctrl + L","Ctrl + D","Ctrl + H","Ctrl + J"],"answer":0,"explanation":"Ctrl + L (also Alt + D or F6) jumps to the address bar. Ctrl + D bookmarks the page, Ctrl + H opens history and Ctrl + J opens downloads.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"सामान्य वेब ब्राउज़रों में कौन-सा शॉर्टकट कर्सर को अड्रेस बार पर ले जाता है और URL चयनित कर देता है ताकि नया पता टाइप किया जा सके?","optionsHi":["Ctrl + L","Ctrl + D","Ctrl + H","Ctrl + J"],"explanationHi":"Ctrl + L (साथ ही Alt + D या F6) अड्रेस बार पर कूदता है। Ctrl + D पेज को बुकमार्क करता है, Ctrl + H इतिहास खोलता है और Ctrl + J डाउनलोड खोलता है।"},
  {"id":"comp-ms-office-internet-416","question":"In a Google search, which query finds pages that have the phrase annual report in their page title?","options":["inurl:\"annual report\"","site:\"annual report\"","intitle:\"annual report\"","filetype:\"annual report\""],"answer":2,"explanation":"intitle: limits results to words in the page title. inurl: looks in the web address, site: restricts results to a domain and filetype: to a file format.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Google खोज में कौन-सी क्वेरी उन पेजों को खोजती है जिनके पेज शीर्षक में वाक्यांश annual report है?","optionsHi":["inurl:\"annual report\"","site:\"annual report\"","intitle:\"annual report\"","filetype:\"annual report\""],"explanationHi":"intitle: परिणामों को पेज शीर्षक के शब्दों तक सीमित करता है। inurl: वेब पते में देखता है, site: परिणामों को किसी डोमेन तक और filetype: किसी फ़ाइल प्रारूप तक सीमित करता है।"},
  {"id":"comp-ms-office-internet-417","question":"Which of these best describes Web 2.0?","options":["Read-only pages put up by site owners just for visitors to view and download","Sites where users create and share content, like blogs and wikis","A newer, faster second internet that runs only over IPv6 addresses","The browser-free network of sensors and smart devices that talk to each other"],"answer":1,"explanation":"Web 2.0 refers to the interactive, user-generated web of blogs, wikis and social networks, unlike the mostly read-only Web 1.0. Connected sensors describe the Internet of Things.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"इनमें से कौन-सा Web 2.0 का सबसे अच्छा वर्णन करता है?","optionsHi":["साइट मालिकों द्वारा केवल आगंतुकों के देखने और डाउनलोड करने के लिए लगाए गए केवल-पठन पेज","ऐसी साइटें जहाँ उपयोगकर्ता सामग्री बनाते और साझा करते हैं, जैसे ब्लॉग और विकी","एक नया, तेज़ दूसरा इंटरनेट जो केवल IPv6 पतों पर चलता है","सेंसरों और स्मार्ट उपकरणों का ब्राउज़र-रहित नेटवर्क जो आपस में बात करते हैं"],"explanationHi":"Web 2.0 ब्लॉग, विकी और सोशल नेटवर्क के इंटरैक्टिव, उपयोगकर्ता-निर्मित वेब को कहते हैं, जो अधिकतर केवल-पठन Web 1.0 से भिन्न है। जुड़े हुए सेंसर Internet of Things का वर्णन करते हैं।"},
  {"id":"comp-ms-office-internet-418","question":"A bank's page that shows each logged-in customer their own balance and recent transactions is an example of a:","options":["Dynamic web page, built by the server for each request","Static web page, stored on the server as one fixed HTML file","Web portal page, shared alike by every visitor","Cached web page, saved in the browser in advance"],"answer":0,"explanation":"A dynamic page is generated on the fly, often from a database, so its content differs per user and per visit. A static page is the same fixed file for everyone.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी बैंक का वह पेज जो हर लॉग-इन ग्राहक को उसकी अपनी शेष राशि और हाल के लेन-देन दिखाता है, किसका उदाहरण है?","optionsHi":["डायनेमिक वेब पेज, जो सर्वर द्वारा हर अनुरोध के लिए बनाया जाता है","स्टैटिक वेब पेज, जो सर्वर पर एक स्थिर HTML फ़ाइल के रूप में संग्रहीत होता है","वेब पोर्टल पेज, जो हर आगंतुक के लिए एक जैसा साझा होता है","कैश किया गया वेब पेज, जो ब्राउज़र में पहले से सहेजा जाता है"],"explanationHi":"डायनेमिक पेज तुरंत बनाया जाता है, अक्सर डेटाबेस से, इसलिए उसकी सामग्री हर उपयोगकर्ता और हर बार भिन्न होती है। स्टैटिक पेज सबके लिए वही स्थिर फ़ाइल होता है।"},
  {"id":"comp-ms-office-internet-419","question":"In the web address www.mail.example.co.in, which part is the top-level domain?","options":[".co.in","example","www",".in"],"answer":3,"explanation":"Domain names are read from the right, and the top-level domain is the last label, .in (India's country-code TLD). .co is a second-level domain under it, and example is registered under .co.in.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"वेब पते www.mail.example.co.in में शीर्ष-स्तरीय डोमेन कौन-सा भाग है?","optionsHi":[".co.in","example","www",".in"],"explanationHi":"डोमेन नाम दाईं ओर से पढ़े जाते हैं, और शीर्ष-स्तरीय डोमेन अंतिम लेबल .in है (भारत का देश-कोड TLD)। .co उसके नीचे द्वितीय-स्तरीय डोमेन है, और example .co.in के अंतर्गत पंजीकृत है।"},
  {"id":"comp-ms-office-internet-420","question":"A search engine program that automatically visits web pages and follows their links to collect pages for its index is called a:","options":["Web hosting server","Domain name server","Web crawler","Browser extension"],"answer":2,"explanation":"Crawlers (spiders or bots) move from link to link fetching pages, which the search engine then indexes. A web server only serves pages when asked.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"वह सर्च इंजन प्रोग्राम जो अपने इंडेक्स के लिए पेज एकत्र करने हेतु अपने आप वेब पेजों पर जाता है और उनके लिंक का अनुसरण करता है, क्या कहलाता है?","optionsHi":["वेब होस्टिंग सर्वर","डोमेन नेम सर्वर","वेब क्रॉलर (Web crawler)","ब्राउज़र एक्सटेंशन"],"explanationHi":"क्रॉलर (स्पाइडर या बॉट) लिंक-दर-लिंक चलकर पेज लाते हैं, जिन्हें सर्च इंजन फिर इंडेक्स करता है। वेब सर्वर पेज केवल माँगे जाने पर परोसता है।"},
  {"id":"comp-ms-office-internet-421","question":"Which organisation coordinates the internet's domain name system and the worldwide allocation of IP address blocks?","options":["ICANN","W3C","IEEE","ITU"],"answer":0,"explanation":"ICANN (through the IANA functions) oversees the DNS root and IP address allocation to regional registries. W3C sets web standards and IEEE sets standards such as Ethernet and Wi-Fi.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कौन-सा संगठन इंटरनेट की डोमेन नेम प्रणाली और IP पता ब्लॉकों के विश्वव्यापी आवंटन का समन्वय करता है?","optionsHi":["ICANN","W3C","IEEE","ITU"],"explanationHi":"ICANN (IANA कार्यों के माध्यम से) DNS रूट और क्षेत्रीय रजिस्ट्रियों को IP पता आवंटन की देखरेख करता है। W3C वेब मानक तय करता है और IEEE Ethernet और Wi-Fi जैसे मानक।"},
  {"id":"comp-ms-office-internet-422","question":"Which body develops web standards such as CSS and the Web Content Accessibility Guidelines (WCAG)?","options":["Internet Corporation for Assigned Names and Numbers","Institute of Electrical and Electronics Engineers","World Wide Web Consortium (W3C)","International Organization for Standardization"],"answer":2,"explanation":"The W3C, founded by Tim Berners-Lee, publishes web standards like CSS and WCAG. ICANN manages names and numbers, and IEEE sets networking standards such as 802.11.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कौन-सी संस्था CSS और Web Content Accessibility Guidelines (WCAG) जैसे वेब मानक विकसित करती है?","optionsHi":["Internet Corporation for Assigned Names and Numbers","Institute of Electrical and Electronics Engineers","World Wide Web Consortium (W3C)","International Organization for Standardization"],"explanationHi":"Tim Berners-Lee द्वारा स्थापित W3C, CSS और WCAG जैसे वेब मानक प्रकाशित करता है। ICANN नाम और संख्याएँ प्रबंधित करता है, और IEEE 802.11 जैसे नेटवर्किंग मानक तय करता है।"},
  {"id":"comp-ms-office-internet-423","question":"Sections 66A to 66F, covering offences such as identity theft and cyber terrorism, were added to the Information Technology Act, 2000 by:","options":["The original Information Technology Act, 2000 itself","The Information Technology (Amendment) Act, 2008","The Digital Personal Data Protection Act, 2023","The Indian Penal Code (Amendment) Act, 2005"],"answer":1,"explanation":"The IT (Amendment) Act, 2008, in force from 2009, inserted Sections 66A to 66F among other changes. The original 2000 Act had only a single, general Section 66.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"पहचान की चोरी और साइबर आतंकवाद जैसे अपराधों को कवर करने वाली धाराएँ 66A से 66F सूचना प्रौद्योगिकी अधिनियम, 2000 में किसके द्वारा जोड़ी गईं?","optionsHi":["स्वयं मूल सूचना प्रौद्योगिकी अधिनियम, 2000 द्वारा","सूचना प्रौद्योगिकी (संशोधन) अधिनियम, 2008 द्वारा","डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम, 2023 द्वारा","भारतीय दंड संहिता (संशोधन) अधिनियम, 2005 द्वारा"],"explanationHi":"IT (संशोधन) अधिनियम, 2008, जो 2009 से लागू हुआ, ने अन्य परिवर्तनों के साथ धाराएँ 66A से 66F जोड़ीं। मूल 2000 के अधिनियम में केवल एक सामान्य धारा 66 थी।"},
  {"id":"comp-ms-office-internet-424","question":"India's Information Technology Act, 2000 was based on which international model?","options":["Budapest Convention on Cybercrime, 2001","EU General Data Protection Regulation, 2016","OECD Guidelines on Privacy Protection, 1980","UNCITRAL Model Law on Electronic Commerce, 1996"],"answer":3,"explanation":"The IT Act gave legal recognition to electronic records following the UN General Assembly's adoption of the UNCITRAL Model Law on Electronic Commerce (1996). India has not joined the Budapest Convention.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"भारत का सूचना प्रौद्योगिकी अधिनियम, 2000 किस अंतरराष्ट्रीय मॉडल पर आधारित था?","optionsHi":["साइबर अपराध पर बुडापेस्ट अभिसमय, 2001","EU सामान्य डेटा संरक्षण विनियमन, 2016","निजता संरक्षण पर OECD दिशानिर्देश, 1980","इलेक्ट्रॉनिक वाणिज्य पर UNCITRAL मॉडल कानून, 1996"],"explanationHi":"IT अधिनियम ने संयुक्त राष्ट्र महासभा द्वारा इलेक्ट्रॉनिक वाणिज्य पर UNCITRAL मॉडल कानून (1996) अपनाए जाने के बाद इलेक्ट्रॉनिक अभिलेखों को कानूनी मान्यता दी। भारत बुडापेस्ट अभिसमय में शामिल नहीं हुआ है।"},
  {"id":"comp-ms-office-internet-425","question":"In India, which authority licenses and regulates the Certifying Authorities that issue digital signature certificates under the IT Act?","options":["Indian Computer Emergency Response Team","Telecom Regulatory Authority of India","Controller of Certifying Authorities (CCA)","Unique Identification Authority of India"],"answer":2,"explanation":"The Controller of Certifying Authorities, appointed under the IT Act, licenses CAs and runs the root certifying authority. CERT-In handles cyber security incidents.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"भारत में कौन-सा प्राधिकरण उन प्रमाणन प्राधिकरणों को लाइसेंस देता और विनियमित करता है जो IT अधिनियम के अंतर्गत डिजिटल हस्ताक्षर प्रमाणपत्र जारी करते हैं?","optionsHi":["भारतीय कंप्यूटर आपातकालीन प्रतिक्रिया दल","भारतीय दूरसंचार विनियामक प्राधिकरण","प्रमाणन प्राधिकारियों का नियंत्रक (CCA)","भारतीय विशिष्ट पहचान प्राधिकरण"],"explanationHi":"IT अधिनियम के अंतर्गत नियुक्त प्रमाणन प्राधिकारियों का नियंत्रक CA को लाइसेंस देता है और रूट प्रमाणन प्राधिकरण चलाता है। CERT-In साइबर सुरक्षा घटनाएँ संभालता है।"},
  {"id":"comp-ms-office-internet-426","question":"Under the First Schedule of the Information Technology Act, 2000, the Act does NOT apply to which of these, so it cannot be validly made as an electronic record?","options":["A will","A purchase order for goods","An income tax return","An e-mail giving notice of a meeting"],"answer":0,"explanation":"The First Schedule excludes wills, trusts, powers of attorney, negotiable instruments other than cheques, and contracts for the sale of immovable property from the Act.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"सूचना प्रौद्योगिकी अधिनियम, 2000 की प्रथम अनुसूची के अंतर्गत, इनमें से किस पर अधिनियम लागू नहीं होता, इसलिए उसे इलेक्ट्रॉनिक अभिलेख के रूप में वैध रूप से नहीं बनाया जा सकता?","optionsHi":["वसीयत","वस्तुओं का क्रय आदेश","आयकर रिटर्न","बैठक की सूचना देने वाला ई-मेल"],"explanationHi":"प्रथम अनुसूची वसीयत, न्यास, मुख्तारनामा, चेकों के अलावा परक्राम्य लिखत, और अचल संपत्ति की बिक्री के अनुबंधों को अधिनियम से बाहर रखती है।"},
  {"id":"comp-ms-office-internet-427","question":"In 2017 the Cyber Appellate Tribunal set up under the IT Act was merged into which body?","options":["National Company Law Appellate Tribunal","Central Administrative Tribunal, Principal Bench at Delhi","Securities Appellate Tribunal","Telecom Disputes Settlement and Appellate Tribunal"],"answer":3,"explanation":"The Finance Act, 2017 merged the Cyber Appellate Tribunal into the TDSAT, which now hears appeals under the IT Act.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"2017 में IT अधिनियम के अंतर्गत स्थापित साइबर अपीलीय अधिकरण का किस निकाय में विलय कर दिया गया?","optionsHi":["राष्ट्रीय कंपनी विधि अपीलीय अधिकरण","केंद्रीय प्रशासनिक अधिकरण, दिल्ली में प्रधान पीठ","प्रतिभूति अपीलीय अधिकरण","दूरसंचार विवाद निपटान एवं अपीलीय अधिकरण"],"explanationHi":"वित्त अधिनियम, 2017 ने साइबर अपीलीय अधिकरण का विलय TDSAT में कर दिया, जो अब IT अधिनियम के अंतर्गत अपीलें सुनता है।"},
  {"id":"comp-ms-office-internet-428","question":"A citizen in India wants to file a complaint about online financial fraud through the government's national online portal for cyber crime. Which website is it?","options":["cert-in.org.in","cybercrime.gov.in","digitalindia.gov.in","uidai.gov.in"],"answer":1,"explanation":"The National Cyber Crime Reporting Portal, cybercrime.gov.in, takes complaints from the public (with the 1930 helpline for financial fraud). CERT-In handles security incidents, not public crime complaints.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"भारत का कोई नागरिक साइबर अपराध के लिए सरकार के राष्ट्रीय ऑनलाइन पोर्टल के माध्यम से ऑनलाइन वित्तीय धोखाधड़ी की शिकायत दर्ज करना चाहता है। वह वेबसाइट कौन-सी है?","optionsHi":["cert-in.org.in","cybercrime.gov.in","digitalindia.gov.in","uidai.gov.in"],"explanationHi":"राष्ट्रीय साइबर अपराध रिपोर्टिंग पोर्टल, cybercrime.gov.in, जनता की शिकायतें लेता है (वित्तीय धोखाधड़ी के लिए 1930 हेल्पलाइन के साथ)। CERT-In सुरक्षा घटनाएँ संभालता है, जनता की अपराध शिकायतें नहीं।"},
  {"id":"comp-ms-office-internet-429","question":"Match the section of the IT Act, 2000 with its subject: 1. Section 65 2. Section 69A 3. Section 72 4. Section 79; a. exemption of intermediaries from liability in certain cases b. tampering with computer source documents c. breach of confidentiality and privacy d. power to block public access to information","options":["1-b, 2-c, 3-d, 4-a","1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a"],"answer":3,"explanation":"Section 65 punishes tampering with source code, 69A lets the government block websites (upheld in Shreya Singhal), 72 covers breach of confidentiality, and 79 is the intermediary safe harbour.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"IT अधिनियम, 2000 की धारा को उसके विषय से सुमेलित कीजिए: 1. धारा 65 2. धारा 69A 3. धारा 72 4. धारा 79; a. कुछ मामलों में मध्यस्थों को दायित्व से छूट b. कंप्यूटर स्रोत दस्तावेज़ों से छेड़छाड़ c. गोपनीयता और निजता का उल्लंघन d. सूचना तक सार्वजनिक पहुँच को अवरुद्ध करने की शक्ति","optionsHi":["1-b, 2-c, 3-d, 4-a","1-d, 2-b, 3-c, 4-a","1-b, 2-d, 3-a, 4-c","1-b, 2-d, 3-c, 4-a"],"explanationHi":"धारा 65 स्रोत कोड से छेड़छाड़ को दंडित करती है, 69A सरकार को वेबसाइटें अवरुद्ध करने देती है (श्रेया सिंघल में बरकरार), 72 गोपनीयता के उल्लंघन को कवर करती है, और 79 मध्यस्थ सुरक्षित बंदरगाह (safe harbour) है।"},
  {"id":"comp-ms-office-internet-430","question":"What does the Excel formula =LEFT(\"Mumbai\", 3) & RIGHT(\"Pune\", 2) return?","options":["Mumpu","baine","Mumne","Mune"],"answer":2,"explanation":"LEFT(\"Mumbai\", 3) gives Mum and RIGHT(\"Pune\", 2) gives the last two letters, ne; & joins them into Mumne.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"Excel का सूत्र =LEFT(\"Mumbai\", 3) & RIGHT(\"Pune\", 2) क्या लौटाता है?","optionsHi":["Mumpu","baine","Mumne","Mune"],"explanationHi":"LEFT(\"Mumbai\", 3) Mum देता है और RIGHT(\"Pune\", 2) अंतिम दो अक्षर, ne, देता है; & उन्हें जोड़कर Mumne बनाता है।"},
  {"id":"comp-ms-office-internet-431","question":"In Excel, A1:A6 contain North, South, (blank), East, North, (blank). What does =COUNTIF(A1:A6, \"<>North\") return?","options":["2","3","6","4"],"answer":3,"explanation":"\"<>North\" counts every cell not equal to North, and that includes empty cells: South, East and the two blanks give 4. Counting only non-blank cells would give 2.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1:A6 में North, South, (रिक्त), East, North, (रिक्त) हैं। =COUNTIF(A1:A6, \"<>North\") क्या लौटाता है?","optionsHi":["2","3","6","4"],"explanationHi":"\"<>North\" हर उस सेल को गिनता है जो North के बराबर नहीं है, और उसमें रिक्त सेल भी शामिल हैं: South, East और दो रिक्त मिलकर 4 देते हैं। केवल गैर-रिक्त सेल गिनने पर 2 मिलता।"},
  {"id":"comp-ms-office-internet-432","question":"In Excel, A1 = Ram, A2 = 25, A3 is blank, A4 = Sita and A5 = TRUE. What does =COUNTIF(A1:A5, \"*\") return?","options":["4","2","3","5"],"answer":1,"explanation":"The wildcard \"*\" matches any TEXT value only, so it counts Ram and Sita. The number 25, the logical TRUE and the blank cell are not text.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 = Ram, A2 = 25 है, A3 रिक्त है, A4 = Sita और A5 = TRUE है। =COUNTIF(A1:A5, \"*\") क्या लौटाता है?","optionsHi":["4","2","3","5"],"explanationHi":"वाइल्डकार्ड \"*\" केवल पाठ (TEXT) मानों से मेल खाता है, इसलिए यह Ram और Sita गिनता है। संख्या 25, तार्किक TRUE और रिक्त सेल पाठ नहीं हैं।"},
  {"id":"comp-ms-office-internet-433","question":"In Excel, A1:A5 contain 10, 0, 20, 0 and 30. What does =AVERAGEIF(A1:A5, \"<>0\") return?","options":["20","12","15","60"],"answer":0,"explanation":"Only the non-zero values 10, 20 and 30 are averaged: 60 / 3 = 20. A plain AVERAGE would include the zeros and give 60 / 5 = 12.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में A1:A5 में 10, 0, 20, 0 और 30 हैं। =AVERAGEIF(A1:A5, \"<>0\") क्या लौटाता है?","optionsHi":["20","12","15","60"],"explanationHi":"केवल गैर-शून्य मानों 10, 20 और 30 का औसत लिया जाता है: 60 / 3 = 20। साधारण AVERAGE शून्यों को भी शामिल करता और 60 / 5 = 12 देता।"},
  {"id":"comp-ms-office-internet-434","question":"A2:A6 contain North, South, North, East, North and B2:B6 contain 100, 200, 300, 400, 500. What does =SUMPRODUCT((A2:A6=\"North\")*(B2:B6)) return?","options":["1500","900","3","600"],"answer":1,"explanation":"(A2:A6=\"North\") gives 1 for North rows and 0 for others, so only 100 + 300 + 500 = 900 survive the multiplication. 3 would be a count of North rows.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A2:A6 में North, South, North, East, North हैं और B2:B6 में 100, 200, 300, 400, 500 हैं। =SUMPRODUCT((A2:A6=\"North\")*(B2:B6)) क्या लौटाता है?","optionsHi":["1500","900","3","600"],"explanationHi":"(A2:A6=\"North\") North वाली पंक्तियों के लिए 1 और अन्य के लिए 0 देता है, इसलिए गुणा के बाद केवल 100 + 300 + 500 = 900 बचते हैं। 3 North पंक्तियों की गिनती होती।"},
  {"id":"comp-ms-office-internet-435","question":"In Excel, A1:C3 hold 10, 20, 30 in row 1; 40, 50, 60 in row 2; and 70, 80, 90 in row 3. What does =OFFSET(A1, 2, 1) return?","options":["60","40","50","80"],"answer":3,"explanation":"OFFSET moves 2 rows down and 1 column right from A1, reaching B3, which holds 80. Swapping the row and column offsets would wrongly reach C2 (60).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में A1:C3 में पंक्ति 1 में 10, 20, 30; पंक्ति 2 में 40, 50, 60; और पंक्ति 3 में 70, 80, 90 हैं। =OFFSET(A1, 2, 1) क्या लौटाता है?","optionsHi":["60","40","50","80"],"explanationHi":"OFFSET, A1 से 2 पंक्ति नीचे और 1 कॉलम दाईं ओर जाता है, B3 पर पहुँचता है, जिसमें 80 है। पंक्ति और कॉलम ऑफ़सेट आपस में बदलने पर गलती से C2 (60) पर पहुँचते।"},
  {"id":"comp-ms-office-internet-436","question":"In Excel, A1:C3 hold 10, 20, 30 in row 1; 40, 50, 60 in row 2; and 70, 80, 90 in row 3. What does =INDIRECT(\"C\" & ROW(A2)) return?","options":["60","40","30","#REF!"],"answer":0,"explanation":"ROW(A2) is 2, so the text built is \"C2\", and INDIRECT turns that text into a real reference to C2, which holds 60.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1:C3 में पंक्ति 1 में 10, 20, 30; पंक्ति 2 में 40, 50, 60; और पंक्ति 3 में 70, 80, 90 हैं। =INDIRECT(\"C\" & ROW(A2)) क्या लौटाता है?","optionsHi":["60","40","30","#REF!"],"explanationHi":"ROW(A2) 2 है, इसलिए बना पाठ \"C2\" है, और INDIRECT उस पाठ को C2 के वास्तविक संदर्भ में बदल देता है, जिसमें 60 है।"},
  {"id":"comp-ms-office-internet-437","question":"What does the Excel formula =ROW(C7) + COLUMN(C7) return?","options":["8","9","10","73"],"answer":2,"explanation":"ROW(C7) is 7 and COLUMN(C7) is 3, because C is the third column, so the sum is 10.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"Excel का सूत्र =ROW(C7) + COLUMN(C7) क्या लौटाता है?","optionsHi":["8","9","10","73"],"explanationHi":"ROW(C7) 7 है और COLUMN(C7) 3 है, क्योंकि C तीसरा कॉलम है, इसलिए योग 10 है।"},
  {"id":"comp-ms-office-internet-438","question":"What does the Excel formula =ADDRESS(2, 3) return?","options":["$B$3","$C$2","C2","B3"],"answer":1,"explanation":"ADDRESS takes the row number first and then the column number, and by default returns an absolute reference as text: row 2, column 3 is $C$2.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =ADDRESS(2, 3) क्या लौटाता है?","optionsHi":["$B$3","$C$2","C2","B3"],"explanationHi":"ADDRESS पहले पंक्ति संख्या और फिर कॉलम संख्या लेता है, और डिफ़ॉल्ट रूप से पाठ के रूप में निरपेक्ष संदर्भ लौटाता है: पंक्ति 2, कॉलम 3 है $C$2।"},
  {"id":"comp-ms-office-internet-439","question":"In Excel, A1:A4 contain 0, 40, 60, 80 and B1:B4 contain F, C, B, A. What does =VLOOKUP(-5, A1:B4, 2, TRUE) return?","options":["#N/A","F","A","#VALUE!"],"answer":0,"explanation":"An approximate VLOOKUP finds the largest value not greater than the lookup value. Nothing in the column is less than or equal to -5, so it returns #N/A.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1:A4 में 0, 40, 60, 80 हैं और B1:B4 में F, C, B, A हैं। =VLOOKUP(-5, A1:B4, 2, TRUE) क्या लौटाता है?","optionsHi":["#N/A","F","A","#VALUE!"],"explanationHi":"सन्निकट VLOOKUP खोज मान से बड़ा न होने वाला सबसे बड़ा मान खोजता है। कॉलम में कुछ भी -5 के बराबर या उससे छोटा नहीं है, इसलिए यह #N/A लौटाता है।"},
  {"id":"comp-ms-office-internet-440","question":"In Excel, cell A1 looks empty but actually contains a single space typed by mistake. What does =IF(A1=\"\", \"Empty\", \"Filled\") return?","options":["Empty","#VALUE!","Filled","TRUE"],"answer":2,"explanation":"A space is a character, so A1 is not equal to the empty string \"\" and the formula returns Filled. Such hidden spaces also upset COUNTBLANK and lookups.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में सेल A1 खाली दिखता है पर वास्तव में उसमें गलती से टाइप किया गया एक रिक्त स्थान है। =IF(A1=\"\", \"Empty\", \"Filled\") क्या लौटाता है?","optionsHi":["Empty","#VALUE!","Filled","TRUE"],"explanationHi":"रिक्त स्थान एक वर्ण है, इसलिए A1 रिक्त स्ट्रिंग \"\" के बराबर नहीं है और सूत्र Filled लौटाता है। ऐसे छिपे रिक्त स्थान COUNTBLANK और लुकअप को भी बिगाड़ते हैं।"},
  {"id":"comp-ms-office-internet-441","question":"What does the Excel formula =HOUR(\"14:45\") + MINUTE(\"14:45\") return?","options":["14.75","47","#VALUE!","59"],"answer":3,"explanation":"Excel converts the text \"14:45\" to a time; HOUR gives 14 and MINUTE gives 45, and their sum is 59. Using 2 for 2 PM would give 47.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =HOUR(\"14:45\") + MINUTE(\"14:45\") क्या लौटाता है?","optionsHi":["14.75","47","#VALUE!","59"],"explanationHi":"Excel पाठ \"14:45\" को समय में बदलता है; HOUR 14 और MINUTE 45 देता है, और उनका योग 59 है। अपराह्न 2 के लिए 2 का उपयोग करने पर 47 मिलता।"},
  {"id":"comp-ms-office-internet-442","question":"What does the Excel formula =TIME(10, 90, 0) show when formatted as a time?","options":["10:30 AM","12:00 PM","#NUM!","11:30 AM"],"answer":3,"explanation":"TIME carries extra minutes into hours, so 90 minutes becomes 1 hour 30 minutes, giving 11:30 AM. Similarly, DATE carries extra months into years.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"समय के रूप में फ़ॉर्मेट करने पर Excel का सूत्र =TIME(10, 90, 0) क्या दिखाता है?","optionsHi":["10:30 AM","12:00 PM","#NUM!","11:30 AM"],"explanationHi":"TIME अतिरिक्त मिनटों को घंटों में जोड़ देता है, इसलिए 90 मिनट 1 घंटा 30 मिनट बन जाते हैं, जिससे 11:30 AM मिलता है। इसी तरह DATE अतिरिक्त माह को वर्षों में जोड़ता है।"},
  {"id":"comp-ms-office-internet-443","question":"What does the Excel formula =(\"18:00\" - \"09:30\") * 24 return?","options":["8.5","8.3","0.35","#VALUE!"],"answer":0,"explanation":"Excel converts both time texts to fractions of a day; their difference is 8 h 30 min, and multiplying by 24 converts it to hours: 8.5. Without × 24 the result would be about 0.35.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel का सूत्र =(\"18:00\" - \"09:30\") * 24 क्या लौटाता है?","optionsHi":["8.5","8.3","0.35","#VALUE!"],"explanationHi":"Excel दोनों समय पाठों को दिन के अंशों में बदलता है; उनका अंतर 8 घंटे 30 मिनट है, और 24 से गुणा करने पर घंटों में 8.5 मिलता है। × 24 के बिना परिणाम लगभग 0.35 होता।"},
  {"id":"comp-ms-office-internet-444","question":"Which statement about the Excel functions =TODAY() and =NOW() is correct?","options":["TODAY gives the date and time and NOW gives the time only; neither ever updates","Both give the date and the time, but only NOW updates when the sheet recalculates","TODAY gives the date only and NOW gives date and time; both update on recalculation","Both are fixed at the moment the formula is typed, like Ctrl + ; and Ctrl + Shift + ;"],"answer":2,"explanation":"TODAY returns the current date and NOW the current date and time; both are volatile and refresh on recalculation. Ctrl + ; and Ctrl + Shift + ; type fixed values instead.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"Excel फ़ंक्शन =TODAY() और =NOW() के बारे में कौन-सा कथन सही है?","optionsHi":["TODAY तारीख़ और समय देता है और NOW केवल समय देता है; कोई कभी अपडेट नहीं होता","दोनों तारीख़ और समय देते हैं, पर केवल NOW शीट की पुनर्गणना पर अपडेट होता है","TODAY केवल तारीख़ देता है और NOW तारीख़ व समय; दोनों पुनर्गणना पर अपडेट होते हैं","दोनों सूत्र टाइप करने के क्षण पर स्थिर हो जाते हैं, जैसे Ctrl + ; और Ctrl + Shift + ;"],"explanationHi":"TODAY वर्तमान तारीख़ और NOW वर्तमान तारीख़ व समय लौटाता है; दोनों वोलेटाइल हैं और पुनर्गणना पर ताज़ा होते हैं। Ctrl + ; और Ctrl + Shift + ; इसके बजाय स्थिर मान टाइप करते हैं।"},
  {"id":"comp-ms-office-internet-445","question":"5 January 2024 was a Friday. What date does =WORKDAY(DATE(2024, 1, 5), 3) return in Excel (no holidays given)?","options":["8 January 2024","10 January 2024","9 January 2024","11 January 2024"],"answer":1,"explanation":"WORKDAY skips weekends: from Friday 5 January, the next three working days are Monday 8, Tuesday 9 and Wednesday 10 January.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"5 जनवरी 2024 शुक्रवार था। Excel में =WORKDAY(DATE(2024, 1, 5), 3) कौन-सी तारीख़ लौटाता है (कोई अवकाश नहीं दिया गया)?","optionsHi":["8 जनवरी 2024","10 जनवरी 2024","9 जनवरी 2024","11 जनवरी 2024"],"explanationHi":"WORKDAY सप्ताहांत छोड़ देता है: शुक्रवार 5 जनवरी से अगले तीन कार्य-दिवस सोमवार 8, मंगलवार 9 और बुधवार 10 जनवरी हैं।"},
  {"id":"comp-ms-office-internet-446","question":"What does the Excel formula =NPV(10%, 110, 121) return?","options":["220","231","200","210"],"answer":2,"explanation":"NPV discounts the first value by one period and the second by two: 110/1.1 + 121/1.21 = 100 + 100 = 200. Treating the first value as today's money would wrongly give 220.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel का सूत्र =NPV(10%, 110, 121) क्या लौटाता है?","optionsHi":["220","231","200","210"],"explanationHi":"NPV पहले मान का एक अवधि और दूसरे का दो अवधि का बट्टा करता है: 110/1.1 + 121/1.21 = 100 + 100 = 200। पहले मान को आज का धन मानने पर गलती से 220 मिलता।"},
  {"id":"comp-ms-office-internet-447","question":"A machine costs ₹10,000, has a salvage value of ₹1,000 and a life of 5 years. What does the Excel formula =SLN(10000, 1000, 5) return?","options":["2000","1800","2200","9000"],"answer":1,"explanation":"SLN gives straight-line depreciation per year: (cost - salvage) / life = 9000 / 5 = 1800. Ignoring the salvage value would give 2000.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक मशीन की लागत ₹10,000 है, उसका अवशेष मूल्य ₹1,000 है और जीवनकाल 5 वर्ष है। Excel का सूत्र =SLN(10000, 1000, 5) क्या लौटाता है?","optionsHi":["2000","1800","2200","9000"],"explanationHi":"SLN प्रति वर्ष सीधी-रेखा मूल्यह्रास देता है: (लागत - अवशेष मूल्य) / जीवनकाल = 9000 / 5 = 1800। अवशेष मूल्य को अनदेखा करने पर 2000 मिलता।"},
  {"id":"comp-ms-office-internet-448","question":"What does the Excel formula =ROUND(5/3, 2) * 3 return?","options":["5.01","5","4.98","5.1"],"answer":0,"explanation":"5/3 = 1.6667, which ROUND makes 1.67, and 1.67 × 3 = 5.01. Doing the maths exactly gives 5, truncating to 1.66 gives 4.98, and rounding to one decimal (1.7) gives 5.1; rounding before multiplying is a classic error in tax and percentage sheets.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =ROUND(5/3, 2) * 3 क्या लौटाता है?","optionsHi":["5.01","5","4.98","5.1"],"explanationHi":"5/3 = 1.6667, जिसे ROUND 1.67 बना देता है, और 1.67 × 3 = 5.01। ठीक-ठीक गणित करने पर 5 मिलता है, 1.66 तक काटने पर 4.98, और एक दशमलव तक पूर्णांकित (1.7) करने पर 5.1; गुणा से पहले पूर्णांकित करना कर और प्रतिशत की शीटों में एक आम त्रुटि है।"},
  {"id":"comp-ms-office-internet-449","question":"In Excel, A1:A6 contain 35, 40, 55, 60, 72 and 48. What does =COUNTIFS(A1:A6, \">=40\", A1:A6, \"<=60\") return?","options":["2","6","3","4"],"answer":3,"explanation":"COUNTIFS needs both conditions, so it counts values from 40 to 60 inclusive: 40, 55, 60 and 48. Using strict > and < would leave only 55 and 48.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel में A1:A6 में 35, 40, 55, 60, 72 और 48 हैं। =COUNTIFS(A1:A6, \">=40\", A1:A6, \"<=60\") क्या लौटाता है?","optionsHi":["2","6","3","4"],"explanationHi":"COUNTIFS को दोनों शर्तें चाहिए, इसलिए यह 40 से 60 तक (दोनों सहित) मान गिनता है: 40, 55, 60 और 48। सख्त > और < का उपयोग करने पर केवल 55 और 48 बचते।"},
  {"id":"comp-ms-office-internet-450","question":"In Excel, A1:A6 contain 12, 58, 33, 71, 50, 49 and B1 = 50. What do =SUMIF(A1:A6, \">\"&B1) and =SUMIF(A1:A6, \">B1\") return respectively?","options":["129 and 129","179 and 0","0 and 129","129 and 0"],"answer":3,"explanation":"\">\"&B1 builds the criterion \">50\", adding 58 + 71 = 129. Inside quotes, \">B1\" compares with the text B1, which no number matches, so the second gives 0.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1:A6 में 12, 58, 33, 71, 50, 49 हैं और B1 = 50 है। =SUMIF(A1:A6, \">\"&B1) और =SUMIF(A1:A6, \">B1\") क्रमशः क्या लौटाते हैं?","optionsHi":["129 और 129","179 और 0","0 और 129","129 और 0"],"explanationHi":"\">\"&B1 मानदंड \">50\" बनाता है, जो 58 + 71 = 129 जोड़ता है। उद्धरण चिह्नों के भीतर \">B1\" पाठ B1 से तुलना करता है, जिससे कोई संख्या मेल नहीं खाती, इसलिए दूसरा 0 देता है।"},
  {"id":"comp-ms-office-internet-451","question":"A1 holds last year's sales (80) and B1 this year's sales (100). Which formula, formatted as a percentage, gives the percentage increase?","options":["=(B1-A1)/B1","=(B1-A1)/A1","=B1/A1-100","=(A1-B1)/A1"],"answer":1,"explanation":"Increase is measured on the old value: (100 - 80)/80 = 25%. Dividing by the new value gives 20%, and B1/A1 - 1 (not - 100) would also work.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"A1 में पिछले वर्ष की बिक्री (80) है और B1 में इस वर्ष की (100)। कौन-सा सूत्र, प्रतिशत के रूप में फ़ॉर्मेट होकर, प्रतिशत वृद्धि देता है?","optionsHi":["=(B1-A1)/B1","=(B1-A1)/A1","=B1/A1-100","=(A1-B1)/A1"],"explanationHi":"वृद्धि पुराने मान पर मापी जाती है: (100 - 80)/80 = 25%। नए मान से भाग देने पर 20% मिलता है, और B1/A1 - 1 (न कि - 100) भी काम करता।"},
  {"id":"comp-ms-office-internet-452","question":"15 August 2024 was a Thursday. What does =TEXT(DATE(2024, 8, 15), \"dddd\") return?","options":["Thu","Wednesday","Thursday","15"],"answer":2,"explanation":"In a TEXT format, dddd gives the full weekday name and ddd the short name (Thu); dd would give the day number.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"15 अगस्त 2024 गुरुवार था। =TEXT(DATE(2024, 8, 15), \"dddd\") क्या लौटाता है?","optionsHi":["Thu","Wednesday","Thursday","15"],"explanationHi":"TEXT फ़ॉर्मेट में dddd सप्ताह के दिन का पूरा नाम देता है और ddd संक्षिप्त नाम (Thu); dd दिन की संख्या देता।"},
  {"id":"comp-ms-office-internet-453","question":"What does the Excel formula =TEXT(0.5, \"hh:mm\") return?","options":["12:00","00:30","05:00","00:05"],"answer":0,"explanation":"Excel stores time as a fraction of a day, so 0.5 is half a day, 12 hours, and the hh:mm format shows 12:00.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =TEXT(0.5, \"hh:mm\") क्या लौटाता है?","optionsHi":["12:00","00:30","05:00","00:05"],"explanationHi":"Excel समय को दिन के अंश के रूप में संग्रहीत करता है, इसलिए 0.5 आधा दिन यानी 12 घंटे है, और hh:mm फ़ॉर्मेट 12:00 दिखाता है।"},
  {"id":"comp-ms-office-internet-454","question":"What does the Excel formula =LEN(TEXT(1234.5, \"#,##0.00\")) return?","options":["6","8","7","10"],"answer":1,"explanation":"TEXT returns the string 1,234.50, which has 8 characters including the comma and decimal point. LEN of the plain number 1234.5 is 6, forgetting the thousands comma gives 7, and counting the format's quote marks as characters gives 10.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel का सूत्र =LEN(TEXT(1234.5, \"#,##0.00\")) क्या लौटाता है?","optionsHi":["6","8","7","10"],"explanationHi":"TEXT स्ट्रिंग 1,234.50 लौटाता है, जिसमें अल्पविराम और दशमलव बिंदु सहित 8 वर्ण हैं। सादी संख्या 1234.5 का LEN 6 है, हज़ार के अल्पविराम को भूलने पर 7 मिलता है, और फ़ॉर्मेट के उद्धरण चिह्नों को वर्ण गिनने पर 10।"},
  {"id":"comp-ms-office-internet-455","question":"In MS Word, the shortcuts Ctrl + 1, Ctrl + 2 and Ctrl + 5 set the line spacing of a paragraph to:","options":["1, 2 and 5 lines respectively","single, 1.5 and double lines respectively","single, double and 1.5 lines respectively","double, single and 1.5 lines respectively"],"answer":2,"explanation":"Ctrl + 1 gives single spacing, Ctrl + 2 double spacing and Ctrl + 5 one-and-a-half (1.5) spacing; the 5 stands for .5, not five lines.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"MS Word में शॉर्टकट Ctrl + 1, Ctrl + 2 और Ctrl + 5 अनुच्छेद का पंक्ति अंतराल क्रमशः क्या सेट करते हैं?","optionsHi":["क्रमशः 1, 2 और 5 पंक्ति","क्रमशः एकल, 1.5 और दोहरी पंक्ति","क्रमशः एकल, दोहरी और 1.5 पंक्ति","क्रमशः दोहरी, एकल और 1.5 पंक्ति"],"explanationHi":"Ctrl + 1 एकल अंतराल देता है, Ctrl + 2 दोहरा अंतराल और Ctrl + 5 डेढ़ (1.5) अंतराल; 5 का अर्थ .5 है, पाँच पंक्तियाँ नहीं।"},
  {"id":"comp-ms-office-internet-456","question":"In MS Word, what happens when Ctrl + M is pressed twice with the cursor in a paragraph?","options":["Only the first line of the paragraph is indented by two tab stops","The left indent of the whole paragraph moves two tab-stop steps right","A hanging indent two tab-stop steps deep is applied to the paragraph","Two tab characters are typed in front of the first word of the paragraph"],"answer":1,"explanation":"Ctrl + M increases the left indent of the entire paragraph by one step each time (Ctrl + Shift + M reduces it). Ctrl + T is the hanging indent shortcut.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Word में, कर्सर किसी अनुच्छेद में होने पर Ctrl + M दो बार दबाने से क्या होता है?","optionsHi":["अनुच्छेद की केवल पहली पंक्ति दो टैब स्टॉप से इंडेंट हो जाती है","पूरे अनुच्छेद का बायाँ इंडेंट दो टैब-स्टॉप कदम दाईं ओर खिसक जाता है","अनुच्छेद पर दो टैब-स्टॉप कदम गहरा हैंगिंग इंडेंट लग जाता है","अनुच्छेद के पहले शब्द के आगे दो टैब वर्ण टाइप हो जाते हैं"],"explanationHi":"Ctrl + M हर बार पूरे अनुच्छेद का बायाँ इंडेंट एक कदम बढ़ाता है (Ctrl + Shift + M उसे घटाता है)। Ctrl + T हैंगिंग इंडेंट का शॉर्टकट है।"},
  {"id":"comp-ms-office-internet-457","question":"In MS Word, what does Alt + Shift + Up Arrow do when the cursor is in a paragraph?","options":["Moves the whole paragraph above the paragraph before it","Selects the text from the cursor to the start of the paragraph","Moves the cursor to the start of the previous paragraph","Promotes the paragraph to a higher heading level"],"answer":0,"explanation":"Alt + Shift + Up/Down moves the paragraph itself up or down. Ctrl + Shift + Up selects to the paragraph start, Ctrl + Up only moves the cursor, and Alt + Shift + Left promotes a heading.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Word में, कर्सर अनुच्छेद में होने पर Alt + Shift + ऊपर तीर क्या करता है?","optionsHi":["पूरे अनुच्छेद को उसके पहले वाले अनुच्छेद के ऊपर ले जाता है","कर्सर से अनुच्छेद के आरंभ तक का टेक्स्ट चयनित करता है","कर्सर को पिछले अनुच्छेद के आरंभ पर ले जाता है","अनुच्छेद को ऊँचे शीर्षक स्तर पर उन्नत करता है"],"explanationHi":"Alt + Shift + ऊपर/नीचे अनुच्छेद को स्वयं ऊपर या नीचे ले जाता है। Ctrl + Shift + ऊपर अनुच्छेद के आरंभ तक चयनित करता है, Ctrl + ऊपर केवल कर्सर ले जाता है, और Alt + Shift + बायाँ शीर्षक को उन्नत करता है।"},
  {"id":"comp-ms-office-internet-458","question":"In MS Word, which shortcut opens the Word Count dialog showing pages, words, characters and paragraphs?","options":["Ctrl + Shift + W","Ctrl + Shift + C","Alt + Shift + W","Ctrl + Shift + G"],"answer":3,"explanation":"Ctrl + Shift + G opens Word Count. Ctrl + Shift + W applies a words-only underline and Ctrl + Shift + C copies formatting.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Word में कौन-सा शॉर्टकट पेज, शब्द, वर्ण और अनुच्छेद दिखाने वाला Word Count डायलॉग खोलता है?","optionsHi":["Ctrl + Shift + W","Ctrl + Shift + C","Alt + Shift + W","Ctrl + Shift + G"],"explanationHi":"Ctrl + Shift + G Word Count खोलता है। Ctrl + Shift + W केवल शब्दों की अधोरेखा लगाता है और Ctrl + Shift + C फ़ॉर्मेटिंग कॉपी करता है।"},
  {"id":"comp-ms-office-internet-459","question":"After reopening a long Word document, the user wants to jump straight back to the place where the last change was made. Which shortcut does this?","options":["Shift + F5","Ctrl + End","Ctrl + Home","Alt + F5"],"answer":0,"explanation":"Shift + F5 moves to the previous editing locations, including the last edit after the document is reopened. Ctrl + End and Ctrl + Home only go to the end or start.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी लंबे Word दस्तावेज़ को दोबारा खोलने के बाद, उपयोगकर्ता सीधे उस जगह लौटना चाहता है जहाँ अंतिम परिवर्तन किया गया था। कौन-सा शॉर्टकट यह करता है?","optionsHi":["Shift + F5","Ctrl + End","Ctrl + Home","Alt + F5"],"explanationHi":"Shift + F5 पिछले संपादन स्थानों पर जाता है, जिसमें दस्तावेज़ दोबारा खोलने के बाद अंतिम संपादन भी शामिल है। Ctrl + End और Ctrl + Home केवल अंत या आरंभ पर ले जाते हैं।"},
  {"id":"comp-ms-office-internet-460","question":"In MS Word, what does Ctrl + Delete remove?","options":["The word to the left of the cursor","The whole line the cursor is on","The whole paragraph the cursor is in","The word to the right of the cursor"],"answer":3,"explanation":"Ctrl + Delete deletes forward to the end of the word on the right of the cursor, while Ctrl + Backspace deletes the word on the left.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"MS Word में Ctrl + Delete क्या हटाता है?","optionsHi":["कर्सर के बाईं ओर का शब्द","कर्सर जिस पंक्ति पर है वह पूरी पंक्ति","कर्सर जिस अनुच्छेद में है वह पूरा अनुच्छेद","कर्सर के दाईं ओर का शब्द"],"explanationHi":"Ctrl + Delete कर्सर के दाईं ओर के शब्द के अंत तक आगे की ओर हटाता है, जबकि Ctrl + Backspace बाईं ओर का शब्द हटाता है।"},
  {"id":"comp-ms-office-internet-461","question":"A legal draft in Word must show a number beside every line in the left margin so that reviewers can refer to, say, line 23 on page 4. Which feature should be used?","options":["Numbering (Home tab)","Page Number (Insert tab)","Line Numbers (Layout tab)","Footnote (References tab)"],"answer":2,"explanation":"Line Numbers prints a count beside each line in the margin, optionally restarting each page or section. The Numbering button only numbers paragraphs as a list.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी Word कानूनी मसौदे में बाएँ हाशिये में हर पंक्ति के बगल में संख्या दिखनी चाहिए ताकि समीक्षक, मान लीजिए, पेज 4 की पंक्ति 23 का हवाला दे सकें। किस सुविधा का उपयोग करना चाहिए?","optionsHi":["Numbering (Home टैब)","Page Number (Insert टैब)","Line Numbers (Layout टैब)","Footnote (References टैब)"],"explanationHi":"Line Numbers हाशिये में हर पंक्ति के बगल में गिनती छापता है, वैकल्पिक रूप से हर पेज या सेक्शन पर पुनः आरंभ होकर। Numbering बटन केवल अनुच्छेदों को सूची के रूप में क्रमांकित करता है।"},
  {"id":"comp-ms-office-internet-462","question":"A clerk types the same four-line disclaimer at the end of many Word letters every day. Which feature stores it as a reusable block that can be picked from a gallery or inserted by typing its name and pressing F3?","options":["Format Painter (Home tab)","Quick Parts (AutoText)","Mail Merge (Mailings tab)","AutoCorrect (Options)"],"answer":1,"explanation":"Quick Parts stores AutoText building blocks; typing an entry's name and pressing F3 inserts it. Format Painter copies only formatting, not text.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक क्लर्क हर दिन कई Word पत्रों के अंत में वही चार-पंक्ति का अस्वीकरण (disclaimer) टाइप करता है। कौन-सी सुविधा उसे पुनः प्रयोग योग्य ब्लॉक के रूप में संग्रहीत करती है जिसे गैलरी से चुना जा सकता है या उसका नाम टाइप करके F3 दबाकर डाला जा सकता है?","optionsHi":["Format Painter (Home टैब)","Quick Parts (AutoText)","Mail Merge (Mailings टैब)","AutoCorrect (Options)"],"explanationHi":"Quick Parts AutoText बिल्डिंग ब्लॉक संग्रहीत करता है; किसी प्रविष्टि का नाम टाइप करके F3 दबाने से वह डल जाती है। Format Painter केवल फ़ॉर्मेटिंग कॉपी करता है, पाठ नहीं।"},
  {"id":"comp-ms-office-internet-463","question":"In MS Excel, what does Ctrl + Shift + & do to the selected cells?","options":["Removes every border from the selected cells","Applies the currency format with the ₹ sign","Joins the text of the selected cells with &","Applies an outline border around the selection"],"answer":3,"explanation":"Ctrl + Shift + & adds an outline border around the selection and Ctrl + Shift + _ removes borders. & joins text only inside a formula.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"MS Excel में, Ctrl + Shift + & चयनित सेलों के साथ क्या करता है?","optionsHi":["चयनित सेलों से हर बॉर्डर हटा देता है","₹ चिह्न के साथ करेंसी फ़ॉर्मेट लगाता है","चयनित सेलों के पाठ को & से जोड़ता है","चयन के चारों ओर आउटलाइन बॉर्डर लगाता है"],"explanationHi":"Ctrl + Shift + & चयन के चारों ओर आउटलाइन बॉर्डर जोड़ता है और Ctrl + Shift + _ बॉर्डर हटाता है। & पाठ को केवल सूत्र के भीतर जोड़ता है।"},
  {"id":"comp-ms-office-internet-464","question":"In Excel, A1 contains 1234.567 in General format. It is selected and Ctrl + Shift + ! is pressed. What does the cell show?","options":["1234.57","1,234.57","1,235","1.23E+03"],"answer":1,"explanation":"Ctrl + Shift + ! applies the Number format with two decimal places and a thousands separator, so the value displays as 1,234.57 (the stored value stays 1234.567).","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 में General फ़ॉर्मेट में 1234.567 है। उसे चयनित करके Ctrl + Shift + ! दबाया जाता है। सेल क्या दिखाता है?","optionsHi":["1234.57","1,234.57","1,235","1.23E+03"],"explanationHi":"Ctrl + Shift + ! दो दशमलव स्थान और हज़ार विभाजक के साथ Number फ़ॉर्मेट लगाता है, इसलिए मान 1,234.57 के रूप में दिखता है (संग्रहीत मान 1234.567 ही रहता है)।"},
  {"id":"comp-ms-office-internet-465","question":"In Excel, column A has entries in A1:A500 with no blank cells. The cursor is in A1 and Ctrl + Down Arrow is pressed. Where does it go?","options":["A2","A1048576","A500","A501"],"answer":2,"explanation":"Ctrl + arrow jumps to the edge of the current data region, here the last filled cell, A500. It would go to the last row of the sheet only if the cells below A1 were empty.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"Excel में कॉलम A की प्रविष्टियाँ A1:A500 में हैं और कोई सेल रिक्त नहीं है। कर्सर A1 में है और Ctrl + नीचे तीर दबाया जाता है। वह कहाँ जाता है?","optionsHi":["A2","A1048576","A500","A501"],"explanationHi":"Ctrl + तीर वर्तमान डेटा क्षेत्र के किनारे पर कूदता है, यहाँ अंतिम भरे सेल A500 पर। वह शीट की अंतिम पंक्ति पर तभी जाता जब A1 के नीचे के सेल खाली होते।"},
  {"id":"comp-ms-office-internet-466","question":"In a large Excel sheet, what is a quick way to jump straight to cell T4500 without scrolling?","options":["Type T4500 in the Name Box and press Enter","Press Ctrl + Home and then the Down Arrow key","Turn on Freeze Panes at row 4500 of column T","Press Ctrl + End and then the Left Arrow key"],"answer":0,"explanation":"The Name Box, to the left of the formula bar, accepts a cell address and jumps there (as does Go To, Ctrl + G). Ctrl + Home and Ctrl + End go to the start or the last used cell.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"किसी बड़ी Excel शीट में, स्क्रॉल किए बिना सीधे सेल T4500 पर कूदने का तेज़ तरीका क्या है?","optionsHi":["Name Box में T4500 टाइप करके Enter दबाएँ","Ctrl + Home दबाएँ और फिर नीचे तीर कुंजी","कॉलम T की पंक्ति 4500 पर Freeze Panes चालू करें","Ctrl + End दबाएँ और फिर बायाँ तीर"],"explanationHi":"फ़ॉर्मूला बार के बाईं ओर का Name Box सेल पता स्वीकार करके वहाँ कूद जाता है (जैसे Go To, Ctrl + G)। Ctrl + Home और Ctrl + End आरंभ या अंतिम प्रयुक्त सेल पर जाते हैं।"},
  {"id":"comp-ms-office-internet-467","question":"An officer selects B2:B40 in Excel and needs their total and average at once, without typing any formula. Where can they be seen?","options":["In the formula bar above the column letters","In the Name Box to the left of the formula bar","In the status bar at the bottom of the window","In the title bar at the top of the window"],"answer":2,"explanation":"For a selection of numbers, the status bar shows Average, Count and Sum by default, and more statistics can be added by right-clicking it.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"एक अधिकारी Excel में B2:B40 चयनित करता है और बिना कोई सूत्र टाइप किए उनका कुल और औसत एक साथ चाहता है। वे कहाँ देखे जा सकते हैं?","optionsHi":["कॉलम अक्षरों के ऊपर फ़ॉर्मूला बार में","फ़ॉर्मूला बार के बाईं ओर Name Box में","विंडो के नीचे स्टेटस बार में","विंडो के ऊपर टाइटल बार में"],"explanationHi":"संख्याओं के चयन के लिए स्टेटस बार डिफ़ॉल्ट रूप से Average, Count और Sum दिखाता है, और उस पर राइट-क्लिक करके और आँकड़े जोड़े जा सकते हैं।"},
  {"id":"comp-ms-office-internet-468","question":"In Excel, A1 = Branch, B1 = Delhi and C1 = 2024. A1:C1 is selected and Merge & Center is applied, and the warning is accepted. What does the merged cell show?","options":["Branch Delhi 2024, joined with spaces","Only 2024, the last value in the range","Nothing, as all three values are cleared","Only Branch, centred across the merged cell"],"answer":3,"explanation":"Merging keeps only the upper-left value and discards the rest after a warning. To join texts, use a formula such as =A1&\" \"&B1&\" \"&C1.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel में A1 = Branch, B1 = Delhi और C1 = 2024 है। A1:C1 चयनित करके Merge & Center लागू किया जाता है, और चेतावनी स्वीकार कर ली जाती है। मर्ज किया सेल क्या दिखाता है?","optionsHi":["Branch Delhi 2024, रिक्त स्थानों से जुड़ा हुआ","केवल 2024, रेंज का अंतिम मान","कुछ नहीं, क्योंकि तीनों मान साफ़ हो जाते हैं","केवल Branch, मर्ज किए सेल में केंद्र में"],"explanationHi":"मर्ज करने पर केवल ऊपर-बाएँ का मान रहता है और चेतावनी के बाद शेष हटा दिए जाते हैं। पाठ जोड़ने के लिए =A1&\" \"&B1&\" \"&C1 जैसे सूत्र का उपयोग करें।"},
  {"id":"comp-ms-office-internet-469","question":"A long branch name must stay on ONE line inside a narrow Excel column, with its font made smaller automatically to fit. Which cell format option does this?","options":["Wrap text","Shrink to fit","Merge cells","AutoFit Column Width"],"answer":1,"explanation":"Shrink to fit reduces the displayed font size so the text fits the cell width. Wrap text splits it over several lines, and AutoFit widens the column instead.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी लंबे शाखा नाम को संकरे Excel कॉलम में एक ही पंक्ति में रहना है, और उसका फ़ॉन्ट अपने आप छोटा होकर समा जाना चाहिए। सेल फ़ॉर्मेट का कौन-सा विकल्प यह करता है?","optionsHi":["Wrap text","Shrink to fit","Merge cells","AutoFit Column Width"],"explanationHi":"Shrink to fit प्रदर्शित फ़ॉन्ट आकार घटा देता है ताकि पाठ सेल की चौड़ाई में समा जाए। Wrap text उसे कई पंक्तियों में बाँटता है, और AutoFit इसके बजाय कॉलम चौड़ा करता है।"},
  {"id":"comp-ms-office-internet-470","question":"A sheet has names in column A and balances in column B. A user selects only column B, sorts it largest to smallest, and chooses Continue with the current selection. What is the result?","options":["Balances get reordered but names stay put, so the rows no longer match","Names and balances are both sorted together, keeping each row intact","Excel sorts nothing, since one column alone cannot be sorted","Names are sorted A to Z and balances largest to smallest"],"answer":0,"explanation":"Continue with the current selection sorts only the selected column, breaking the link between each name and its balance. Expand the selection keeps whole rows together.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक शीट में कॉलम A में नाम और कॉलम B में शेष राशियाँ हैं। एक उपयोगकर्ता केवल कॉलम B चयनित करता है, उसे बड़े से छोटे के क्रम में सॉर्ट करता है, और Continue with the current selection चुनता है। परिणाम क्या होता है?","optionsHi":["शेष राशियाँ पुनः क्रमबद्ध हो जाती हैं पर नाम अपनी जगह रहते हैं, इसलिए पंक्तियाँ अब मेल नहीं खातीं","नाम और शेष राशियाँ दोनों साथ-साथ सॉर्ट होते हैं, हर पंक्ति अक्षुण्ण रहती है","Excel कुछ सॉर्ट नहीं करता, क्योंकि अकेला कॉलम सॉर्ट नहीं हो सकता","नाम A से Z और शेष राशियाँ बड़े से छोटे के क्रम में सॉर्ट होती हैं"],"explanationHi":"Continue with the current selection केवल चयनित कॉलम को सॉर्ट करता है, जिससे हर नाम और उसकी शेष राशि का संबंध टूट जाता है। Expand the selection पूरी पंक्तियों को साथ रखता है।"},
  {"id":"comp-ms-office-internet-471","question":"Data > Subtotal is run on a list to give a total for each region, but the result shows several separate subtotals for the same region. What was missed?","options":["The list was not first formatted as an Excel Table","The list was not first sorted by the region column","The region column was not set to the Text format","Filters were not turned on before running Subtotal"],"answer":1,"explanation":"The Subtotal command inserts a total each time the value in the grouping column changes, so the data must be sorted by that column first to bring each region together.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"किसी सूची पर प्रत्येक क्षेत्र का कुल देने के लिए Data > Subtotal चलाया जाता है, पर परिणाम में एक ही क्षेत्र के कई अलग-अलग उप-योग दिखते हैं। क्या चूक हुई?","optionsHi":["सूची को पहले Excel Table के रूप में फ़ॉर्मेट नहीं किया गया","सूची को पहले क्षेत्र कॉलम के अनुसार सॉर्ट नहीं किया गया","क्षेत्र कॉलम को Text फ़ॉर्मेट पर सेट नहीं किया गया","Subtotal चलाने से पहले फ़िल्टर चालू नहीं किए गए"],"explanationHi":"Subtotal आदेश हर बार तब कुल डालता है जब समूहीकरण कॉलम का मान बदलता है, इसलिए डेटा को पहले उसी कॉलम से सॉर्ट करना होता है ताकि हर क्षेत्र एक साथ आए।"},
  {"id":"comp-ms-office-internet-472","question":"Twelve monthly sheets with the same layout must be combined into one summary sheet that adds matching figures by position or by label. Which Excel feature does this?","options":["Consolidate","Flash Fill","Text to Columns","Remove Duplicates"],"answer":0,"explanation":"Data > Consolidate combines ranges from several sheets using a function such as Sum, matching them by position or by row and column labels.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक ही लेआउट वाली बारह मासिक शीटों को एक सार शीट में मिलाना है जो संगत आँकड़ों को स्थिति या लेबल के अनुसार जोड़ती है। Excel की कौन-सी सुविधा यह करती है?","optionsHi":["Consolidate","Flash Fill","Text to Columns","Remove Duplicates"],"explanationHi":"Data > Consolidate कई शीटों की रेंजों को Sum जैसे फ़ंक्शन से, स्थिति या पंक्ति व कॉलम लेबल से मिलाकर, जोड़ता है।"},
  {"id":"comp-ms-office-internet-473","question":"One Excel chart must show monthly sales (in thousands of rupees) as columns and growth percentage (single digits) as a line, with both readable. What should be used?","options":["A pie chart with both series shown in the same pie","A single-axis line chart with both series as lines","A combo chart with the growth series on a secondary axis","Two sparklines placed in one cell next to each other"],"answer":2,"explanation":"On one axis, the small percentages would sit flat near zero. A combo chart plots one series as columns and the other as a line on its own secondary axis.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक Excel चार्ट को मासिक बिक्री (हज़ार रुपये में) स्तंभों के रूप में और वृद्धि प्रतिशत (इकाई अंकों में) रेखा के रूप में दिखाना है, दोनों पठनीय रहें। क्या उपयोग करना चाहिए?","optionsHi":["पाई चार्ट, जिसमें दोनों श्रेणियाँ एक ही पाई में दिखें","एकल-अक्ष लाइन चार्ट, जिसमें दोनों श्रेणियाँ रेखाओं के रूप में हों","कॉम्बो चार्ट, जिसमें वृद्धि श्रेणी द्वितीयक अक्ष पर हो","एक सेल में साथ-साथ रखी दो स्पार्कलाइन"],"explanationHi":"एक ही अक्ष पर छोटे प्रतिशत शून्य के पास सपाट रहते। कॉम्बो चार्ट एक श्रेणी को स्तंभ के रूप में और दूसरी को उसके अपने द्वितीयक अक्ष पर रेखा के रूप में दर्शाता है।"},
  {"id":"comp-ms-office-internet-474","question":"Figures in the source data of an Excel PivotTable are corrected, but the PivotTable still shows the old totals. What is needed?","options":["Press F9 to recalculate","Re-sort the source data","Turn off AutoFilter","Refresh the PivotTable"],"answer":3,"explanation":"A PivotTable works from a stored cache of the source, so it updates only when refreshed (Refresh or Alt + F5). F9 recalculates formulas but not PivotTables.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"Excel PivotTable के स्रोत डेटा में आँकड़े सुधार दिए जाते हैं, पर PivotTable अब भी पुराने कुल दिखाता है। क्या चाहिए?","optionsHi":["पुनर्गणना के लिए F9 दबाएँ","स्रोत डेटा को दोबारा सॉर्ट करें","AutoFilter बंद करें","PivotTable को रिफ़्रेश करें"],"explanationHi":"PivotTable स्रोत के संग्रहीत कैश से काम करता है, इसलिए वह रिफ़्रेश करने पर ही अपडेट होता है (Refresh या Alt + F5)। F9 सूत्रों की पुनर्गणना करता है, PivotTable की नहीं।"},
  {"id":"comp-ms-office-internet-475","question":"In Excel Data Validation, which Error Alert style shows a message asking whether to continue, and accepts the invalid entry if the user clicks Yes?","options":["Stop","Information","Warning","Input Message"],"answer":2,"explanation":"Stop refuses invalid data, Warning asks Continue? and accepts it on Yes, and Information only informs and accepts it on OK. Input Message is a hint shown before typing, not an alert.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"Excel Data Validation में कौन-सी Error Alert शैली यह पूछने वाला संदेश दिखाती है कि जारी रखना है या नहीं, और उपयोगकर्ता के Yes क्लिक करने पर अमान्य प्रविष्टि स्वीकार कर लेती है?","optionsHi":["Stop","Information","Warning","Input Message"],"explanationHi":"Stop अमान्य डेटा अस्वीकार करता है, Warning पूछता है Continue? और Yes पर उसे स्वीकार कर लेता है, और Information केवल सूचित करता है और OK पर स्वीकार करता है। Input Message टाइप करने से पहले दिखने वाला संकेत है, चेतावनी नहीं।"},
  {"id":"comp-ms-office-internet-476","question":"In PowerPoint 2013 and later, what is the default slide size for a new blank presentation?","options":["Standard (4:3)","A4 Paper","Widescreen (16:10)","Widescreen (16:9)"],"answer":3,"explanation":"Since PowerPoint 2013 new presentations are widescreen 16:9; the older 4:3 Standard size can still be chosen in Slide Size.","difficulty":"hard","source":"SBI Clerk Mains · IBPS Clerk Mains","questionHi":"PowerPoint 2013 और उसके बाद के संस्करणों में, नई खाली प्रस्तुति के लिए डिफ़ॉल्ट स्लाइड आकार क्या है?","optionsHi":["Standard (4:3)","A4 Paper","Widescreen (16:10)","Widescreen (16:9)"],"explanationHi":"PowerPoint 2013 से नई प्रस्तुतियाँ वाइडस्क्रीन 16:9 होती हैं; पुराना 4:3 Standard आकार Slide Size में अब भी चुना जा सकता है।"},
  {"id":"comp-ms-office-internet-477","question":"A 60-slide PowerPoint deck needs its slides grouped under named, collapsible headings such as Introduction, Results and Way Forward in Slide Sorter view. Which feature does this?","options":["Sections","Hide Slide","Handout Master","Slide Layout"],"answer":0,"explanation":"Sections divide a deck into named groups that can be collapsed, moved or printed together. Hide Slide only skips a slide during the show.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"60 स्लाइडों वाले PowerPoint डेक की स्लाइडों को Slide Sorter व्यू में Introduction, Results और Way Forward जैसे नामित, संक्षिप्त किए जा सकने वाले शीर्षकों के अंतर्गत समूहित करना है। कौन-सी सुविधा यह करती है?","optionsHi":["Sections","Hide Slide","Handout Master","Slide Layout"],"explanationHi":"Sections डेक को नामित समूहों में बाँटते हैं जिन्हें संक्षिप्त, स्थानांतरित या साथ-साथ प्रिंट किया जा सकता है। Hide Slide केवल शो के दौरान स्लाइड को छोड़ता है।"},
  {"id":"comp-ms-office-internet-478","question":"Match the file extension with its type: 1. .odt 2. .ods 3. .odp 4. .xps; a. Microsoft's fixed-layout document format b. OpenDocument presentation c. OpenDocument spreadsheet d. OpenDocument text document","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-a, 2-c, 3-b, 4-d"],"answer":1,"explanation":"The OpenDocument formats (used by LibreOffice and openable in Office) are .odt for text, .ods for spreadsheets and .odp for presentations. .xps is Microsoft's fixed-layout format, similar to PDF.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"फ़ाइल एक्सटेंशन को उसके प्रकार से सुमेलित कीजिए: 1. .odt 2. .ods 3. .odp 4. .xps; a. Microsoft का निश्चित-लेआउट दस्तावेज़ प्रारूप b. OpenDocument प्रस्तुति c. OpenDocument स्प्रेडशीट d. OpenDocument टेक्स्ट दस्तावेज़","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-a, 2-c, 3-b, 4-d"],"explanationHi":"OpenDocument प्रारूप (LibreOffice द्वारा प्रयुक्त और Office में खुलने योग्य) टेक्स्ट के लिए .odt, स्प्रेडशीट के लिए .ods और प्रस्तुतियों के लिए .odp हैं। .xps Microsoft का निश्चित-लेआउट प्रारूप है, जो PDF जैसा है।"},
  {"id":"comp-ms-office-internet-479","question":"An office replaces its old hub with a switch. Why does network traffic on each computer's cable drop?","options":["A switch compresses every frame so that less data travels on each of the cables","A switch blocks all broadcast traffic, so no computer gets a broadcast again","A switch learns MAC addresses and sends frames only to the receiver's port","A switch encrypts the frames, so the other computers can no longer read them"],"answer":2,"explanation":"A hub repeats every frame out of all ports. A switch keeps a MAC address table and forwards unicast frames only to the right port, though it still floods broadcasts.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कोई कार्यालय अपने पुराने हब की जगह स्विच लगाता है। हर कंप्यूटर की केबल पर नेटवर्क ट्रैफ़िक क्यों घट जाता है?","optionsHi":["स्विच हर फ़्रेम को संपीड़ित करता है, इसलिए हर केबल पर कम डेटा जाता है","स्विच सारा ब्रॉडकास्ट ट्रैफ़िक अवरुद्ध करता है, इसलिए किसी कंप्यूटर को फिर ब्रॉडकास्ट नहीं मिलता","स्विच MAC पते सीखता है और फ़्रेम केवल प्राप्तकर्ता के पोर्ट पर भेजता है","स्विच फ़्रेमों को एन्क्रिप्ट करता है, इसलिए अन्य कंप्यूटर उन्हें अब नहीं पढ़ सकते"],"explanationHi":"हब हर फ़्रेम को सभी पोर्टों से बाहर दोहराता है। स्विच MAC पता तालिका रखता है और यूनिकास्ट फ़्रेम केवल सही पोर्ट पर भेजता है, हालाँकि वह ब्रॉडकास्ट अब भी सभी पोर्टों पर फैलाता है।"},
  {"id":"comp-ms-office-internet-480","question":"Taking 1 KB = 1024 bytes, how many bits are there in a 2 KB file?","options":["2048","16000","8192","16384"],"answer":3,"explanation":"2 KB = 2 × 1024 = 2048 bytes, and each byte has 8 bits, so 2048 × 8 = 16384 bits. 8192 is the number of bits in 1 KB.","difficulty":"moderate","source":"SSC CGL · SBI Clerk","questionHi":"1 KB = 1024 बाइट मानकर, 2 KB की फ़ाइल में कितने बिट होते हैं?","optionsHi":["2048","16000","8192","16384"],"explanationHi":"2 KB = 2 × 1024 = 2048 बाइट, और हर बाइट में 8 बिट होते हैं, इसलिए 2048 × 8 = 16384 बिट। 8192 1 KB के बिटों की संख्या है।"},
  {"id":"comp-ms-office-internet-481","question":"A phone connected by Bluetooth to a smartwatch and wireless earbuds, all within a few metres of the user, forms which type of network?","options":["LAN","PAN","MAN","WAN"],"answer":1,"explanation":"A Personal Area Network links devices around one person over a few metres, typically using Bluetooth. A LAN covers a building or campus.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk","questionHi":"उपयोगकर्ता के कुछ ही मीटर के भीतर, एक फ़ोन जो Bluetooth से स्मार्टवॉच और वायरलेस ईयरबड से जुड़ा है, किस प्रकार का नेटवर्क बनाता है?","optionsHi":["LAN","PAN","MAN","WAN"],"explanationHi":"Personal Area Network किसी एक व्यक्ति के आसपास के उपकरणों को कुछ ही मीटर में जोड़ता है, सामान्यतः Bluetooth से। LAN किसी इमारत या परिसर को कवर करता है।"},
  {"id":"comp-ms-office-internet-482","question":"A bank runs a private website for circulars and leave forms that only its own employees can open, using the same web technology as the internet. This is called an:","options":["Intranet","Extranet","Internet","Ethernet"],"answer":0,"explanation":"An intranet is an organisation's private network using internet protocols, for staff only. An extranet extends part of it to outside partners such as vendors.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"कोई बैंक परिपत्रों और अवकाश फ़ॉर्मों के लिए निजी वेबसाइट चलाता है जिसे केवल उसके अपने कर्मचारी खोल सकते हैं, और जो इंटरनेट जैसी ही वेब तकनीक का उपयोग करती है। इसे क्या कहते हैं?","optionsHi":["इंट्रानेट (Intranet)","एक्स्ट्रानेट (Extranet)","इंटरनेट (Internet)","ईथरनेट (Ethernet)"],"explanationHi":"इंट्रानेट किसी संगठन का निजी नेटवर्क है जो इंटरनेट प्रोटोकॉल का उपयोग करता है, केवल कर्मचारियों के लिए। एक्स्ट्रानेट उसके एक भाग को विक्रेताओं जैसे बाहरी भागीदारों तक बढ़ाता है।"},
  {"id":"comp-ms-office-internet-483","question":"In a BitTorrent download, a file is received in pieces from many users' computers, while the same computer also uploads pieces to others. Which network model is this?","options":["Client-server","Mainframe terminal","Star topology","Peer-to-peer"],"answer":3,"explanation":"In peer-to-peer networking every computer acts as both client and server, sharing pieces directly. In client-server, central servers provide the service to clients.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"BitTorrent डाउनलोड में, फ़ाइल कई उपयोगकर्ताओं के कंप्यूटरों से टुकड़ों में प्राप्त होती है, जबकि वही कंप्यूटर दूसरों को टुकड़े अपलोड भी करता है। यह कौन-सा नेटवर्क मॉडल है?","optionsHi":["क्लाइंट-सर्वर","मेनफ़्रेम टर्मिनल","स्टार टोपोलॉजी","पीयर-टू-पीयर (Peer-to-peer)"],"explanationHi":"पीयर-टू-पीयर नेटवर्किंग में हर कंप्यूटर क्लाइंट और सर्वर दोनों की तरह काम करता है, सीधे टुकड़े साझा करता है। क्लाइंट-सर्वर में केंद्रीय सर्वर क्लाइंटों को सेवा देते हैं।"},
  {"id":"comp-ms-office-internet-484","question":"Match the cloud service with its model: 1. Gmail used by a bank's staff 2. Renting virtual servers and storage to run the bank's own operating system 3. A platform where developers just upload code and the provider runs it; a. IaaS b. PaaS c. SaaS","options":["1-a, 2-c, 3-b","1-c, 2-b, 3-a","1-c, 2-a, 3-b","1-b, 2-a, 3-c"],"answer":2,"explanation":"Ready-to-use software is SaaS, raw virtual machines and storage are IaaS, and a managed environment for deploying your own code is PaaS.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"क्लाउड सेवा को उसके मॉडल से सुमेलित कीजिए: 1. किसी बैंक के कर्मचारियों द्वारा उपयोग किया जाने वाला Gmail 2. बैंक के अपने ऑपरेटिंग सिस्टम को चलाने के लिए वर्चुअल सर्वर और स्टोरेज किराये पर लेना 3. ऐसा प्लेटफ़ॉर्म जहाँ डेवलपर केवल कोड अपलोड करते हैं और प्रदाता उसे चलाता है; a. IaaS b. PaaS c. SaaS","optionsHi":["1-a, 2-c, 3-b","1-c, 2-b, 3-a","1-c, 2-a, 3-b","1-b, 2-a, 3-c"],"explanationHi":"उपयोग के लिए तैयार सॉफ़्टवेयर SaaS है, कच्चे वर्चुअल मशीन और स्टोरेज IaaS हैं, और अपना कोड तैनात करने का प्रबंधित वातावरण PaaS है।"},
  {"id":"comp-ms-office-internet-485","question":"In e-mail and online chat etiquette (netiquette), what does typing a whole message IN CAPITAL LETTERS usually suggest?","options":["Urgency approved by a manager","Shouting","A formal legal notice","An automatic system message"],"answer":1,"explanation":"Writing in all capitals is read as shouting and is considered rude; important words are better shown with bold or a clear subject line.","difficulty":"moderate","source":"SSC CHSL · SBI Clerk","questionHi":"ई-मेल और ऑनलाइन चैट शिष्टाचार (नेटिकेट) में, पूरा संदेश बड़े अक्षरों (CAPITAL LETTERS) में टाइप करना सामान्यतः क्या संकेत देता है?","optionsHi":["प्रबंधक द्वारा अनुमोदित तात्कालिकता","चिल्लाना","औपचारिक कानूनी नोटिस","स्वचालित सिस्टम संदेश"],"explanationHi":"पूरे बड़े अक्षरों में लिखना चिल्लाना माना जाता है और अशिष्ट समझा जाता है; महत्वपूर्ण शब्दों को बोल्ड या स्पष्ट विषय पंक्ति से दिखाना बेहतर है।"},
  {"id":"comp-ms-office-internet-486","question":"An antivirus program finds a suspicious file and moves it into quarantine. What does this mean?","options":["The file is isolated where it cannot run, and can be restored or deleted later","The file is immediately and permanently deleted from the disk with no way to restore it","The file is uploaded to the police cyber cell along with the details of the user","The file is repaired and put back in its place, so it is now safe to open"],"answer":0,"explanation":"Quarantine locks a suspect file away so it cannot execute, while keeping it in case it was a false alarm. Cleaning or deletion is a separate choice.","difficulty":"moderate","source":"SBI Clerk · IBPS Clerk","questionHi":"कोई एंटीवायरस प्रोग्राम संदिग्ध फ़ाइल पाकर उसे क्वारंटीन (quarantine) में डाल देता है। इसका क्या अर्थ है?","optionsHi":["फ़ाइल अलग कर दी जाती है जहाँ वह चल नहीं सकती, और बाद में बहाल या हटाई जा सकती है","फ़ाइल डिस्क से तुरंत और स्थायी रूप से हटा दी जाती है, बहाली का कोई तरीका नहीं","फ़ाइल उपयोगकर्ता के विवरण के साथ पुलिस साइबर सेल को अपलोड कर दी जाती है","फ़ाइल की मरम्मत करके उसकी जगह वापस रख दी जाती है, इसलिए अब उसे खोलना सुरक्षित है"],"explanationHi":"क्वारंटीन संदिग्ध फ़ाइल को बंद करके रख देता है ताकि वह निष्पादित न हो, और उसे इस स्थिति में बचाए रखता है कि वह झूठा अलार्म रहा हो। सफ़ाई या हटाना अलग विकल्प है।"},
  {"id":"comp-ms-office-internet-487","question":"A security team opens a suspicious e-mail attachment inside an isolated environment where any harm it does cannot reach the real system, and watches what it does. This environment is called a:","options":["Honeypot","Sandbox","Firewall","Proxy"],"answer":1,"explanation":"A sandbox runs untrusted code in isolation to observe its behaviour safely. A honeypot is a decoy that lures attackers, not a place to test files.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक सुरक्षा टीम किसी संदिग्ध ई-मेल अटैचमेंट को ऐसे अलग वातावरण में खोलती है जहाँ उसकी की गई कोई भी हानि वास्तविक सिस्टम तक नहीं पहुँच सकती, और देखती है कि वह क्या करता है। इस वातावरण को क्या कहते हैं?","optionsHi":["हनीपॉट (Honeypot)","सैंडबॉक्स (Sandbox)","फ़ायरवॉल (Firewall)","प्रॉक्सी (Proxy)"],"explanationHi":"सैंडबॉक्स अविश्वसनीय कोड को अलग वातावरण में चलाकर उसके व्यवहार को सुरक्षित रूप से देखता है। हनीपॉट हमलावरों को लुभाने वाला चारा है, फ़ाइलों का परीक्षण करने की जगह नहीं।"},
  {"id":"comp-ms-office-internet-488","question":"The WannaCry ransomware of May 2017 spread mostly through Windows computers that had not been updated. Why?","options":["It used a flaw that no vendor had heard of, so no patch existed anywhere at that time","It spread only through infected USB drives, which updated systems refused to read","It exploited a Windows file-sharing (SMB) flaw for which a patch had been released earlier","It needed the user to type an administrator password, which updates had removed"],"answer":2,"explanation":"WannaCry used the EternalBlue exploit against SMBv1; Microsoft had issued a fix (MS17-010) in March 2017, so patched systems were protected. It was not a zero-day at the time.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"मई 2017 का WannaCry रैनसमवेयर मुख्यतः उन Windows कंप्यूटरों के ज़रिए फैला जो अपडेट नहीं किए गए थे। ऐसा क्यों?","optionsHi":["उसने ऐसी खामी का उपयोग किया जिसके बारे में किसी विक्रेता को पता नहीं था, इसलिए उस समय कहीं कोई पैच नहीं था","वह केवल संक्रमित USB ड्राइवों से फैला, जिन्हें अपडेट किए गए सिस्टम पढ़ने से मना कर देते थे","उसने Windows की फ़ाइल-साझाकरण (SMB) खामी का फ़ायदा उठाया जिसका पैच पहले जारी हो चुका था","उसे उपयोगकर्ता से एडमिनिस्ट्रेटर पासवर्ड टाइप करवाना पड़ता था, जिसे अपडेट ने हटा दिया था"],"explanationHi":"WannaCry ने SMBv1 के विरुद्ध EternalBlue एक्सप्लॉइट का उपयोग किया; Microsoft ने मार्च 2017 में सुधार (MS17-010) जारी किया था, इसलिए पैच किए गए सिस्टम सुरक्षित थे। वह उस समय ज़ीरो-डे नहीं था।"},
  {"id":"comp-ms-office-internet-489","question":"A bank moves from a 4-digit to a 6-digit numeric PIN. How many times larger is the number of possible PINs?","options":["100 times","2 times","10 times","50 times"],"answer":0,"explanation":"A 4-digit PIN has 10^4 = 10,000 combinations and a 6-digit PIN 10^6 = 1,000,000, which is 10^2 = 100 times as many.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"कोई बैंक 4-अंकीय से 6-अंकीय संख्यात्मक PIN पर जाता है। संभावित PIN की संख्या कितने गुना बड़ी हो जाती है?","optionsHi":["100 गुना","2 गुना","10 गुना","50 गुना"],"explanationHi":"4-अंकीय PIN के 10^4 = 10,000 संयोजन होते हैं और 6-अंकीय PIN के 10^6 = 1,000,000, जो 10^2 = 100 गुना है।"},
  {"id":"comp-ms-office-internet-490","question":"In a Caesar cipher each letter is replaced by the letter 3 places later in the alphabet. What is the word BANK after encryption?","options":["DCPM","YXKH","EDNQ","EDQN"],"answer":3,"explanation":"B→E, A→D, N→Q and K→N, giving EDQN. Shifting backwards by 3 would give YXKH. Such simple substitution ciphers are easy to break.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL","questionHi":"सीज़र सिफ़र (Caesar cipher) में हर अक्षर को वर्णमाला में 3 स्थान आगे वाले अक्षर से बदला जाता है। शब्द BANK एन्क्रिप्शन के बाद क्या बनता है?","optionsHi":["DCPM","YXKH","EDNQ","EDQN"],"explanationHi":"B→E, A→D, N→Q और K→N, जिससे EDQN मिलता है। 3 पीछे खिसकाने पर YXKH मिलता। ऐसे सरल प्रतिस्थापन सिफ़र आसानी से तोड़े जा सकते हैं।"},
  {"id":"comp-ms-office-internet-491","question":"A bank publishes the SHA-256 hash of a downloadable app. A customer changes just one character in the downloaded file and hashes it again. What will the new hash look like?","options":["Identical to the published hash, as the size is unchanged","Different from the published hash in one character only","Completely different from the published hash","The same as the published hash but one character shorter"],"answer":2,"explanation":"Good hash functions show the avalanche effect: a tiny change in input changes the output unpredictably and completely, while the length stays fixed (64 hex characters for SHA-256).","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कोई बैंक डाउनलोड योग्य ऐप का SHA-256 हैश प्रकाशित करता है। एक ग्राहक डाउनलोड की गई फ़ाइल में केवल एक वर्ण बदलता है और उसका फिर हैश बनाता है। नया हैश कैसा दिखेगा?","optionsHi":["प्रकाशित हैश के समान, क्योंकि आकार अपरिवर्तित है","प्रकाशित हैश से केवल एक वर्ण में भिन्न","प्रकाशित हैश से पूरी तरह भिन्न","प्रकाशित हैश जैसा ही पर एक वर्ण छोटा"],"explanationHi":"अच्छे हैश फ़ंक्शन में हिमस्खलन प्रभाव (avalanche effect) होता है: इनपुट में छोटा सा परिवर्तन आउटपुट को अप्रत्याशित और पूर्णतः बदल देता है, जबकि लंबाई स्थिर रहती है (SHA-256 के लिए 64 हेक्स वर्ण)।"},
  {"id":"comp-ms-office-internet-492","question":"Malware hidden inside a pirated game gives an attacker full remote control of the victim's computer, including the webcam and files. It is best described as a:","options":["Remote Access Trojan (RAT)","Boot sector virus on the disk","Logic bomb with a timer","Adware program with pop-ups"],"answer":0,"explanation":"A RAT is a Trojan that opens a hidden backdoor so the attacker can control the system remotely. A logic bomb only waits for a trigger condition.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी पाइरेटेड गेम के भीतर छिपा मैलवेयर हमलावर को पीड़ित के कंप्यूटर पर, वेबकैम और फ़ाइलों सहित, पूर्ण दूरस्थ नियंत्रण दे देता है। इसका सबसे अच्छा वर्णन क्या है?","optionsHi":["रिमोट एक्सेस ट्रोजन (RAT)","डिस्क पर बूट सेक्टर वायरस","टाइमर वाला लॉजिक बम","पॉप-अप वाला एडवेयर प्रोग्राम"],"explanationHi":"RAT ऐसा ट्रोजन है जो छिपा बैकडोर खोलता है ताकि हमलावर सिस्टम को दूर से नियंत्रित कर सके। लॉजिक बम केवल किसी ट्रिगर शर्त की प्रतीक्षा करता है।"},
  {"id":"comp-ms-office-internet-493","question":"A ransom note suddenly appears on one computer in a branch network. What should be done first?","options":["Pay the ransom quickly before the price goes up","Disconnect that computer from the network at once","Restart the computer several times to clear it","Copy its files to the shared drive to save them"],"answer":1,"explanation":"Isolating the infected machine stops the ransomware spreading to shares and other PCs. Paying does not guarantee recovery, and copying files can spread the infection.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी शाखा नेटवर्क के एक कंप्यूटर पर अचानक फिरौती का नोट दिखता है। सबसे पहले क्या करना चाहिए?","optionsHi":["कीमत बढ़ने से पहले जल्दी से फिरौती चुका दें","उस कंप्यूटर को तुरंत नेटवर्क से अलग कर दें","उसे साफ़ करने के लिए कंप्यूटर को कई बार रीस्टार्ट करें","उसकी फ़ाइलों को बचाने के लिए साझा ड्राइव पर कॉपी कर दें"],"explanationHi":"संक्रमित मशीन को अलग करने से रैनसमवेयर साझा ड्राइवों और अन्य PC में फैलने से रुकता है। भुगतान से बहाली की गारंटी नहीं मिलती, और फ़ाइलें कॉपी करने से संक्रमण फैल सकता है।"},
  {"id":"comp-ms-office-internet-494","question":"Arrange these Wi-Fi security standards from the weakest to the strongest:","options":["WPA, WEP, WPA2, WPA3","WEP, WPA2, WPA, WPA3","WPA3, WPA2, WPA, WEP","WEP, WPA, WPA2, WPA3"],"answer":3,"explanation":"WEP (1990s) is easily cracked, WPA was a stop-gap, WPA2 brought AES encryption, and WPA3 (2018) is the newest and strongest.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"इन Wi-Fi सुरक्षा मानकों को सबसे कमज़ोर से सबसे मज़बूत के क्रम में व्यवस्थित कीजिए:","optionsHi":["WPA, WEP, WPA2, WPA3","WEP, WPA2, WPA, WPA3","WPA3, WPA2, WPA, WEP","WEP, WPA, WPA2, WPA3"],"explanationHi":"WEP (1990 के दशक का) आसानी से तोड़ा जा सकता है, WPA एक अस्थायी उपाय था, WPA2 ने AES एन्क्रिप्शन दिया, और WPA3 (2018) सबसे नया और सबसे मज़बूत है।"},
  {"id":"comp-ms-office-internet-495","question":"A branch hides its Wi-Fi network name (SSID) and believes the network is now secure. Why is this weak protection?","options":["Hiding the SSID turns off encryption, so all the data travels in plain form","Hiding the SSID makes the router accept any password typed by a device","The SSID still travels in normal Wi-Fi traffic and can be seen with simple tools","A hidden SSID can be used only on 2.4 GHz, which has no security at all"],"answer":2,"explanation":"A hidden SSID is left out of beacons but still appears when devices connect, so attackers find it easily. Real protection comes from WPA2/WPA3 with a strong passphrase.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"कोई शाखा अपने Wi-Fi नेटवर्क का नाम (SSID) छिपा देती है और मानती है कि नेटवर्क अब सुरक्षित है। यह कमज़ोर सुरक्षा क्यों है?","optionsHi":["SSID छिपाने से एन्क्रिप्शन बंद हो जाता है, इसलिए सारा डेटा सादे रूप में जाता है","SSID छिपाने से राउटर उपकरण द्वारा टाइप किया गया कोई भी पासवर्ड स्वीकार कर लेता है","SSID अब भी सामान्य Wi-Fi ट्रैफ़िक में जाता है और सरल उपकरणों से देखा जा सकता है","छिपा SSID केवल 2.4 GHz पर उपयोग हो सकता है, जिसमें कोई सुरक्षा नहीं होती"],"explanationHi":"छिपा SSID बीकन से हटा दिया जाता है पर उपकरणों के जुड़ते समय फिर भी दिखता है, इसलिए हमलावर उसे आसानी से खोज लेते हैं। वास्तविक सुरक्षा मज़बूत पासफ़्रेज़ वाले WPA2/WPA3 से मिलती है।"},
  {"id":"comp-ms-office-internet-496","question":"Who sent the first e-mail between two computers on ARPANET in 1971 and chose the @ sign to separate the user from the host?","options":["Tim Berners-Lee","Ray Tomlinson","Vint Cerf","Bob Kahn"],"answer":1,"explanation":"Ray Tomlinson created network e-mail on ARPANET in 1971 and used @. Tim Berners-Lee invented the World Wide Web, and Cerf and Kahn designed TCP/IP.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL","questionHi":"1971 में ARPANET पर दो कंप्यूटरों के बीच पहला ई-मेल किसने भेजा और उपयोगकर्ता को होस्ट से अलग करने के लिए @ चिह्न चुना?","optionsHi":["Tim Berners-Lee","Ray Tomlinson","Vint Cerf","Bob Kahn"],"explanationHi":"Ray Tomlinson ने 1971 में ARPANET पर नेटवर्क ई-मेल बनाया और @ का उपयोग किया। Tim Berners-Lee ने World Wide Web का आविष्कार किया, और Cerf व Kahn ने TCP/IP की रूपरेखा बनाई।"},
  {"id":"comp-ms-office-internet-497","question":"Public internet access in India was launched on 15 August 1995 by which organisation?","options":["VSNL","BSNL","MTNL","ERNET"],"answer":0,"explanation":"Videsh Sanchar Nigam Limited (VSNL) launched public internet service in India on 15 August 1995. ERNET earlier connected only academic and research institutions.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL","questionHi":"भारत में सार्वजनिक इंटरनेट सेवा 15 अगस्त 1995 को किस संगठन द्वारा शुरू की गई?","optionsHi":["VSNL","BSNL","MTNL","ERNET"],"explanationHi":"विदेश संचार निगम लिमिटेड (VSNL) ने 15 अगस्त 1995 को भारत में सार्वजनिक इंटरनेट सेवा शुरू की। ERNET ने इससे पहले केवल शैक्षणिक और अनुसंधान संस्थानों को जोड़ा था।"},
  {"id":"comp-ms-office-internet-498","question":"Roughly how many distinct addresses does the IPv4 address space allow?","options":["About 4.3 million","About 65 thousand","About 16 million","About 4.3 billion"],"answer":3,"explanation":"IPv4 uses 32 bits, giving 2^32 = 4,294,967,296 addresses, about 4.3 billion. The shortage of these led to NAT and to 128-bit IPv6.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"IPv4 पता स्थान लगभग कितने अलग-अलग पते देता है?","optionsHi":["लगभग 4.3 मिलियन","लगभग 65 हज़ार","लगभग 16 मिलियन","लगभग 4.3 अरब"],"explanationHi":"IPv4 32 बिट का उपयोग करता है, जिससे 2^32 = 4,294,967,296 पते मिलते हैं, यानी लगभग 4.3 अरब। इनकी कमी के कारण NAT और 128-बिट IPv6 आए।"},
  {"id":"comp-ms-office-internet-499","question":"Why has Telnet largely been replaced by SSH for logging in to remote servers?","options":["Telnet works only inside a single LAN, while SSH also works over the internet","Telnet sends data, including passwords, as plain text, while SSH encrypts it","Telnet cannot run commands on the server, while SSH can run them","Telnet needs a graphical screen, while SSH works on a text console"],"answer":1,"explanation":"Telnet (port 23) has no encryption, so anyone capturing traffic can read passwords. SSH (port 22) gives the same remote login over an encrypted channel.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"दूरस्थ सर्वरों में लॉग इन करने के लिए Telnet की जगह बड़े पैमाने पर SSH क्यों आ गया है?","optionsHi":["Telnet केवल एक LAN के भीतर काम करता है, जबकि SSH इंटरनेट पर भी काम करता है","Telnet डेटा, पासवर्ड सहित, सादे पाठ में भेजता है, जबकि SSH उसे एन्क्रिप्ट करता है","Telnet सर्वर पर कमांड नहीं चला सकता, जबकि SSH चला सकता है","Telnet को ग्राफ़िकल स्क्रीन चाहिए, जबकि SSH टेक्स्ट कंसोल पर काम करता है"],"explanationHi":"Telnet (पोर्ट 23) में कोई एन्क्रिप्शन नहीं है, इसलिए ट्रैफ़िक पकड़ने वाला कोई भी पासवर्ड पढ़ सकता है। SSH (पोर्ट 22) वही रिमोट लॉगिन एन्क्रिप्टेड चैनल पर देता है।"},
  {"id":"comp-ms-office-internet-500","question":"Which statement about SSL and TLS is correct?","options":["TLS is outdated and HTTPS now uses SSL 3.0, the latest version of the protocol","SSL and TLS are two names for exactly the same current protocol version","SSL is outdated; HTTPS now uses TLS, though people still say SSL","TLS protects only e-mail, while SSL protects only web browsing"],"answer":2,"explanation":"TLS succeeded SSL; all SSL versions are deprecated as insecure, and modern HTTPS uses TLS 1.2 or 1.3. People still say 'SSL certificate' out of habit.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"SSL और TLS के बारे में कौन-सा कथन सही है?","optionsHi":["TLS पुराना हो चुका है और HTTPS अब SSL 3.0 का उपयोग करता है, जो प्रोटोकॉल का नवीनतम संस्करण है","SSL और TLS ठीक उसी वर्तमान प्रोटोकॉल संस्करण के दो नाम हैं","SSL पुराना हो चुका है; HTTPS अब TLS का उपयोग करता है, हालाँकि लोग अब भी SSL कहते हैं","TLS केवल ई-मेल की रक्षा करता है, और SSL केवल वेब ब्राउज़िंग की"],"explanationHi":"TLS ने SSL का स्थान लिया; सभी SSL संस्करण असुरक्षित होने के कारण अप्रचलित हैं, और आधुनिक HTTPS TLS 1.2 या 1.3 का उपयोग करता है। लोग आदतन अब भी 'SSL प्रमाणपत्र' कहते हैं।"},
  {"id":"comp-ms-office-internet-501","question":"A branch's phone calls are carried as data packets over its internet connection instead of the traditional telephone line. This technology is called:","options":["VoIP","IPTV","VPN","PSTN"],"answer":0,"explanation":"Voice over Internet Protocol (VoIP) digitises speech into IP packets. PSTN is the traditional circuit-switched telephone network, and IPTV carries television over IP.","difficulty":"moderate","source":"SBI Clerk · SSC CHSL","questionHi":"किसी शाखा की फ़ोन कॉल पारंपरिक टेलीफ़ोन लाइन की जगह उसके इंटरनेट कनेक्शन पर डेटा पैकेट के रूप में ले जाई जाती हैं। इस तकनीक को क्या कहते हैं?","optionsHi":["VoIP","IPTV","VPN","PSTN"],"explanationHi":"Voice over Internet Protocol (VoIP) वाणी को IP पैकेटों में डिजिटल बनाता है। PSTN पारंपरिक सर्किट-स्विच्ड टेलीफ़ोन नेटवर्क है, और IPTV IP पर टेलीविज़न ले जाता है।"},
];

export default questions;
